sys.setrecursionlimit(20000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # State grid: 0 = Unknown, 1 = White (Unshaded), -1 = Black (Shaded)
    # We start with all Unknown.
    state = [[0 for _ in range(N)] for _ in range(N)]

    # Helper to get neighbors
    def get_neighbors(r, c):
        neighs = []
        if r > 0: neighs.append((r-1, c))
        if r < N-1: neighs.append((r+1, c))
        if c > 0: neighs.append((r, c-1))
        if c < N-1: neighs.append((r, c+1))
        return neighs

    # Propagate constraints
    # Returns True if consistent, False if conflict
    def propagate(current_state):
        changed = True
        while changed:
            changed = False

            # 1. No Adjacent Black Cells
            # If a cell is Black, neighbors must be White.
            for r in range(N):
                for c in range(N):
                    if current_state[r][c] == -1:
                        for nr, nc in get_neighbors(r, c):
                            if current_state[nr][nc] == -1:
                                return False # Adjacent blacks
                            if current_state[nr][nc] == 0:
                                current_state[nr][nc] = 1
                                changed = True

            # 2. Uniqueness in Rows and Cols
            # If a number appears in multiple "non-black" cells in a row/col,
            # and one of them is White, the others MUST be Black.

            # Check Rows
            for r in range(N):
                val_indices = {}
                for c in range(N):
                    if current_state[r][c] != -1: # White or Unknown
                        val = data[r][c]
                        if val not in val_indices:
                            val_indices[val] = []
                        val_indices[val].append(c)

                for val, cols in val_indices.items():
                    if len(cols) > 1:
                        # Check if any is already White
                        white_cols = [c for c in cols if current_state[r][c] == 1]
                        if len(white_cols) > 1:
                            return False # Two whites with same value
                        if len(white_cols) == 1:
                            # The one white cell forces others to be Black
                            wc = white_cols[0]
                            for c in cols:
                                if c != wc:
                                    if current_state[r][c] == 0:
                                        current_state[r][c] = -1
                                        changed = True
                                    elif current_state[r][c] == 1:
                                        return False # Should have been caught above

            # Check Cols
            for c in range(N):
                val_indices = {}
                for r in range(N):
                    if current_state[r][c] != -1:
                        val = data[r][c]
                        if val not in val_indices:
                            val_indices[val] = []
                        val_indices[val].append(r)

                for val, rows in val_indices.items():
                    if len(rows) > 1:
                        white_rows = [r for r in rows if current_state[r][c] == 1]
                        if len(white_rows) > 1:
                            return False
                        if len(white_rows) == 1:
                            wr = white_rows[0]
                            for r in rows:
                                if r != wr:
                                    if current_state[r][c] == 0:
                                        current_state[r][c] = -1
                                        changed = True
                                    elif current_state[r][c] == 1:
                                        return False

            # 3. Connectivity Check (Lightweight - Isolation)
            # If a White cell is surrounded by Black cells (and it's not the only white cell), it's isolated.
            # Note: Unknown neighbors (0) can become White, so they don't cause isolation yet.
            # Only if ALL neighbors are -1 (Black) is it isolated.

            # Count white cells first
            white_count = sum(1 for r in range(N) for c in range(N) if current_state[r][c] == 1)

            if white_count > 1:
                for r in range(N):
                    for c in range(N):
                        if current_state[r][c] == 1:
                            has_potential_neighbor = False
                            for nr, nc in get_neighbors(r, c):
                                if current_state[nr][nc] != -1: # White or Unknown
                                    has_potential_neighbor = True
                                    break
                            if not has_potential_neighbor:
                                return False # Isolated white cell

        return True

    def is_fully_connected(current_state):
        # Find first white cell
        start_r, start_c = -1, -1
        white_count = 0
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == 1:
                    white_count += 1
                    if start_r == -1:
                        start_r, start_c = r, c

        if white_count == 0:
            return False # Must have at least one? Rules say "All unshaded... form one group". Usually implies non-empty.
                         # If empty, technically vacuously true, but puzzles usually have solution.
                         # Let's assume non-empty.

        # BFS
        visited = set()
        queue = [(start_r, start_c)]
        visited.add((start_r, start_c))

        while queue:
            r, c = queue.pop(0)
            for nr, nc in get_neighbors(r, c):
                if current_state[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == white_count

    def get_unknowns(current_state):
        unknowns = []
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == 0:
                    unknowns.append((r, c))
        return unknowns

    # Heuristic: Pick unknown with most constraints?
    # For now, just pick first.
    # Better heuristic: Pick cell that is part of a duplicate pair?
    def pick_best_unknown(current_state):
        # Simple strategy: find a cell that, if set to White, forces many Blacks (due to duplicates)
        # or if set to Black, forces many Whites (neighbors).
        # Actually, just finding any unknown is fine for 10x10 if propagation is strong.
        # Let's try to find a cell involved in a row/col with duplicates to prioritize.

        candidates = []
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == 0:
                    candidates.append((r, c))

        if not candidates:
            return None

        # Sort candidates?
        # Maybe prioritize cells with values that appear multiple times in row/col
        best = candidates[0]
        max_score = -1

        for r, c in candidates:
            val = data[r][c]
            score = 0
            # Count duplicates in row
            row_count = sum(1 for cc in range(N) if data[r][cc] == val and current_state[r][cc] != -1)
            # Count duplicates in col
            col_count = sum(1 for rr in range(N) if data[rr][c] == val and current_state[rr][c] != -1)
            score = row_count + col_count
            if score > max_score:
                max_score = score
                best = (r, c)
        return best

    def backtrack(current_state):
        # Propagate
        if not propagate(current_state):
            return None

        # Check if solved
        unknowns = get_unknowns(current_state)
        if not unknowns:
            if is_fully_connected(current_state):
                return current_state
            else:
                return None

        # Pick a cell
        r, c = pick_best_unknown(current_state)

        # Try White (1)
        # Copy state
        state_white = [row[:] for row in current_state]
        state_white[r][c] = 1
        res = backtrack(state_white)
        if res:
            return res

        # Try Black (-1)
        state_black = [row[:] for row in current_state]
        state_black[r][c] = -1
        res = backtrack(state_black)
        if res:
            return res

        return None

    final_state = backtrack(state)

    if final_state is None:
        return "No Solution"

    # Format output
    # 'B' for black, None for white
    result_grid = []
    for r in range(N):
        row_res = []
        for c in range(N):
            if final_state[r][c] == -1:
                row_res.append('B')
            else:
                row_res.append(None)
        result_grid.append(row_res)

    return result_grid

