        # Copy domains for backtracking
        # Since N is small, deep copy is acceptable, but we can optimize by restoring.
        # Let's use a stack of changes.

        values = sorted(list(domains[r][c]))

        for val in values:
            # Assign
            domains[r][c] = {val}

            # Propagate
            if propagate():
                if solve_recursive():
                    return True

            # Backtrack: restore domain (propagate might have changed others)
            # This is tricky with the current propagate structure which modifies in place.
            # We need to save state.
            # Given N=7, copying the whole domains grid is cheap enough.
            pass

        # If we are here, we need to restore. 
        # But wait, the loop above modifies `domains` permanently if we don't copy.
        # Let's restructure to use copying.
        return False

    # Revised Backtracking with copying
    def solve_bt(current_domains):
        # Check for completion
        is_complete = True
        min_len = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                if len(current_domains[r][c]) == 0:
                    return None # Failure
                if len(current_domains[r][c]) > 1:
                    is_complete = False
                    if len(current_domains[r][c]) < min_len:
                        min_len = len(current_domains[r][c])
                        best_cell = (r, c)

        if is_complete:
            return current_domains

        r, c = best_cell

        # Try values
        # Heuristic: Order values?
        # Let's just try all.
        for val in sorted(list(current_domains[r][c])):
            # Create new domains state
            new_domains = [row[:] for row in current_domains] # Shallow copy of rows
            new_domains[r][c] = {val}

            # We need to run propagation on new_domains.
            # But my propagate function uses the global `domains`.
            # I need to make propagate work on a passed domains object.

            if propagate_domains(new_domains):
                result = solve_bt(new_domains)
                if result:
                    return result

        return None

    def propagate_domains(domains):
        # Same logic as propagate but on `domains` argument
        changed = True
        while changed:
            changed = False

            # Horizontal
            for (r, c), sym in h_constraints.items():
                d1 = domains[r][c]
                d2 = domains[r][c+1]

                if len(d1) == 1:
                    v1 = list(d1)[0]
                    new_d2 = set()
                    for v2 in d2:
                        if is_consistent(r, c, v1, r, c+1, v2, sym):
                            new_d2.add(v2)
                    if new_d2 != d2:
                        domains[r][c+1] = new_d2
                        changed = True
                        if not new_d2: return False

                if len(d2) == 1:
                    v2 = list(d2)[0]
                    new_d1 = set()
                    for v1 in d1:
                        if is_consistent(r, c, v1, r, c+1, v2, sym):
                            new_d1.add(v1)
                    if new_d1 != d1:
                        domains[r][c] = new_d1
                        changed = True
                        if not new_d1: return False

            # Vertical
            for (r, c), sym in v_constraints.items():
                d1 = domains[r][c]
                d2 = domains[r+1][c]

                if len(d1) == 1:
                    v1 = list(d1)[0]
                    new_d2 = set()
                    for v2 in d2:
                        if is_consistent(r, c, v1, r+1, c, v2, sym):
                            new_d2.add(v2)
                    if new_d2 != d2:
                        domains[r+1][c] = new_d2
                        changed = True
                        if not new_d2: return False

                if len(d2) == 1:
                    v2 = list(d2)[0]
                    new_d1 = set()
                    for v1 in d1:
                        if is_consistent(r, c, v1, r+1, c, v2, sym):
                            new_d1.add(v1)
                    if new_d1 != d1:
                        domains[r][c] = new_d1
                        changed = True
                        if not new_d1: return False

            # Latin Square
            for r in range(N):
                row_vals = set()
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        row_vals.add(list(domains[r][c])[0])

                for c in range(N):
                    if len(domains[r][c]) > 1:
                        old_len = len(domains[r][c])
                        domains[r][c] -= row_vals
                        if len(domains[r][c]) != old_len:
                            changed = True
                            if not domains[r][c]: return False

            for c in range(N):
                col_vals = set()
                for r in range(N):
                    if len(domains[r][c]) == 1:
                        col_vals.add(list(domains[r][c])[0])

                for r in range(N):
                    if len(domains[r][c]) > 1:
                        old_len = len(domains[r][c])
                        domains[r][c] -= col_vals
                        if len(domains[r][c]) != old_len:
                            changed = True
                            if not domains[r][c]: return False

            # Hidden Singles
            for r in range(N):
                for num in range(1, N + 1):
                    possible_cols = [c for c in range(N) if num in domains[r][c]]
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {num}
                            changed = True

            for c in range(N):
                for num in range(1, N + 1):
                    possible_rows = [r for r in range(N) if num in domains[r][c]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {num}
                            changed = True
        return True

    # Initial propagation
    if not propagate_domains(domains):
        return "No Solution"

    final_domains = solve_bt(domains)

    if final_domains:
        result_grid = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(list(final_domains[r][c])[0])
            result_grid.append(row)
        return result_grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
