OBSERVATION = {'U': [0, 0, 0, 0], 'D': [3, 2, 0, 0], 'L': [0, 0, 0, 0], 'R': [3, 3, 0, 2]}

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    N = len(U)
    grid = [[0] * N for _ in range(N)]

    def count_visible(line):
        count = 0
        max_h = 0
        for h in line:
            if h == 0: continue
            if h > max_h:
                max_h = h
                count += 1
        return count

    def get_max_possible_visible(line, clue):
        # Calculate max possible visible buildings given current state and clue direction
        # line is the row/col as seen from the clue direction
        max_h = 0
        vis = 0
        zeros = 0
        for h in line:
            if h == 0:
                zeros += 1
            else:
                if h > max_h:
                    max_h = h
                    vis += 1

        # If N is already in the line, visibility is fixed
        if N in line:
            return vis

        # Otherwise, we can potentially see more buildings.
        # The remaining visible buildings must be taller than current max_h.
        # Available taller buildings: N - max_h
        # We have 'zeros' spots to fill.
        # We can see at most min(zeros, N - max_h) additional buildings.
        additional = min(zeros, N - max_h)
        return vis + additional

    def is_valid(r, c, val):
        # Check row uniqueness
        if val in grid[r]:
            return False
        # Check col uniqueness
        for i in range(N):
            if grid[i][c] == val:
                return False

        # Place temporarily
        grid[r][c] = val

        # Check Row Constraints
        # Left Clue
        if L[r] > 0:
            row_vals = grid[r]
            vis = count_visible(row_vals)
            if vis > L[r]:
                grid[r][c] = 0; return False

            max_vis = get_max_possible_visible(row_vals, L[r])
            if max_vis < L[r]:
                grid[r][c] = 0; return False

            if N in row_vals:
                if vis != L[r]:
                    grid[r][c] = 0; return False

        # Right Clue
        if R[r] > 0:
            row_vals_rev = grid[r][::-1]
            vis = count_visible(row_vals_rev)
            if vis > R[r]:
                grid[r][c] = 0; return False

            max_vis = get_max_possible_visible(row_vals_rev, R[r])
            if max_vis < R[r]:
                grid[r][c] = 0; return False

            if N in grid[r]: # N is in the row (order doesn't matter for presence)
                 # Need to check visibility from right specifically
                 # If N is present, visibility from right is fixed
                 if vis != R[r]: # vis was calculated on reversed row
                     grid[r][c] = 0; return False

        # Check Col Constraints
        col_vals = [grid[i][c] for i in range(N)]

        # Top Clue
        if U[c] > 0:
            vis = count_visible(col_vals)
            if vis > U[c]:
                grid[r][c] = 0; return False

            max_vis = get_max_possible_visible(col_vals, U[c])
            if max_vis < U[c]:
                grid[r][c] = 0; return False

            if N in col_vals:
                if vis != U[c]:
                    grid[r][c] = 0; return False

        # Bottom Clue
        if D[c] > 0:
            col_vals_rev = col_vals[::-1]
            vis = count_visible(col_vals_rev)
            if vis > D[c]:
                grid[r][c] = 0; return False

            max_vis = get_max_possible_visible(col_vals_rev, D[c])
            if max_vis < D[c]:
                grid[r][c] = 0; return False

            if N in col_vals:
                if vis != D[c]:
                    grid[r][c] = 0; return False

        grid[r][c] = 0
        return True

    def backtrack(idx):
        if idx == N * N:
            return True

        r, c = divmod(idx, N)

        # Optimization: Order of values? 
        # For skyscrapers, usually no specific order helps globally, 
        # but trying 1..N is standard.

        for val in range(1, N + 1):
            if is_valid(r, c, val):
                grid[r][c] = val
                if backtrack(idx + 1):
                    return True
                grid[r][c] = 0
        return False

    if backtrack(0):
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
