OBSERVATION = {'U': [0, 5, 0, 0, 3], 'D': [0, 2, 4, 0, 0], 'L': [0, 4, 0, 0, 0], 'R': [3, 0, 0, 0, 3]}

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    N = len(U)
    grid = [[0] * N for _ in range(N)]

    def count_visible(line):
        max_h = 0
        count = 0
        for h in line:
            if h > max_h:
                max_h = h
                count += 1
        return count

    def check_clue(line, clue):
        if clue == 0: return True
        return count_visible(line) == clue

    # Pre-fill obvious clues (1 and N)
    assignments = []

    # U clues
    for c, clue in enumerate(U):
        if clue == 1:
            assignments.append((0, c, N))
        elif clue == N:
            for r in range(N):
                assignments.append((r, c, r + 1))

    # D clues
    for c, clue in enumerate(D):
        if clue == 1:
            assignments.append((N - 1, c, N))
        elif clue == N:
            for r in range(N):
                assignments.append((N - 1 - r, c, r + 1))

    # L clues
    for r, clue in enumerate(L):
        if clue == 1:
            assignments.append((r, 0, N))
        elif clue == N:
            for c in range(N):
                assignments.append((r, c, c + 1))

    # R clues
    for r, clue in enumerate(R):
        if clue == 1:
            assignments.append((r, N - 1, N))
        elif clue == N:
            for c in range(N):
                assignments.append((r, N - 1 - c, c + 1))

    # Apply assignments and check conflicts
    for r, c, val in assignments:
        if grid[r][c] != 0 and grid[r][c] != val:
            return "No Solution"
        grid[r][c] = val

    # Helper to get possible values for a cell
    def get_possible(r, c):
        if grid[r][c] != 0:
            return [grid[r][c]]

        used_r = set(grid[r])
        used_c = set(grid[k][c] for k in range(N))
        used = used_r.union(used_c)
        used.discard(0)

        return [v for v in range(1, N + 1) if v not in used]

    def is_row_full(r):
        return all(grid[r][k] != 0 for k in range(N))

    def is_col_full(c):
        return all(grid[k][c] != 0 for k in range(N))

    def solve_bt():
        # MRV Heuristic: Find empty cell with fewest possibilities
        min_len = N + 1
        target_r, target_c = -1, -1

        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    poss = get_possible(r, c)
                    if len(poss) == 0:
                        return False
                    if len(poss) < min_len:
                        min_len = len(poss)
                        target_r, target_c = r, c
                        if min_len == 1:
                            break
            if min_len == 1:
                break

        if target_r == -1:
            # Grid full, final check (redundant if we check incrementally, but safe)
            return True

        r, c = target_r, target_c
        possible_values = get_possible(r, c)

        for val in possible_values:
            grid[r][c] = val

            # Pruning: Check constraints if row/col is full
            valid_move = True

            # Check Row r
            if is_row_full(r):
                if not check_clue(grid[r], L[r]):
                    valid_move = False
                elif not check_clue(grid[r][::-1], R[r]):
                    valid_move = False

            # Check Col c
            if valid_move and is_col_full(c):
                col_vals = [grid[k][c] for k in range(N)]
                if not check_clue(col_vals, U[c]):
                    valid_move = False
                else:
                    col_vals_rev = [grid[k][c] for k in range(N - 1, -1, -1)]
                    if not check_clue(col_vals_rev, D[c]):
                        valid_move = False

            if valid_move:
                if solve_bt():
                    return True

            grid[r][c] = 0

        return False

    if solve_bt():
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
