OBSERVATION = {'data': [[0, None, None, 3, None, 3, None], [None, None, 2, 3, None, None, None], [None, None, None, None, 1, None, 1], [1, None, None, 1, None, 2, None], [1, None, None, None, 1, None, 2], [None, None, None, 2, None, None, None], [None, 1, 0, None, None, None, 1]]}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Identify clues and initial safe cells
    # Clues are cells with numbers. They are safe (not mines).
    clues = {}
    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val is not None:
                clues[(r, c)] = val

    # State: -1 = Unknown, 0 = Safe, 1 = Mine
    # Initialize: Clues are Safe (0), others Unknown (-1)
    state = [[-1] * C for _ in range(R)]
    for (r, c) in clues:
        state[r][c] = 0

    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighs.append((nr, nc))
        return neighs

    def propagate(st):
        changed = True
        while changed:
            changed = False
            for (cr, cc), val in clues.items():
                neighbors = get_neighbors(cr, cc)
                current_mines = 0
                unknown_neighbors = []
                for n in neighbors:
                    nr, nc = n
                    if st[nr][nc] == 1:
                        current_mines += 1
                    elif st[nr][nc] == -1:
                        unknown_neighbors.append(n)

                # Rule 1: All mines found -> remaining unknowns are safe
                if current_mines == val:
                    for u in unknown_neighbors:
                        ur, uc = u
                        if st[ur][uc] == -1:
                            st[ur][uc] = 0
                            changed = True
                # Rule 2: All remaining unknowns must be mines to satisfy count
                elif current_mines + len(unknown_neighbors) == val:
                    for u in unknown_neighbors:
                        ur, uc = u
                        if st[ur][uc] == -1:
                            st[ur][uc] = 1
                            changed = True
        return st

    def is_consistent(st):
        for (cr, cc), val in clues.items():
            neighbors = get_neighbors(cr, cc)
            current_mines = 0
            unknown_count = 0
            for n in neighbors:
                nr, nc = n
                if st[nr][nc] == 1:
                    current_mines += 1
                elif st[nr][nc] == -1:
                    unknown_count += 1

            if current_mines > val: return False
            if current_mines + unknown_count < val: return False
        return True

    def solve_recursive(st):
        # 1. Propagate constraints
        st = propagate(st)

        # 2. Check consistency
        if not is_consistent(st):
            return None

        # 3. Check if solved (no unknowns)
        unknowns = []
        for r in range(R):
            for c in range(C):
                if st[r][c] == -1:
                    unknowns.append((r, c))

        if not unknowns:
            return st

        # 4. Pick a variable (heuristic: most constrained)
        # Count how many clues touch each unknown
        best_cell = None
        max_constraints = -1

        for cell in unknowns:
            r, c = cell
            count = 0
            for (cr, cc) in clues:
                if abs(r-cr) <= 1 and abs(c-cc) <= 1:
                    count += 1
            if count > max_constraints:
                max_constraints = count
                best_cell = cell

        r, c = best_cell

        # 5. Branch: Try Mine (1)
        st_mine = [row[:] for row in st]
        st_mine[r][c] = 1
        res = solve_recursive(st_mine)
        if res is not None:
            return res

        # 6. Branch: Try Safe (0)
        st_safe = [row[:] for row in st]
        st_safe[r][c] = 0
        res = solve_recursive(st_safe)
        if res is not None:
            return res

        return None

    final_state = solve_recursive(state)

    if final_state is None:
        return "No Solution"

    # Format output
    result_grid = [[None for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if final_state[r][c] == 1:
                result_grid[r][c] = 'F'
            # Else None (Safe or Clue)

    return result_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
