    C = len(data[0])

    clues = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]

    mines = set()
    safe = set(clues.keys())

    neighbors_map = {}
    for r in range(R):
        for c in range(C):
            neighs = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        neighs.append((nr, nc))
            neighbors_map[(r, c)] = neighs

    relevant_cells = set()
    for (r, c) in clues:
        for nr, nc in neighbors_map[(r, c)]:
            relevant_cells.add((nr, nc))

    def check_consistency(current_mines, current_safe):
        for (r, c), val in clues.items():
            neighs = neighbors_map[(r, c)]
            mine_count = 0
            unknown_count = 0
            for nr, nc in neighs:
                if (nr, nc) in current_mines:
                    mine_count += 1
                elif (nr, nc) not in current_safe:
                    unknown_count += 1

            if mine_count > val: return False
            if mine_count + unknown_count < val: return False
        return True

    def is_solved(current_mines, current_safe):
        for (r, c), val in clues.items():
            neighs = neighbors_map[(r, c)]
            mine_count = 0
            for nr, nc in neighs:
                if (nr, nc) in current_mines:
                    mine_count += 1
            if mine_count != val:
                return False
        return True

    def deduce(current_mines, current_safe):
        changed = True
        while changed:
            changed = False
            for (r, c), val in clues.items():
                neighs = neighbors_map[(r, c)]
                current_mines_count = 0
                unknown_neighbors = []

                for nr, nc in neighs:
                    if (nr, nc) in current_mines:
                        current_mines_count += 1
                    elif (nr, nc) not in current_safe:
                        unknown_neighbors.append((nr, nc))

                if current_mines_count == val:
                    for u in unknown_neighbors:
                        if u not in current_safe:
                            current_safe.add(u)
                            changed = True

                if current_mines_count + len(unknown_neighbors) == val:
                    for u in unknown_neighbors:
                        if u not in current_mines:
                            current_mines.add(u)
                            changed = True
        return current_mines, current_safe

    mines, safe = deduce(mines, safe)

    if not check_consistency(mines, safe):
        return "No Solution"

    if is_solved(mines, safe):
        res = [[None for _ in range(C)] for _ in range(R)]
        for (r, c) in mines:
            res[r][c] = 'F'
        return res

    unknown_relevant = [cell for cell in relevant_cells if cell not in mines and cell not in safe]

    def solve_recursive(current_mines, current_safe, unknown_list):
        m_copy = set(current_mines)
        s_copy = set(current_safe)
        m_copy, s_copy = deduce(m_copy, s_copy)

        if not check_consistency(m_copy, s_copy):
            return None

        if is_solved(m_copy, s_copy):
            return m_copy, s_copy

        next_unknowns = [u for u in unknown_list if u not in m_copy and u not in s_copy]

        if not next_unknowns:
            return None

        cell = next_unknowns[0]
        remaining = next_unknowns[1:]

        res = solve_recursive(m_copy | {cell}, s_copy, remaining)
        if res: return res

        res = solve_recursive(m_copy, s_copy | {cell}, remaining)
        if res: return res

        return None

    final = solve_recursive(mines, safe, unknown_relevant)

    if final is None:
        return "No Solution"

    final_mines, _ = final
    res = [[None for _ in range(C)] for _ in range(R)]
    for (r, c) in final_mines:
        res[r][c] = 'F'
    return res

