            for r in range(n - 1):
                for c in range(n - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    vals = [g[rr][cc] for rr, cc in cells]

                    count_b = vals.count('B')
                    count_w = vals.count('W')
                    count_none = vals.count(None)

                    # If 3 are B and 1 is None, the None must be W
                    if count_b == 3 and count_none == 1:
                        for rr, cc in cells:
                            if g[rr][cc] is None:
                                g[rr][cc] = 'W'
                                changed = True
                    # If 3 are W and 1 is None, the None must be B
                    elif count_w == 3 and count_none == 1:
                        for rr, cc in cells:
                            if g[rr][cc] is None:
                                g[rr][cc] = 'B'
                                changed = True
        return g

    # Check for immediate 2x2 violations (4 same colors)
    def check_2x2_violation(g):
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                vals = [g[rr][cc] for rr, cc in cells]
                if None not in vals:
                    if vals.count('B') == 4 or vals.count('W') == 4:
                        return True
        return False

    # Check if current placement makes connectivity impossible for a color.
    # Returns True if all cells of 'color' are connected via a path of 'color' or 'None' cells.
    # This ensures that we haven't separated regions of 'color' with a wall of the opposite color.
    def check_possible_connectivity(g, color):
        cells_of_color = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
        if len(cells_of_color) <= 1:
            return True

        start = cells_of_color[0]
        visited = set()
        queue = collections.deque([start])
        visited.add(start)

        count_visited_color = 0

        while queue:
            r, c = queue.popleft()
            if g[r][c] == color:
                count_visited_color += 1

            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited:
                    # Can traverse if it is the target color or empty (potential target color)
                    # If it is the opposite color, it acts as a wall.
                    if g[nr][nc] == color or g[nr][nc] is None:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        return count_visited_color == len(cells_of_color)

    # Check full connectivity for a completed grid
    def check_full_connectivity(g, color):
        cells_of_color = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
        if len(cells_of_color) == 0:
            return True

        start = cells_of_color[0]
        visited = set()
        queue = collections.deque([start])
        visited.add(start)
        count = 0

        while queue:
            r, c = queue.popleft()
            count += 1
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited and g[nr][nc] == color:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return count == len(cells_of_color)

    def backtrack(g):
        # 1. Propagate constraints
        g = propagate(g)

        # 2. Check for immediate 2x2 violations
        if check_2x2_violation(g):
            return None

        # 3. Check if current placement makes connectivity impossible
        if not check_possible_connectivity(g, 'B'):
            return None
        if not check_possible_connectivity(g, 'W'):
            return None

        # 4. Check if grid is full
        empty_cells = [(r, c) for r in range(n) for c in range(n) if g[r][c] is None]
        if not empty_cells:
            # Final connectivity check
            if check_full_connectivity(g, 'B') and check_full_connectivity(g, 'W'):
                return g
            else:
                return None

        # 5. Branching
        # Heuristic: Pick the first empty cell.
        r, c = empty_cells[0]

        # Try 'B'
        g_b = [row[:] for row in g]
        g_b[r][c] = 'B'
        res_b = backtrack(g_b)
        if res_b:
            return res_b

        # Try 'W'
        g_w = [row[:] for row in g]
        g_w[r][c] = 'W'
        res_w = backtrack(g_w)
        if res_w:
            return res_w

        return None

    result = backtrack(grid)
    if result:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
