OBSERVATION = {'data': [[None, None, None, 3, None], [4, None, None, None, None], [None, 9, None, 6, None], [None, None, None, None, 5], [None, 7, None, None, None]]}

def solve(observation):
    data = observation['data']
    N = len(data)

    # Constants
    WHITE = 0
    BLACK = 1
    UNKNOWN = 2

    # Initialize grid
    # 0: White, 1: Black, 2: Unknown
    grid = [[UNKNOWN for _ in range(N)] for _ in range(N)]
    clues = {}

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                grid[r][c] = WHITE
                clues[(r, c)] = val

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    def stabilize(g):
        # g is a grid (list of lists)
        # Apply rules until no change. Returns g or None if invalid.
        changed = True
        while changed:
            changed = False

            # Rule: Neighbors of Black must be White
            # Also checks for Black adjacency violation
            for r in range(N):
                for c in range(N):
                    if g[r][c] == BLACK:
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == UNKNOWN:
                                g[nr][nc] = WHITE
                                changed = True
                            elif g[nr][nc] == BLACK:
                                return None # Adjacency violation

            # Rule: Clue logic
            for (cr, cc), val in clues.items():
                dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
                view_cells = []
                known_white_count = 1 # The clue cell itself

                # Scan directions
                for dr, dc in dirs:
                    r, c = cr + dr, cc + dc
                    while 0 <= r < N and 0 <= c < N:
                        if g[r][c] == BLACK:
                            break
                        view_cells.append((r, c))
                        if g[r][c] == WHITE:
                            known_white_count += 1
                        r += dr
                        c += dc

                unknown_count = sum(1 for r, c in view_cells if g[r][c] == UNKNOWN)

                # Check bounds
                if known_white_count > val:
                    return None
                if known_white_count + unknown_count < val:
                    return None

                # Deductions
                if known_white_count == val:
                    # All remaining unknowns in view must be Black
                    for r, c in view_cells:
                        if g[r][c] == UNKNOWN:
                            g[r][c] = BLACK
                            changed = True

                if known_white_count + unknown_count == val:
                    # All unknowns in view must be White
                    for r, c in view_cells:
                        if g[r][c] == UNKNOWN:
                            g[r][c] = WHITE
                            changed = True

        return g

    def check_connectivity(g):
        # Check if all known White cells are connected via White/Unknown cells
        white_cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == WHITE:
                    white_cells.append((r, c))

        if not white_cells:
            return True

        start_node = white_cells[0]
        visited = set()
        queue = [start_node]
        visited.add(start_node)

        while queue:
            r, c = queue.pop(0)
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited:
                    if g[nr][nc] != BLACK: # White or Unknown
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        for r, c in white_cells:
            if (r, c) not in visited:
                return False
        return True

    def solve_recursive(g):
        # Stabilize
        g = stabilize(g)
        if g is None:
            return None

        # Check connectivity
        if not check_connectivity(g):
            return None

        # Find unknown
        unknown_pos = None
        for r in range(N):
            for c in range(N):
                if g[r][c] == UNKNOWN:
                    unknown_pos = (r, c)
                    break
            if unknown_pos: break

        if unknown_pos is None:
            # Final validation: Check exact clue counts
            for (cr, cc), val in clues.items():
                count = 1
                dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
                for dr, dc in dirs:
                    r, c = cr + dr, cc + dc
                    while 0 <= r < N and 0 <= c < N:
                        if g[r][c] == BLACK:
                            break
                        count += 1
                        r += dr
                        c += dc
                if count != val:
                    return None
            return g

        r, c = unknown_pos

        # Try Black
        # Check adjacency first (optimization)
        can_be_black = True
        for nr, nc in get_neighbors(r, c):
            if g[nr][nc] == BLACK:
                can_be_black = False
                break

        if can_be_black:
            new_g = [row[:] for row in g]
            new_g[r][c] = BLACK
            res = solve_recursive(new_g)
            if res: return res

        # Try White
        new_g = [row[:] for row in g]
        new_g[r][c] = WHITE
        res = solve_recursive(new_g)
        if res: return res

        return None

    final_grid = solve_recursive(grid)

    if final_grid is None:
        return "No Solution"

    # Format output
    result_grid = []
    for r in range(N):
        row_res = []
        for c in range(N):
            val = final_grid[r][c]
            if val == BLACK:
                row_res.append('B')
            elif (r, c) in clues:
                row_res.append(clues[(r, c)])
            else:
                row_res.append(None)
        result_grid.append(row_res)

    return result_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
