def solve(observation):
    data = observation['data']
    N = len(data)

    # Domains initialization
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Parse constraints
    h_constraints = {} 
    v_constraints = {} 

    for k, v in observation['horizontal'].items():
        try:
            coords = ast.literal_eval(k)
        except:
            continue
        r, c_float = coords
        r = int(r)
        c = int(c_float - 0.5)
        h_constraints[(r, c)] = v

    for k, v in observation['vertical'].items():
        try:
            coords = ast.literal_eval(k)
        except:
            continue
        r_float, c = coords
        r = int(r_float - 0.5)
        c = int(c)
        v_constraints[(r, c)] = v

    # Apply Givens
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                domains[r][c] = {val}

    # Precompute peers for efficiency
    peers = {}
    for r in range(N):
        for c in range(N):
            p = []
            for i in range(N):
                if i != c: p.append((r, i))
                if i != r: p.append((i, c))
            peers[(r, c)] = p

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1. Uniqueness (Row/Col)
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        for pr, pc in peers[(r, c)]:
                            if val in domains[pr][pc]:
                                domains[pr][pc].discard(val)
                                changed = True
                                if not domains[pr][pc]:
                                    return False

            # 2. Inequalities
            # Horizontal
            for (r, c), sym in h_constraints.items():
                d1 = domains[r][c]
                d2 = domains[r][c+1]

                if not d1 or not d2: return False

                min_d2 = min(d2)
                max_d2 = max(d2)

                to_remove_d1 = set()
                for val in d1:
                    if sym == '>':
                        if val <= min_d2: to_remove_d1.add(val)
                    elif sym == '<':
                        if val >= max_d2: to_remove_d1.add(val)

                if to_remove_d1:
                    domains[r][c] -= to_remove_d1
                    if not domains[r][c]: return False
                    changed = True

                d1_curr = domains[r][c]
                d2_curr = domains[r][c+1]
                if not d1_curr or not d2_curr: return False

                min_d1_curr = min(d1_curr)
                max_d1_curr = max(d1_curr)

                to_remove_d2 = set()
                for val in d2_curr:
                    if sym == '>':
                        if val >= max_d1_curr: to_remove_d2.add(val)
                    elif sym == '<':
                        if val <= min_d1_curr: to_remove_d2.add(val)

                if to_remove_d2:
                    domains[r][c+1] -= to_remove_d2
                    if not domains[r][c+1]: return False
                    changed = True

            # Vertical
            for (r, c), sym in v_constraints.items():
                d1 = domains[r][c]
                d2 = domains[r+1][c]

                if not d1 or not d2: return False

                min_d2 = min(d2)
                max_d2 = max(d2)

                to_remove_d1 = set()
                for val in d1:
                    if sym == 'v': # Top > Bottom
                        if val <= min_d2: to_remove_d1.add(val)
                    elif sym == '^': # Top < Bottom
                        if val >= max_d2: to_remove_d1.add(val)

                if to_remove_d1:
                    domains[r][c] -= to_remove_d1
                    if not domains[r][c]: return False
                    changed = True

                d1_curr = domains[r][c]
                d2_curr = domains[r+1][c]
                if not d1_curr or not d2_curr: return False

                min_d1_curr = min(d1_curr)
                max_d1_curr = max(d1_curr)

                to_remove_d2 = set()
                for val in d2_curr:
                    if sym == 'v':
                        if val >= max_d1_curr: to_remove_d2.add(val)
                    elif sym == '^':
                        if val <= min_d1_curr: to_remove_d2.add(val)

                if to_remove_d2:
                    domains[r+1][c] -= to_remove_d2
                    if not domains[r+1][c]: return False
                    changed = True

        return True

    if not propagate(domains):
        return "No Solution"

    def solve_recursive(domains):
        # Check solved
        is_solved = True
        target_r, target_c = -1, -1
        min_len = N + 1

        for r in range(N):
            for c in range(N):
                l = len(domains[r][c])
                if l == 0: return None
                if l > 1:
                    is_solved = False
                    if l < min_len:
                        min_len = l
                        target_r, target_c = r, c

        if is_solved:
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        # MRV heuristic
        if target_r == -1:
             return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        # Try values
        for val in sorted(list(domains[target_r][target_c])):
            # Deep copy domains
            domains_copy = [[set(s) for s in row] for row in domains]
            domains_copy[target_r][target_c] = {val}

            if propagate(domains_copy):
                res = solve_recursive(domains_copy)
                if res:
                    return res

        return None

    res = solve_recursive(domains)
    return res if res else "No Solution"

