def solve(observation):
    data = observation['data']
    h_ineq_raw = observation['horizontal']
    v_ineq_raw = observation['vertical']

    N = len(data)

    # Initialize domains
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]

    # Apply givens
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                val = data[r][c]
                domains[r][c] = {val}

    # Pre-parse constraints
    # Each constraint: (r1, c1, r2, c2, type)
    # type: 'lt' (r1,c1 < r2,c2), 'gt' (r1,c1 > r2,c2)
    constraints = []

    def parse_key(k):
        content = k.strip("()")
        parts = content.split(",")
        return float(parts[0].strip()), float(parts[1].strip())

    for k, sign in h_ineq_raw.items():
        r, c_float = parse_key(k)
        r = int(r)
        c = int(c_float) 
        if sign == '<':
            constraints.append((r, c, r, c+1, 'lt'))
        else:
            constraints.append((r, c, r, c+1, 'gt'))

    for k, sign in v_ineq_raw.items():
        r_float, c = parse_key(k)
        r = int(r_float) 
        c = int(c)
        if sign == '^': # Top < Bottom
            constraints.append((r, c, r+1, c, 'lt'))
        else: # 'v' -> Top > Bottom
            constraints.append((r, c, r+1, c, 'gt'))

    def propagate(doms):
        changed = True
        while changed:
            changed = False

            # 1. Uniqueness
            for r in range(N):
                for c in range(N):
                    if len(doms[r][c]) == 1:
                        val = next(iter(doms[r][c]))
                        for c2 in range(N):
                            if c2 != c and val in doms[r][c2]:
                                doms[r][c2].discard(val)
                                changed = True
            for c in range(N):
                for r in range(N):
                    if len(doms[r][c]) == 1:
                        val = next(iter(doms[r][c]))
                        for r2 in range(N):
                            if r2 != r and val in doms[r2][c]:
                                doms[r2][c].discard(val)
                                changed = True

            # 2. Inequalities
            for (r1, c1, r2, c2, ctype) in constraints:
                d1 = doms[r1][c1]
                d2 = doms[r2][c2]
                if not d1 or not d2: return False 

                if ctype == 'lt':
                    if not d1 or not d2: return False
                    max_d2 = max(d2)
                    min_d1 = min(d1)

                    new_d1 = {x for x in d1 if x < max_d2}
                    new_d2 = {x for x in d2 if x > min_d1}

                    if new_d1 != d1:
                        doms[r1][c1] = new_d1
                        changed = True
                    if new_d2 != d2:
                        doms[r2][c2] = new_d2
                        changed = True
                else: # gt
                    if not d1 or not d2: return False
                    max_d1 = max(d1)
                    min_d2 = min(d2)

                    new_d1 = {x for x in d1 if x > min_d2}
                    new_d2 = {x for x in d2 if x < max_d1}

                    if new_d1 != d1:
                        doms[r1][c1] = new_d1
                        changed = True
                    if new_d2 != d2:
                        doms[r2][c2] = new_d2
                        changed = True

            for r in range(N):
                for c in range(N):
                    if len(doms[r][c]) == 0:
                        return False
        return True

    if not propagate(domains):
        return "No Solution"

    def search_recursive(doms):
        is_complete = True
        for r in range(N):
            for c in range(N):
                if len(doms[r][c]) > 1:
                    is_complete = False
                    break
            if not is_complete: break

        if is_complete:
            return [[next(iter(doms[r][c])) for c in range(N)] for r in range(N)]

        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                l = len(doms[r][c])
                if l > 1 and l < min_len:
                    min_len = l
                    best_cell = (r, c)

        if best_cell is None:
             return [[next(iter(doms[r][c])) for c in range(N)] for r in range(N)]

        r, c = best_cell

        for val in sorted(list(doms[r][c])):
            new_doms = [[set(s) for s in row] for row in doms]
            new_doms[r][c] = {val}

            if propagate(new_doms):
                res = search_recursive(new_doms)
                if res:
                    return res
        return None

    res = search_recursive(domains)
    return res

