    N = len(data)
    # Create a mutable grid
    grid = [list(row) for row in data]

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def get_components(grid, color):
        visited = set()
        components = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] == color and (r, c) not in visited:
                    comp = set()
                    stack = [(r, c)]
                    visited.add((r, c))
                    comp.add((r, c))
                    while stack:
                        curr_r, curr_c = stack.pop()
                        for nr, nc in get_neighbors(curr_r, curr_c):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                comp.add((nr, nc))
                                stack.append((nr, nc))
                    components.append(comp)
        return components

    def is_trapped(grid, component, color):
        # A component is trapped if all its neighbors are either the opposite color or borders.
        opposite = 'W' if color == 'B' else 'B'
        for r, c in component:
            for nr, nc in get_neighbors(r, c):
                val = grid[nr][nc]
                if val is None:
                    return False # Found a path out
                if val == color:
                    continue # Part of component
                # if val == opposite, it's a wall.
        return True

    def propagate(grid):
        changes = []
        changed = True
        while changed:
            changed = False
            for r in range(N - 1):
                for c in range(N - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    vals = [grid[rr][cc] for rr, cc in cells]

                    count_b = vals.count('B')
                    count_w = vals.count('W')
                    count_none = vals.count(None)

                    if count_none == 1:
                        if count_b == 3:
                            idx = vals.index(None)
                            rr, cc = cells[idx]
                            if grid[rr][cc] is None:
                                grid[rr][cc] = 'W'
                                changes.append((rr, cc))
                                changed = True
                        elif count_w == 3:
                            idx = vals.index(None)
                            rr, cc = cells[idx]
                            if grid[rr][cc] is None:
                                grid[rr][cc] = 'B'
                                changes.append((rr, cc))
                                changed = True
        return changes

    def check_2x2_violations(grid):
        for r in range(N - 1):
            for c in range(N - 1):
                cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                vals = [grid[rr][cc] for rr, cc in cells]
                if None not in vals:
                    if all(v == 'B' for v in vals) or all(v == 'W' for v in vals):
                        return False
        return True

    def check_connectivity_pruning(grid):
        b_comps = get_components(grid, 'B')
        if len(b_comps) > 1:
            for comp in b_comps:
                if is_trapped(grid, comp, 'B'):
                    return False

        w_comps = get_components(grid, 'W')
        if len(w_comps) > 1:
            for comp in w_comps:
                if is_trapped(grid, comp, 'W'):
                    return False
        return True

    def undo_changes(grid, changes):
        for r, c in changes:
            grid[r][c] = None

    def backtrack(grid):
        # 1. Propagate constraints (Human-like deduction: 2x2 rule)
        changes = propagate(grid)

        # 2. Check hard violations
        if not check_2x2_violations(grid):
            undo_changes(grid, changes)
            return None
        if not check_connectivity_pruning(grid):
            undo_changes(grid, changes)
            return None

        # 3. Find empty cells
        empty_cells = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    empty_cells.append((r, c))

        if not empty_cells:
            # Grid full, check final connectivity
            b_comps = get_components(grid, 'B')
            w_comps = get_components(grid, 'W')
            if len(b_comps) == 1 and len(w_comps) == 1:
                return [row[:] for row in grid]
            undo_changes(grid, changes)
            return None

        # Heuristic: Pick cell with most filled neighbors (Most Constrained Variable)
        best_cell = None
        max_neighbors = -1
        for r, c in empty_cells:
            filled_count = 0
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] is not None:
                    filled_count += 1
            if filled_count > max_neighbors:
                max_neighbors = filled_count
                best_cell = (r, c)

        r, c = best_cell

        # Try 'B'
        grid[r][c] = 'B'
        res = backtrack(grid)
        if res:
            return res
        grid[r][c] = None

        # Try 'W'
        grid[r][c] = 'W'
        res = backtrack(grid)
        if res:
            return res
        grid[r][c] = None

        # Undo propagation changes for this level to restore state
        undo_changes(grid, changes)
        return None

    result = backtrack(grid)
    if result:
        return result
    return "No Solution"

