        if count != len(w_cells):
            return False

        return True

    def get_next_cell(g):
        # Simple row-major ordering
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    return r, c
        return None

    def backtrack(g):
        # Propagate constraints
        if not propagate(g):
            return None

        # Check potential connectivity
        if not check_potential_connectivity(g):
            return None

        # Check if grid is full
        next_cell = get_next_cell(g)
        if next_cell is None:
            if check_final_connectivity(g):
                return g
            return None

        r, c = next_cell

        # Try 'B'
        g_b = [row[:] for row in g]
