import sys
from collections import deque

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # State: 0=Unknown, 1=White, 2=Black
    state = [[0] * N for _ in range(N)]

    # Sets for tracking numbers in rows/cols to enforce uniqueness
    row_sets = [set() for _ in range(N)]
    col_sets = [set() for _ in range(N)]

    # Queue for constraint propagation
    queue = deque()

    def push(r, c, s):
        queue.append((r, c, s))

    def propagate():
        """
        Propagates constraints based on the current queue.
        Returns False if a conflict is detected.
        """
        while queue:
            r, c, s = queue.popleft()

            # If cell is already decided, check for consistency
            if state[r][c] != 0:
                if state[r][c] != s:
                    return False # Conflict: cell was already set to a different state
                continue

            state[r][c] = s

            if s == 2: # Black
                # Rule: Black cells cannot touch orthogonally.
                # So neighbors must be White.
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if state[nr][nc] == 2:
                            return False # Conflict: Black touches Black
                        if state[nr][nc] == 0:
                            push(nr, nc, 1) # Force neighbor to White

            elif s == 1: # White
                val = data[r][c]
                # Rule: Each unshaded number appears at most once in row/col.
                if val in row_sets[r]:
                    return False # Conflict: Duplicate number in row
                if val in col_sets[c]:
                    return False # Conflict: Duplicate number in col

                row_sets[r].add(val)
                col_sets[c].add(val)

                # Force other occurrences of the same number in this row/col to be Black
                # Row
                for k in range(N):
                    if k != c and data[r][k] == val:
                        if state[r][k] == 1:
                            return False # Conflict: Duplicate White
                        if state[r][k] == 0:
                            push(r, k, 2)
                # Col
                for k in range(N):
                    if k != r and data[k][c] == val:
                        if state[k][c] == 1:
                            return False # Conflict: Duplicate White
                        if state[k][c] == 0:
                            push(k, c, 2)
        return True

    def check_connectivity():
        """
        Pruning check: Ensures all current White cells are connected 
        via a path of non-Black cells (White or Unknown).
        If White cells are separated by Black cells, they can never connect.
        """
        whites = []
        for r in range(N):
            for c in range(N):
                if state[r][c] == 1:
                    whites.append((r, c))

        if not whites:
            return True 

        start_r, start_c = whites[0]
        visited = set()
        stack = [(start_r, start_c)]
        visited.add((start_r, start_c))

        reachable_whites = 0

        while stack:
            r, c = stack.pop()
            if state[r][c] == 1:
                reachable_whites += 1

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if (nr, nc) not in visited:
                        # Can traverse White or Unknown (potential path)
                        if state[nr][nc] != 2: # Not Black
                            visited.add((nr, nc))
                            stack.append((nr, nc))

        # If we can't reach all White cells, they are disconnected by Black cells
        if reachable_whites < len(whites):
            return False
        return True

    def get_unknown_cell():
        """
        Heuristic: Pick an unknown cell.
        Prioritize cells that have duplicates in their row/col to trigger propagation.
        """
        # First pass: look for cells with duplicates
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    val = data[r][c]
                    has_dup = False
                    # Check row
                    for k in range(N):
                        if k != c and data[r][k] == val:
                            has_dup = True
                            break
                    if has_dup: return (r, c)
                    # Check col
                    for k in range(N):
                        if k != r and data[k][c] == val:
                            has_dup = True
                            break
                    if has_dup: return (r, c)

        # Second pass: any unknown cell
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    return (r, c)
        return None

    def solve_recursive():
        # 1. Propagate constraints
        if not propagate():
            return None

        # 2. Check connectivity pruning
        if not check_connectivity():
            return None

        # 3. Check if solved
        unknown = get_unknown_cell()
        if unknown is None:
            # All cells decided. Connectivity check in step 2 ensures validity 
            # (since no Unknowns, path must be White).
            return [row[:] for row in state]

        r, c = unknown

        # Save state for backtracking
        saved_state = [row[:] for row in state]
        saved_row_sets = [s.copy() for s in row_sets]
        saved_col_sets = [s.copy() for s in col_sets]
        # Queue is empty after propagate

        # Branch 1: Try Black (2)
        queue.append((r, c, 2))
        res = solve_recursive()
        if res: return res

        # Restore state
        for i in range(N):
            state[i] = saved_state[i]
        for i in range(N):
            row_sets[i] = saved_row_sets[i]
            col_sets[i] = saved_col_sets[i]
        queue.clear()

        # Branch 2: Try White (1)
        queue.append((r, c, 1))
        res = solve_recursive()
        if res: return res

        return None

    final_state = solve_recursive()

    if final_state is None:
        return "No Solution"

    # Convert state to output mask: 'B' for Black, None for White
    mask = []
    for r in range(N):
        row_mask = []
        for c in range(N):
            if final_state[r][c] == 2:
                row_mask.append('B')
            else:
                row_mask.append(None)
        mask.append(row_mask)
    return mask

