                                    else: # cc == c
                                        step = 1 if cr < r else -1
                                        for k in range(cr + step, r, step):
                                            if state[k][c] == 2:
                                                visible = False
                                                break
                                    if visible:
                                        constraints += 1
                    if constraints > max_constraints:
                        max_constraints = constraints
                        best_cell = (r, c)

        if best_cell is None:
            # Fallback to first unknown
            for r in range(R):
                for c in range(C):
                    if state[r][c] == 0:
                        best_cell = (r, c)
                        break
                if best_cell: break

        if best_cell is None:
            return None # Should be handled by is_solved

        r_pick, c_pick = best_cell

        # Save state
        saved_state = [row[:] for row in state]

        # Try Black
        state[r_pick][c_pick] = 2
        res = backtrack()
        if res is not None:
            return res

        # Restore
        for r in range(R):
            for c in range(C):
                state[r][c] = saved_state[r][c]

        # Try White
        state[r_pick][c_pick] = 1
        res = backtrack()
        if res is not None:
            return res

        return None

    return backtrack()

if __name__ == "__main__":
    print(solve(OBSERVATION))
