import sys
sys.setrecursionlimit(20000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # State: 0 = Unknown, 1 = White, 2 = Black
    state = [[0] * N for _ in range(N)]

    # Precompute duplicates for fast lookup
    # row_dupes[r][val] = [c1, c2, ...]
    row_dupes = [{} for _ in range(N)]
    col_dupes = [{} for _ in range(N)]

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val not in row_dupes[r]:
                row_dupes[r][val] = []
            row_dupes[r][val].append(c)

            if val not in col_dupes[c]:
                col_dupes[c][val] = []
            col_dupes[c][val].append(r)

    # Propagation function with undo support
    # Returns (success, list_of_changes)
    def propagate_with_undo(initial_changes):
        changes = [] 
        queue = list(initial_changes)

        # Apply initial changes
        for r, c, s in queue:
            if state[r][c] != 0:
                if state[r][c] != s:
                    return False, [] # Contradiction: cell already set to different value
            else:
                changes.append((r, c, 0))
                state[r][c] = s

        idx = 0
        while idx < len(queue):
            r, c, s = queue[idx]
            idx += 1

            if s == 2: # Black
                # Neighbors must be White
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if state[nr][nc] == 2:
                            return False, changes # Adjacent black cells
                        if state[nr][nc] == 0:
                            changes.append((nr, nc, 0))
                            state[nr][nc] = 1
                            queue.append((nr, nc, 1))

            elif s == 1: # White
                val = data[r][c]

                # Force other duplicates in row to Black
                if val in row_dupes[r]:
                    for c2 in row_dupes[r][val]:
                        if c2 != c:
                            if state[r][c2] == 1:
                                return False, changes # Duplicate white in row
                            if state[r][c2] == 0:
                                changes.append((r, c2, 0))
                                state[r][c2] = 2
                                queue.append((r, c2, 2))

                # Force other duplicates in col to Black
                if val in col_dupes[c]:
                    for r2 in col_dupes[c][val]:
                        if r2 != r:
                            if state[r2][c] == 1:
                                return False, changes # Duplicate white in col
                            if state[r2][c] == 0:
                                changes.append((r2, c, 0))
                                state[r2][c] = 2
                                queue.append((r2, c, 2))

        return True, changes

    def undo(changes):
        for r, c, old_state in reversed(changes):
            state[r][c] = old_state

    # Heuristic to pick the next cell to decide
    def get_best_cell():
        best_cell = None
        max_score = -1

        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    val = data[r][c]
                    # Score based on number of duplicates (higher score = more constrained)
                    row_count = len(row_dupes[r].get(val, []))
                    col_count = len(col_dupes[c].get(val, []))
                    score = row_count + col_count

                    # Check if forced to be White (neighbor is Black)
                    is_forced_white = False
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N:
                            if state[nr][nc] == 2:
                                is_forced_white = True
                                break

                    if is_forced_white:
                        return r, c # Priority to forced moves

                    if score > max_score:
                        max_score = score
                        best_cell = (r, c)

        return best_cell

    # Check if all current White cells are potentially connected (via White or Unknown)
    def check_potential_connectivity():
        total_white = 0
        start_r, start_c = -1, -1
        for r in range(N):
            for c in range(N):
                if state[r][c] == 1:
                    total_white += 1
                    if start_r == -1:
                        start_r, start_c = r, c

        if total_white == 0:
            return True

        reachable_white = 0
        q = [(start_r, start_c)]
        vis = set()
        vis.add((start_r, start_c))

        while q:
            cr, cc = q.pop(0)
            if state[cr][cc] == 1:
                reachable_white += 1

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if (nr, nc) not in vis:
                        # Can traverse through White or Unknown
                        if state[nr][nc] != 2: 
                            vis.add((nr, nc))
                            q.append((nr, nc))

        return reachable_white == total_white

    def solve_recursive():
        # Pruning: Check connectivity
        if not check_potential_connectivity():
            return False

        cell = get_best_cell()
        if cell is None:
            # All cells filled. Check strict connectivity.
            total_white = 0
            start_r, start_c = -1, -1
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 1:
                        total_white += 1
                        if start_r == -1:
                            start_r, start_c = r, c

            if total_white == 0:
                return False # Must have at least one white cell

            q = [(start_r, start_c)]
            vis = set()
            vis.add((start_r, start_c))
            count = 0
            while q:
                cr, cc = q.pop(0)
                count += 1
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if state[nr][nc] == 1 and (nr, nc) not in vis:
                            vis.add((nr, nc))
                            q.append((nr, nc))

            return count == total_white

        r, c = cell
        val = data[r][c]

        # Determine if White is possible
        can_be_white = True
        # Check if duplicate exists in row/col as White
        for c2 in row_dupes[r].get(val, []):
            if c2 != c and state[r][c2] == 1:
                can_be_white = False
                break
        if can_be_white:
            for r2 in col_dupes[c].get(val, []):
                if r2 != r and state[r2][c] == 1:
                    can_be_white = False
                    break

        # Determine if Black is possible
        can_be_black = True
        # Check neighbors
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                if state[nr][nc] == 2:
                    can_be_black = False
                    break

        # Try White first (heuristic: keep cells white to maintain connectivity)
        if can_be_white:
            ok, changes = propagate_with_undo([(r, c, 1)])
            if ok:
                if solve_recursive():
                    return True
            undo(changes)

        if can_be_black:
            ok, changes = propagate_with_undo([(r, c, 2)])
            if ok:
                if solve_recursive():
                    return True
            undo(changes)

        return False

    if solve_recursive():
        result = []
        for r in range(N):
            row_res = []
            for c in range(N):
                if state[r][c] == 2:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
