OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, 5, None], [None, None, None, None, 1], [None, None, None, None, None], [1, None, 3, None, None]]}

import sys

# Constants
UNKNOWN = 0
WHITE = 1
BLACK = 2

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    grid = [[UNKNOWN for _ in range(C)] for _ in range(R)]
    numbers = {}

    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val is not None:
                numbers[(r, c)] = val
                grid[r][c] = WHITE

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                yield nr, nc

    def get_components(g):
        visited = set()
        comps = []
        for r in range(R):
            for c in range(C):
                if g[r][c] == WHITE and (r, c) not in visited:
                    comp_cells = []
                    stack = [(r, c)]
                    visited.add((r, c))
                    num_pos = None
                    num_val = 0
                    while stack:
                        curr = stack.pop()
                        comp_cells.append(curr)
                        cr, cc = curr
                        if (cr, cc) in numbers:
                            if num_pos is not None:
                                return None 
                            num_pos = (cr, cc)
                            num_val = numbers[(cr, cc)]

                        for nr, nc in get_neighbors(cr, cc):
                            if g[nr][nc] == WHITE and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
                    comps.append({'cells': comp_cells, 'num_pos': num_pos, 'num_val': num_val})
        return comps

    def apply_logic(g):
        changed = True
        curr = [row[:] for row in g]

        while changed:
            changed = False

            # 1. 2x2 Black -> 4th White
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                    vals = [curr[cr][cc] for cr, cc in cells]
                    if vals.count(BLACK) == 3 and vals.count(UNKNOWN) == 1:
                        idx = vals.index(UNKNOWN)
                        ur, uc = cells[idx]
                        curr[ur][uc] = WHITE
                        changed = True

            # 2. Island Full -> Neighbors Black
            comps = get_components(curr)
            if comps is None: return None 

            for comp in comps:
                if comp['num_pos'] is not None:
                    if len(comp['cells']) == comp['num_val']:
                        for r, c in comp['cells']:
                            for nr, nc in get_neighbors(r, c):
                                if curr[nr][nc] == UNKNOWN:
                                    curr[nr][nc] = BLACK
                                    changed = True
                                    # Check 2x2 black immediately
                                    for dr in [-1, 0]:
                                        for dc in [-1, 0]:
                                            rr, cc = nr + dr, nc + dc
                                            if 0 <= rr < R - 1 and 0 <= cc < C - 1:
                                                sq_cells = [(rr, cc), (rr+1, cc), (rr, cc+1), (rr+1, cc+1)]
                                                if all(curr[sr][sc] == BLACK for sr, sc in sq_cells):
                                                    return None

            # 3. Reachability Pruning
            for (nr, nc), val in numbers.items():
                count = 0
                stack = [(nr, nc)]
                vis = set([(nr, nc)])
                while stack:
                    curr_cell = stack.pop()
                    count += 1
                    cr, cc = curr_cell
                    for ncr, ncc in get_neighbors(cr, cc):
                        if curr[ncr][ncc] != BLACK and (ncr, ncc) not in vis:
                            vis.add((ncr, ncc))
                            stack.append((ncr, ncc))
                if count < val:
                    return None

        return curr

    def is_valid_partial(g):
        # Check 2x2 Black
        for r in range(R - 1):
            for c in range(C - 1):
                if g[r][c] == BLACK and g[r+1][c] == BLACK and \
                   g[r][c+1] == BLACK and g[r+1][c+1] == BLACK:
                    return False

        comps = get_components(g)
        if comps is None: return False

        for comp in comps:
            if comp['num_pos'] is not None:
                if len(comp['cells']) > comp['num_val']:
                    return False
            else:
                surrounded = True
                for r, c in comp['cells']:
                    for nr, nc in get_neighbors(r, c):
                        if g[nr][nc] == UNKNOWN:
                            surrounded = False
                            break
                    if not surrounded: break
                if surrounded:
                    return False 
        return True

    def solve_recursive(g):
        g = apply_logic(g)
        if g is None:
            return None

        if not is_valid_partial(g):
            return None

        unknown_pos = None
        for r in range(R):
            for c in range(C):
                if g[r][c] == UNKNOWN:
                    unknown_pos = (r, c)
                    break
            if unknown_pos: break

        if unknown_pos is None:
            # Final checks
            black_cells = []
            for r in range(R):
                for c in range(C):
                    if g[r][c] == BLACK:
                        black_cells.append((r, c))

            if len(black_cells) > 0:
                start = black_cells[0]
                stack = [start]
                visited = set([start])
                count = 0
                while stack:
                    curr = stack.pop()
                    count += 1
                    cr, cc = curr
                    for nr, nc in get_neighbors(cr, cc):
                        if g[nr][nc] == BLACK and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))
                if count != len(black_cells):
                    return None

            comps = get_components(g)
            if comps is None: return None
            for comp in comps:
                if comp['num_pos'] is None: return None
                if len(comp['cells']) != comp['num_val']: return None

            return g

        r, c = unknown_pos

        # Try WHITE
        g_white = [row[:] for row in g]
        g_white[r][c] = WHITE
        res = solve_recursive(g_white)
        if res: return res

        # Try BLACK
        g_black = [row[:] for row in g]
        g_black[r][c] = BLACK
        res = solve_recursive(g_black)
        if res: return res

        return None

    final_grid = solve_recursive(grid)

    if final_grid:
        result = []
        for r in range(R):
            row_res = []
            for c in range(C):
                if final_grid[r][c] == BLACK:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
