OBSERVATION = {'data': [[None, 1, None, None, 3, None, None], [None, None, 1, None, 4, None, 2], [None, 3, 2, 2, None, None, None], [2, None, 1, None, None, None, None], [None, None, None, None, 1, None, 0], [None, None, None, 1, None, None, None], [2, None, 2, None, None, None, 1]]}

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    # Precompute neighbors for efficiency
    neighbors_map = {}
    for r in range(rows):
        for c in range(cols):
            neighs = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighs.append((nr, nc))
            neighbors_map[(r, c)] = neighs

    # State: 0=Unknown, 1=Mine, -1=Safe
    # Initialize state: cells with clues are Safe (-1)
    state = [[0 for _ in range(cols)] for _ in range(rows)]
    clues = {}

    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is not None:
                state[r][c] = -1
                clues[(r, c)] = val

    # Propagation function: applies basic human logic rules (Constraint Propagation)
    # Returns None if a contradiction is found, otherwise returns the updated state
    def propagate(current_state):
        changed = True
        while changed:
            changed = False
            for (r, c), val in clues.items():
                neighbors = neighbors_map[(r, c)]
                mines_count = 0
                unknown_neighbors = []

                for nr, nc in neighbors:
                    s = current_state[nr][nc]
                    if s == 1:
                        mines_count += 1
                    elif s == 0:
                        unknown_neighbors.append((nr, nc))

                # Rule 1: If mines found equals clue value, remaining unknowns are Safe
                if mines_count == val:
                    for nr, nc in unknown_neighbors:
                        if current_state[nr][nc] == 0:
                            current_state[nr][nc] = -1
                            changed = True
                        elif current_state[nr][nc] == 1:
                            return None # Contradiction: Cell was Mine, now must be Safe

                # Rule 2: If mines found + unknowns equals clue value, all unknowns are Mines
                if mines_count + len(unknown_neighbors) == val:
                    for nr, nc in unknown_neighbors:
                        if current_state[nr][nc] == 0:
                            current_state[nr][nc] = 1
                            changed = True
                        elif current_state[nr][nc] == -1:
                            return None # Contradiction: Cell was Safe, now must be Mine
        return current_state

    # Consistency check: ensures no clue is violated (Forward Checking)
    def is_consistent(current_state):
        for (r, c), val in clues.items():
            neighbors = neighbors_map[(r, c)]
            mines_count = 0
            unknown_count = 0
            for nr, nc in neighbors:
                s = current_state[nr][nc]
                if s == 1:
                    mines_count += 1
                elif s == 0:
                    unknown_count += 1

            # Cannot have more mines than clue
            if mines_count > val:
                return False
            # Cannot have fewer mines than clue even if all unknowns are mines
            if mines_count + unknown_count < val:
                return False
        return True

    # Recursive solver with backtracking
    def solve_recursive(current_state):
        # Apply logic propagation first to reduce search space
        current_state = propagate(current_state)

        # If propagation found a contradiction, backtrack
        if current_state is None:
            return None

        # If state is inconsistent, backtrack
        if not is_consistent(current_state):
            return None

        # Find all unknown cells
        unknowns = []
        for r in range(rows):
            for c in range(cols):
                if current_state[r][c] == 0:
                    unknowns.append((r, c))

        # If no unknowns, we found a solution
        if not unknowns:
            return current_state

        # Heuristic: Pick the unknown cell adjacent to the most clues (Most Constrained Variable)
        # This mimics human strategy of focusing on areas with the most information.
        best_cell = None
        max_score = -1

        for r, c in unknowns:
            score = 0
            for nr, nc in neighbors_map[(r, c)]:
                if (nr, nc) in clues:
                    score += 1
            if score > max_score:
                max_score = score
                best_cell = (r, c)

        # Fallback if no clues nearby
        if best_cell is None:
            best_cell = unknowns[0]

        r, c = best_cell

        # Branch 1: Assume cell is a Mine
        # Create a copy of the state for this branch to allow backtracking
        state_mine = [row[:] for row in current_state]
        state_mine[r][c] = 1
        res = solve_recursive(state_mine)
        if res:
            return res

        # Branch 2: Assume cell is Safe
        state_safe = [row[:] for row in current_state]
        state_safe[r][c] = -1
        res = solve_recursive(state_safe)
        if res:
            return res

        # If both branches fail, return None (backtrack)
        return None

    # Initial propagation on the starting state
    state = propagate(state)
    if state is None or not is_consistent(state):
        return "No Solution"

    final_state = solve_recursive(state)

    if final_state is None:
        return "No Solution"

    # Format the output grid
    res_grid = [[None for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if final_state[r][c] == 1:
                res_grid[r][c] = 'F'
    return res_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
