                            conflict = False
                            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                                nr, nc = ur+dr, uc+dc
                                if 0 <= nr < R and 0 <= nc < C:
                                    if g[nr][nc] == 1 and o[nr][nc] is not None:
                                        if owner_found is None:
                                            owner_found = o[nr][nc]
                                        elif owner_found != o[nr][nc]:
                                            conflict = True
                            if conflict:
                                return False
                            if owner_found:
                                o[ur][uc] = owner_found

            # Rule: Separation (White neighbors with diff owners)
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 1 and o[r][c] is not None:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if g[nr][nc] == 1 and o[nr][nc] is not None:
                                    if o[r][c] != o[nr][nc]:
                                        return False

            # Rule: Island Size Limit & Reachability
            for (r, c), val in numbers:
                cells = get_island_cells(g, o, (r, c))
                current_size = len(cells)
                if current_size > val:
                    return False

                # Reachability check
                reachable = set(cells)
                queue = list(cells)
                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if (nr, nc) not in reachable:
                                if g[nr][nc] == 0 or (g[nr][nc] == 1 and o[nr][nc] is None):
                                    reachable.add((nr, nc))
                                    queue.append((nr, nc))

                if len(reachable) < val:
                    return False

                if current_size == val:
                    for cr, cc in cells:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if g[nr][nc] == 0:
                                    g[nr][nc] = 2
                                    changed = True
                                elif g[nr][nc] == 1:
                                    if o[nr][nc] != (r, c):
                                        return False

            # Rule: Orphan White Check
            visited_white = set()
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 1 and (r, c) not in visited_white:
                        comp_cells = []
                        queue = [(r, c)]
                        visited_white.add((r, c))
                        has_number = False
                        number_owners = set()
                        while queue:
                            cr, cc = queue.pop(0)
                            comp_cells.append((cr, cc))
                            if o[cr][cc] is not None:
                                has_number = True
                                number_owners.add(o[cr][cc])
                            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                                nr, nc = cr+dr, cc+dc
                                if 0 <= nr < R and 0 <= nc < C:
                                    if (nr, nc) not in visited_white and g[nr][nc] == 1:
                                        visited_white.add((nr, nc))
                                        queue.append((nr, nc))

                        if len(number_owners) > 1:
                            return False

                        if not has_number:
                            surrounded = True
                            for cr, cc in comp_cells:
                                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                                    nr, nc = cr+dr, cc+dc
                                    if 0 <= nr < R and 0 <= nc < C:
                                        if g[nr][nc] == 0:
                                            surrounded = False
                                            break
                                if not surrounded: break
                            if surrounded:
                                return False

        return True

    def check_final(g, o):
        # Black connectivity
        black_cells = []
        for r in range(R):
            for c in range(C):
                if g[r][c] == 2:
                    black_cells.append((r, c))

        if black_cells:
            start = black_cells[0]
            q = [start]
            visited = {start}
            while q:
                cr, cc = q.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < R and 0 <= nc < C:
                        if (nr, nc) not in visited and g[nr][nc] == 2:
                            visited.add((nr, nc))
                            q.append((nr, nc))
            if len(visited) != len(black_cells):
                return False

        # Island sizes
        for (r, c), val in numbers:
            cells = get_island_cells(g, o, (r, c))
            if len(cells) != val:
                return False

        # All white cells must have an owner
        for r in range(R):
            for c in range(C):
                if g[r][c] == 1:
                    if o[r][c] is None:
                        return False

        return True

    def get_solution(g):
        res = []
        for r in range(R):
            row = []
            for c in range(C):
                if g[r][c] == 2:
                    row.append('B')
                else:
                    row.append(None)
            res.append(row)
        return res

    def search(g, o):
        if not propagate(g, o):
            return None

        unknown_pos = None
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    unknown_pos = (r, c)
                    break
            if unknown_pos: break

        if unknown_pos is None:
            if check_final(g, o):
                return get_solution(g)
            else:
                return None

        r, c = unknown_pos

        # Try White
        can_white = True
        neighbor_owners = set()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C:
                if g[nr][nc] == 1 and o[nr][nc] is not None:
                    neighbor_owners.add(o[nr][nc])

        if len(neighbor_owners) > 1:
            can_white = False

        if can_white:
            g_w = copy.deepcopy(g)
            o_w = copy.deepcopy(o)
            g_w[r][c] = 1
            if len(neighbor_owners) == 1:
                o_w[r][c] = list(neighbor_owners)[0]

            res = search(g_w, o_w)
            if res: return res

        # Try Black
        g_b = copy.deepcopy(g)
        o_b = copy.deepcopy(o)
        g_b[r][c] = 2

        res = search(g_b, o_b)
        if res: return res

        return None

    return search(grid, owners)

if __name__ == "__main__":
    print(solve(OBSERVATION))
