    'col_water_counts': [5, 4, 3, 3, 4, 3]
}

def solve(observation):
    region_grid = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']

    rows = len(region_grid)
    cols = len(region_grid[0])

    # Identify unique regions and their cells
    regions = {}
    for r in range(rows):
        for c in range(cols):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_ids = sorted(regions.keys())
    num_regions = len(region_ids)

    # For each region, the water level can be from 0 to rows (rows means empty)
    # If level is L, then all cells (r, c) in region with r >= L are water.
    # Possible levels: 0, 1, ..., rows. (rows means no water)

    # Precompute cell contributions for each region and each level
    # region_contrib[rid][level] = list of (r, c) that become water
    region_contrib = {}
    for rid in region_ids:
        region_contrib[rid] = {}
        cells = regions[rid]
        for level in range(rows + 1):
            water_cells = []
            for r, c in cells:
                if r >= level:
                    water_cells.append((r, c))
            region_contrib[rid][level] = water_cells

    # Current state
    # region_levels: dict rid -> level
    region_levels = {}

    # Current row/col counts
    current_row_counts = [0] * rows
    current_col_counts = [0] * cols

    def is_valid_partial():
        for r in range(rows):
            if current_row_counts[r] > row_targets[r]:
                return False
        for c in range(cols):
            if current_col_counts[c] > col_targets[c]:
                return False
        return True

    def is_valid_complete():
        for r in range(rows):
            if current_row_counts[r] != row_targets[r]:
                return False
        for c in range(cols):
            if current_col_counts[c] != col_targets[c]:
                return False
        return True

    def backtrack(idx):
        if idx == num_regions:
            return is_valid_complete()

        rid = region_ids[idx]

        # Try all possible levels for this region
        # Optimization: try levels that are more likely to fit?
        # Just iterate 0 to rows
        for level in range(rows + 1):
            # Apply level
            cells_to_add = region_contrib[rid][level]

            # Update counts
            for r, c in cells_to_add:
                current_row_counts[r] += 1
                current_col_counts[c] += 1

            if is_valid_partial():
                region_levels[rid] = level
                if backtrack(idx + 1):
                    return True

            # Backtrack counts
            for r, c in cells_to_add:
                current_row_counts[r] -= 1
                current_col_counts[c] -= 1

            if rid in region_levels:
                del region_levels[rid]

        return False

    if backtrack(0):
        # Construct solution grid
        sol_grid = [[None for _ in range(cols)] for _ in range(rows)]
        for rid, level in region_levels.items():
            cells = region_contrib[rid][level]
            for r, c in cells:
                sol_grid[r][c] = 'W'
        return sol_grid
    else:
        return "No Solution"

