import sys
import copy

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Identify numbers and their positions
    numbers = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                numbers[(r, c)] = data[r][c]

    # State representation
    # cell_status[r][c]: 0=Unknown, 1=White, 2=Black
    cell_status = [[0]*C for _ in range(R)]
    # cell_owner[r][c]: None or (r_num, c_num) indicating which island this white cell belongs to
    cell_owner = [[None]*C for _ in range(R)]
    # possible_owners[r][c]: set of (r_num, c_num) that this cell could belong to if it is White
    possible_owners = [[set(numbers.keys()) for _ in range(C)] for _ in range(R)]

    # Initialize numbered cells
    for (r, c), val in numbers.items():
        cell_status[r][c] = 1 # White
        cell_owner[r][c] = (r, c)
        possible_owners[r][c] = {(r, c)}

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                yield nr, nc

    def propagate():
        """
        Applies logical deduction rules repeatedly until no changes occur or a contradiction is found.
        Returns:
            False: Contradiction found.
            'solved': Puzzle is completely solved and valid.
            True: Consistent state, but not fully solved.
        """
        changed = True
        while changed:
            changed = False

            # Rule 1: Distance Pruning
            # A cell cannot belong to an island if the Manhattan distance is >= island size.
            for (r_num, c_num), val in numbers.items():
                for r in range(R):
                    for c in range(C):
                        if cell_status[r][c] == 2: continue # Skip black cells
                        dist = abs(r - r_num) + abs(c - c_num)
                        if dist >= val:
                            if (r_num, c_num) in possible_owners[r][c]:
                                possible_owners[r][c].discard((r_num, c_num))
                                changed = True

            # Rule 2: Empty possible owners implies Black
            for r in range(R):
                for c in range(C):
                    if cell_status[r][c] == 0: # Unknown
                        if not possible_owners[r][c]:
                            cell_status[r][c] = 2 # Must be Black
                            changed = True
                    elif cell_status[r][c] == 1: # White
                        if not possible_owners[r][c]:
                            return False # Contradiction: White cell has no valid owner
                        # If owner is not determined but only one possibility remains
                        if cell_owner[r][c] is None and len(possible_owners[r][c]) == 1:
                            cell_owner[r][c] = list(possible_owners[r][c])[0]
                            changed = True

            # Rule 3: Island Size Check
            # Group white cells by owner
            island_cells = {k: [] for k in numbers}
            for r in range(R):
                for c in range(C):
                    if cell_status[r][c] == 1 and cell_owner[r][c]:
                        island_cells[cell_owner[r][c]].append((r, c))

            for (r_num, c_num), val in numbers.items():
                cells = island_cells[(r_num, c_num)]
                if len(cells) > val:
                    return False # Island too big
                if len(cells) == val:
                    # Island is full. All orthogonal neighbors must be Black.
                    for (r, c) in cells:
                        for nr, nc in get_neighbors(r, c):
                            if cell_status[nr][nc] == 0:
                                cell_status[nr][nc] = 2
                                changed = True
                            elif cell_status[nr][nc] == 1:
                                # Neighbor is White. It must belong to this island.
                                # If it belongs to another, contradiction.
                                if cell_owner[nr][nc] is not None and cell_owner[nr][nc] != (r_num, c_num):
                                    return False
                                # If it's not in the list of cells for this island, it's a contradiction
                                # (because the island is full, so no new white cells can touch it)
                                if (nr, nc) not in cells:
                                    return False

            # Rule 4: 2x2 Black Block Check
            for r in range(R - 1):
                for c in range(C - 1):
                    blacks = 0
                    unknowns = 0
                    coords = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    for rr, cc in coords:
                        if cell_status[rr][cc] == 2: blacks += 1
                        elif cell_status[rr][cc] == 0: unknowns += 1

                    if blacks == 4: return False # 2x2 black block formed
                    if blacks == 3 and unknowns == 1:
                        # The unknown cell must be White to prevent 2x2 black
                        for rr, cc in coords:
                            if cell_status[rr][cc] == 0:
                                cell_status[rr][cc] = 1
                                changed = True

            # Rule 5: Owner Propagation (Island Separation)
            # If a cell is White (Owner O), its neighbors cannot be White (Owner O') where O' != O.
            for r in range(R):
                for c in range(C):
                    if cell_status[r][c] == 1 and cell_owner[r][c]:
                        owner = cell_owner[r][c]
                        for nr, nc in get_neighbors(r, c):
                            if cell_status[nr][nc] == 1:
                                if cell_owner[nr][nc] is None:
                                    # Neighbor is White but unowned; must be same owner
                                    cell_owner[nr][nc] = owner
                                    possible_owners[nr][nc] = {owner}
                                    changed = True
                                elif cell_owner[nr][nc] != owner:
                                    return False # Two different islands touching
                            elif cell_status[nr][nc] == 0:
                                # Neighbor is Unknown. If it becomes White, it MUST be Owner O.
                                # So remove all other owners from possibilities.
                                old_len = len(possible_owners[nr][nc])
                                possible_owners[nr][nc] &= {owner}
                                if len(possible_owners[nr][nc]) < old_len:
                                    changed = True
                                if not possible_owners[nr][nc]:
                                    # No valid owners left -> Must be Black
                                    cell_status[nr][nc] = 2
                                    changed = True

            # Rule 6: Closed White Regions (Pools)
            # If a region of White cells is surrounded by Black/Edges, it must be a valid island.
            visited = [[False]*C for _ in range(R)]
            for r in range(R):
                for c in range(C):
                    if cell_status[r][c] == 1 and not visited[r][c]:
                        component = []
                        queue = [(r, c)]
                        visited[r][c] = True
                        is_closed = True # Assume closed until we find an Unknown boundary

                        while queue:
                            curr_r, curr_c = queue.pop(0)
                            component.append((curr_r, curr_c))
                            for nr, nc in get_neighbors(curr_r, curr_c):
                                if cell_status[nr][nc] == 0:
                                    is_closed = False # Touches unknown, so not closed yet
                                elif cell_status[nr][nc] == 1:
                                    if not visited[nr][nc]:
                                        visited[nr][nc] = True
                                        queue.append((nr, nc))

                        if is_closed:
                            # Check validity of this closed pool
                            nums_in_comp = [pos for pos in component if pos in numbers]
                            if len(nums_in_comp) == 0: return False # Pool with no number
                            if len(nums_in_comp) > 1: return False # Pool with >1 number
                            num_pos = nums_in_comp[0]
                            if len(component) != numbers[num_pos]:
                                return False # Pool size mismatch

        # Check if fully solved
        unknown_count = sum(row.count(0) for row in cell_status)
        if unknown_count == 0:
            # Final Check: Black Connectivity
            black_cells = [(r, c) for r in range(R) for c in range(C) if cell_status[r][c] == 2]
            if black_cells:
                start = black_cells[0]
                q = [start]
                vis = {start}
                while q:
                    curr = q.pop(0)
                    for nr, nc in get_neighbors(*curr):
                        if cell_status[nr][nc] == 2 and (nr, nc) not in vis:
                            vis.add((nr, nc))
                            q.append((nr, nc))
                if len(vis) != len(black_cells):
                    return False # Black cells are not connected
            return 'solved'
        return True

    def solve_recursive():
        res = propagate()
        if res == False: return False
        if res == 'solved': return True

        # Save state for backtracking
        s_status = copy.deepcopy(cell_status)
        s_owner = copy.deepcopy(cell_owner)
        s_poss = copy.deepcopy(possible_owners)

        # Find the best cell to guess (heuristic: fewest options)
        r_guess, c_guess = -1, -1
        min_opts = 100

        for r in range(R):
            for c in range(C):
                if cell_status[r][c] == 0:
                    # Options: Black (1) + number of possible owners
                    opts = len(possible_owners[r][c]) + 1 
                    if opts < min_opts:
                        min_opts = opts
                        r_guess, c_guess = r, c

        if r_guess == -1: return False # Should have been caught by 'solved'

        # Branch 1: Try Black
        cell_status[r_guess][c_guess] = 2
        if solve_recursive(): return True

        # Restore state
        for r in range(R):
            for c in range(C):
                cell_status[r][c] = s_status[r][c]
                cell_owner[r][c] = s_owner[r][c]
                possible_owners[r][c] = s_poss[r][c]

        # Branch 2: Try White for each possible owner
        for owner in list(s_poss[r_guess][c_guess]):
            # Restore state (in case previous iteration modified it, though we restore at end of loop)
            # Actually, we need to restore from s_status before each try
            for r in range(R):
                for c in range(C):
                    cell_status[r][c] = s_status[r][c]
                    cell_owner[r][c] = s_owner[r][c]
                    possible_owners[r][c] = s_poss[r][c]

            cell_status[r_guess][c_guess] = 1
            cell_owner[r_guess][c_guess] = owner
            possible_owners[r_guess][c_guess] = {owner}

            if solve_recursive(): return True

        return False

    if solve_recursive():
        result = []
        for r in range(R):
            row_res = []
            for c in range(C):
                if cell_status[r][c] == 2:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return result
    return "No Solution"

