def solve(observation):
    """
    Solves the Consecutive Neighbours Latin Square puzzle.

    Rules:
    1. Grid is N x N.
    2. Each row and column contains numbers 1..N exactly once.
    3. If a dot exists between two adjacent cells, their values are consecutive (|a-b|=1).
    4. If no dot exists between two adjacent cells, their values are NOT consecutive (|a-b|!=1).
    """
    data = observation['data']
    adjacent_dots = set(tuple(d) for d in observation['adjacent'])

    N = len(data)

    # Precompute constraints for faster access
    # has_dot[r][c][direction] where direction is 0 (right) or 1 (down)
    # We only store dots that exist. Absence implies not consecutive.

    # Helper to check if a dot exists between (r1, c1) and (r2, c2)
    def has_dot(r1, c1, r2, c2):
        if r1 == r2: # Horizontal
            mid_c = c1 + 0.5 if c2 > c1 else c2 + 0.5
            return (float(r1), float(mid_c)) in adjacent_dots
        elif c1 == c2: # Vertical
            mid_r = r1 + 0.5 if r2 > r1 else r2 + 0.5
            return (float(mid_r), float(c1)) in adjacent_dots
        return False

    # Initialize grid with 0s (empty)
    grid = [[0]*N for _ in range(N)]

    # Fill initial clues
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]

    # Backtracking solver with constraint propagation
    # We will use MRV (Minimum Remaining Values) heuristic

    def get_candidates(r, c):
        if grid[r][c] != 0:
            return [grid[r][c]]

        candidates = set(range(1, N+1))

        # Row constraint
        for k in range(N):
            if grid[r][k] != 0:
                candidates.discard(grid[r][k])

        # Col constraint
        for k in range(N):
            if grid[k][c] != 0:
                candidates.discard(grid[k][c])

        # Neighbor constraints
        neighbors = []
        if r > 0: neighbors.append((r-1, c))
        if r < N-1: neighbors.append((r+1, c))
        if c > 0: neighbors.append((r, c-1))
        if c < N-1: neighbors.append((r, c+1))

        for nr, nc in neighbors:
            val = grid[nr][nc]
            if val != 0:
                if has_dot(r, c, nr, nc):
                    # Must be consecutive
                    new_cands = set()
                    for cand in candidates:
                        if abs(cand - val) == 1:
                            new_cands.add(cand)
                    candidates = new_cands
                else:
                    # Must NOT be consecutive
                    new_cands = set()
                    for cand in candidates:
                        if abs(cand - val) != 1:
                            new_cands.add(cand)
                    candidates = new_cands

        return list(candidates)

    def is_valid(r, c, num):
        # Check row
        for k in range(N):
            if k != c and grid[r][k] == num:
                return False
        # Check col
        for k in range(N):
            if k != r and grid[k][c] == num:
                return False

        # Check neighbors
        neighbors = []
        if r > 0: neighbors.append((r-1, c))
        if r < N-1: neighbors.append((r+1, c))
        if c > 0: neighbors.append((r, c-1))
        if c < N-1: neighbors.append((r, c+1))

        for nr, nc in neighbors:
            val = grid[nr][nc]
            if val != 0:
                if has_dot(r, c, nr, nc):
                    if abs(num - val) != 1:
                        return False
                else:
                    if abs(num - val) == 1:
                        return False

        return True

    def solve_recursive():
        # Find empty cell with fewest candidates (MRV)
        min_cands = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    cands = get_candidates(r, c)
                    if len(cands) == 0:
                        return False # Dead end
                    if len(cands) < min_cands:
                        min_cands = len(cands)
                        best_cell = (r, c)
                        if min_cands == 1:
                            break
            if min_cands == 1:
                break

        if best_cell is None:
            return True # Solved

        r, c = best_cell
        cands = get_candidates(r, c)

        for num in cands:
            if is_valid(r, c, num):
                grid[r][c] = num
                if solve_recursive():
                    return True
                grid[r][c] = 0

        return False

    if solve_recursive():
        return grid
    else:
        return "No Solution"

