import sys

# Increase recursion depth to handle deep search if necessary
sys.setrecursionlimit(3000)

def solve(observation):
    grid = observation['data']
    N = len(grid)

    # Identify unique region IDs
    region_ids = set()
    for r in range(N):
        for c in range(N):
            region_ids.add(grid[r][c])
    region_ids = sorted(list(region_ids))

    # Precompute region statistics for pruning
    # cells_per_region_per_row[rid][r] = count of cells of region rid in row r
    cells_per_region_per_row = {rid: [0] * N for rid in region_ids}

    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            cells_per_region_per_row[rid][r] += 1

    # Precompute remaining cells for each region from row r onwards (inclusive)
    # remaining_cells_from_row[rid][r] = sum(cells in rows r..N-1)
    remaining_cells_from_row = {rid: [0] * (N + 1) for rid in region_ids}
    for rid in region_ids:
        s = 0
        for r in range(N - 1, -1, -1):
            s += cells_per_region_per_row[rid][r]
            remaining_cells_from_row[rid][r] = s
        remaining_cells_from_row[rid][N] = 0

    # State variables
    col_counts = [0] * N
    region_counts = {rid: 0 for rid in region_ids}
    solution = [None] * N

    # Precompute valid star pairs for each row to speed up iteration
    # A pair (c1, c2) is valid if c2 > c1 + 1 (stars cannot touch horizontally)
    row_pairs = []
    for r in range(N):
        pairs = []
        for c1 in range(N):
            for c2 in range(c1 + 2, N):
                pairs.append((c1, c2))
        row_pairs.append(pairs)

    def backtrack(r, col_counts, region_counts, last_stars):
        # Base case: all rows processed
        if r == N:
            # Verify all constraints are met (should be guaranteed by pruning)
            if all(c == 2 for c in col_counts) and all(v == 2 for v in region_counts.values()):
                return True
            return False

        # Pruning: Check column feasibility
        for c in range(N):
            # If a column already has 2 stars, it's fine (checked before placement)
            # If a column has > 2, impossible (checked before placement)
            # If a column cannot possibly reach 2 stars with remaining rows
            if col_counts[c] + (N - r) < 2:
                return False 

        # Pruning: Check region feasibility
        for rid in region_ids:
            if region_counts[rid] > 2: 
                return False
            rem = remaining_cells_from_row[rid][r]
            if region_counts[rid] + rem < 2:
                return False

        # Try placing 2 stars in the current row
        for c1, c2 in row_pairs[r]:
            rid1 = grid[r][c1]
            rid2 = grid[r][c2]

            # Check region constraints
            if rid1 == rid2:
                # Both stars in same region
                if region_counts[rid1] + 2 > 2: 
                    continue
            else:
                # Stars in different regions
                if region_counts[rid1] + 1 > 2: 
                    continue
                if region_counts[rid2] + 1 > 2: 
                    continue

            # Check column constraints
            if col_counts[c1] + 1 > 2: 
                continue
            if col_counts[c2] + 1 > 2: 
                continue

            # Check "No Touch" constraint with the previous row
            if last_stars:
                lc1, lc2 = last_stars
                # Check c1 against previous stars
                if abs(c1 - lc1) <= 1 or abs(c1 - lc2) <= 1:
                    continue
                # Check c2 against previous stars
                if abs(c2 - lc1) <= 1 or abs(c2 - lc2) <= 1:
                    continue

            # Place stars (Update state)
            col_counts[c1] += 1
            col_counts[c2] += 1
            region_counts[rid1] += 1
            if rid1 != rid2:
                region_counts[rid2] += 1

            solution[r] = (c1, c2)

            # Recurse
            if backtrack(r + 1, col_counts, region_counts, (c1, c2)):
                return True

            # Backtrack (Restore state)
            col_counts[c1] -= 1
            col_counts[c2] -= 1
            region_counts[rid1] -= 1
            if rid1 != rid2:
                region_counts[rid2] -= 1
            solution[r] = None

        return False

    # Start solving
    if backtrack(0, col_counts, region_counts, None):
        # Format the output grid
        res_grid = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            c1, c2 = solution[r]
            res_grid[r][c1] = 'S'
            res_grid[r][c2] = 'S'
        return res_grid
    else:
        return "No Solution"

