    # cols_used: set of column indices already occupied by stars in previous rows
    # last_col: column index of the star placed in row r-1 (to check adjacency constraints)
    def backtrack(r, cols_used, last_col):
        # Base case: If we have successfully placed stars in all rows
        if r == N:
            return []

        # Iterate through valid columns for the current row
        for c in row_options[r]:
            # Constraint 1: Column uniqueness (1 star per column)
            if c in cols_used:
                continue

            # Constraint 2: No touching (including diagonally) with the star in the previous row
            # Since we fill row by row, we only need to check against row r-1.
            # Vertical touch is covered by cols_used, but we check abs diff <= 1 for diagonal/vertical.
            if last_col is not None and abs(c - last_col) <= 1:
                continue

            # Pruning Strategy 1: Lookahead to the immediate next row (r+1)
            # If placing a star at (r, c) makes it impossible to place a star in row r+1, prune.
            if r + 1 < N:
                can_next_row_be_filled = False
                for nc in row_options[r+1]:
                    # Check if nc is valid for row r+1 given current placement (r, c)
                    if nc not in cols_used and nc != c and abs(nc - c) > 1:
                        can_next_row_be_filled = True
                        break
                if not can_next_row_be_filled:
                    continue # Prune this branch

            # Pruning Strategy 2: Global Column Availability (Pigeonhole Principle / Hall's Condition simplified)
            # Check if every future row k > r has at least one available column remaining.
            # This ignores the "no touch" constraint for k > r+1 but is a necessary condition.
            new_cols_used = cols_used | {c}
            possible_global = True
            for k in range(r + 1, N):
                # Check if row k has any column not in new_cols_used
                has_option = False
                for kc in row_options[k]:
                    if kc not in new_cols_used:
                        has_option = True
                        break
                if not has_option:
                    possible_global = False
                    break

            if not possible_global:
                continue

            # Recursive step: Place star at (r, c) and proceed to next row
            res = backtrack(r + 1, new_cols_used, c)
            if res is not None:
                return [(r, c)] + res

        return None

    # Start backtracking from row 0
    solution = backtrack(0, set(), None)

    if solution is None:
        return "No Solution"

    # Format the output as a grid with 'S' for stars and None for empty cells
    result_grid = [[None for _ in range(N)] for _ in range(N)]
    for r, c in solution:
        result_grid[r][c] = 'S'

    return result_grid

