                        val = next(iter(domains[(r,c)]))
                        # Row peers
                        for cc in range(N):
                            if cc != c:
                                if val in domains[(r, cc)]:
                                    domains[(r, cc)].discard(val)
                                    changed = True
                                    if len(domains[(r, cc)]) == 0: return False
                        # Col peers
                        for rr in range(N):
                            if rr != r:
                                if val in domains[(rr, c)]:
                                    domains[(rr, c)].discard(val)
                                    changed = True
                                    if len(domains[(rr, c)]) == 0: return False

            # Hidden Singles
            for r in range(N):
                row_cells = [(r, c) for c in range(N)]
                if not _check_hidden_singles(row_cells): return False
                # Check if any domain changed size
                # (Implicitly handled by the loop structure if we track changes, but let's just loop again)
                # To detect change, we can snapshot sizes, but simpler to just set changed=True if we do anything.
                # Let's rely on the fact that if we find a hidden single, we reduce a domain to size 1.

            for c in range(N):
                col_cells = [(r, c) for r in range(N)]
                if not _check_hidden_singles(col_cells): return False

            if not changed:
                break

        return True

    def _check_hidden_singles(cells):
        # cells is a list of (r, c)
        # Count occurrences of each value in domains
        counts = {v: [] for v in range(1, N+1)}
        for cell in cells:
            for val in domains[cell]:
                counts[val].append(cell)

        for val, cell_list in counts.items():
            if len(cell_list) == 1:
                cell = cell_list[0]
                if len(domains[cell]) > 1:
                    domains[cell] = {val}
                    # This is a change, propagate will catch it in next iteration
                    # But we need to signal change to the outer loop. 
                    # Since we are inside full_propagate, we can't easily signal 'changed' unless we use a nonlocal or return status.
                    # Let's just return True/False for consistency.
                    # Actually, full_propagate loops 'while True', so it will pick it up.
                    pass 
            elif len(cell_list) == 0:
                return False # Contradiction
        return True

    # Initial Propagation
    if not full_propagate():
        return "No Solution"

    # 6. Backtracking Search
    # Select cell with MRV (Minimum Remaining Values)
    def get_unassigned_cell():
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[(r, c)]) > 1:
                    if len(domains[(r, c)]) < min_len:
                        min_len = len(domains[(r, c)])
                        best_cell = (r, c)
        return best_cell

    def backtrack():
        cell = get_unassigned_cell()
        if cell is None:
            return True # Solved

        r, c = cell
        # Try values. Heuristic: try values that are least constraining? 
        # For N=5, simple order is fine.
        # Maybe sort by frequency in neighbors?

        # Save state for backtracking
        # Since domains is a dict of sets, deep copy is expensive.
        # Instead, we modify domains and revert.

        original_domain = domains[cell].copy()

        for val in sorted(list(original_domain)):
            # Assign
            domains[cell] = {val}

            # Propagate
            # We need to be careful. full_propagate modifies domains in place.
            # We need to save the state of ALL domains before this step to revert if it fails.
            # This is expensive for large N, but for N=5 it's acceptable.
            # Optimization: Only save domains that change? 
            # Or just implement a stack of changes.

            # Let's use a simpler approach: copy domains.
            # N=5, 25 cells. Copying 25 sets of size 5 is very fast.

            # Actually, let's implement a "save/restore" mechanism or just copy.
            # Given the constraints, copying is safest and fast enough.

            # Wait, full_propagate is destructive.
            # Let's make a copy of domains before calling propagate.
            saved_domains = {k: v.copy() for k, v in domains.items()}

            if full_propagate():
                if backtrack():
                    return True

            # Restore
            for k in domains:
                domains[k] = saved_domains[k]

        return False

    if backtrack():
        # Construct solution grid
        grid = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(next(iter(domains[(r, c)])))
            grid.append(row)
        return grid
    else:
        return "No Solution"

