import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)
    M = len(data[0])

    # Initialize grid with the observation data
    # We use a list of lists for mutability
    grid = [list(row) for row in data]

    # Helper to get orthogonal neighbors
    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < M:
                yield nr, nc

    # Propagate constraints based on the "No 2x2 monochromatic" rule.
    # If a 2x2 block has 3 cells of one color, the 4th must be the other.
    # If a 2x2 block has 4 cells of one color, the state is invalid.
    # Returns False if an invalid state is detected, True otherwise.
    # Modifies the grid in place.
    def propagate(g):
        changed = True
        while changed:
            changed = False
            for i in range(N - 1):
                for j in range(M - 1):
                    cells = [(i, j), (i, j+1), (i+1, j), (i+1, j+1)]
                    vals = [g[r][c] for r, c in cells]

                    if None in vals:
                        count_b = vals.count('B')
                        count_w = vals.count('W')

                        # If 3 are Black, the None must be White
                        if count_b == 3:
                            idx = vals.index(None)
                            r, c = cells[idx]
                            if g[r][c] is None:
                                g[r][c] = 'W'
                                changed = True
                        # If 3 are White, the None must be Black
                        elif count_w == 3:
                            idx = vals.index(None)
                            r, c = cells[idx]
                            if g[r][c] is None:
                                g[r][c] = 'B'
                                changed = True
                    else:
                        # If no None, check if all are same (invalid)
                        if vals[0] == vals[1] == vals[2] == vals[3]:
                            return False
        return True

    # Pruning function: Check if current Black/White cells can potentially be connected.
    # All current Black cells must be in the same connected component of the graph 
    # formed by cells that are currently Black or None (potential Black).
    # Same for White.
    def check_pruning(g):
        b_cells = []
        w_cells = []
        for r in range(N):
            for c in range(M):
                if g[r][c] == 'B':
                    b_cells.append((r, c))
                elif g[r][c] == 'W':
                    w_cells.append((r, c))

        # Check Black connectivity potential
        if len(b_cells) > 1:
            start = b_cells[0]
            visited = set([start])
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                for nr, nc in get_neighbors(r, c):
                    # Can traverse through Black or None (potential Black)
                    if (nr, nc) not in visited and g[nr][nc] in ('B', None):
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            # If not all Black cells are reachable, they are separated by White walls
            if len(visited.intersection(set(b_cells))) != len(b_cells):
                return False

        # Check White connectivity potential
        if len(w_cells) > 1:
            start = w_cells[0]
            visited = set([start])
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                for nr, nc in get_neighbors(r, c):
                    # Can traverse through White or None (potential White)
                    if (nr, nc) not in visited and g[nr][nc] in ('W', None):
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            if len(visited.intersection(set(w_cells))) != len(w_cells):
                return False

        return True

    # List of empty cells to fill
    empty_cells = [(r, c) for r in range(N) for c in range(M) if grid[r][c] is None]

    # Backtracking solver
    def backtrack(idx, g):
        # Skip cells that have been filled by propagation
        while idx < len(empty_cells) and g[empty_cells[idx][0]][empty_cells[idx][1]] is not None:
            idx += 1

        # Base case: all cells filled
        if idx == len(empty_cells):
            # Final strict connectivity check
            b_cells = [(r, c) for r in range(N) for c in range(M) if g[r][c] == 'B']
            w_cells = [(r, c) for r in range(N) for c in range(M) if g[r][c] == 'W']

            # Must have at least one of each (implied by 2x2 rule on grid >= 2x2)
            if not b_cells or not w_cells:
                return None 

            # Check strict Black connectivity
            start = b_cells[0]
            visited = set([start])
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                for nr, nc in get_neighbors(r, c):
                    if (nr, nc) not in visited and g[nr][nc] == 'B':
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            if len(visited) != len(b_cells):
                return None

            # Check strict White connectivity
            start = w_cells[0]
            visited = set([start])
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                for nr, nc in get_neighbors(r, c):
                    if (nr, nc) not in visited and g[nr][nc] == 'W':
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            if len(visited) != len(w_cells):
                return None

            return g

        r, c = empty_cells[idx]

        # Try setting to 'B'
        g_b = [row[:] for row in g]
        g_b[r][c] = 'B'
        if propagate(g_b):
            if check_pruning(g_b):
                res = backtrack(idx + 1, g_b)
                if res: return res

        # Try setting to 'W'
        g_w = [row[:] for row in g]
        g_w[r][c] = 'W'
        if propagate(g_w):
            if check_pruning(g_w):
                res = backtrack(idx + 1, g_w)
                if res: return res

        return None

    # Initial propagation and pruning check
    if not propagate(grid):
        return "No Solution"
    if not check_pruning(grid):
        return "No Solution"

    result = backtrack(0, grid)
    if result:
        return result
    return "No Solution"

