def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Grid state: 'B' for Black, 'W' for White, None for Unknown
    grid = [[None for _ in range(C)] for _ in range(R)]

    # Helper to get 3x3 neighborhood coordinates
    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighbors.append((nr, nc))
        return neighbors

    # Constraint Propagation
    # Returns True if consistent, False if contradiction found
    def propagate(current_grid):
        changed = True
        while changed:
            changed = False
            for r in range(R):
                for c in range(C):
                    val = data[r][c]
                    if val is None:
                        continue

                    neighbors = get_neighbors(r, c)
                    count_b = 0
                    count_u = 0
                    unknown_cells = []

                    for nr, nc in neighbors:
                        cell_state = current_grid[nr][nc]
                        if cell_state == 'B':
                            count_b += 1
                        elif cell_state is None:
                            count_u += 1
                            unknown_cells.append((nr, nc))

                    # Check for contradiction
                    if count_b > val:
                        return False
                    if count_b + count_u < val:
                        return False

                    # Deduction 1: If max possible blacks equals val, all unknowns must be Black
                    if count_b + count_u == val:
                        for ur, uc in unknown_cells:
                            if current_grid[ur][uc] is None:
                                current_grid[ur][uc] = 'B'
                                changed = True

                    # Deduction 2: If current blacks equals val, all unknowns must be White
                    if count_b == val:
                        for ur, uc in unknown_cells:
                            if current_grid[ur][uc] is None:
                                current_grid[ur][uc] = 'W'
                                changed = True
        return True

    # Check if the current grid satisfies all number constraints (for final validation or pruning)
    def is_valid(current_grid):
        for r in range(R):
            for c in range(C):
                val = data[r][c]
                if val is None:
                    continue

                neighbors = get_neighbors(r, c)
                count_b = 0
                count_u = 0

                for nr, nc in neighbors:
                    if current_grid[nr][nc] == 'B':
                        count_b += 1
                    elif current_grid[nr][nc] is None:
                        count_u += 1

                # If there are still unknowns, we can't fully validate yet, 
                # but we can check if it's impossible.
                if count_b > val:
                    return False
                if count_b + count_u < val:
                    return False

                # If fully determined, check exact match
                if count_u == 0 and count_b != val:
                    return False
        return True

    # Backtracking Solver
    def backtrack(current_grid):
        # Propagate constraints first
        if not propagate(current_grid):
            return None

        # Check if solved (no None left)
        # Actually, we just need to find a valid assignment. 
        # If propagate finishes and no None left, we are done.
        # If None left, we branch.

        # Find first unknown cell
        r_unknown, c_unknown = -1, -1
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] is None:
                    r_unknown, c_unknown = r, c
                    break
            if r_unknown != -1:
                break

        if r_unknown == -1:
            # No unknowns left, check validity one last time
            if is_valid(current_grid):
                return current_grid
            else:
                return None

        # Try 'B'
        # Deep copy not strictly needed if we backtrack carefully, but for safety in recursion:
        # Actually, modifying in place and reverting is faster.

        # Try Black
        current_grid[r_unknown][c_unknown] = 'B'
        res = backtrack(current_grid)
        if res is not None:
            return res

        # Backtrack: revert
        current_grid[r_unknown][c_unknown] = None

        # Try White
        current_grid[r_unknown][c_unknown] = 'W'
        res = backtrack(current_grid)
        if res is not None:
            return res

        # Backtrack: revert
        current_grid[r_unknown][c_unknown] = None

        return None

    # Initial propagation
    if not propagate(grid):
        return "No Solution"

    final_grid = backtrack(grid)

    if final_grid is None:
        return "No Solution"

    # Format output: 'B' for black, None for white
    # The problem asks for 'B' and None.
    # My internal 'W' is effectively None in the output.
    result = []
    for r in range(R):
        row_res = []
        for c in range(C):
            if final_grid[r][c] == 'B':
                row_res.append('B')
            else:
                row_res.append(None)
        result.append(row_res)

    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
