                grid[r][c] = 1 # Clues are always White

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)] # U, D, L, R

    def get_min_max_vis(r, c, grid):
        min_v = 0
        max_v = 0
        for dr, dc in dirs:
            # Min scan: stop at Black or Unknown
            curr_min = 0
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N:
                if grid[nr][nc] == 2: break
                if grid[nr][nc] == 1: curr_min += 1
                else: break # Unknown treated as Black
