                                if data[nr][nc] is not None: return False # Clue cannot be Black
                                break # Blocked
                            nr += dr
                            nc += dc

                # Propagation Rule 2: If max_v + 1 == val, visible Unknowns must be White
                if max_v + 1 == val:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        while 0 <= nr < N and 0 <= nc < N:
                            if grid[nr][nc] == 2: break
                            if grid[nr][nc] == 0:
                                grid[nr][nc] = 1
                                changed = True
                            nr += dr
                            nc += dc
        return True

    def is_connected(grid):
        start = None
        white_count = 0
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 1:
                    white_count += 1
                    if start is None:
                        start = (r, c)

        if start is None: return white_count == 0

        visited = set()
        stack = [start]
        visited.add(start)
        count = 0
        while stack:
            r, c = stack.pop()
            count += 1
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if grid[nr][nc] == 1 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        stack.append((nr, nc))
        return count == white_count

    def solve_dfs(grid):
        if not propagate(grid):
            return None

        # Find unknown cell
        unknown_pos = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    unknown_pos = (r, c)
                    break
            if unknown_pos: break

        if unknown_pos is None:
            if is_connected(grid):
                return grid
            return None

        r, c = unknown_pos

        # Try Black
        can_black = True
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                if grid[nr][nc] == 2:
                    can_black = False
                    break

        if can_black:
            grid[r][c] = 2
            res = solve_dfs(grid)
            if res: return res
            grid[r][c] = 0

        # Try White
        grid[r][c] = 1
        res = solve_dfs(grid)
        if res: return res
        grid[r][c] = 0

        return None

    if not propagate(grid):
        return "No Solution"

    final_grid = solve_dfs(grid)

    if final_grid is None:
        return "No Solution"

    result = []
    for r in range(N):
        row = []
        for c in range(N):
            if final_grid[r][c] == 2:
                row.append('B')
            elif data[r][c] is not None:
                row.append(data[r][c])
            else:
                row.append(None)
        result.append(row)
    return result

