import itertools

def solve(observation):
    N = 6
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    # Helper to count visible buildings from a direction
    def count_visible(line):
        if not line: return 0
        max_h = 0
        count = 0
        for h in line:
            if h > max_h:
                max_h = h
                count += 1
        return count

    # Generate all permutations of 1..N
    perms = list(itertools.permutations(range(1, N + 1)))

    # Precompute valid rows based on Left and Right clues
    row_candidates = []
    for r in range(N):
        l_clue = L[r]
        r_clue = R[r]
        valid = []
        for p in perms:
            # Check Left visibility
            if l_clue > 0 and count_visible(p) != l_clue:
                continue
            # Check Right visibility
            if r_clue > 0 and count_visible(p[::-1]) != r_clue:
                continue
            valid.append(p)
        row_candidates.append(valid)

    # Precompute valid columns based on Up and Down clues
    col_candidates = []
    for c in range(N):
        u_clue = U[c]
        d_clue = D[c]
        valid = []
        for p in perms:
            # Check Up (Top) visibility
            if u_clue > 0 and count_visible(p) != u_clue:
                continue
            # Check Down (Bottom) visibility
            if d_clue > 0 and count_visible(p[::-1]) != d_clue:
                continue
            valid.append(p)
        col_candidates.append(valid)

    # Precompute valid prefixes for columns to speed up checking during backtracking
    # col_prefixes[c][length] = set of tuples representing valid prefixes of that length
    col_prefixes = []
    for c in range(N):
        prefixes = {}
        for perm in col_candidates[c]:
            for l in range(1, N + 1):
                prefix = perm[:l]
                if l not in prefixes:
                    prefixes[l] = set()
                prefixes[l].add(prefix)
        col_prefixes.append(prefixes)

    grid = [[0] * N for _ in range(N)]

    def solve_row(r):
        if r == N:
            return True

        # Try each valid candidate for the current row
        for cand in row_candidates[r]:
            possible = True
            for c in range(N):
                val = cand[c]

                # Check column uniqueness (Latin Square property)
                for r_prev in range(r):
                    if grid[r_prev][c] == val:
                        possible = False
                        break
                if not possible: break

                # Check if the current column prefix is valid according to column clues
                # The column will have values from row 0 to r
                current_col_prefix = tuple(grid[k][c] for k in range(r)) + (val,)

                # Check if this prefix exists in our precomputed valid prefixes
                if (r + 1) not in col_prefixes[c] or current_col_prefix not in col_prefixes[c][r + 1]:
                    possible = False
                    break

            if possible:
                grid[r] = list(cand)
                if solve_row(r + 1):
                    return True
                grid[r] = [0] * N # Backtrack

        return False

    if solve_row(0):
        return grid
    else:
        return "No Solution"

