            # Hidden Singles check (optional but good for efficiency)
            # For N=5, simple propagation + MRV is usually enough.
            # Let's add a quick hidden singles pass
            units = []
            for r in range(N): units.append([(r, c) for c in range(N)])
            for c in range(N): units.append([(r, c) for r in range(N)])
            for rid in regions: units.append(regions[rid])

            hidden_single_found = False
            for unit in units:
                counts = {v: [] for v in range(1, N + 1)}
                for u_cell in unit:
                    if len(new_domains[u_cell]) > 1:
                        for v in new_domains[u_cell]:
                            counts[v].append(u_cell)
                for v, cells in counts.items():
                    if len(cells) == 1:
                        target = cells[0]
                        if len(new_domains[target]) > 1:
                            new_domains[target] = {v}
                            queue.append(target) # Add to queue to propagate
                            hidden_single_found = True

            if hidden_single_found:
                 # Propagate the new singles
                 while queue:
                    curr = queue.pop(0)
                    if len(new_domains[curr]) == 0:
                        valid = False
                        break
                    if len(new_domains[curr]) == 1:
                        v = next(iter(new_domains[curr]))
                        for peer in peers[curr]:
                            if v in new_domains[peer]:
                                new_domains[peer].discard(v)
                                if len(new_domains[peer]) == 0:
                                    valid = False
                                    break
                                if len(new_domains[peer]) == 1:
                                    queue.append(peer)
                        if not valid: break
                    if not valid: break

            if not valid:
                continue

            result = search(new_domains)
            if result:
                return result

        return None

    return search(domains)

