import sys

# Increase recursion depth just in case, though 5x5 is small.
sys.setrecursionlimit(2000)

def solve(observation):
    data = observation['data']
    adjacent_clues = observation['adjacent']

    N = len(data)

    # Initialize domains
    # domains[r][c] is a set of possible values
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Apply initial data
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                val = data[r][c]
                domains[r][c] = {val}

    # Parse adjacent clues into a set for O(1) lookup
    # Format: (r, c) where c is float for horizontal, r is float for vertical
    # Actually, let's store them as normalized tuples.
    # Horizontal dot at (r, c+0.5) connects (r, c) and (r, c+1)
    # Vertical dot at (r+0.5, c) connects (r, c) and (r+1, c)

    has_dot = set()

    for coord in adjacent_clues:
        r, c = coord
        # Check if it's horizontal or vertical
        if isinstance(c, float) and c != int(c):
            # Horizontal gap: (r, c) where c is x.5
            # Connects (r, int(c)) and (r, int(c)+1)
            c_int = int(c)
            has_dot.add(((r, c_int), (r, c_int + 1)))
            has_dot.add(((r, c_int + 1), (r, c_int)))
        elif isinstance(r, float) and r != int(r):
            # Vertical gap: (r, c) where r is y.5
            # Connects (int(r), c) and (int(r)+1, c)
            r_int = int(r)
            has_dot.add(((r_int, c), (r_int + 1, c)))
            has_dot.add(((r_int + 1, c), (r_int, c)))

    # Define all orthogonal neighbors
    neighbors = []
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                neighbors.append(((r, c), (r, c + 1)))
            if r + 1 < N:
                neighbors.append(((r, c), (r + 1, c)))

    # Constraint Propagation (AC-3 like)
    # We will maintain a queue of arcs to revise
    queue = list(neighbors) # All arcs initially

    def revise(domains, xi, xj):
        revised = False
        ri, ci = xi
        rj, cj = xj

        # Determine constraint type
        is_consecutive = (xi, xj) in has_dot

        for vi in list(domains[ri][ci]):
            # Check if there is a valid vj in domains[rj][cj]
            has_support = False
            for vj in domains[rj][cj]:
                if is_consecutive:
                    if abs(vi - vj) == 1:
                        has_support = True
                        break
                else:
                    if abs(vi - vj) != 1:
                        has_support = True
                        break

            if not has_support:
                domains[ri][ci].remove(vi)
                revised = True
        return revised

    # Initial propagation
    while queue:
        xi, xj = queue.pop(0)
        if revise(domains, xi, xj):
            if not domains[xi[0]][xi[1]]:
                return "No Solution" # Domain wipeout
            # Add neighbors of xi back to queue
            ri, ci = xi
            if ci + 1 < N:
                queue.append(((ri, ci), (ri, ci + 1)))
                queue.append(((ri, ci + 1), (ri, ci)))
            if ci - 1 >= 0:
                queue.append(((ri, ci), (ri, ci - 1)))
                queue.append(((ri, ci - 1), (ri, ci)))
            if ri + 1 < N:
                queue.append(((ri, ci), (ri + 1, ci)))
                queue.append(((ri + 1, ci), (ri, ci)))
            if ri - 1 >= 0:
                queue.append(((ri, ci), (ri - 1, ci)))
                queue.append(((ri - 1, ci), (ri, ci)))

    # Backtracking Search
    # Flatten grid for easier handling
    cells = [(r, c) for r in range(N) for c in range(N)]

    # Sort cells by domain size (MRV heuristic) - dynamic sorting is better inside recursion
    # But for initial setup, we can just start.

    assignment = [[None for _ in range(N)] for _ in range(N)]

    # Pre-fill assigned values
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) == 1:
                val = list(domains[r][c])[0]
                assignment[r][c] = val

    def is_complete(assignment):
        for r in range(N):
            for c in range(N):
                if assignment[r][c] is None:
                    return False
        return True

    def select_unassigned_variable(assignment, domains):
        # MRV: Minimum Remaining Values
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if assignment[r][c] is None:
                    size = len(domains[r][c])
                    if size < min_size:
                        min_size = size
                        best_cell = (r, c)
        return best_cell

    def backtrack(assignment, domains):
        if is_complete(assignment):
            return assignment

        r, c = select_unassigned_variable(assignment, domains)

        # Try values in domain
        # Heuristic: LCV (Least Constraining Value) could be used, but for N=5, order doesn't matter much.
        # Let's just iterate sorted.
        for val in sorted(list(domains[r][c])):
            # Check consistency with neighbors (though domains should handle most)
            # We need to check against currently assigned neighbors to be safe
            consistent = True

            # Check row and col uniqueness
            for i in range(N):
                if assignment[r][i] == val: consistent = False; break
                if assignment[i][c] == val: consistent = False; break
            if not consistent: continue

            # Check adjacency constraints with assigned neighbors
            # Up
            if r > 0 and assignment[r-1][c] is not None:
                neighbor_val = assignment[r-1][c]
                is_consec = ((r, c), (r-1, c)) in has_dot
                if is_consec and abs(val - neighbor_val) != 1: consistent = False
                if not is_consec and abs(val - neighbor_val) == 1: consistent = False
            if not consistent: continue

            # Down
            if r < N - 1 and assignment[r+1][c] is not None:
                neighbor_val = assignment[r+1][c]
                is_consec = ((r, c), (r+1, c)) in has_dot
                if is_consec and abs(val - neighbor_val) != 1: consistent = False
                if not is_consec and abs(val - neighbor_val) == 1: consistent = False
            if not consistent: continue

            # Left
            if c > 0 and assignment[r][c-1] is not None:
                neighbor_val = assignment[r][c-1]
                is_consec = ((r, c), (r, c-1)) in has_dot
                if is_consec and abs(val - neighbor_val) != 1: consistent = False
                if not is_consec and abs(val - neighbor_val) == 1: consistent = False
            if not consistent: continue

            # Right
            if c < N - 1 and assignment[r][c+1] is not None:
                neighbor_val = assignment[r][c+1]
                is_consec = ((r, c), (r, c+1)) in has_dot
                if is_consec and abs(val - neighbor_val) != 1: consistent = False
                if not is_consec and abs(val - neighbor_val) == 1: consistent = False
            if not consistent: continue

            # Assign
            assignment[r][c] = val

            # Forward Checking / Propagate
            # We create a copy of domains to avoid modifying the original state permanently until we know it works
            # Or we modify and revert. Modifying and reverting is faster.

            # Save state
            saved_domains = {}
            inference_failed = False

            # Propagate constraints to neighbors
            neighbors_to_check = []
            if r > 0: neighbors_to_check.append((r-1, c))
            if r < N - 1: neighbors_to_check.append((r+1, c))
            if c > 0: neighbors_to_check.append((r, c-1))
            if c < N - 1: neighbors_to_check.append((r, c+1))

            # Also need to check row/col constraints
            for i in range(N):
                if i != c: neighbors_to_check.append((r, i))
                if i != r: neighbors_to_check.append((i, c))

            # Remove val from domains of neighbors
            for nr, nc in neighbors_to_check:
                if assignment[nr][nc] is None:
                    if val in domains[nr][nc]:
                        saved_domains[(nr, nc)] = domains[nr][nc].copy()
                        domains[nr][nc].discard(val)
                        if not domains[nr][nc]:
                            inference_failed = True
                            break

            if not inference_failed:
                # Further propagation (AC-3 step for the affected arcs)
                # This is crucial for efficiency
                queue_prop = []
                for nr, nc in neighbors_to_check:
                     if assignment[nr][nc] is None:
                        # Add arcs involving (nr, nc)
                        if nc + 1 < N: queue_prop.append(((nr, nc), (nr, nc + 1)))
                        if nc - 1 >= 0: queue_prop.append(((nr, nc), (nr, nc - 1)))
                        if nr + 1 < N: queue_prop.append(((nr, nc), (nr + 1, nc)))
                        if nr - 1 >= 0: queue_prop.append(((nr, nc), (nr - 1, nc)))

                while queue_prop:
                    xi, xj = queue_prop.pop(0)
                    ri, ci = xi
                    rj, cj = xj
                    if assignment[ri][ci] is not None or assignment[rj][cj] is not None:
                         continue # One is assigned, handled by simple check or already consistent

                    if revise(domains, xi, xj):
                        if not domains[ri][ci]:
                            inference_failed = True
                            break
                        # Add neighbors of xi
                        if ci + 1 < N: queue_prop.append(((ri, ci), (ri, ci + 1)))
                        if ci - 1 >= 0: queue_prop.append(((ri, ci), (ri, ci - 1)))
                        if ri + 1 < N: queue_prop.append(((ri, ci), (ri + 1, ci)))
                        if ri - 1 >= 0: queue_prop.append(((ri, ci), (ri - 1, ci)))

                if not inference_failed:
                    result = backtrack(assignment, domains)
                    if result is not None:
                        return result

            # Backtrack: restore domains
            for (nr, nc), old_domain in saved_domains.items():
                domains[nr][nc] = old_domain

            assignment[r][c] = None

        return None

    result = backtrack(assignment, domains)
    if result:
        return result
    return "No Solution"

