        # If cutoff is k, cells with r >= k are water.
        possible_cutoffs = list(range(min_r, max_r + 2))
        region_domains[rid] = possible_cutoffs

        cells_by_r = {}
        for r, c in cells:
            if r not in cells_by_r:
