OBSERVATION = {'U': [2, 0, 4, 0, 0, 2], 'D': [0, 4, 3, 0, 1, 0], 'L': [0, 0, 4, 0, 2, 3], 'R': [3, 4, 0, 3, 0, 0]}

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    N = len(U)

    # Domains: domains[r][c] is a set of possible values
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    grid = [[0] * N for _ in range(N)]

    # Helper to get line domains
    def get_row_domains(r):
        return [domains[r][c] for c in range(N)]

    def get_col_domains(c):
        return [domains[r][c] for r in range(N)]

    # Helper to calculate min and max possible visibility for a list of domains
    def get_visibility_bounds(doms):
        # Max visibility: assume we can always pick a number larger than current max if possible
        max_vis = 0
        current_max = 0
        for d in doms:
            # Can we pick a number > current_max?
            # We need at least one number in d that is > current_max
            possible_higher = [x for x in d if x > current_max]
            if possible_higher:
                max_vis += 1
                # To maximize visibility, we pick the smallest possible number > current_max
                # to leave room for more increases later? 
                # Actually, to maximize count, we want 1, 2, 3...
                # So we pick min(possible_higher)
                current_max = min(possible_higher)
            else:
                # All numbers in d are <= current_max, so this building is hidden in the best case?
                # No, if all are <= current_max, it is definitely hidden.
                pass

        # Min visibility: assume we hide as much as possible
        min_vis = 0
        current_max = 0
        for d in doms:
            # Must we see a building?
            # We see it if min(d) > current_max
            if min(d) > current_max:
                min_vis += 1
                current_max = max(d) # In worst case (for visibility count), we pick the largest possible to hide subsequent ones?
                # Wait, to MINIMIZE visibility, we want to hide buildings.
                # So if we see a building, we want it to be as tall as possible to hide the rest.
                # So current_max becomes max(d).
            else:
                # We can potentially hide it.
                # To minimize visibility, we assume it is hidden.
                # But we must update current_max? 
                # If we hide it, it doesn't become the new max.
                # However, the actual value placed might be larger than current_max but smaller than some future building?
                # No, if it's hidden, value <= current_max. So current_max doesn't change.
                # But what if the domain contains values > current_max?
                # Then we *could* see it. But we are calculating MIN visibility.
                # So we assume we pick a value <= current_max if possible.
                if any(x <= current_max for x in d):
                    # We can hide it. current_max stays same.
                    pass
                else:
                    # All values in d are > current_max. We MUST see it.
                    # To minimize future visibility, we pick the largest possible value?
                    # No, to minimize total count, if we MUST see it, we want it to be TALL to hide others.
                    min_vis += 1
                    current_max = max(d)

        return min_vis, max_vis

    # Apply initial constraints
    def apply_initial_constraints():
        # Top clues
        for c, clue in enumerate(U):
            if clue == 1:
                val = N
                domains[0][c] = {val}
            elif clue == N:
                for r in range(N):
                    domains[r][c] = {r + 1}

        # Bottom clues
        for c, clue in enumerate(D):
            if clue == 1:
                val = N
                domains[N-1][c] = {val}
            elif clue == N:
                for r in range(N):
                    domains[N-1-r][c] = {r + 1}

        # Left clues
        for r, clue in enumerate(L):
            if clue == 1:
                val = N
                domains[r][0] = {val}
            elif clue == N:
                for c in range(N):
                    domains[r][c] = {c + 1}

        # Right clues
        for r, clue in enumerate(R):
            if clue == 1:
                val = N
                domains[r][N-1] = {val}
            elif clue == N:
                for c in range(N):
                    domains[r][N-1-c] = {c + 1}

    apply_initial_constraints()

    # Propagate singletons
    def propagate():
        changed = True
        while changed:
            changed = False
            # Row/Col uniqueness
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        if grid[r][c] != val:
                            grid[r][c] = val
                            changed = True
                            # Remove from row
                            for cc in range(N):
                                if cc != c and val in domains[r][cc]:
                                    domains[r][cc].discard(val)
                                    changed = True
                            # Remove from col
                            for rr in range(N):
                                if rr != r and val in domains[rr][c]:
                                    domains[rr][c].discard(val)
                                    changed = True

            # Check for empty domains
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 0:
                        return False
        return True

    if not propagate():
        return "No Solution"

    # Check visibility constraints for fully or partially filled lines
    def check_all_constraints():
        # Check rows
        for r in range(N):
            row_doms = get_row_domains(r)
            # Left
            if L[r] != 0:
                mn, mx = get_visibility_bounds(row_doms)
                if not (mn <= L[r] <= mx):
                    return False
            # Right
            if R[r] != 0:
                mn, mx = get_visibility_bounds(list(reversed(row_doms)))
                if not (mn <= R[r] <= mx):
                    return False

        # Check cols
        for c in range(N):
            col_doms = get_col_domains(c)
            # Top
            if U[c] != 0:
                mn, mx = get_visibility_bounds(col_doms)
                if not (mn <= U[c] <= mx):
                    return False
            # Bottom
            if D[c] != 0:
                mn, mx = get_visibility_bounds(list(reversed(col_doms)))
                if not (mn <= D[c] <= mx):
                    return False
        return True

    if not check_all_constraints():
