                        # Contradiction Check 2: Not enough cells left to reach the target
                        if black_count + unknown_count < val:
                            return False

                        # Deduction 1: If black_count == val, all remaining unknowns must be White (0)
                        if black_count == val:
                            for nr, nc in unknown_cells:
                                if grid[nr][nc] == -1:
                                    grid[nr][nc] = 0
                                    changed = True

                        # Deduction 2: If black_count + unknown_count == val, all unknowns must be Black (1)
                        elif black_count + unknown_count == val:
                            for nr, nc in unknown_cells:
                                if grid[nr][nc] == -1:
                                    grid[nr][nc] = 1
                                    changed = True
        return True

    def solve_dfs():
        # Apply logic propagation first
        if not propagate():
            return None

        if is_solved():
            # Return a deep copy to preserve the solution state
            return [row[:] for row in grid]

        # Heuristic: Pick the unknown cell that is part of the most numbered constraints
        # This maximizes the impact of the guess on propagation.
        best_cell = None
        max_constraints = -1

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == -1:
                    # Count how many numbered cells have (r, c) in their neighborhood
                    constraint_count = 0
                    # Check neighbors of (r,c) to see if they are numbered
                    # Actually, we need to check which numbered cells cover (r,c).
                    # A numbered cell at (nr, nc) covers (r, c) if (r, c) is in neighbors_map[(nr, nc)].
                    # This is equivalent to checking if (nr, nc) is in neighbors_map[(r, c)].
                    for nr, nc in neighbors_map[(r, c)]:
                        if data[nr][nc] is not None:
                            constraint_count += 1

                    if constraint_count > max_constraints:
                        max_constraints = constraint_count
                        best_cell = (r, c)

        if best_cell is None:
            return None 

        r, c = best_cell

        # Try Black (1)
        grid[r][c] = 1
        res = solve_dfs()
        if res: return res

        # Try White (0)
        grid[r][c] = 0
        res = solve_dfs()
        if res: return res

        # Backtrack
        grid[r][c] = -1
        return None

    result_grid = solve_dfs()

    if result_grid is None:
        return "No Solution"

    # Format output: 'B' for black, None for white
    output_grid = []
    for r in range(rows):
        row_out = []
        for c in range(cols):
            if result_grid[r][c] == 1:
                row_out.append('B')
            else:
                row_out.append(None)
        output_grid.append(row_out)

    return output_grid

