import copy

OBSERVATION = {
    'data': [
        [None, 2, None, 2, None, 5, None],
        [4, 5, 4, None, 6, 6, 3],
        [3, None, 5, None, 6, 6, None],
        [3, None, None, None, 5, 4, None],
        [3, None, 6, None, 5, 4, 4],
        [5, None, 6, None, 4, None, None],
        [None, 4, None, None, None, 3, 2]
    ]
}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Grid state: -1 unknown, 0 white, 1 black
    grid = [[-1 for _ in range(C)] for _ in range(R)]

    constraints = []
    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val is not None:
                constraints.append((r, c, val))

    # Precompute neighborhoods for each constraint
    neighborhoods = {}
    for r, c, val in constraints:
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighbors.append((nr, nc))
        neighborhoods[(r, c)] = neighbors

    def propagate(g):
        """
        Applies logical deduction rules (Naked Singles) to the grid.
        Returns False if a contradiction is found.
        Returns True otherwise (even if no changes were made).
        """
        changed = True
        while changed:
            changed = False
            for r, c, val in constraints:
                neighbors = neighborhoods[(r, c)]
                current_black = 0
                unknowns = []
                for nr, nc in neighbors:
                    if g[nr][nc] == 1:
                        current_black += 1
                    elif g[nr][nc] == -1:
                        unknowns.append((nr, nc))

                # Rule 1: If current black count exceeds the number, contradiction.
                if current_black > val:
                    return False

                # Rule 2: If even filling all unknowns with black isn't enough, contradiction.
                if current_black + len(unknowns) < val:
                    return False

                # Rule 3: If current black + unknowns == val, all unknowns must be Black.
                if current_black + len(unknowns) == val:
                    for nr, nc in unknowns:
                        if g[nr][nc] == -1:
                            g[nr][nc] = 1
                            changed = True

                # Rule 4: If current black == val, all unknowns must be White.
                elif current_black == val:
                    for nr, nc in unknowns:
                        if g[nr][nc] == -1:
                            g[nr][nc] = 0
                            changed = True
        return True

    def is_complete(g):
        for r in range(R):
            for c in range(C):
                if g[r][c] == -1:
                    return False
        return True

    def get_best_variable(g):
        """
        Heuristic: Find the unknown cell that is part of the most constrained neighborhood.
        Specifically, the neighborhood with the fewest remaining unknowns (but > 0).
        """
        best_var = None
        min_remaining = float('inf')

        for r, c, val in constraints:
            neighbors = neighborhoods[(r, c)]
            unknowns_count = 0
            current_black = 0
            for nr, nc in neighbors:
                if g[nr][nc] == -1:
                    unknowns_count += 1
                elif g[nr][nc] == 1:
                    current_black += 1

            # We look for active constraints (not yet satisfied or failed).
            # After propagation, active constraints satisfy:
            # current_black < val AND current_black + unknowns_count > val
            # Thus unknowns_count >= 1.

            if unknowns_count > 0:
                if unknowns_count < min_remaining:
                    min_remaining = unknowns_count
                    # Pick the first unknown in this neighborhood
                    for nr, nc in neighbors:
                        if g[nr][nc] == -1:
                            best_var = (nr, nc)
                            break
        return best_var

    def solve_recursive(g):
        # 1. Propagate constraints
        if not propagate(g):
            return None

        # 2. Check if solved
        if is_complete(g):
            return g

        # 3. Select variable to branch on
        r, c = get_best_variable(g)

        # Fallback: if no constrained variable found (all constraints satisfied but unknowns remain),
        # pick the first unknown (unconstrained cell).
        if r is None:
            for rr in range(R):
                for cc in range(C):
                    if g[rr][cc] == -1:
                        r, c = rr, cc
                        break
                if r is not None: break

        if r is None:
            return g # Should be complete

        # 4. Branch: Try Black (1)
        g1 = copy.deepcopy(g)
        g1[r][c] = 1
        res = solve_recursive(g1)
        if res:
            return res

        # 5. Branch: Try White (0)
        g2 = copy.deepcopy(g)
        g2[r][c] = 0
        res = solve_recursive(g2)
        if res:
            return res

        return None

    final_grid = solve_recursive(grid)

    if final_grid is None:
        return "No Solution"

    # Format output: 'B' for black, None for white
    result = []
    for r in range(R):
        row_res = []
        for c in range(C):
            if final_grid[r][c] == 1:
                row_res.append('B')
            else:
                row_res.append(None)
        result.append(row_res)
    return result

