        """
        changed = True
        while changed:
            changed = False

            # Process Rows
            for r in range(N):
                row = g[r]
                limit = N // 2

                # Rule 1: No three consecutive same colors (XX -> neighbor !X)
                for c in range(N - 1):
                    if row[c] is not None and row[c] == row[c+1]:
                        val = row[c]
                        opp = 'B' if val == 'W' else 'W'
                        # Left neighbor
                        if c > 0:
                            if row[c-1] is None:
                                g[r][c-1] = opp
                                changed = True
                            elif row[c-1] == val:
                                return None # Contradiction: XXX
                        # Right neighbor
                        if c + 2 < N:
                            if row[c+2] is None:
                                g[r][c+2] = opp
                                changed = True
                            elif row[c+2] == val:
                                return None # Contradiction: XXX

                # Rule 2: Pattern X_X implies middle is X
                for c in range(N - 2):
                    if row[c] is not None and row[c+2] is not None and row[c] == row[c+2]:
                        if row[c+1] is None:
                            g[r][c+1] = row[c]
                            changed = True
                        elif row[c+1] != row[c]:
                            return None # Contradiction

                # Rule 3: Equal number of B and W
                w_count = row.count('W')
                b_count = row.count('B')
                if w_count > limit or b_count > limit:
                    return None
                if w_count == limit:
                    for c in range(N):
                        if row[c] is None:
                            g[r][c] = 'B'
                            changed = True
                elif b_count == limit:
                    for c in range(N):
                        if row[c] is None:
                            g[r][c] = 'W'
                            changed = True

            # Process Columns
            for c in range(N):
                # Extract column
                col_vals = [g[r][c] for r in range(N)]
                limit = N // 2

                # Rule 1: No three consecutive
                for r in range(N - 1):
                    if col_vals[r] is not None and col_vals[r] == col_vals[r+1]:
                        val = col_vals[r]
                        opp = 'B' if val == 'W' else 'W'
                        # Up neighbor
                        if r > 0:
                            if g[r-1][c] is None:
                                g[r-1][c] = opp
                                changed = True
                            elif g[r-1][c] == val:
                                return None
                        # Down neighbor
                        if r + 2 < N:
                            if g[r+2][c] is None:
                                g[r+2][c] = opp
                                changed = True
                            elif g[r+2][c] == val:
                                return None

                # Rule 2: Pattern X_X
                for r in range(N - 2):
                    if col_vals[r] is not None and col_vals[r+2] is not None and col_vals[r] == col_vals[r+2]:
                        if g[r+1][c] is None:
                            g[r+1][c] = col_vals[r]
                            changed = True
                        elif g[r+1][c] != col_vals[r]:
                            return None

                # Rule 3: Count
                w_count = col_vals.count('W')
                b_count = col_vals.count('B')
                if w_count > limit or b_count > limit:
                    return None
                if w_count == limit:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True
                elif b_count == limit:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
        return g

    def check_uniqueness(g):
        """
        Checks if any completed rows or columns are identical.
        """
        # Check Rows
        completed_rows = []
        for r in range(N):
            if None not in g[r]:
                completed_rows.append(tuple(g[r]))
        if len(completed_rows) != len(set(completed_rows)):
            return False

        # Check Cols
        completed_cols = []
        for c in range(N):
            col = tuple(g[r][c] for r in range(N))
            if None not in col:
                completed_cols.append(col)
        if len(completed_cols) != len(set(completed_cols)):
            return False
        return True

    def is_solved(g):
        for r in range(N):
            if None in g[r]:
                return False
        return True

    def backtrack(g):
        # Apply logical deductions first
        g = propagate(g)
        if g is None:
            return None

        # Check global constraints (uniqueness)
        if not check_uniqueness(g):
            return None

        # Check if solved
        if is_solved(g):
            return g

        # Find an empty cell to branch on
        # Heuristic: Find cell in the most constrained row/col? 
        # For N=8, simple first-empty is usually sufficient given strong propagation.
        r_pick, c_pick = -1, -1
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    r_pick, c_pick = r, c
                    break
            if r_pick != -1: break

        if r_pick == -1: return None # Should be caught by is_solved

        # Try 'W'
        g_w = [list(row) for row in g]
        g_w[r_pick][c_pick] = 'W'
        res = backtrack(g_w)
        if res: return res

        # Try 'B'
        g_b = [list(row) for row in g]
        g_b[r_pick][c_pick] = 'B'
        res = backtrack(g_b)
        if res: return res

        return None

    result = backtrack(grid)
    return result

