OBSERVATION = {'data': [[None, None, 2, None, None, None, None], [None, 1, -1, None, None, -1, None], [None, None, None, None, None, 0, -1], [None, None, None, None, None, None, None], [0, -1, None, None, None, None, None], [None, 1, None, None, 1, 2, None], [None, None, None, None, -1, None, None]]}

def solve(observation):
    grid_data = observation['data']
    N = len(grid_data)

    # Identify black cells and white cells
    black_cells = {} # (r, c) -> value
    # white_cells are implicitly those not in black_cells

    for r in range(N):
        for c in range(N):
            val = grid_data[r][c]
            if val is not None: # It's a black cell (number or -1)
                black_cells[(r, c)] = val

    # Initial state
    bulbs = set()
    empty = set() # Cells that cannot have bulbs (includes black cells and lit white cells)

    # Initialize empty with black cells
    for pos in black_cells:
        empty.add(pos)

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    def get_line_of_sight(r, c):
        # Returns all cells visible from (r,c) excluding (r,c) itself
        visible = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            while 0 <= nr < N and 0 <= nc < N and (nr, nc) not in black_cells:
                visible.append((nr, nc))
                nr += dr
                nc += dc
        return visible

    def is_lit(r, c, current_bulbs):
        # Check if (r,c) is lit by any bulb in current_bulbs
        for br, bc in current_bulbs:
            if br == r:
                min_c, max_c = min(bc, c), max(bc, c)
                blocked = False
                for k in range(min_c + 1, max_c):
                    if (r, k) in black_cells:
                        blocked = True
                        break
                if not blocked:
                    return True
            elif bc == c:
                min_r, max_r = min(br, r), max(br, r)
                blocked = False
                for k in range(min_r + 1, max_r):
                    if (k, c) in black_cells:
                        blocked = True
                        break
                if not blocked:
                    return True
        return False

    def propagate(bulbs, empty):
        changed = True
        while changed:
            changed = False

            # 1. Numbered Cell Constraints
            for (r, c), val in black_cells.items():
                if val == -1: continue 

                neighbors = get_neighbors(r, c)
                white_neighbors = [n for n in neighbors if n not in black_cells]

                current_bulb_count = sum(1 for n in white_neighbors if n in bulbs)

                if current_bulb_count > val:
                    return None, None, "invalid" 

                available_neighbors = [n for n in white_neighbors if n not in bulbs and n not in empty]

                if current_bulb_count == val:
                    for n in available_neighbors:
                        if n not in empty:
                            empty.add(n)
                            changed = True
                elif current_bulb_count + len(available_neighbors) == val:
                    for n in available_neighbors:
                        if n not in bulbs:
                            bulbs.add(n)
                            changed = True

            # 2. Bulb Line of Sight Constraints
            bulbs_list = list(bulbs) 
            for b in bulbs_list:
                visible = get_line_of_sight(b[0], b[1])
                for v in visible:
                    if v in bulbs:
                        return None, None, "invalid" 
                    if v not in empty:
                        empty.add(v)
                        changed = True

            # 3. Unlit Cell Constraints (Forced Moves)
            # Identify currently unlit white cells
            unlit_white_cells = []
            for r in range(N):
                for c in range(N):
                    if (r, c) in black_cells: continue
                    if not is_lit(r, c, bulbs):
                        unlit_white_cells.append((r, c))

            for cell in unlit_white_cells:
                r, c = cell
                # If it got lit by a previous step in this loop, skip
                if is_lit(r, c, bulbs):
                    continue

                candidates = set()

                # Row segment candidates
                nc = c - 1
                while nc >= 0 and (r, nc) not in black_cells:
                    if (r, nc) not in empty:
                        candidates.add((r, nc))
                    nc -= 1
                nc = c + 1
                while nc < N and (r, nc) not in black_cells:
                    if (r, nc) not in empty:
                        candidates.add((r, nc))
                    nc += 1

                # Col segment candidates
                nr = r - 1
                while nr >= 0 and (nr, c) not in black_cells:
                    if (nr, c) not in empty:
                        candidates.add((nr, c))
                    nr -= 1
                nr = r + 1
                while nr < N and (nr, c) not in black_cells:
                    if (nr, c) not in empty:
                        candidates.add((nr, c))
                    nr += 1

                # The cell itself
                if (r, c) not in empty:
                    candidates.add((r, c))

                if not candidates:
                    return None, None, "invalid" 

                if len(candidates) == 1:
                    cand = candidates.pop()
                    if cand not in bulbs:
                        bulbs.add(cand)
                        changed = True

        # Check if solved (all white cells lit)
        for r in range(N):
            for c in range(N):
                if (r, c) in black_cells: continue
                if not is_lit(r, c, bulbs):
                    return bulbs, empty, "stuck" 

        return bulbs, empty, "solved"

    def backtrack(bulbs, empty):
        bulbs, empty, status = propagate(bulbs, empty)

        if status == "invalid":
            return None
        if status == "solved":
            return bulbs

        # Pick a cell to branch
        branch_cell = None
        for r in range(N):
            for c in range(N):
                if (r, c) in black_cells: continue
                if (r, c) not in bulbs and (r, c) not in empty:
                    branch_cell = (r, c)
                    break
            if branch_cell: break

        if not branch_cell:
            return None

        r, c = branch_cell

        # Try placing bulb
        new_bulbs = set(bulbs)
        new_bulbs.add((r, c))
        new_empty = set(empty)

        res = backtrack(new_bulbs, new_empty)
        if res:
            return res

        # Try marking empty
        new_empty2 = set(empty)
        new_empty2.add((r, c))
        res = backtrack(bulbs, new_empty2)
        if res:
            return res

        return None

    final_bulbs = backtrack(bulbs, empty)

    if final_bulbs is None:
        return "No Solution"

    result_grid = [[None for _ in range(N)] for _ in range(N)]
    for r, c in final_bulbs:
        result_grid[r][c] = 'B'

    return result_grid

