                        if grid[u[0]][u[1]] is None:
                            grid[u[0]][u[1]] = 'W'
                            changed = True

                # Deduction 2: If we need all remaining to be black to reach val
                elif blacks + len(unknowns) == val:
                    for u in unknowns:
                        if grid[u[0]][u[1]] is None:
                            grid[u[0]][u[1]] = 'B'
                            changed = True
        return grid

    def get_unassigned_cell(grid):
