            unknowns = [n for n in neighbors if grid[n[0]][n[1]] is None]
            # We want constraints that are "tight" - few unknowns left
            if 0 < len(unknowns) < min_unknowns:
                min_unknowns = len(unknowns)
                best_cell = unknowns[0]
                if min_unknowns == 1: # Optimization: can't get better than 1
                    break 

        if best_cell:
            return best_cell

        # Fallback: any unassigned cell
        for r in range(rows):
            for c in range(cols):
