        grid_b = [row[:] for row in grid]
        grid_b[r][c] = 'B'
        res = backtrack(grid_b)
        if res is not None:
            return res

        # Try White
        grid_w = [row[:] for row in grid]
        grid_w[r][c] = 'W'
        res = backtrack(grid_w)
        if res is not None:
            return res

        return None

    final_grid = backtrack(initial_grid)

    if final_grid is None:
        return "No Solution"

    # Convert to output format: 'B' -> 'B', 'W' -> None
    output_grid = []
    for r in range(rows):
        row_out = []
        for c in range(cols):
            if final_grid[r][c] == 'B':
                row_out.append('B')
            else:
                row_out.append(None)
        output_grid.append(row_out)

    return output_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
