                for c in range(N - 2):
                    # Pattern X X _ -> _ must be opposite
                    if g[r][c] is not None and g[r][c] == g[r][c+1]:
                        val = 'W' if g[r][c] == 'B' else 'B'
                        if g[r][c+2] is None:
                            g[r][c+2] = val
                            changed = True
                        elif g[r][c+2] != val:
                            return False # Contradiction
                    # Pattern _ X X
                    if g[r][c+1] is not None and g[r][c+1] == g[r][c+2]:
                        val = 'W' if g[r][c+1] == 'B' else 'B'
                        if g[r][c] is None:
                            g[r][c] = val
                            changed = True
                        elif g[r][c] != val:
                            return False
                    # Pattern X _ X
                    if g[r][c] is not None and g[r][c] == g[r][c+2]:
                        val = 'W' if g[r][c] == 'B' else 'B'
                        if g[r][c+1] is None:
                            g[r][c+1] = val
                            changed = True
                        elif g[r][c+1] != val:
                            return False

            # Cols
            for c in range(N):
                for r in range(N - 2):
                    if g[r][c] is not None and g[r][c] == g[r+1][c]:
                        val = 'W' if g[r][c] == 'B' else 'B'
                        if g[r+2][c] is None:
                            g[r+2][c] = val
                            changed = True
                        elif g[r+2][c] != val:
                            return False
                    if g[r+1][c] is not None and g[r+1][c] == g[r+2][c]:
                        val = 'W' if g[r+1][c] == 'B' else 'B'
                        if g[r][c] is None:
                            g[r][c] = val
                            changed = True
                        elif g[r][c] != val:
                            return False
                    if g[r][c] is not None and g[r][c] == g[r+2][c]:
                        val = 'W' if g[r][c] == 'B' else 'B'
                        if g[r+1][c] is None:
                            g[r+1][c] = val
                            changed = True
                        elif g[r+1][c] != val:
                            return False

            # Rule 2: Equal counts
            # Rows
            for r in range(N):
                b_count = g[r].count('B')
                w_count = g[r].count('W')
                if b_count == HALF:
                    for c in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == HALF:
                    for c in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            # Cols
            for c in range(N):
                col = [g[r][c] for r in range(N)]
                b_count = col.count('B')
                w_count = col.count('W')
                if b_count == HALF:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == HALF:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            # Rule 3: Uniqueness
            # Check completed rows for duplicates
            completed_rows = []
            for r in range(N):
                if None not in g[r]:
                    completed_rows.append((r, tuple(g[r])))

            row_tuples = [t for _, t in completed_rows]
            if len(row_tuples) != len(set(row_tuples)):
                return False

            # Check rows with 1 empty spot
            for r in range(N):
                if g[r].count(None) == 1:
                    empty_c = g[r].index(None)
                    temp_row_b = g[r][:]
                    temp_row_b[empty_c] = 'B'
                    temp_row_w = g[r][:]
                    temp_row_w[empty_c] = 'W'

                    for other_r, other_tuple in completed_rows:
                        if other_r == r: continue
                        if tuple(temp_row_b) == other_tuple:
                            if g[r][empty_c] == 'B': return False
                            g[r][empty_c] = 'W'
                            changed = True
                        if tuple(temp_row_w) == other_tuple:
                            if g[r][empty_c] == 'W': return False
                            g[r][empty_c] = 'B'
                            changed = True

            # Check completed cols for duplicates
            completed_cols = []
            for c in range(N):
                col = [g[r][c] for r in range(N)]
                if None not in col:
                    completed_cols.append((c, tuple(col)))

            col_tuples = [t for _, t in completed_cols]
            if len(col_tuples) != len(set(col_tuples)):
                return False

            # Check cols with 1 empty spot
            for c in range(N):
                col = [g[r][c] for r in range(N)]
                if col.count(None) == 1:
                    empty_r = col.index(None)
                    temp_col_b = col[:]
                    temp_col_b[empty_r] = 'B'
                    temp_col_w = col[:]
                    temp_col_w[empty_r] = 'W'

                    for other_c, other_tuple in completed_cols:
                        if other_c == c: continue
                        if tuple(temp_col_b) == other_tuple:
                            if g[empty_r][c] == 'B': return False
                            g[empty_r][c] = 'W'
                            changed = True
                        if tuple(temp_col_w) == other_tuple:
                            if g[empty_r][c] == 'W': return False
                            g[empty_r][c] = 'B'
                            changed = True

        return True

    def solve_recursive(g):
        if not propagate(g):
            return None

        is_full = True
        first_empty = None
        for i in range(N):
            for j in range(N):
                if g[i][j] is None:
                    is_full = False
                    first_empty = (i, j)
                    break
            if not is_full: break

        if is_full:
            rows = [tuple(r) for r in g]
            if len(rows) != len(set(rows)): return None
            cols = [tuple(g[r][c] for r in range(N)) for c in range(N)]
            if len(cols) != len(set(cols)): return None
            return g

        r, c = first_empty

        g_b = [row[:] for row in g]
        g_b[r][c] = 'B'
        res = solve_recursive(g_b)
        if res: return res

        g_w = [row[:] for row in g]
        g_w[r][c] = 'W'
        res = solve_recursive(g_w)
        if res: return res

        return None

    result = solve_recursive(grid)
    if result:
        return result
    return "No Solution"

