def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    n_rows = len(row_targets)
    n_cols = len(col_targets)

    # Weights are 1-based indices as per image labels (1..7)
    col_weights = list(range(1, n_cols + 1))
    row_weights = list(range(1, n_rows + 1))

    # Precompute candidates
    # row_candidates[r] = list of masks (bits for cols)
    row_candidates = []
    for r in range(n_rows):
        target = row_targets[r]
        candidates = []
        # Iterate all subsets of cols (2^7 = 128 max)
        for i in range(1 << n_cols):
            current_sum = 0
            for c in range(n_cols):
                if (i >> c) & 1:
                    current_sum += col_weights[c]
            if current_sum == target:
                candidates.append(i)
        row_candidates.append(candidates)

    # col_candidates[c] = list of masks (bits for rows)
    col_candidates = []
    for c in range(n_cols):
        target = col_targets[c]
        candidates = []
        for i in range(1 << n_rows):
            current_sum = 0
            for r in range(n_rows):
                if (i >> r) & 1:
                    current_sum += row_weights[r]
            if current_sum == target:
                candidates.append(i)
        col_candidates.append(candidates)

    # Grid state: -1 unknown, 0 white (None), 1 black ('B')
    grid = [[-1] * n_cols for _ in range(n_rows)]

    # Current valid candidates (mutable)
    current_row_cands = [list(c) for c in row_candidates]
    current_col_cands = [list(c) for c in col_candidates]

    def propagate():
        changed = True
        while changed:
            changed = False

            # Filter row candidates based on grid
            for r in range(n_rows):
                new_cands = []
                for mask in current_row_cands[r]:
                    valid = True
                    for c in range(n_cols):
                        cell_val = grid[r][c]
                        is_black = (mask >> c) & 1
                        if cell_val == 1 and not is_black: 
                            valid = False; break
                        if cell_val == 0 and is_black: 
                            valid = False; break
                    if valid:
                        new_cands.append(mask)

                if len(new_cands) < len(current_row_cands[r]):
                    current_row_cands[r] = new_cands
                    changed = True
                    if not new_cands: return False 

            # Filter col candidates based on grid
            for c in range(n_cols):
                new_cands = []
                for mask in current_col_cands[c]:
                    valid = True
                    for r in range(n_rows):
                        cell_val = grid[r][c]
                        is_black = (mask >> r) & 1
                        if cell_val == 1 and not is_black:
                            valid = False; break
                        if cell_val == 0 and is_black:
                            valid = False; break
                    if valid:
                        new_cands.append(mask)

                if len(new_cands) < len(current_col_cands[c]):
                    current_col_cands[c] = new_cands
                    changed = True
                    if not new_cands: return False

            # Deduce from candidates (Intersection/Union)
            # Row deductions
            for r in range(n_rows):
                if not current_row_cands[r]: return False

                all_ones = (1 << n_cols) - 1
                intersection = all_ones
                union = 0

                for mask in current_row_cands[r]:
                    intersection &= mask
                    union |= mask

                for c in range(n_cols):
                    # If bit is 1 in all masks -> Must be Black
                    if (intersection >> c) & 1:
                        if grid[r][c] != 1:
                            grid[r][c] = 1
                            changed = True
                    # If bit is 0 in all masks (i.e. not in union) -> Must be White
                    if not ((union >> c) & 1):
                        if grid[r][c] != 0:
                            grid[r][c] = 0
                            changed = True

            # Col deductions
            for c in range(n_cols):
                if not current_col_cands[c]: return False

                all_ones = (1 << n_rows) - 1
                intersection = all_ones
                union = 0

                for mask in current_col_cands[c]:
                    intersection &= mask
                    union |= mask

                for r in range(n_rows):
                    if (intersection >> r) & 1:
                        if grid[r][c] != 1:
                            grid[r][c] = 1
                            changed = True
                    if not ((union >> r) & 1):
                        if grid[r][c] != 0:
                            grid[r][c] = 0
                            changed = True

        return True

    def solve_recursive():
        if not propagate():
            return False

        # Check if solved
        is_full = True
        for r in range(n_rows):
            for c in range(n_cols):
                if grid[r][c] == -1:
                    is_full = False
                    break
            if not is_full: break

        if is_full:
            return True

        # MRV Heuristic (Minimum Remaining Values)
        best_r, best_c = -1, -1
        min_options = float('inf')

        for r in range(n_rows):
            for c in range(n_cols):
                if grid[r][c] == -1:
                    # Heuristic: sum of remaining candidates for row and col
                    score = len(current_row_cands[r]) + len(current_col_cands[c])
                    if score < min_options:
                        min_options = score
                        best_r, best_c = r, c

        if best_r == -1: return False 

        r, c = best_r, best_c

        # Save state for backtracking
        saved_grid = [row[:] for row in grid]
        saved_row_cands = [list(lst) for lst in current_row_cands]
        saved_col_cands = [list(lst) for lst in current_col_cands]

        # Try Black (1)
        grid[r][c] = 1
        if solve_recursive():
            return True

        # Restore
        for i in range(n_rows):
            for j in range(n_cols):
                grid[i][j] = saved_grid[i][j]
        for i in range(n_rows):
            current_row_cands[i] = saved_row_cands[i]
        for i in range(n_cols):
            current_col_cands[i] = saved_col_cands[i]

        # Try White (0)
        grid[r][c] = 0
        if solve_recursive():
            return True

        # Restore
        for i in range(n_rows):
            for j in range(n_cols):
                grid[i][j] = saved_grid[i][j]
        grid[r][c] = -1 

        return False

    if solve_recursive():
        result_grid = []
        for r in range(n_rows):
            row_res = []
            for c in range(n_cols):
                if grid[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result_grid.append(row_res)
        return str(result_grid)
    else:
        return "No Solution"

