def solve(observation):
    region_map = observation['region']
    data = observation['data']
    N = len(region_map)

    # Precompute region info
    regions = {} 
    for r in range(N):
        for c in range(N):
            rid = region_map[r][c]
            if rid not in regions:
                regions[rid] = {'cells': [], 'clue': None}
            regions[rid]['cells'].append((r, c))
            if data[r][c] is not None:
                regions[rid]['clue'] = data[r][c]

    # Grid state: 0=Unknown, 1=White, 2=Black
    grid = [[0]*N for _ in range(N)]

    # Precompute neighbors
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighbors[(r,c)] = []
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighbors[(r,c)].append((nr, nc))

    def is_valid_partial():
        # Check black adjacency
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 2: 
                    for nr, nc in neighbors[(r,c)]:
                        if grid[nr][nc] == 2:
                            return False

        # Check region counts (upper bound)
        for rid, info in regions.items():
            clue = info['clue']
            if clue is not None:
                black_count = sum(1 for r, c in info['cells'] if grid[r][c] == 2)
                if black_count > clue:
                    return False

        # Check white segment rule
        # Scan rows
        for r in range(N):
            current_segment_regions = set()
            for c in range(N):
                if grid[r][c] == 1: 
                    current_segment_regions.add(region_map[r][c])
                    if len(current_segment_regions) > 2:
                        return False
                else:
                    current_segment_regions = set()

        # Scan cols
        for c in range(N):
            current_segment_regions = set()
            for r in range(N):
                if grid[r][c] == 1: 
                    current_segment_regions.add(region_map[r][c])
                    if len(current_segment_regions) > 2:
                        return False
                else:
                    current_segment_regions = set()

        return True

    def solve_recursive(idx):
        if idx == N*N:
            # Check connectivity
            start = None
            white_count = 0
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 1:
                        white_count += 1
                        if start is None:
                            start = (r, c)

            if white_count == 0:
                # If no white cells, check if valid (usually not, but technically connected)
                # However, clue 0 implies white cells exist.
                pass 

            if start:
                visited = set()
                queue = [start]
                visited.add(start)
                while queue:
                    curr = queue.pop(0)
                    for nb in neighbors[curr]:
                        if grid[nb[0]][nb[1]] == 1 and nb not in visited:
                            visited.add(nb)
                            queue.append(nb)

                if len(visited) != white_count:
                    return False

            # Check region counts (exact)
            for rid, info in regions.items():
                clue = info['clue']
                if clue is not None:
                    black_count = sum(1 for r, c in info['cells'] if grid[r][c] == 2)
                    if black_count != clue:
                        return False
            return True

        r, c = divmod(idx, N)
        rid = region_map[r][c]

        # Try Black
        can_black = True

        # Check neighbors
        for nr, nc in neighbors[(r,c)]:
            if grid[nr][nc] == 2:
                can_black = False
                break

        if can_black:
            # Check region count
            if regions[rid]['clue'] is not None:
                current_blacks = sum(1 for rr, cc in regions[rid]['cells'] if grid[rr][cc] == 2)
                if current_blacks >= regions[rid]['clue']:
                    can_black = False

            if can_black:
                grid[r][c] = 2
                if is_valid_partial():
                    if solve_recursive(idx + 1):
                        return True
                grid[r][c] = 0

        # Try White
        can_white = True

        # Check region count lower bound
        if regions[rid]['clue'] is not None:
            current_blacks = sum(1 for rr, cc in regions[rid]['cells'] if grid[rr][cc] == 2)
            unknown_cells = sum(1 for rr, cc in regions[rid]['cells'] if grid[rr][cc] == 0)
            # We are setting one unknown to White
            if current_blacks + (unknown_cells - 1) < regions[rid]['clue']:
                can_white = False

        if can_white:
            grid[r][c] = 1
            if is_valid_partial():
                if solve_recursive(idx + 1):
                    return True
            grid[r][c] = 0

        return False

    if solve_recursive(0):
        result = []
        for r in range(N):
            row = []
            for c in range(N):
                if grid[r][c] == 2:
                    row.append('B')
                else:
                    row.append(None)
            result.append(row)
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
