def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']
    N = len(region_grid)

    # Parse regions
    regions = {}
    clues = {}
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

            val = data_grid[r][c]
            if val is not None:
                # If a region has multiple clues, this logic assumes they are consistent or we take one.
                # Based on image analysis, each region has at most one clue.
                # If a region has multiple clues (e.g. 0 and 2), it's a contradiction unless interpreted differently.
                # But my parsing ensures one clue per region.
                clues[rid] = val

    # State: -1 Unknown, 0 White, 1 Black
    grid = [[-1 for _ in range(N)] for _ in range(N)]

    # Pre-calculate region info
    region_cells = regions
    region_clues = clues

    # Helper to get neighbors
    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    # Check constraints
    def is_valid_state():
        # 1. Region counts
        for rid, cells in region_cells.items():
            if rid in region_clues:
                target = region_clues[rid]
                black_count = 0
                unknown_count = 0
                for r, c in cells:
                    if grid[r][c] == 1:
                        black_count += 1
                    elif grid[r][c] == -1:
                        unknown_count += 1

                if black_count > target:
                    return False
                if black_count + unknown_count < target:
                    return False

        # 2. Black cells cannot touch
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 1:
                    for nr, nc in get_neighbors(r, c):
                        if grid[nr][nc] == 1:
                            return False

        # 3. White segment region count <= 2
        # Check rows
        for r in range(N):
            c = 0
            while c < N:
                if grid[r][c] == 0: # White
                    start_c = c
                    regions_in_segment = set()
                    while c < N and grid[r][c] == 0:
                        regions_in_segment.add(region_grid[r][c])
                        c += 1
                    if len(regions_in_segment) > 2:
                        return False
                else:
                    c += 1

        # Check cols
        for c in range(N):
            r = 0
            while r < N:
                if grid[r][c] == 0: # White
                    start_r = r
                    regions_in_segment = set()
                    while r < N and grid[r][c] == 0:
                        regions_in_segment.add(region_grid[r][c])
                        r += 1
                    if len(regions_in_segment) > 2:
                        return False
                else:
                    r += 1

        return True

    def is_connected():
        # Find first white cell
        start = None
        white_count = 0
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    white_count += 1
                    if start is None:
                        start = (r, c)

        if white_count == 0:
            return True # No white cells, trivially connected? Or invalid? Usually at least one white.

        visited = set()
        stack = [start]
        visited.add(start)

        while stack:
            r, c = stack.pop()
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        return len(visited) == white_count

    # Initial deductions
    # Clue 0 -> All White
    for rid, target in region_clues.items():
        if target == 0:
            for r, c in region_cells[rid]:
                grid[r][c] = 0

    # Clue == Size -> All Black (Check validity)
    # Note: If size > 1, all black is impossible due to touching rule.
    # So this case implies size must be 1.
    for rid, target in region_clues.items():
        if target == len(region_cells[rid]):
            if target == 1:
                r, c = region_cells[rid][0]
                grid[r][c] = 1
            else:
                # Impossible state
                return "No Solution"

    # Propagate Black -> Neighbors White
    changed = True
    while changed:
        changed = False
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 1:
                    for nr, nc in get_neighbors(r, c):
                        if grid[nr][nc] == -1:
                            grid[nr][nc] = 0
                            changed = True
                        elif grid[nr][nc] == 1:
                            return "No Solution" # Touching black

    # Backtracking
    # Flatten cells for ordering
    cells = [(r, c) for r in range(N) for c in range(N)]

    # Heuristic: Sort cells. 
    # Prioritize cells in regions with clues, or cells that are constrained.
    # Simple order is fine for 8x8 with strong pruning.

    def backtrack(idx):
        if idx == len(cells):
            if is_connected():
                return True
            return False

        r, c = cells[idx]
        if grid[r][c] != -1:
            return backtrack(idx + 1)

        # Try Black
        # Check if placing Black is valid locally
        # 1. Neighbors not Black
        can_black = True
        for nr, nc in get_neighbors(r, c):
            if grid[nr][nc] == 1:
                can_black = False
                break

        if can_black:
            # Check region count
            rid = region_grid[r][c]
            if rid in region_clues:
                target = region_clues[rid]
                current_black = sum(1 for rr, cc in region_cells[rid] if grid[rr][cc] == 1)
                if current_black + 1 > target:
                    can_black = False

            if can_black:
                grid[r][c] = 1
                # Propagate neighbors to White
                neighbors_to_reset = []
                for nr, nc in get_neighbors(r, c):
                    if grid[nr][nc] == -1:
                        grid[nr][nc] = 0
                        neighbors_to_reset.append((nr, nc))
                    elif grid[nr][nc] == 1:
                        # Should be caught by can_black check, but double check
                        grid[r][c] = -1
                        for nr2, nc2 in neighbors_to_reset:
                            grid[nr2][nc2] = -1
                        return False # Should not happen if check is correct

                # Check white segments (placing black breaks segments, so usually safe, 
                # but we need to ensure we didn't isolate white areas? No, connectivity check at end)
                # Actually, placing black might create a white segment that is valid.
                # The constraint is "White segment <= 2 regions". Placing black shortens segments.
                # So placing black never violates Rule 3.

                if backtrack(idx + 1):
                    return True

                # Backtrack
                grid[r][c] = -1
                for nr, nc in neighbors_to_reset:
                    grid[nr][nc] = -1

        # Try White
        # Check if placing White is valid
        # 1. White segment constraint
        # Temporarily set to 0
        grid[r][c] = 0

        # Check row segment
        valid_white = True

        # Check Row
        c_start = c
        while c_start > 0 and grid[r][c_start-1] == 0:
            c_start -= 1
        c_end = c
        while c_end < N - 1 and grid[r][c_end+1] == 0:
            c_end += 1

        regions_in_row = set()
        for cc in range(c_start, c_end + 1):
            regions_in_row.add(region_grid[r][cc])
        if len(regions_in_row) > 2:
            valid_white = False

        if valid_white:
            # Check Col
            r_start = r
            while r_start > 0 and grid[r_start-1][c] == 0:
                r_start -= 1
            r_end = r
            while r_end < N - 1 and grid[r_end+1][c] == 0:
                r_end += 1

            regions_in_col = set()
            for rr in range(r_start, r_end + 1):
                regions_in_col.add(region_grid[rr][c])
            if len(regions_in_col) > 2:
                valid_white = False

        if valid_white:
            # Check region count (if placing white makes it impossible to reach target)
            rid = region_grid[r][c]
            if rid in region_clues:
                target = region_clues[rid]
                current_black = sum(1 for rr, cc in region_cells[rid] if grid[rr][cc] == 1)
                unknown_remaining = sum(1 for rr, cc in region_cells[rid] if grid[rr][cc] == -1)
                # We just set one unknown to white, so unknown_remaining decreased by 1 (conceptually)
                # But in the grid it's 0 now.
                # So max possible black = current_black + (unknown_remaining - 1)
                # Wait, I need to count unknowns in the region *excluding* current cell which is now 0.
                max_possible_black = current_black + sum(1 for rr, cc in region_cells[rid] if grid[rr][cc] == -1)
                if max_possible_black < target:
                    valid_white = False

            if valid_white:
                if backtrack(idx + 1):
                    return True

        # Backtrack
        grid[r][c] = -1
        return False

    if backtrack(0):
        # Format output
        result = []
        for r in range(N):
            row_res = []
            for c in range(N):
                if grid[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
