def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    # State: 'MINE', 'SAFE', 'UNKNOWN'
    grid_state = [['UNKNOWN' for _ in range(cols)] for _ in range(rows)]

    constraints = []

    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is not None:
                grid_state[r][c] = 'SAFE'
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neighbors.append((nr, nc))

                unknown_neighbors = set()
                for n in neighbors:
                    if data[n[0]][n[1]] is None:
                        unknown_neighbors.add(n)

                constraints.append({
                    'cells': unknown_neighbors,
                    'val': val,
                    'source': (r, c)
                })

    def propagate(state, cons_list):
        changed = True
        contradiction = False

        while changed:
            changed = False

            # 1. Basic Rules
            for con in cons_list:
                if con['val'] < 0:
                    contradiction = True
                    return state, cons_list, False, True

                mines_found = 0
                unknowns = []
                for cell in con['cells']:
                    r, c = cell
                    if state[r][c] == 'MINE':
                        mines_found += 1
                    elif state[r][c] == 'UNKNOWN':
                        unknowns.append(cell)

                needed = con['val'] - mines_found

                if needed < 0:
                    contradiction = True
                    return state, cons_list, False, True

                if len(unknowns) == 0:
                    if needed != 0:
                        contradiction = True
                        return state, cons_list, False, True
                    continue

                if needed == 0:
                    for u in unknowns:
                        if state[u[0]][u[1]] == 'UNKNOWN':
                            state[u[0]][u[1]] = 'SAFE'
                            changed = True
                elif needed == len(unknowns):
                    for u in unknowns:
                        if state[u[0]][u[1]] == 'UNKNOWN':
                            state[u[0]][u[1]] = 'MINE'
                            changed = True

            if contradiction: return state, cons_list, False, True
            if not changed:
                # 2. Subset Logic
                snapshot = list(cons_list)
                for i in range(len(snapshot)):
                    for j in range(i + 1, len(snapshot)):
                        c1 = snapshot[i]
                        c2 = snapshot[j]

                        m1 = sum(1 for cell in c1['cells'] if state[cell[0]][cell[1]] == 'MINE')
                        u1 = set(cell for cell in c1['cells'] if state[cell[0]][cell[1]] == 'UNKNOWN')
                        needed1 = c1['val'] - m1

                        m2 = sum(1 for cell in c2['cells'] if state[cell[0]][cell[1]] == 'MINE')
                        u2 = set(cell for cell in c2['cells'] if state[cell[0]][cell[1]] == 'UNKNOWN')
                        needed2 = c2['val'] - m2

                        if u1.issubset(u2) and u1 != u2:
                            diff = u2 - u1
                            diff_needed = needed2 - needed1

                            if diff_needed < 0 or diff_needed > len(diff):
                                contradiction = True
                                return state, cons_list, False, True

                            if diff_needed == 0:
                                for u in diff:
                                    if state[u[0]][u[1]] == 'UNKNOWN':
                                        state[u[0]][u[1]] = 'SAFE'
                                        changed = True
                            elif diff_needed == len(diff):
                                for u in diff:
                                    if state[u[0]][u[1]] == 'UNKNOWN':
                                        state[u[0]][u[1]] = 'MINE'
                                        changed = True
                            else:
                                is_new = True
                                for existing in cons_list:
                                    ex_m = sum(1 for cell in existing['cells'] if state[cell[0]][cell[1]] == 'MINE')
                                    ex_u = set(cell for cell in existing['cells'] if state[cell[0]][cell[1]] == 'UNKNOWN')
                                    ex_needed = existing['val'] - ex_m

                                    if ex_u == diff and ex_needed == diff_needed:
                                        is_new = False
                                        break

                                if is_new:
                                    cons_list.append({'cells': diff, 'val': diff_needed, 'source': 'derived'})
                                    changed = True

                if changed: continue

        return state, cons_list, changed, contradiction

    def backtrack(state, cons_list):
        current_state = [row[:] for row in state]
        current_cons = copy.deepcopy(cons_list)

        current_state, current_cons, _, contradiction = propagate(current_state, current_cons)

        if contradiction:
            return None

        unknowns = []
        for r in range(rows):
            for c in range(cols):
                if current_state[r][c] == 'UNKNOWN':
                    unknowns.append((r, c))

        if not unknowns:
            return current_state

        best_u = None
        max_constraints = -1

        for u in unknowns:
            count = 0
            for con in current_cons:
                if u in con['cells']:
                    count += 1
            if count > max_constraints:
                max_constraints = count
                best_u = u

        if best_u is None:
            best_u = unknowns[0]

        r, c = best_u

        state_mine = [row[:] for row in current_state]
        state_mine[r][c] = 'MINE'
        cons_mine = copy.deepcopy(current_cons)

        res = backtrack(state_mine, cons_mine)
        if res: return res

        state_safe = [row[:] for row in current_state]
        state_safe[r][c] = 'SAFE'
        cons_safe = copy.deepcopy(current_cons)

        res = backtrack(state_safe, cons_safe)
        if res: return res

        return None

    initial_state = [row[:] for row in grid_state]
    initial_cons = copy.deepcopy(constraints)

    final_state, final_cons, _, contradiction = propagate(initial_state, initial_cons)

    if contradiction:
        return "No Solution"

    solved = True
    for r in range(rows):
        for c in range(cols):
            if final_state[r][c] == 'UNKNOWN':
                solved = False
                break
        if not solved: break

    if solved:
        res_state = final_state
    else:
        res_state = backtrack(final_state, final_cons)

    if res_state is None:
        return "No Solution"

    output_grid = []
    for r in range(rows):
        row_out = []
        for c in range(cols):
            if data[r][c] is not None:
                row_out.append(None)
            else:
                if res_state[r][c] == 'MINE':
                    row_out.append('F')
                else:
                    row_out.append(None)
        output_grid.append(row_out)

    return output_grid

