def solve(observation):
    import sys
    sys.setrecursionlimit(2000)

    region_map = observation['region']
    data = observation['data']
    N = len(region_map)

    # Identify regions and their clues
    region_clues = {}
    for r in range(N):
        for c in range(N):
            rid = region_map[r][c]
            val = data[r][c]
            if val is not None:
                # If a region has multiple clues, they should be consistent (or we take the max/first)
                # Assuming consistent or single clue per region based on puzzle type
                if rid not in region_clues:
                    region_clues[rid] = val
                else:
                    # Should not happen in valid puzzles, but just in case
                    pass

    # Identify all region IDs
    all_regions = set()
    for r in range(N):
        for c in range(N):
            all_regions.add(region_map[r][c])

    # Determine target black counts for each region
    # Rule: "A numbered region contains exactly that many black cells."
    # Assumption: Unnumbered regions contain 0 black cells.
    region_target_black = {}
    for rid in all_regions:
        if rid in region_clues:
            region_target_black[rid] = region_clues[rid]
        else:
            region_target_black[rid] = 0

    # Classify cells
    # Fixed White: Regions with target 0
    # Variable: Regions with target > 0
    fixed_white = set()
    variable_cells = [] # List of (r, c)

    for r in range(N):
        for c in range(N):
            rid = region_map[r][c]
            if region_target_black[rid] == 0:
                fixed_white.add((r, c))
            else:
                variable_cells.append((r, c))

    # Group variable cells by region
    variable_regions = {}
    for r, c in variable_cells:
        rid = region_map[r][c]
        if rid not in variable_regions:
            variable_regions[rid] = []
        variable_regions[rid].append((r, c))

    # We need to select exactly K black cells for each variable region
    # K = region_target_black[rid]

    # Backtracking state
    # grid: N x N, None (unknown), 'B' (black), None (white - wait, let's use 'W' for white to be explicit)
    # Actually, let's use a set for black cells. All others are white.

    current_black_cells = set()

    # Pre-calculate neighbors for "No Touching" check
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighs = []
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighs.append((nr, nc))
            neighbors[(r, c)] = neighs

    def is_valid_partial(black_set):
        # Check "Black cells cannot touch orthogonally"
        for (r, c) in black_set:
            for nr, nc in neighbors[(r, c)]:
                if (nr, nc) in black_set:
                    return False
        return True

    def check_white_segments(black_set):
        # "Any uninterrupted straight white segment (row/column) cannot pass through more than 2 regions."
        # White cells are all cells NOT in black_set.

        # Check Rows
        for r in range(N):
            regions_in_segment = set()
            for c in range(N):
                if (r, c) in black_set:
                    regions_in_segment = set() # Reset segment
                else:
                    rid = region_map[r][c]
                    regions_in_segment.add(rid)
                    if len(regions_in_segment) > 2:
                        return False

        # Check Cols
        for c in range(N):
            regions_in_segment = set()
            for r in range(N):
                if (r, c) in black_set:
                    regions_in_segment = set() # Reset segment
                else:
                    rid = region_map[r][c]
                    regions_in_segment.add(rid)
                    if len(regions_in_segment) > 2:
                        return False
        return True

    def check_connectivity(black_set):
        # "All white cells are orthogonally connected."
        white_cells = []
        for r in range(N):
            for c in range(N):
                if (r, c) not in black_set:
                    white_cells.append((r, c))

        if not white_cells:
            return True # No white cells? (Unlikely)

        start = white_cells[0]
        visited = set()
        stack = [start]
        visited.add(start)

        while stack:
            curr = stack.pop()
            for nr, nc in neighbors[curr]:
                if (nr, nc) not in black_set and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        return len(visited) == len(white_cells)

    # Solver
    # We process region by region to reduce branching factor
    region_ids = sorted(variable_regions.keys())

    def solve_region(idx, current_black_set):
        if idx == len(region_ids):
            # All regions assigned
            # Check global constraints
            if not check_white_segments(current_black_set):
                return None
            if not check_connectivity(current_black_set):
                return None
            return current_black_set

        rid = region_ids[idx]
        cells = variable_regions[rid]
        k = region_target_black[rid]

        # We need to choose k cells from 'cells' to be black
        # Generate combinations
        from itertools import combinations

        for combo in combinations(cells, k):
            new_black_set = current_black_set | set(combo)

            # Pruning 1: No touching
            # Check only new cells against existing and each other
            valid = True
            combo_list = list(combo)
            for i in range(len(combo_list)):
                r, c = combo_list[i]
                # Check against existing
                for nr, nc in neighbors[(r, c)]:
                    if (nr, nc) in current_black_set:
                        valid = False
                        break
                if not valid: break
                # Check against other new cells
                for j in range(i + 1, len(combo_list)):
                    r2, c2 = combo_list[j]
                    if abs(r - r2) + abs(c - c2) == 1:
                        valid = False
                        break
                if not valid: break

            if not valid:
                continue

            # Pruning 2: White segments (Partial check?)
            # Hard to check partially. Let's skip for now, check at end or row/col completion.
            # Given small size, checking at end is fine. 
            # But we can check rows/cols that are fully determined?
            # A row is fully determined if all variable cells in it are assigned.
            # This is complex. Let's rely on final check + no-touching pruning.

            res = solve_region(idx + 1, new_black_set)
            if res is not None:
                return res

        return None

    # Initial call
    # Check if fixed white cells violate segment rule?
    # No, because we don't know black cells yet.

    # However, we can pre-check if fixed white cells alone violate connectivity?
    # No, black cells will be added.

    final_black_set = solve_region(0, set())

