            completed_rows = [tuple(r) for r in g if None not in r]
            if len(completed_rows) != len(set(completed_rows)):
                return g, False

            completed_cols = []
            for c in range(N):
                col = tuple(g[r][c] for r in range(N))
                if None not in col:
                    completed_cols.append(col)
            if len(completed_cols) != len(set(completed_cols)):
                return g, False

            # 5. Basic validity check for all lines
            for r in range(N):
                if not is_line_valid(g[r]):
