            for c in range(N):
                col = [g[r][c] for r in range(N)]
                if not is_line_valid(col):
                    return g, False

        return g, True

    # Recursive solver with backtracking
    def solve_recursive(g):
        # Apply propagation first to reduce search space
        g_prop, valid = propagate(g)
        if not valid:
            return None

        # Find empty cells
        empty_cells = []
        for r in range(N):
            for c in range(N):
                if g_prop[r][c] is None:
                    empty_cells.append((r, c))

        # If no empty cells, we have a candidate solution
        if not empty_cells:
            # Final check for uniqueness (redundant due to propagation but safe)
            rows = [tuple(row) for row in g_prop]
            if len(set(rows)) != N:
                return None
            cols = [tuple(g_prop[r][c] for r in range(N)) for c in range(N)]
            if len(set(cols)) != N:
                return None
            return g_prop

        # Pick a cell to branch on. 
        # For 6x6, picking the first empty cell is efficient enough given strong propagation.
        r, c = empty_cells[0]

        # Try 'B'
        g_next = [list(row) for row in g_prop]
        g_next[r][c] = 'B'
        res = solve_recursive(g_next)
        if res:
            return res

        # Try 'W'
        g_next = [list(row) for row in g_prop]
        g_next[r][c] = 'W'
        res = solve_recursive(g_next)
        if res:
            return res

        return None

    # Start solving
    result = solve_recursive(grid)
    return result

