            # Rows
            for r in range(N):
                for c in range(N):
                    val = grid[r][c]
                    if val:
                        opp = 'W' if val == 'B' else 'B'
                        # B B .
                        if c < N-2 and grid[r][c+1] == val and grid[r][c+2] is None:
                            grid[r][c+2] = opp
                            changes.append((r, c+2))
                            made_change = True
                        # . B B
