        grid[r_pick][c_pick] = 'B'
        res = solve_recursive()
        if res: return res
        grid[r_pick][c_pick] = None
        # Note: We don't need to undo 'changes' from propagate here because
        # the recursive call would have undone them if it failed.
        # Wait, if solve_recursive returns None, it means the branch failed.
        # The recursive call undoes its own propagation changes.
        # But what about the propagation changes made in *this* call (before branching)?
        # They are still in the grid.
