                            r = none_indices[0]
                            val = col1[r]
                            opp = 'W' if val == 'B' else 'B'
                            if g[r][c2] is None:
                                g[r][c2] = opp
                                changed = True
                        elif len(none_indices) == 0:
                            return False # Duplicate full cols

            if not is_valid(g):
                return False
        return True

    def solve_recursive(g):
        if not propagate(g):
            return None

        full = True
        for r in range(n):
            for c in range(n):
                if g[r][c] is None:
                    full = False
                    break
            if not full: break

        if full:
            if is_valid(g):
                return g
            return None

        best_cell = None
        max_density = -1

        for r in range(n):
            for c in range(n):
                if g[r][c] is None:
                    row_density = n - g[r].count(None)
                    col_density = n - get_col(g, c).count(None)
                    density = row_density + col_density
                    if density > max_density:
                        max_density = density
                        best_cell = (r, c)

        if best_cell is None:
            return None

        r, c = best_cell

        g_b = copy.deepcopy(g)
        g_b[r][c] = 'B'
        res = solve_recursive(g_b)
        if res: return res

        g_w = copy.deepcopy(g)
        g_w[r][c] = 'W'
        res = solve_recursive(g_w)
        if res: return res

        return None

    res = solve_recursive(grid)
    if res:
        return res
    return "No Solution"

