import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    # Parse observation
    region_grid = observation['region']
    row_targets = observation['row_stitch_counts']
    col_targets = observation['col_stitch_counts']
    N = len(region_grid)

    # State: 0=free, 1=used (in a stitch), 2=skipped (cannot be used)
    status = [[0] * N for _ in range(N)]
    row_rem = list(row_targets)
    col_rem = list(col_targets)

    # Precompute valid neighbors (different regions)
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighbors[(r, c)] = []
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if region_grid[r][c] != region_grid[nr][nc]:
                        neighbors[(r, c)].append((nr, nc))

    solution_stitches = []

    def get_free_cells():
        cells = []
        for r in range(N):
            for c in range(N):
                if status[r][c] == 0:
                    cells.append((r, c))
        return cells

    def check_consistency():
        # Check if remaining targets are possible given free cells
        for r in range(N):
            free_count = sum(1 for c in range(N) if status[r][c] == 0)
            if row_rem[r] > free_count:
                return False
            if row_rem[r] < 0:
                return False
        for c in range(N):
            free_count = sum(1 for r in range(N) if status[r][c] == 0)
            if col_rem[c] > free_count:
                return False
            if col_rem[c] < 0:
                return False
        return True

    def propagate():
        # If row_rem[r] == 0, all free cells in that row must be skipped
        # If col_rem[c] == 0, all free cells in that col must be skipped
        changed = True
        while changed:
            changed = False
            for r in range(N):
                if row_rem[r] == 0:
                    for c in range(N):
                        if status[r][c] == 0:
                            status[r][c] = 2
                            changed = True
            for c in range(N):
                if col_rem[c] == 0:
                    for r in range(N):
                        if status[r][c] == 0:
                            status[r][c] = 2
                            changed = True

            if not check_consistency():
                return False
        return True

    def backtrack():
        # Apply constraint propagation
        if not propagate():
            return False

        free_cells = get_free_cells()
        if not free_cells:
            # All cells processed. Check if targets are exactly 0.
            return all(x == 0 for x in row_rem) and all(x == 0 for x in col_rem)

        # Heuristic: Pick a cell that is "forced" or has few options
        # Forced: row_rem == free_count_in_row or col_rem == free_count_in_col
        best_cell = None
        min_options = float('inf')

        for r, c in free_cells:
            row_free = sum(1 for cc in range(N) if status[r][cc] == 0)
            col_free = sum(1 for rr in range(N) if status[rr][c] == 0)

            is_forced = (row_rem[r] == row_free) or (col_rem[c] == col_free)

            # Count valid unused neighbors
            valid_neighbors = [n for n in neighbors[(r,c)] if status[n[0]][n[1]] == 0]
            num_options = len(valid_neighbors)

            # Prioritize forced cells, then fewest options
            priority = 0 if is_forced else 1

            if best_cell is None or (priority, num_options) < (best_cell[2], best_cell[3]):
                best_cell = (r, c, priority, num_options)

        r, c, _, _ = best_cell

        row_free = sum(1 for cc in range(N) if status[r][cc] == 0)
        col_free = sum(1 for rr in range(N) if status[rr][c] == 0)

        can_skip = True
        if row_rem[r] == row_free: can_skip = False
        if col_rem[c] == col_free: can_skip = False

        # Option 1: Skip (r, c)
        if can_skip:
            status[r][c] = 2
            if backtrack():
                return True
            status[r][c] = 0 # Backtrack

        # Option 2: Use (r, c) in a stitch
        # Must have remaining capacity
        if row_rem[r] > 0 and col_rem[c] > 0:
            # Try to match with a neighbor
            # Sort neighbors to try deterministic order?
            for nr, nc in neighbors[(r, c)]:
                if status[nr][nc] == 0:
                    # Check if neighbor has capacity
                    if row_rem[nr] > 0 and col_rem[nc] > 0:
                        # Place stitch
                        status[r][c] = 1
                        status[nr][nc] = 1
                        row_rem[r] -= 1
                        col_rem[c] -= 1
                        row_rem[nr] -= 1
                        col_rem[nc] -= 1
                        solution_stitches.append(((r, c), (nr, nc)))

                        if backtrack():
                            return True

                        # Undo
                        solution_stitches.pop()
                        row_rem[r] += 1
                        col_rem[c] += 1
                        row_rem[nr] += 1
                        col_rem[nc] += 1
                        status[r][c] = 0
                        status[nr][nc] = 0

        return False

    if backtrack():
        return solution_stitches
    else:
