import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, None, None, 'B3', 'B3', 'B2'], [None, None, 'W2', None, None, None], [None, 'W2', None, None, None, None], [None, None, None, None, None, 'W2'], ['B7', None, None, None, 'B2', None]]}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # H[r][c] is edge between (r,c) and (r,c+1). r in 0..R-1, c in 0..C-2
    # V[r][c] is edge between (r,c) and (r+1,c). r in 0..R-2, c in 0..C-1
    # Values: 0 (unknown), 1 (present), -1 (absent)
    H = [[0]*(C-1) for _ in range(R)]
    V = [[0]*(C) for _ in range(R-1)]

    clues = {}
    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val:
                t = val[0]
                k = int(val[1:])
                clues[(r,c)] = (t, k)

    def get_edges(r, c):
        edges = []
        if c > 0: edges.append(('H', r, c-1))
        if c < C-1: edges.append(('H', r, c))
        if r > 0: edges.append(('V', r-1, c))
        if r < R-1: edges.append(('V', r, c))
        return edges

    def get_val(type, r, c):
        if type == 'H': return H[r][c]
        else: return V[r][c]

    def set_val(type, r, c, val):
        if type == 'H': 
            if H[r][c] != 0 and H[r][c] != val: return False
            H[r][c] = val
        else:
            if V[r][c] != 0 and V[r][c] != val: return False
            V[r][c] = val
        return True

    def propagate():
        while True:
            made_change = False

            # 1. Degree constraints
            for r in range(R):
                for c in range(C):
                    edges = get_edges(r, c)
                    present = [e for e in edges if get_val(*e) == 1]
                    absent = [e for e in edges if get_val(*e) == -1]
                    unknown = [e for e in edges if get_val(*e) == 0]

                    deg = len(present)

                    if deg > 2: return False

                    if (r,c) in clues:
                        # Clue node must have degree 2
                        if deg == 2:
                            for e in unknown:
                                if not set_val(*e, -1): return False
                                made_change = True
                        elif len(absent) > len(edges) - 2:
                            return False 
                        elif deg + len(unknown) < 2:
                            return False
                    else:
                        # Non-clue: degree 0 or 2
                        if deg == 2:
                            for e in unknown:
                                if not set_val(*e, -1): return False
                                made_change = True
                        elif deg == 1:
                            if len(unknown) == 1:
                                if not set_val(*unknown[0], 1): return False
                                made_change = True
                            elif len(unknown) == 0:
                                return False # Degree 1 is invalid for non-clue
                        elif deg == 0:
                            if len(unknown) == 1:
                                # Must be degree 0
                                if not set_val(*unknown[0], -1): return False
                                made_change = True

            # 2. Clue Geometry Constraints
            for (r,c), (ctype, k) in clues.items():
                edges = get_edges(r, c)
                present = [e for e in edges if get_val(*e) == 1]
                unknown = [e for e in edges if get_val(*e) == 0]

                if len(present) == 1:
                    e1 = present[0]
                    etype1 = e1[0]

                    valid_unknowns = []
                    invalid_unknowns = []

                    for e2 in unknown:
                        etype2 = e2[0]
                        is_collinear = (etype1 == etype2)
                        if ctype == 'W':
                            if is_collinear: valid_unknowns.append(e2)
                            else: invalid_unknowns.append(e2)
                        else: # B
                            if not is_collinear: valid_unknowns.append(e2)
                            else: invalid_unknowns.append(e2)

                    for e2 in invalid_unknowns:
                        if not set_val(*e2, -1): return False
                        made_change = True

                    if len(valid_unknowns) == 1:
                        if not set_val(*valid_unknowns[0], 1): return False
                        made_change = True
                    elif len(valid_unknowns) == 0:
                        return False

            # 3. Loop Prevention & Completion
            # Check for cycles
            adj = {}
            for r in range(R):
                for c in range(C): adj[(r,c)] = []

            present_edges_count = 0
            for r in range(R):
                for c in range(C-1):
                    if H[r][c] == 1:
                        adj[(r,c)].append((r,c+1))
                        adj[(r,c+1)].append((r,c))
                        present_edges_count += 1
            for r in range(R-1):
                for c in range(C):
                    if V[r][c] == 1:
                        adj[(r,c)].append((r+1,c))
                        adj[(r+1,c)].append((r,c))
                        present_edges_count += 1

            visited = set()
            components = []
            for r in range(R):
                for c in range(C):
                    if (r,c) not in visited and len(adj[(r,c)]) > 0:
                        comp = []
                        stack = [(r,c)]
                        visited.add((r,c))
                        while stack:
                            u = stack.pop()
                            comp.append(u)
                            for v in adj[u]:
                                if v not in visited:
                                    visited.add(v)
                                    stack.append(v)
                        components.append(comp)

            for comp in components:
                edges_in_comp = 0
                for u in comp:
                    edges_in_comp += len(adj[u])
                edges_in_comp //= 2

                if edges_in_comp == len(comp):
                    # Cycle detected
                    # Must cover all clues
                    if not all(cn in comp for cn in clues):
                        return False # Small loop

                    # Must be the only component with edges
                    other_edges = False
                    for other_comp in components:
                        if other_comp != comp:
                            cnt = 0
                            for u in other_comp: cnt += len(adj[u])
                            if cnt > 0: other_edges = True

                    if other_edges:
                        return False # Disconnected cycle

                    # If valid full cycle, set all unknowns to -1
                    for r in range(R):
                        for c in range(C-1):
                            if H[r][c] == 0:
                                H[r][c] = -1
                                made_change = True
                    for r in range(R-1):
                        for c in range(C):
                            if V[r][c] == 0:
                                V[r][c] = -1
                                made_change = True
                    return True # Solved state reached in propagation

            if not made_change:
                break
        return True

    def check_clues_bounds():
        for (r,c), (ctype, k) in clues.items():
            present = []
            for etype, er, ec in get_edges(r, c):
                if get_val(etype, er, ec) == 1:
                    present.append((etype, er, ec))

            if len(present) == 2:
                def trace_length(start_node, direction_edge):
                    etype, er, ec = direction_edge
                    if etype == 'H':
                        if ec == c - 1: dr, dc = 0, -1
                        else: dr, dc = 0, 1
                    else:
                        if er == r - 1: dr, dc = -1, 0
                        else: dr, dc = 1, 0

                    curr_r, curr_c = start_node
                    length = 0
                    while True:
                        next_r, next_c = curr_r + dr, curr_c + dc
                        if not (0 <= next_r < R and 0 <= next_c < C): break

                        edge_ok = False
                        if dr == 0:
                            ec_idx = min(curr_c, next_c)
                            if 0 <= ec_idx < C-1 and H[curr_r][ec_idx] == 1: edge_ok = True
                        else:
                            er_idx = min(curr_r, next_r)
                            if 0 <= er_idx < R-1 and V[er_idx][curr_c] == 1: edge_ok = True

                        if not edge_ok: break
                        length += 1
                        curr_r, curr_c = next_r, next_c

                        deg = 0
                        has_perp = False
                        for etype2, er2, ec2 in get_edges(curr_r, curr_c):
                            if get_val(etype2, er2, ec2) == 1:
                                deg += 1
                                if etype2 != ('H' if dr==0 else 'V'): has_perp = True
                        if deg == 2 and has_perp: break
                    return length

                e1, e2 = present
                l1 = trace_length((r,c), e1)
                l2 = trace_length((r,c), e2)
                if l1 + l2 > k: return False
        return True

    def is_solved():
        for r in range(R):
            for c in range(C-1):
                if H[r][c] == 0: return False
        for r in range(R-1):
            for c in range(C):
                if V[r][c] == 0: return False

        for (r,c), (ctype, k) in clues.items():
             present = []
             for etype, er, ec in get_edges(r, c):
                 if get_val(etype, er, ec) == 1:
                     present.append((etype, er, ec))
             if len(present) != 2: return False

             def trace_full(start_node, direction_edge):
                 etype, er, ec = direction_edge
                 if etype == 'H':
                     if ec == c - 1: dr, dc = 0, -1
                     else: dr, dc = 0, 1
                 else:
                     if er == r - 1: dr, dc = -1, 0
                     else: dr, dc = 1, 0

                 curr_r, curr_c = start_node
                 length = 0
                 while True:
                     next_r, next_c = curr_r + dr, curr_c + dc
                     if not (0 <= next_r < R and 0 <= next_c < C): break

                     edge_ok = False
                     if dr == 0:
                         ec_idx = min(curr_c, next_c)
                         if 0 <= ec_idx < C-1 and H[curr_r][ec_idx] == 1: edge_ok = True
                     else:
                         er_idx = min(curr_r, next_r)
                         if 0 <= er_idx < R-1 and V[er_idx][curr_c] == 1: edge_ok = True

                     if not edge_ok: break
                     length += 1
                     curr_r, curr_c = next_r, next_c

                     deg = 0
                     has_perp = False
                     for etype2, er2, ec2 in get_edges(curr_r, curr_c):
                         if get_val(etype2, er2, ec2) == 1:
                             deg += 1
                             if etype2 != ('H' if dr==0 else 'V'): has_perp = True
                     if deg == 2 and has_perp: break
                 return length

             e1, e2 = present
             l1 = trace_full((r,c), e1)
             l2 = trace_full((r,c), e2)
             if l1 + l2 != k: return False

        # Check single loop
        adj = {}
        for r in range(R):
            for c in range(C): adj[(r,c)] = []
        for r in range(R):
            for c in range(C-1):
                if H[r][c] == 1:
                    adj[(r,c)].append((r,c+1))
                    adj[(r,c+1)].append((r,c))
        for r in range(R-1):
            for c in range(C):
                if V[r][c] == 1:
                    adj[(r,c)].append((r+1,c))
                    adj[(r+1,c)].append((r,c))

        visited = set()
        comp_count = 0
        for r in range(R):
            for c in range(C):
                if (r,c) not in visited and len(adj[(r,c)]) > 0:
                    comp_count += 1
                    if comp_count > 1: return False
                    stack = [(r,c)]
                    visited.add((r,c))
                    while stack:
                        u = stack.pop()
                        for v in adj[u]:
                            if v not in visited:
                                visited.add(v)
                                stack.append(v)
        return True

    def get_unknown_edge():
        for (r,c) in clues:
            for etype, er, ec in get_edges(r, c):
                if get_val(etype, er, ec) == 0:
                    return (etype, er, ec)

        for r in range(R):
            for c in range(C-1):
                if H[r][c] == 0: return ('H', r, c)
        for r in range(R-1):
            for c in range(C):
                if V[r][c] == 0: return ('V', r, c)
        return None

    def search():
        if not propagate(): return False
        if not check_clues_bounds(): return False

        if is_solved(): return True

        edge = get_unknown_edge()
        if not edge: return False

        etype, r, c = edge

        H_copy = [row[:] for row in H]
        V_copy = [row[:] for row in V]

        set_val(etype, r, c, 1)
        if search(): return True

        for i in range(R): H[i] = H_copy[i][:]
        for i in range(R-1): V[i] = V_copy[i][:]

        set_val(etype, r, c, -1)
        if search(): return True

        for i in range(R): H[i] = H_copy[i][:]
        for i in range(R-1): V[i] = V_copy[i][:]

        return False

    if search():
        start_node = list(clues.keys())[0]
        path = [start_node]
        curr = start_node
        prev = None

        while True:
            neighbors = []
            r, c = curr
            if c > 0 and H[r][c-1] == 1: neighbors.append((r, c-1))
            if c < C-1 and H[r][c] == 1: neighbors.append((r, c+1))
            if r > 0 and V[r-1][c] == 1: neighbors.append((r-1, c))
            if r < R-1 and V[r][c] == 1: neighbors.append((r+1, c))

            next_node = None
            for n in neighbors:
                if n != prev:
                    next_node = n
                    break

            if next_node is None: break
            if next_node == start_node: break

            path.append(next_node)
            prev = curr
            curr = next_node

        path.append(start_node)
        return path
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
