import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']
    N = len(region_grid)

    # State: 0=Unknown, 1=White, 2=Black
    # Using a flat list for potentially faster access, but 2D is fine for N=8
    state = [[0]*N for _ in range(N)]

    # Region info
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = {'cells': [], 'clue': None}
            regions[rid]['cells'].append((r, c))
            if data_grid[r][c] is not None:
                # If a region has multiple clues, this logic might need adjustment,
                # but assuming one clue per region based on puzzle type.
                # If multiple, we can store a list or sum? 
                # Based on visual, each region has at most one number.
                regions[rid]['clue'] = data_grid[r][c]

    # Precompute neighbors
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighbors[(r,c)] = []
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighbors[(r,c)].append((nr, nc))

    def count_blacks_in_region(rid):
        count = 0
        for r, c in regions[rid]['cells']:
            if state[r][c] == 2:
                count += 1
        return count

    def count_unknowns_in_region(rid):
        count = 0
        for r, c in regions[rid]['cells']:
            if state[r][c] == 0:
                count += 1
        return count

    def propagate():
        changed = True
        while changed:
            changed = False

            # Rule 1: Clue 0 -> All White
            for rid, info in regions.items():
                if info['clue'] == 0:
                    for r, c in info['cells']:
                        if state[r][c] == 0:
                            state[r][c] = 1
                            changed = True
                        elif state[r][c] == 2:
                            return False # Contradiction: Black cell in 0-clue region

            # Rule 2: No Touch (Black cells cannot touch orthogonally)
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 2:
                        for nr, nc in neighbors[(r,c)]:
                            if state[nr][nc] == 2:
                                return False # Contradiction: Touching blacks
                            if state[nr][nc] == 0:
                                state[nr][nc] = 1
                                changed = True

            # Rule 3: Region Count
            for rid, info in regions.items():
                clue = info['clue']
                if clue is not None:
                    blacks = count_blacks_in_region(rid)
                    unknowns = count_unknowns_in_region(rid)
                    if blacks > clue:
                        return False # Contradiction: Too many blacks
                    if blacks + unknowns == clue:
                        # All unknowns must be black
                        for r, c in info['cells']:
                            if state[r][c] == 0:
                                state[r][c] = 2
                                changed = True
                    if blacks == clue:
                        # All unknowns must be white
                        for r, c in info['cells']:
                            if state[r][c] == 0:
                                state[r][c] = 1
                                changed = True

            # Rule 4: White Segment (Row/Col) - Max 2 regions
            # Check rows
            for r in range(N):
                c = 0
                while c < N:
                    if state[r][c] == 1: # White
                        start_c = c
                        segment_regions = set()
                        # Collect regions in this contiguous white segment
                        while c < N and state[r][c] == 1:
                            segment_regions.add(region_grid[r][c])
                            c += 1
                        end_c = c

                        if len(segment_regions) > 2:
                            return False # Contradiction: >2 regions

                        # Propagation: If segment has 2 regions, neighbors must not extend to a 3rd region as White
                        if len(segment_regions) == 2:
                            # Check right neighbor
                            if end_c < N:
                                next_rid = region_grid[r][end_c]
                                if next_rid not in segment_regions:
                                    if state[r][end_c] == 0:
                                        state[r][end_c] = 2 # Must be black to stop segment
                                        changed = True
                                    elif state[r][end_c] == 1:
                                        return False # Already white, creates 3rd region
                            # Check left neighbor
                            if start_c > 0:
                                prev_rid = region_grid[r][start_c-1]
                                if prev_rid not in segment_regions:
                                    if state[r][start_c-1] == 0:
                                        state[r][start_c-1] = 2
                                        changed = True
                                    elif state[r][start_c-1] == 1:
                                        return False
                    else:
                        c += 1

            # Check cols
            for c in range(N):
                r = 0
                while r < N:
                    if state[r][c] == 1:
                        start_r = r
                        segment_regions = set()
                        while r < N and state[r][c] == 1:
                            segment_regions.add(region_grid[r][c])
                            r += 1
                        end_r = r

                        if len(segment_regions) > 2:
                            return False

                        if len(segment_regions) == 2:
                            # Check down neighbor
                            if end_r < N:
                                next_rid = region_grid[end_r][c]
                                if next_rid not in segment_regions:
                                    if state[end_r][c] == 0:
                                        state[end_r][c] = 2
                                        changed = True
                                    elif state[end_r][c] == 1:
                                        return False
                            # Check up neighbor
                            if start_r > 0:
                                prev_rid = region_grid[start_r-1][c]
                                if prev_rid not in segment_regions:
                                    if state[start_r-1][c] == 0:
                                        state[start_r-1][c] = 2
                                        changed = True
                                    elif state[start_r-1][c] == 1:
                                        return False
                    else:
                        r += 1

            # Rule 5: Connectivity (Weak check - isolated white regions)
            # If a white cell is surrounded by blacks/borders and there are other white cells, it might be disconnected.
            # This is expensive to check fully every time, so we do a simple check:
            # If a white cell has no white neighbors and is not the only white cell, fail?
            # No, it could be a 1x1 white island connected diagonally? No, orthogonal connection required.
            # So if a white cell has 0 white neighbors, it must be the ONLY white cell.
            white_cells = [(r,c) for r in range(N) for c in range(N) if state[r][c] == 1]
            if len(white_cells) > 1:
                for r, c in white_cells:
                    has_white_neighbor = False
                    for nr, nc in neighbors[(r,c)]:
                        if state[nr][nc] == 1:
                            has_white_neighbor = True
                            break
                    if not has_white_neighbor:
                        # This white cell is isolated.
                        # Unless it's the only one, this is a contradiction.
                        return False

        return True

    def is_complete():
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    return False
        return True

    def check_connectivity():
        # Find first white cell
        start = None
        white_count = 0
        for r in range(N):
            for c in range(N):
                if state[r][c] == 1:
                    white_count += 1
                    if start is None:
                        start = (r, c)
        if white_count == 0:
            return True 

        # BFS
        visited = set()
        queue = [start]
        visited.add(start)
        idx = 0
        while idx < len(queue):
            r, c = queue[idx]
            idx += 1
            for nr, nc in neighbors[(r,c)]:
                if state[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == white_count

    def solve_recursive():
        if not propagate():
            return None
        if is_complete():
            if check_connectivity():
                res = []
                for r in range(N):
                    row = []
                    for c in range(N):
                        if state[r][c] == 2:
                            row.append('B')
                        else:
                            row.append(None)
                    res.append(row)
                return res
            else:
                return None

        # Heuristic: Pick cell with most constraints? 
        # For simplicity, pick first unknown.
        r, c = -1, -1
        for i in range(N):
            for j in range(N):
                if state[i][j] == 0:
                    r, c = i, j
                    break
            if r != -1: break

        # Try Black
        state[r][c] = 2
        res = solve_recursive()
        if res: return res
        state[r][c] = 0 

        # Try White
        state[r][c] = 1
        res = solve_recursive()
        if res: return res
        state[r][c] = 0 

        return None

    result = solve_recursive()
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
