    col_clues = observation['col_black_runs']

    rows = len(row_clues)
    cols = len(col_clues)

    # Grid state: -1 unknown, 0 white, 1 black
    grid = [[-1 for _ in range(cols)] for _ in range(rows)]

    # Precompute all valid lines for each clue set to speed up propagation
    # This is a cache: key = tuple(clues), value = list of valid binary tuples
    line_cache = {}

    def get_valid_lines(clues, length):
        key = (tuple(clues), length)
        if key in line_cache:
            return line_cache[key]

        valid_lines = []

        # Recursive generator
        def generate(current_line, clue_idx, current_pos):
            # Base case: all clues placed
            if clue_idx == len(clues):
                # Fill rest with 0
                remaining = length - current_pos
                if remaining >= 0:
                    valid_lines.append(tuple(current_line + [0] * remaining))
                return

            clue = clues[clue_idx]
            # Try placing the current clue at every possible position
            # Minimum space needed for remaining clues (including separators)
            remaining_clues_sum = sum(clues[clue_idx:])
            remaining_clues_count = len(clues) - clue_idx
            min_space_needed = remaining_clues_sum + (remaining_clues_count - 1)

            # Max start position
            max_start = length - min_space_needed

            for start in range(current_pos, max_start + 1):
                # Check if placement is valid (doesn't overlap with existing 0s if we were checking against a mask, 
                # but here we are generating all possibilities first)
                # Actually, we just generate all structurally valid lines.
                # Filtering against the current grid state happens in the propagation step.

                new_line = current_line + [0] * (start - current_pos) + [1] * clue
                # Add separator if not last clue
                if clue_idx < len(clues) - 1:
                    new_line.append(0)

                generate(new_line, clue_idx + 1, len(new_line))

        generate([], 0, 0)
        line_cache[key] = valid_lines
        return valid_lines

    def solve_line(clues, current_line):
        length = len(current_line)
        all_valid = get_valid_lines(clues, length)

        # Filter valid lines based on current known state
        compatible_lines = []
        for line in all_valid:
            match = True
            for i in range(length):
                if current_line[i] != -1:
                    if line[i] != current_line[i]:
                        match = False
                        break
            if match:
                compatible_lines.append(line)

        if not compatible_lines:
            return None # Contradiction

        # Intersect
        new_line = list(current_line)
        changed = False

        # If only one compatible line, we know the whole row/col
        if len(compatible_lines) == 1:
            for i in range(length):
                if new_line[i] == -1:
                    new_line[i] = compatible_lines[0][i]
                    changed = True
        else:
            # Check each cell
            for i in range(length):
                if new_line[i] == -1:
                    vals = set(l[i] for l in compatible_lines)
                    if len(vals) == 1:
                        val = vals.pop()
                        new_line[i] = val
                        changed = True

        return new_line, changed

    def propagate(g):
        changed_global = True
        while changed_global:
            changed_global = False

            # Rows
            for r in range(rows):
                res = solve_line(row_clues[r], g[r])
                if res is None:
                    return None # Contradiction
                new_row, changed = res
                if changed:
                    g[r] = new_row
                    changed_global = True

            # Cols
            for c in range(cols):
                col_vals = [g[r][c] for r in range(rows)]
                res = solve_line(col_clues[c], col_vals)
                if res is None:
                    return None # Contradiction
                new_col, changed = res
                if changed:
                    for r in range(rows):
                        g[r][c] = new_col[r]
                    changed_global = True
        return g

    # Initial propagation
    grid = propagate(grid)
    if grid is None:
        return "No Solution"

    # Check if solved
    def is_solved(g):
        for r in range(rows):
            for c in range(cols):
                if g[r][c] == -1:
                    return False
        return True

    if is_solved(grid):
        # Format output
        result = []
        for r in range(rows):
            row_str = []
            for c in range(cols):
                row_str.append('B' if grid[r][c] == 1 else None)
            result.append(row_str)
        return result

    # Backtracking
    # Find first unknown
    def find_unknown(g):
        for r in range(rows):
            for c in range(cols):
                if g[r][c] == -1:
                    return (r, c)
        return None

    def backtrack(g):
        # Propagate first
        g = propagate(g)
        if g is None:
            return None

        if is_solved(g):
            return g

        r, c = find_unknown(g)

        # Try Black (1)
        g_try = copy.deepcopy(g)
        g_try[r][c] = 1
        res = backtrack(g_try)
        if res is not None:
            return res

        # Try White (0)
        g_try = copy.deepcopy(g)
        g_try[r][c] = 0
        res = backtrack(g_try)
        if res is not None:
            return res

        return None

    final_grid = backtrack(grid)

    if final_grid is None:
        return "No Solution"

    result = []
    for r in range(rows):
        row_str = []
        for c in range(cols):
            row_str.append('B' if final_grid[r][c] == 1 else None)
        result.append(row_str)
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
