def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Board: -1 Unknown, 0 White, 1 Black
    initial_board = [[-1 for _ in range(C)] for _ in range(R)]

    constraints = []
    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val is not None:
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            neighbors.append((nr, nc))
                constraints.append({
                    'r': r, 'c': c, 'val': val, 
                    'neighbors': neighbors
                })

    cell_to_constraints = {}
    for i, con in enumerate(constraints):
        for nr, nc in con['neighbors']:
            if (nr, nc) not in cell_to_constraints:
                cell_to_constraints[(nr, nc)] = []
            cell_to_constraints[(nr, nc)].append(i)

    def propagate(board):
        queue = set(range(len(constraints)))
        while queue:
            con_idx = queue.pop()
            con = constraints[con_idx]

            current_blacks = 0
            current_unknowns = []
            for nr, nc in con['neighbors']:
                v = board[nr][nc]
                if v == 1:
                    current_blacks += 1
                elif v == -1:
                    current_unknowns.append((nr, nc))

            target = con['val']

            if current_blacks > target:
                return False
            if current_blacks + len(current_unknowns) < target:
                return False

            changed_cells = []

            if current_blacks == target:
                for nr, nc in current_unknowns:
                    if board[nr][nc] == -1:
                        board[nr][nc] = 0
                        changed_cells.append((nr, nc))
            elif current_blacks + len(current_unknowns) == target:
                for nr, nc in current_unknowns:
                    if board[nr][nc] == -1:
                        board[nr][nc] = 1
                        changed_cells.append((nr, nc))

            for nr, nc in changed_cells:
                if (nr, nc) in cell_to_constraints:
                    for affected_con_idx in cell_to_constraints[(nr, nc)]:
                        queue.add(affected_con_idx)
        return True

    def is_full(board):
        for r in range(R):
            for c in range(C):
                if board[r][c] == -1:
                    return False
        return True

    def get_best_cell(board):
        unknown_cells = []
        for r in range(R):
            for c in range(C):
                if board[r][c] == -1:
                    unknown_cells.append((r, c))

        if not unknown_cells:
            return None

        candidate = None
        best_score = float('inf')

        for r, c in unknown_cells:
            if (r, c) in cell_to_constraints:
                for con_idx in cell_to_constraints[(r, c)]:
                    con = constraints[con_idx]
                    u_count = 0
                    for nr, nc in con['neighbors']:
                        if board[nr][nc] == -1:
                            u_count += 1
                    if u_count < best_score:
                        best_score = u_count
                        candidate = (r, c)
            else:
                if candidate is None:
                    candidate = (r, c)
        return candidate

    def solve_recursive(board):
        if not propagate(board):
            return None

        if is_full(board):
            for con in constraints:
                count = 0
                for nr, nc in con['neighbors']:
                    if board[nr][nc] == 1:
                        count += 1
                if count != con['val']:
                    return None
            return board

        cell = get_best_cell(board)
        if cell is None:
            return None

        r, c = cell

        # Try Black
        board_black = [row[:] for row in board]
        board_black[r][c] = 1
        res = solve_recursive(board_black)
        if res: return res

        # Try White
        board_white = [row[:] for row in board]
        board_white[r][c] = 0
        res = solve_recursive(board_white)
        if res: return res

        return None

    if not propagate(initial_board):
        return "No Solution"

    result = solve_recursive(initial_board)

    if result:
        output = []
        for r in range(R):
            row_out = []
            for c in range(C):
                if result[r][c] == 1:
                    row_out.append('B')
                else:
                    row_out.append(None)
            output.append(row_out)
        return output
    else:
        return "No Solution"

if __name__ == "__main__":
