    rows = len(data)
    cols = len(data[0])

    # State constants
    UNKNOWN, WHITE, BLACK = 0, 1, 2

    # Initial state: all unknown
    state = [[UNKNOWN] * cols for _ in range(rows)]

    # Identify numbered cells
    numbered_cells = []
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                numbered_cells.append((r, c, data[r][c]))

    # Precompute neighbors for each numbered cell
    # neighbors_map: (r, c) -> list of (nr, nc)
    neighbors_map = {}
    for r, c, val in numbered_cells:
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        neighbors_map[(r, c)] = neighs

    # Propagation function
    # Modifies state in place. Returns state if consistent, None if contradiction.
    def propagate(st):
        changed = True
        while changed:
            changed = False
            for r, c, val in numbered_cells:
                neighs = neighbors_map[(r, c)]
                b_count = 0
                u_count = 0

                for nr, nc in neighs:
                    s = st[nr][nc]
                    if s == BLACK:
                        b_count += 1
                    elif s == UNKNOWN:
                        u_count += 1

                # Constraint checks
                if b_count > val:
                    return None # Too many black cells
                if b_count + u_count < val:
                    return None # Not enough space for required black cells

                # Deductions
                if b_count == val:
                    # All remaining unknowns must be WHITE
                    for nr, nc in neighs:
                        if st[nr][nc] == UNKNOWN:
                            st[nr][nc] = WHITE
                            changed = True
                elif b_count + u_count == val:
                    # All remaining unknowns must be BLACK
                    for nr, nc in neighs:
                        if st[nr][nc] == UNKNOWN:
                            st[nr][nc] = BLACK
                            changed = True
        return st

    # Backtracking solver
    def backtrack(current_state):
        # Apply propagation
        res_state = propagate(current_state)
        if res_state is None:
            return None

        # Check if solved (no UNKNOWNs)
        solved = True
        first_unknown = None
        for r in range(rows):
            for c in range(cols):
                if res_state[r][c] == UNKNOWN:
                    solved = False
                    if first_unknown is None:
                        first_unknown = (r, c)

        if solved:
            return res_state

        r, c = first_unknown

        # Try BLACK
        # Create a deep copy of the grid
        state_black = [row[:] for row in res_state]
        state_black[r][c] = BLACK
        res = backtrack(state_black)
        if res is not None:
            return res

        # Try WHITE
        state_white = [row[:] for row in res_state]
        state_white[r][c] = WHITE
        res = backtrack(state_white)
        if res is not None:
            return res

        return None

    # Start solving
    # Pass a copy of initial state
    initial_state = [row[:] for row in state]
    final_state = backtrack(initial_state)

    if final_state is None:
        return "No Solution"

    # Convert to output format: 'B' for Black, None for White
    output_grid = []
