import collections

def solve(observation):
    grid = observation['data']
    N = len(grid)

    # State constants: 0=Unknown, 1=White, 2=Black
    UNKNOWN, WHITE, BLACK = 0, 1, 2
    # Initialize state grid
    state = [[UNKNOWN for _ in range(N)] for _ in range(N)]

    def get_neighbors(r, c):
        """Returns list of valid orthogonal neighbors."""
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    def propagate(current_state):
        """
        Applies logical deduction rules repeatedly until no changes occur.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False
            # Rule 3 Propagation: Black cells force orthogonal neighbors to be White.
            # Also checks for Rule 3 violation (adjacent Blacks).
            for r in range(N):
                for c in range(N):
                    if current_state[r][c] == BLACK:
                        for nr, nc in get_neighbors(r, c):
                            if current_state[nr][nc] == UNKNOWN:
                                current_state[nr][nc] = WHITE
                                changed = True
                            elif current_state[nr][nc] == BLACK:
                                return False # Contradiction: Adjacent black cells

            # Rule 1 & 2 Propagation: White cells force duplicates in row/col to be Black.
            # Also checks for Rule 1 & 2 violation (duplicate Whites).
            for r in range(N):
                for c in range(N):
                    if current_state[r][c] == WHITE:
                        val = grid[r][c]
                        # Check row for duplicates
                        for c2 in range(N):
                            if c2 != c and grid[r][c2] == val:
                                if current_state[r][c2] == UNKNOWN:
                                    current_state[r][c2] = BLACK
                                    changed = True
                                elif current_state[r][c2] == WHITE:
                                    return False # Contradiction: Duplicate white number in row
                        # Check col for duplicates
                        for r2 in range(N):
                            if r2 != r and grid[r2][c] == val:
                                if current_state[r2][c] == UNKNOWN:
                                    current_state[r2][c] = BLACK
                                    changed = True
                                elif current_state[r2][c] == WHITE:
                                    return False # Contradiction: Duplicate white number in col
        return True

    def check_connectivity(current_state):
        """
        Checks if all White cells form a single orthogonally connected group (Rule 4).
        """
        white_cells = []
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == WHITE:
                    white_cells.append((r, c))

        if not white_cells:
            return True # Vacuously true or handled by puzzle constraints usually implying non-empty

        # BFS to count connected component size
        start = white_cells[0]
        visited = set()
        queue = collections.deque([start])
        visited.add(start)

        while queue:
            r, c = queue.popleft()
            for nr, nc in get_neighbors(r, c):
                if current_state[nr][nc] == WHITE and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(white_cells)

    def backtrack(current_state):
        """
        Recursive backtracking solver with constraint propagation.
        """
        # First, apply all logical deductions
        if not propagate(current_state):
            return None

        # Find the first unknown cell
        unknown_pos = None
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == UNKNOWN:
                    unknown_pos = (r, c)
                    break
            if unknown_pos: break

        # If no unknown cells, check final connectivity
        if unknown_pos is None:
            if check_connectivity(current_state):
                return current_state
            else:
                return None

        r, c = unknown_pos

        # Branch 1: Try setting cell to Black
        # We create a deep copy of the state to avoid modifying the current branch's state
        state_black = [row[:] for row in current_state]
        state_black[r][c] = BLACK
        res = backtrack(state_black)
        if res: return res

        # Branch 2: Try setting cell to White
        state_white = [row[:] for row in current_state]
        state_white[r][c] = WHITE
        res = backtrack(state_white)
        if res: return res

        return None

    # Start solving
    final_state = backtrack(state)

    if final_state is None:
        return "No Solution"

    # Format output as requested: 'B' for black, None for white
    result = []
    for r in range(N):
        row_res = []
        for c in range(N):
            if final_state[r][c] == BLACK:
                row_res.append('B')
            else:
                row_res.append(None)
        result.append(row_res)
    return result

