OBSERVATION = {'data': [[None, None, None, None, None, None], ['W', None, None, None, None, 'B'], [None, 'B', None, None, 'W', None], [None, 'W', None, None, 'W', None], [None, None, None, None, None, None], ['W', None, None, None, None, 'W']], 'horizontal': {'(0, 0.5)': 'x', '(0, 4.5)': '='}, 'vertical': {'(2.5, 0)': '=', '(2.5, 5)': 'x', '(3.5, 2)': 'x', '(3.5, 3)': '='}}

def solve(observation):
    data = observation['data']
    horizontal_constraints = observation.get('horizontal', {})
    vertical_constraints = observation.get('vertical', {})

    # Parse constraints into usable format
    # horizontal: (row, col) -> constraint between (row, col) and (row, col+1)
    # vertical: (row, col) -> constraint between (row, col) and (row+1, col)

    h_cons = {}
    for k, v in horizontal_constraints.items():
        # k is like '(0, 0.5)'
        parts = k.strip('()').split(', ')
        r = int(parts[0])
        c = float(parts[1])
        # c is col + 0.5, so col is int(c - 0.5)
        col = int(c - 0.5)
        h_cons[(r, col)] = v

    v_cons = {}
    for k, v in vertical_constraints.items():
        # k is like '(0.5, 0)'
        parts = k.strip('()').split(', ')
        r = float(parts[0])
        c = int(parts[1])
        # r is row + 0.5, so row is int(r - 0.5)
        row = int(r - 0.5)
        v_cons[(row, c)] = v

    grid = [row[:] for row in data]
    N = len(grid)

    def is_valid_placement(grid, r, c, val):
        # Check if placing val at (r, c) is valid locally
        # 1. Check row constraints
        # Count B/W in row r
        row_vals = grid[r][:c] + [val]
        # We don't check full row here, just partial validity

        # Check 3 consecutive in row
        if c >= 2:
            if grid[r][c-2] == val and grid[r][c-1] == val:
                return False
        if c >= 1 and c < N-1:
            # We can't check forward yet unless we look ahead, but we check backward
            pass

        # Check 3 consecutive in col
        if r >= 2:
            if grid[r-2][c] == val and grid[r-1][c] == val:
                return False

        # Check counts (partial)
        # Count B/W in row r so far
        b_count = sum(1 for x in row_vals if x == 'B')
        w_count = sum(1 for x in row_vals if x == 'W')
        if b_count > N//2 or w_count > N//2:
            return False

        # Count B/W in col c so far
        col_vals = [grid[i][c] for i in range(r)] + [val]
        b_count_c = sum(1 for x in col_vals if x == 'B')
        w_count_c = sum(1 for x in col_vals if x == 'W')
        if b_count_c > N//2 or w_count_c > N//2:
            return False

        # Check constraints with neighbors
        # Horizontal left
        if c > 0:
            left_val = grid[r][c-1]
            if left_val is not None:
                if (r, c-1) in h_cons:
                    cons = h_cons[(r, c-1)]
                    if cons == '=' and left_val != val:
                        return False
                    if cons == 'x' and left_val == val:
                        return False

        # Horizontal right (if already filled)
        if c < N-1:
            right_val = grid[r][c+1]
            if right_val is not None:
                if (r, c) in h_cons:
                    cons = h_cons[(r, c)]
                    if cons == '=' and val != right_val:
                        return False
                    if cons == 'x' and val == right_val:
                        return False

        # Vertical up
        if r > 0:
            up_val = grid[r-1][c]
            if up_val is not None:
                if (r-1, c) in v_cons:
                    cons = v_cons[(r-1, c)]
                    if cons == '=' and up_val != val:
                        return False
                    if cons == 'x' and up_val == val:
                        return False

        # Vertical down (if already filled)
        if r < N-1:
            down_val = grid[r+1][c]
            if down_val is not None:
                if (r, c) in v_cons:
                    cons = v_cons[(r, c)]
                    if cons == '=' and val != down_val:
                        return False
                    if cons == 'x' and val == down_val:
                        return False

        return True

    def is_complete_valid(grid):
        # Check full grid validity
        # 1. Counts
        for r in range(N):
            if grid[r].count('B') != N//2 or grid[r].count('W') != N//2:
