def solve(observation):
    import sys
    # Increase recursion depth just in case, though 9x9 is small.
    sys.setrecursionlimit(2000)

    data = observation['data']
    unit_str = observation['unit']

    # Parse unit dimensions
    if 'x' in unit_str:
        h, w = map(int, unit_str.split('x'))
    else:
        h = w = int(unit_str)

    N = len(data)

    # Initialize grid (0 for empty)
    grid = []
    for r in range(N):
        row = []
        for c in range(N):
            val = data[r][c]
            row.append(val if val is not None else 0)
        grid.append(row)

    # Precompute peers for each cell
    peers = {}
    for r in range(N):
        for c in range(N):
            p = set()
            # Row peers
            for k in range(N):
                if k != c: p.add((r, k))
            # Col peers
            for k in range(N):
                if k != r: p.add((k, c))
            # Box peers
            br_start = (r // h) * h
            bc_start = (c // w) * w
            for dr in range(h):
                for dc in range(w):
                    nr, nc = br_start + dr, bc_start + dc
                    if (nr, nc) != (r, c):
                        p.add((nr, nc))
            peers[(r, c)] = p

    # Initialize possibilities
    possibilities = {}
    for r in range(N):
        for c in range(N):
            if grid[r][c] == 0:
                possibilities[(r, c)] = set(range(1, N + 1))
            else:
                possibilities[(r, c)] = set()

    # Initial constraint propagation
    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            if val != 0:
                for pr, pc in peers[(r, c)]:
                    if val in possibilities[(pr, pc)]:
                        possibilities[(pr, pc)].discard(val)

    class State:
        def __init__(self, g, poss):
            self.grid = g
            self.possibilities = poss

        def copy(self):
            new_g = [row[:] for row in self.grid]
            new_poss = {k: v.copy() for k, v in self.possibilities.items()}
            return State(new_g, new_poss)

    initial_state = State(grid, possibilities)

    def solve_state(state):
        # Constraint Propagation Loop (Naked and Hidden Singles)
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles
            for r in range(N):
                for c in range(N):
                    if state.grid[r][c] == 0:
                        if len(state.possibilities[(r, c)]) == 1:
                            val = state.possibilities[(r, c)].pop()
                            state.grid[r][c] = val
                            for pr, pc in peers[(r, c)]:
                                if val in state.possibilities[(pr, pc)]:
                                    state.possibilities[(pr, pc)].discard(val)
                            changed = True

            # 2. Hidden Singles
            # Row
            for r in range(N):
                counts = {}
                empty_cs = []
                for c in range(N):
                    if state.grid[r][c] == 0:
                        empty_cs.append(c)
                        for val in state.possibilities[(r, c)]:
                            counts[val] = counts.get(val, 0) + 1
                for val, count in counts.items():
                    if count == 1:
                        for c in empty_cs:
                            if val in state.possibilities[(r, c)]:
                                state.grid[r][c] = val
                                state.possibilities[(r, c)] = set()
                                for pr, pc in peers[(r, c)]:
                                    if val in state.possibilities[(pr, pc)]:
                                        state.possibilities[(pr, pc)].discard(val)
                                changed = True
                                break

            # Col
            for c in range(N):
                counts = {}
                empty_rs = []
                for r in range(N):
                    if state.grid[r][c] == 0:
                        empty_rs.append(r)
                        for val in state.possibilities[(r, c)]:
                            counts[val] = counts.get(val, 0) + 1
                for val, count in counts.items():
                    if count == 1:
                        for r in empty_rs:
                            if val in state.possibilities[(r, c)]:
                                state.grid[r][c] = val
                                state.possibilities[(r, c)] = set()
                                for pr, pc in peers[(r, c)]:
                                    if val in state.possibilities[(pr, pc)]:
                                        state.possibilities[(pr, pc)].discard(val)
                                changed = True
                                break

            # Box
            for br in range(0, N, h):
                for bc in range(0, N, w):
                    counts = {}
                    empty_cells = []
                    for r in range(br, br + h):
                        for c in range(bc, bc + w):
                            if state.grid[r][c] == 0:
                                empty_cells.append((r, c))
                                for val in state.possibilities[(r, c)]:
                                    counts[val] = counts.get(val, 0) + 1
                    for val, count in counts.items():
                        if count == 1:
                            for r, c in empty_cells:
                                if val in state.possibilities[(r, c)]:
                                    state.grid[r][c] = val
                                    state.possibilities[(r, c)] = set()
                                    for pr, pc in peers[(r, c)]:
                                        if val in state.possibilities[(pr, pc)]:
                                            state.possibilities[(pr, pc)].discard(val)
                                    changed = True
                                    break

        # Check if solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if state.grid[r][c] == 0:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            return state.grid

        # Check for contradiction (empty possibilities for an empty cell)
        for r in range(N):
            for c in range(N):
                if state.grid[r][c] == 0 and len(state.possibilities[(r, c)]) == 0:
                    return None

        # MRV (Minimum Remaining Values) Heuristic
        min_len = N + 1
        target = None
        for r in range(N):
            for c in range(N):
                if state.grid[r][c] == 0:
                    l = len(state.possibilities[(r, c)])
                    if l < min_len:
                        min_len = l
                        target = (r, c)

        if target is None:
            return state.grid # Should be caught by is_solved, but safe guard

        r, c = target
        vals = list(state.possibilities[(r, c)])

        # LCV (Least Constraining Value) Heuristic
        def lcv_key(val):
            count = 0
            for pr, pc in peers[(r, c)]:
                if val in state.possibilities[(pr, pc)]:
                    count += 1
            return count

        vals.sort(key=lcv_key)

        for val in vals:
            new_state = state.copy()
            new_state.grid[r][c] = val
            new_state.possibilities[(r, c)] = set()
            for pr, pc in peers[(r, c)]:
                new_state.possibilities[(pr, pc)].discard(val)

            res = solve_state(new_state)
            if res is not None:
                return res

        return None

    result = solve_state(initial_state)
    return result

