import copy

def solve(observation):
    data = observation['data']
    N = len(data)

    # State: None (Unknown White), True (Bulb), False (Empty White), 'W' (Wall)
    state = [[None] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None: 
                state[r][c] = 'W'

    def get_wall_num(r, c):
        val = data[r][c]
        if val is None: return None
        if val == -1: return None
        return val

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    def compute_light_map(state):
        lmap = [[0]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if state[r][c] == True:
                    # Light row right
                    for k in range(c+1, N):
                        if data[r][k] is not None: break
                        lmap[r][k] += 1
                    # Light row left
                    for k in range(c-1, -1, -1):
                        if data[r][k] is not None: break
                        lmap[r][k] += 1
                    # Light col down
                    for k in range(r+1, N):
                        if data[k][c] is not None: break
                        lmap[k][c] += 1
                    # Light col up
                    for k in range(r-1, -1, -1):
                        if data[k][c] is not None: break
                        lmap[k][c] += 1
                    lmap[r][c] += 1 
        return lmap

    def propagate(state):
        changed = True
        while changed:
            changed = False
            lmap = compute_light_map(state)

            # Rule 1: Lit unknown cells must be Empty (cannot be bulb if lit by another)
            for r in range(N):
                for c in range(N):
                    if state[r][c] is None:
                        if lmap[r][c] > 0:
                            state[r][c] = False
                            changed = True

            # Rule 2: Wall Constraints
            for r in range(N):
                for c in range(N):
                    w_num = get_wall_num(r, c)
                    if w_num is not None:
                        neighs = get_neighbors(r, c)
                        bulbs = 0
                        unknowns = []
                        for nr, nc in neighs:
                            if state[nr][nc] == True:
                                bulbs += 1
                            elif state[nr][nc] is None:
                                unknowns.append((nr, nc))

                        if bulbs > w_num:
                            return False 
                        if bulbs == w_num:
                            for nr, nc in unknowns:
                                if state[nr][nc] is None:
                                    state[nr][nc] = False
                                    changed = True
                        if bulbs + len(unknowns) == w_num:
                            for nr, nc in unknowns:
                                if state[nr][nc] is None:
                                    state[nr][nc] = True
                                    changed = True
        return True

    def is_valid_solution(state):
        lmap = compute_light_map(state)
        for r in range(N):
            for c in range(N):
                if data[r][c] is None: 
                    if lmap[r][c] == 0:
                        return False
        for r in range(N):
            for c in range(N):
                w_num = get_wall_num(r, c)
                if w_num is not None:
                    bulbs = 0
                    for nr, nc in get_neighbors(r, c):
                        if state[nr][nc] == True:
                            bulbs += 1
                    if bulbs != w_num:
                        return False
        return True

    def backtrack(state):
        curr_state = copy.deepcopy(state)

        if not propagate(curr_state):
            return None

        if is_valid_solution(curr_state):
            return curr_state

        lmap = compute_light_map(curr_state)
        target = None
        for r in range(N):
            for c in range(N):
                if data[r][c] is None and lmap[r][c] == 0:
                    target = (r, c)
                    break
            if target: break

        if not target:
            return None 

        r, c = target
        candidates = []

        # Row Left
        for k in range(c-1, -1, -1):
            if data[r][k] is not None: break
            if curr_state[r][k] is None:
                candidates.append((r, k))
        # Row Right
        for k in range(c+1, N):
            if data[r][k] is not None: break
            if curr_state[r][k] is None:
