            if curr_state[k][c] is None:
                candidates.append((k, c))

        if curr_state[r][c] is None:
            candidates.append((r, c))

        valid_candidates = []
        for br, bc in candidates:
            conflict = False

            # Check Row br
            for k in range(bc-1, -1, -1):
                if data[br][k] is not None: break
                if curr_state[br][k] == True:
                    conflict = True; break
            if conflict: continue
            for k in range(bc+1, N):
                if data[br][k] is not None: break
                if curr_state[br][k] == True:
                    conflict = True; break
            if conflict: continue

            # Check Col bc
            for k in range(br-1, -1, -1):
