            if wall_conflict: continue

            valid_candidates.append((br, bc))

        for br, bc in valid_candidates:
            curr_state[br][bc] = True
            res = backtrack(curr_state)
            if res:
                return res
            curr_state[br][bc] = None 

        return None

    res = backtrack(state)
    if res:
