        queue = [k for k in domains if len(domains[k]) == 1]
        in_queue = set(queue)

        while True:
            # Process Naked Singles
            while queue:
                cell = queue.pop(0)
                in_queue.discard(cell)
                val = next(iter(domains[cell]))

                for p in peers[cell]:
                    if val in domains[p]:
                        domains[p].discard(val)
                        if len(domains[p]) == 0:
                            return False # Contradiction
                        if len(domains[p]) == 1:
                            if p not in in_queue:
                                queue.append(p)
                                in_queue.add(p)

            # Check for Hidden Singles
            found_hidden = False
            for unit in units:
                # Count occurrences of each value in this unit's domains
                val_counts = {v: [] for v in range(1, N + 1)}
                for c in unit:
                    for v in domains[c]:
                        val_counts[v].append(c)

                for v, locs in val_counts.items():
                    if len(locs) == 1:
                        target = locs[0]
                        if len(domains[target]) > 1:
                            domains[target] = {v}
                            found_hidden = True
                            if target not in in_queue:
                                queue.append(target)
                                in_queue.add(target)

            if not found_hidden:
                break

        return True

    # Backtracking Search with MRV
    def backtrack():
        if is_solved():
            return True

        # MRV: Select unassigned cell with minimum remaining values
        unassigned = [k for k in domains if len(domains[k]) > 1]
        if not unassigned:
            return False # Should be caught by is_solved, but safety

        unassigned.sort(key=lambda k: len(domains[k]))
        cell = unassigned[0]

        # Save state for backtracking
        # Deep copy is expensive, but necessary. 
        # Optimization: Only copy what changes? 
        # Given N<=16, full copy is acceptable.
        saved_domains = {k: v.copy() for k, v in domains.items()}

        # Try values (LCV heuristic could be added, but simple sort is usually fine)
        possible_values = sorted(list(domains[cell]))

        for val in possible_values:
            domains[cell] = {val}
            if propagate():
                if backtrack():
                    return True
            # Restore state
            for k in saved_domains:
                domains[k] = saved_domains[k]

        return False

    # Initial Propagation
    if not propagate():
        return "No Solution"

    if not backtrack():
        return "No Solution"

    # Construct result
    result = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append(next(iter(domains[(r, c)])))
        result.append(row)

    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
