OBSERVATION = {'data': [[None, None, 0, None, 1, None, None], [None, None, None, None, None, None, None], [2, None, None, None, None, None, 1], [None, None, None, None, None, None, None], [2, None, None, None, None, None, 0], [None, None, None, None, None, None, None], [None, None, 0, None, 0, None, None]]}

def solve(observation):
    data = observation['data']
    N = len(data)

    # Board state:
    # None: Unknown white cell
    # 'B': Bulb
    # '.': Empty white cell (confirmed no bulb)
    # int (0-4): Wall with number

    # We work on a mutable copy
    board = [row[:] for row in data]

    def is_wall_cb(r, c, cb):
        val = cb[r][c]
        return isinstance(val, int)

    def is_unknown_cb(r, c, cb):
        return cb[r][c] is None

    def is_illuminated_cb(r, c, cb):
        if cb[r][c] == 'B': return True
        if is_wall_cb(r, c, cb): return True

        # Row Left
        for cc in range(c - 1, -1, -1):
            val = cb[r][cc]
            if val == 'B': return True
            if is_wall_cb(r, cc, cb): break
        # Row Right
        for cc in range(c + 1, N):
            val = cb[r][cc]
            if val == 'B': return True
            if is_wall_cb(r, cc, cb): break

        # Col Up
        for rr in range(r - 1, -1, -1):
            val = cb[rr][c]
            if val == 'B': return True
            if is_wall_cb(rr, c, cb): break
        # Col Down
        for rr in range(r + 1, N):
            val = cb[rr][c]
            if val == 'B': return True
            if is_wall_cb(rr, c, cb): break

        return False

    def can_place_bulb_cb(r, c, cb):
        if not is_unknown_cb(r, c, cb): return False

        # Check Row
        for cc in range(c - 1, -1, -1):
            val = cb[r][cc]
            if val == 'B': return False
            if is_wall_cb(r, cc, cb): break
        for cc in range(c + 1, N):
            val = cb[r][cc]
            if val == 'B': return False
            if is_wall_cb(r, cc, cb): break

        # Check Col
        for rr in range(r - 1, -1, -1):
            val = cb[rr][c]
            if val == 'B': return False
            if is_wall_cb(rr, c, cb): break
        for rr in range(r + 1, N):
            val = cb[rr][c]
            if val == 'B': return False
            if is_wall_cb(rr, c, cb): break

        return True

    def count_adjacent_bulbs_cb(r, c, cb):
        count = 0
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                if cb[nr][nc] == 'B':
                    count += 1
        return count

    def count_available_neighbors_cb(r, c, cb):
        count = 0
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                if is_unknown_cb(nr, nc, cb):
                    count += 1
        return count

    def apply_wall_constraints_cb(cb):
        changed = False
        for r in range(N):
            for c in range(N):
                val = cb[r][c]
                if isinstance(val, int):
                    needed = val
                    current_bulbs = count_adjacent_bulbs_cb(r, c, cb)

                    if current_bulbs > needed:
                        return False

                    if current_bulbs == needed:
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if is_unknown_cb(nr, nc, cb):
                                    cb[nr][nc] = '.'
                                    changed = True
                    else:
                        available = count_available_neighbors_cb(r, c, cb)
                        if available + current_bulbs == needed:
                            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < N and 0 <= nc < N:
                                    if is_unknown_cb(nr, nc, cb):
                                        if can_place_bulb_cb(nr, nc, cb):
                                            cb[nr][nc] = 'B'
                                            changed = True
                                        else:
                                            return False
        return changed

    def apply_illumination_constraints_cb(cb):
        changed = False

        unlit_cells = []
        for r in range(N):
            for c in range(N):
                if not is_wall_cb(r, c, cb):
                    if not is_illuminated_cb(r, c, cb):
                        unlit_cells.append((r, c))

        for r, c in unlit_cells:
            if is_illuminated_cb(r, c, cb):
                continue

            candidates = []

            # Check if cell itself can be a bulb
            if is_unknown_cb(r, c, cb) and can_place_bulb_cb(r, c, cb):
                candidates.append((r, c))

            # Row candidates
            for cc in range(N):
                if cc == c: continue
                blocked = False
                min_c, max_c = min(c, cc), max(c, cc)
                for k in range(min_c + 1, max_c):
                    if is_wall_cb(r, k, cb):
                        blocked = True
                        break
                if not blocked:
                    if is_unknown_cb(r, cc, cb) and can_place_bulb_cb(r, cc, cb):
                        candidates.append((r, cc))

            # Col candidates
            for rr in range(N):
                if rr == r: continue
                blocked = False
                min_r, max_r = min(r, rr), max(r, rr)
                for k in range(min_r + 1, max_r):
                    if is_wall_cb(k, c, cb):
                        blocked = True
                        break
                if not blocked:
                    if is_unknown_cb(rr, c, cb) and can_place_bulb_cb(rr, c, cb):
                        candidates.append((rr, c))

            if not candidates:
                return False

            if len(candidates) == 1:
                br, bc = candidates[0]
                cb[br][bc] = 'B'
                changed = True

        return changed

    def solve_recursive(cb):
        while True:
            c1 = apply_wall_constraints_cb(cb)
            if c1 is False: return None
            c2 = apply_illumination_constraints_cb(cb)
            if c2 is False: return None
            if not c1 and not c2:
                break

        all_lit = True
        for r in range(N):
            for c in range(N):
                if not is_wall_cb(r, c, cb):
                    if not is_illuminated_cb(r, c, cb):
                        all_lit = False
                        break
            if not all_lit: break

        if all_lit:
            for r in range(N):
                for c in range(N):
                    val = cb[r][c]
                    if isinstance(val, int):
                        if count_adjacent_bulbs_cb(r, c, cb) != val:
                            return None
            for r in range(N):
                for c in range(N):
                    if cb[r][c] is None:
                        cb[r][c] = '.'
            return cb

        target = None
        for r in range(N):
            for c in range(N):
                if not is_wall_cb(r, c, cb) and not is_illuminated_cb(r, c, cb):
                    target = (r, c)
                    break
            if target: break

        if not target:
            for r in range(N):
                for c in range(N):
                    if is_unknown_cb(r, c, cb):
                        target = (r, c)
                        break
                if target: break

        if not target:
             return None

        tr, tc = target
        is_target_unlit = not is_illuminated_cb(tr, tc, cb) and not is_wall_cb(tr, tc, cb)

        if is_target_unlit:
            candidates = []
            if is_unknown_cb(tr, tc, cb) and can_place_bulb_cb(tr, tc, cb):
                candidates.append((tr, tc))
            for cc in range(N):
                if cc == tc: continue
                blocked = False
                min_c, max_c = min(tc, cc), max(tc, cc)
                for k in range(min_c + 1, max_c):
                    if is_wall_cb(tr, k, cb): blocked = True; break
                if not blocked and is_unknown_cb(tr, cc, cb) and can_place_bulb_cb(tr, cc, cb):
                    candidates.append((tr, cc))
            for rr in range(N):
                if rr == tr: continue
                blocked = False
                min_r, max_r = min(tr, rr), max(tr, rr)
                for k in range(min_r + 1, max_r):
                    if is_wall_cb(k, tc, cb): blocked = True; break
                if not blocked and is_unknown_cb(rr, tc, cb) and can_place_bulb_cb(rr, tc, cb):
                    candidates.append((rr, tc))

            for br, bc in candidates:
                new_cb = [row[:] for row in cb]
                new_cb[br][bc] = 'B'
                res = solve_recursive(new_cb)
                if res: return res
            return None
        else:
            if is_unknown_cb(tr, tc, cb) and can_place_bulb_cb(tr, tc, cb):
                new_cb = [row[:] for row in cb]
                new_cb[tr][tc] = 'B'
                res = solve_recursive(new_cb)
                if res: return res

            new_cb = [row[:] for row in cb]
            new_cb[tr][tc] = '.'
            res = solve_recursive(new_cb)
            if res: return res

            return None

    res = solve_recursive([row[:] for row in board])
    if res is None:
        return "No Solution"

    final_grid = []
    for r in range(N):
        row_out = []
        for c in range(N):
            if res[r][c] == 'B':
                row_out.append('B')
            else:
                row_out.append(None)
        final_grid.append(row_out)
    return final_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
