        [None, -1, None, None, None, None, 1, None, -1, None],
        [None, 0, 1, None, None, 1, None, 1, 0, None],
        [None, None, None, None, None, None, None, None, None, None]
    ]
}

def solve(observation):
    # Deep copy to avoid modifying original observation data
    grid = [row[:] for row in observation['data']]

    # Run solver
    result = backtrack(grid)

    if result is None:
        return "No Solution"

    # Format output: 'B' for bulb, None for everything else (including black cells)
    final_grid = []
    for r in range(len(result)):
        row_out = []
        for c in range(len(result[0])):
            if result[r][c] == 'B':
                row_out.append('B')
            else:
                row_out.append(None)
        final_grid.append(row_out)
    return final_grid

def backtrack(grid):
    # 1. Propagate constraints (Human-like deduction)
    if not propagate(grid):
        return None

    # 2. Check if solved
    if is_solved(grid):
        return grid

    # 3. Find branching point
    # Find an unilluminated white cell (represented as None in our state)
    # In our state: None = White, unknown status (and unilluminated, due to propagation)
    #               'X' = White, definitely no bulb (illuminated or ruled out)
    #               'B' = Bulb
    #               int = Black cell
    r, c = find_unilluminated_white(grid)
    if r is None:
        # No unilluminated white cells found, but is_solved returned False?
        # This implies numbered constraints might be failing, handled by propagate/is_solved
        return None

    # Get candidates to place a bulb to illuminate (r,c)
    # Candidates are 'None' cells in the same row/col segment
    candidates = get_candidates(grid, r, c)

    # Try each candidate
    for cr, cc in candidates:
        new_grid = copy.deepcopy(grid)
        new_grid[cr][cc] = 'B'

        res = backtrack(new_grid)
        if res is not None:
            return res

    return None

def propagate(grid):
    changed = True
    rows = len(grid)
    cols = len(grid[0])

    while changed:
        changed = False

        # Rule 1: Numbered cells constraints
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                if isinstance(val, int) and val >= 0:
                    bulbs = 0
                    unknowns = []
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neighbor = grid[nr][nc]
                            if neighbor == 'B':
                                bulbs += 1
                            elif neighbor is None:
                                unknowns.append((nr, nc))

                    # If too many bulbs, invalid
                    if bulbs > val:
                        return False
                    # If satisfied, remaining unknowns cannot be bulbs
                    if bulbs == val:
                        for ur, uc in unknowns:
                            if grid[ur][uc] is None:
                                grid[ur][uc] = 'X'
                                changed = True
                    # If max possible bulbs equals required, all unknowns must be bulbs
                    if bulbs + len(unknowns) == val:
                        for ur, uc in unknowns:
                            if grid[ur][uc] is None:
                                grid[ur][uc] = 'B'
                                changed = True

        # Rule 2: Bulb visibility and illumination
        # Collect bulbs first to avoid modification issues during iteration
        bulbs_found = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'B':
                    bulbs_found.append((r,c))

        for br, bc in bulbs_found:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                r, c = br + dr, bc + dc
                while 0 <= r < rows and 0 <= c < cols:
                    cell = grid[r][c]
                    if isinstance(cell, int): # Black wall
                        break
                    if cell == 'B':
                        # Found another bulb in line of sight -> Invalid
                        return False
                    if cell is None:
                        # This white cell is illuminated, so it cannot be a bulb
                        grid[r][c] = 'X'
                        changed = True
                    r += dr
                    c += dc

    return True

def is_solved(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Check numbered constraints are exactly met
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if isinstance(val, int) and val >= 0:
                bulbs = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == 'B':
                            bulbs += 1
                if bulbs != val:
                    return False

    # Check all white cells are illuminated
    # In our representation:
    # 'None' = White, unilluminated (because propagate marks illuminated ones as 'X')
    # 'X' = White, illuminated (or ruled out)
    # 'B' = Bulb (illuminates itself)
    # So we just check for any remaining 'None'.
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                return False

    return True

def find_unilluminated_white(grid):
    rows = len(grid)
    cols = len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                return r, c
    return None, None

def get_candidates(grid, r, c):
    rows = len(grid)
    cols = len(grid[0])
    candidates = set()

    # Check row left
    for dc in range(-1, -cols, -1):
        nc = c + dc
        if nc < 0: break
        cell = grid[r][nc]
        if isinstance(cell, int): break
        if cell is None:
            candidates.add((r, nc))

    # Check row right
    for dc in range(1, cols):
        nc = c + dc
        if nc >= cols: break
        cell = grid[r][nc]
        if isinstance(cell, int): break
        if cell is None:
            candidates.add((r, nc))

    # Check col up
    for dr in range(-1, -rows, -1):
        nr = r + dr
        if nr < 0: break
        cell = grid[nr][c]
        if isinstance(cell, int): break
        if cell is None:
            candidates.add((nr, c))

    # Check col down
    for dr in range(1, rows):
        nr = r + dr
        if nr >= rows: break
        cell = grid[nr][c]
        if isinstance(cell, int): break
        if cell is None:
            candidates.add((nr, c))

    # The cell itself is a candidate
    candidates.add((r, c))
    return list(candidates)

if __name__ == "__main__":
    print(solve(OBSERVATION))
