import sys

# Increase recursion depth just in case
sys.setrecursionlimit(2000)

OBSERVATION = {
    'data': [
        [None, None, 'W4', None, None, None, None, None, None, None, 'B12'],
        [None, None, None, 'B5', None, 'B2', 'B4', 'B2', None, None, None],
        [None, None, None, None, None, 'B3', None, None, None, None, None],
        [None, 'B2', None, 'B3', None, None, None, None, None, None, None],
        ['W3', None, None, 'B3', None, None, None, None, 'W2', None, None],
        [None, 'B2', 'B5', 'B3', None, None, 'B7', None, None, 'W5', None],
        [None, None, None, None, None, 'B3', None, None, 'W2', None, None],
        [None, None, None, None, None, 'B3', None, None, None, None, None],
        [None, None, None, None, None, 'B3', None, None, None, 'W2', 'B3'],
        [None, 'B2', None, None, None, None, None, 'B4', None, None, None],
        [None, 'W4', None, None, None, None, None, None, None, None, None]
    ]
}

def solve(observation):
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0])

    # Clues: (r, c) -> (type, k)
    # type: 'W' or 'B'
    clues = {}
    for r in range(R):
        for c in range(C):
            val = grid_data[r][c]
            if val:
                t = val[0]
                k = int(val[1:])
                clues[(r, c)] = (t, k)

    # Edges: H[r][c] is edge (r,c)-(r,c+1)
    #        V[r][c] is edge (r,c)-(r+1,c)
    # Values: 0 (Unknown), 1 (On), -1 (Off)
    H = [[0] * (C - 1) for _ in range(R)]
    V = [[0] * (R - 1) for _ in range(C)] # Wait, V should be (R-1) x C
    # Correct dimensions:
    # H: R rows, C-1 cols
    # V: R-1 rows, C cols
    H = [[0] * (C - 1) for _ in range(R)]
    V = [[0] * C for _ in range(R - 1)]

    # Degrees
    degrees = [[0] * C for _ in range(R)]

    # Union-Find for connectivity
    parent = list(range(R * C))
    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False # Already connected

    # Helper to get node index
    def idx(r, c):
        return r * C + c

    # Helper to get edges at (r, c)
    def get_edges(r, c):
        edges = []
        # Left: H[r][c-1]
        if c > 0: edges.append(('H', r, c-1, -1)) # dir: (0, -1)
        # Right: H[r][c]
        if c < C - 1: edges.append(('H', r, c, 1)) # dir: (0, 1)
        # Up: V[r-1][c]
        if r > 0: edges.append(('V', r-1, c, -1)) # dir: (-1, 0)
        # Down: V[r][c]
        if r < R - 1: edges.append(('V', r, c, 1)) # dir: (1, 0)
        return edges

    # Propagate constraints
    def propagate():
        changed = True
        while changed:
            changed = False

            # 1. Degree constraints
            for r in range(R):
                for c in range(C):
                    deg = degrees[r][c]
                    if deg == 2:
                        # All unknown edges must be Off
                        for etype, er, ec, _ in get_edges(r, c):
                            if etype == 'H':
                                if H[er][ec] == 0:
                                    H[er][ec] = -1
                                    changed = True
                            else:
                                if V[er][ec] == 0:
                                    V[er][ec] = -1
                                    changed = True
                    elif deg == 0:
                        # If it's a clue, it MUST have degree 2 eventually.
                        # If all neighbors are blocked, fail.
                        if (r, c) in clues:
                            possible = 0
                            for etype, er, ec, _ in get_edges(r, c):
                                if etype == 'H':
                                    if H[er][ec] != -1: possible += 1
                                else:
                                    if V[er][ec] != -1: possible += 1
                            if possible < 2:
                                return False # Fail

            # 2. Clue Geometry Propagation
            for (r, c), (ctype, k) in clues.items():
                deg = degrees[r][c]
                edges_info = get_edges(r, c)
                on_edges = []
                off_edges = []
                unknown_edges = []

                for etype, er, ec, d in edges_info:
                    val = H[er][ec] if etype == 'H' else V[er][ec]
                    if val == 1:
                        on_edges.append((etype, er, ec, d))
                    elif val == -1:
                        off_edges.append((etype, er, ec, d))
                    else:
                        unknown_edges.append((etype, er, ec, d))

                if ctype == 'W':
                    # Must be collinear: (Left, Right) or (Up, Down)
                    # Pairs: (Left, Right) -> dirs -1, 1 in H
                    #        (Up, Down) -> dirs -1, 1 in V

                    # Check if we have enough info to deduce
                    # If one is On, the other collinear must be On, perpendicular Off.
                    if len(on_edges) == 1:
                        et, er, ec, d = on_edges[0]
                        if et == 'H': # Horizontal
                            # Must be (Left, Right). So other H must be On, Vs Off.
                            # Find the other H
                            other_h = None
                            for et2, er2, ec2, d2 in edges_info:
                                if et2 == 'H' and not (er2 == er and ec2 == ec):
                                    other_h = (et2, er2, ec2, d2)
                            if other_h:
                                et2, er2, ec2, d2 = other_h
                                if H[er2][ec2] == 0:
                                    H[er2][ec2] = 1
                                    degrees[r][c] += 1 # Will be updated in loop? No, need to update degrees manually or re-scan
                                    # Actually, better to update degrees immediately
                                    nr, nc = r, c + d2
                                    degrees[nr][nc] += 1
                                    changed = True
                                elif H[er2][ec2] == -1:
                                    return False # Contradiction
                            # Perpendiculars must be Off
                            for et2, er2, ec2, d2 in edges_info:
                                if et2 == 'V':
                                    if V[er2][ec2] == 0:
                                        V[er2][ec2] = -1
                                        changed = True
                                    elif V[er2][ec2] == 1:
                                        return False
                        else: # Vertical
                            # Must be (Up, Down).
                            other_v = None
                            for et2, er2, ec2, d2 in edges_info:
                                if et2 == 'V' and not (er2 == er and ec2 == ec):
                                    other_v = (et2, er2, ec2, d2)
                            if other_v:
                                et2, er2, ec2, d2 = other_v
                                if V[er2][ec2] == 0:
                                    V[er2][ec2] = 1
                                    nr, nc = r + d2, c
                                    degrees[nr][nc] += 1
                                    changed = True
                                elif V[er2][ec2] == -1:
                                    return False
                            for et2, er2, ec2, d2 in edges_info:
                                if et2 == 'H':
                                    if H[er2][ec2] == 0:
                                        H[er2][ec2] = -1
                                        changed = True
                                    elif H[er2][ec2] == 1:
                                        return False

                    elif len(on_edges) == 0:
                        # If two perpendiculars are Off, the other pair must be On.
                        # e.g., if Left and Up are Off, must be (Right, Down)? No.
                        # W means (L, R) or (U, D).
                        # If L is Off, (L, R) impossible. Must be (U, D).
                        # So R must be Off, U On, D On.

                        # Check if any direction is blocked
                        dirs_blocked = set()
                        for et, er, ec, d in off_edges:
                            if et == 'H':
                                if d == -1: dirs_blocked.add('L')
                                else: dirs_blocked.add('R')
                            else:
                                if d == -1: dirs_blocked.add('U')
                                else: dirs_blocked.add('D')

                        if 'L' in dirs_blocked or 'R' in dirs_blocked:
                            # Must be Vertical (U, D)
                            # Check if U or D blocked
                            if 'U' in dirs_blocked or 'D' in dirs_blocked:
                                return False # Both pairs blocked
                            # Force U, D On, L, R Off (L, R already handled if blocked)
                            for et, er, ec, d in edges_info:
                                if et == 'V':
                                    if (et, er, ec, d) not in off_edges: # Not already off
                                        if (et, er, ec, d) not in on_edges:
                                            # Set On
                                            if V[er][ec] == 0:
                                                V[er][ec] = 1
                                                nr, nc = r + d, c
                                                degrees[nr][nc] += 1
                                                changed = True
                                            elif V[er][ec] == -1:
                                                return False
                                else: # H
                                    if (et, er, ec, d) not in on_edges:
                                        if H[er][ec] == 0:
                                            H[er][ec] = -1
                                            changed = True
                                        elif H[er][ec] == 1:
                                            return False
                        elif 'U' in dirs_blocked or 'D' in dirs_blocked:
                            # Must be Horizontal (L, R)
                            if 'L' in dirs_blocked or 'R' in dirs_blocked:
                                return False
                            for et, er, ec, d in edges_info:
                                if et == 'H':
                                    if (et, er, ec, d) not in off_edges:
                                        if (et, er, ec, d) not in on_edges:
                                            if H[er][ec] == 0:
                                                H[er][ec] = 1
                                                nr, nc = r, c + d
                                                degrees[nr][nc] += 1
                                                changed = True
                                            elif H[er][ec] == -1:
                                                return False
                                else:
                                    if (et, er, ec, d) not in on_edges:
                                        if V[er][ec] == 0:
                                            V[er][ec] = -1
                                            changed = True
                                        elif V[er][ec] == 1:
                                            return False

                elif ctype == 'B':
                    # Must be perpendicular.
                    # Pairs: (L, U), (L, D), (R, U), (R, D).
                    if len(on_edges) == 1:
                        et, er, ec, d = on_edges[0]
                        # The other edge must be perpendicular.
                        # So the collinear edge must be Off.
                        if et == 'H':
                            # Collinear is other H.
                            for et2, er2, ec2, d2 in edges_info:
                                if et2 == 'H' and not (er2 == er and ec2 == ec):
                                    if H[er2][ec2] == 0:
                                        H[er2][ec2] = -1
                                        changed = True
                                    elif H[er2][ec2] == 1:
                                        return False
                        else: # V
                            for et2, er2, ec2, d2 in edges_info:
                                if et2 == 'V' and not (er2 == er and ec2 == ec):
                                    if V[er2][ec2] == 0:
                                        V[er2][ec2] = -1
                                        changed = True
                                    elif V[er2][ec2] == 1:
                                        return False

                    elif len(on_edges) == 0:
                        # If 3 directions are blocked, the 4th must be On? No, need 2 edges.
                        # If 2 perpendiculars are blocked, e.g., L and U blocked.
                        # Possible pairs: (L, D) - No (L blocked). (R, U) - No (U blocked). (R, D).
                        # So must be (R, D).

                        dirs_blocked = set()
                        for et, er, ec, d in off_edges:
                            if et == 'H':
                                if d == -1: dirs_blocked.add('L')
                                else: dirs_blocked.add('R')
                            else:
                                if d == -1: dirs_blocked.add('U')
                                else: dirs_blocked.add('D')

                        # Check possible pairs
                        pairs = [('L', 'U'), ('L', 'D'), ('R', 'U'), ('R', 'D')]
                        valid_pairs = []
                        for p in pairs:
                            if p[0] not in dirs_blocked and p[1] not in dirs_blocked:
                                valid_pairs.append(p)

                        if len(valid_pairs) == 1:
                            p = valid_pairs[0]
                            # Force these two On, others Off
                            # Map dir to edge
                            dir_map = {
                                'L': ('H', r, c-1, -1),
                                'R': ('H', r, c, 1),
                                'U': ('V', r-1, c, -1),
                                'D': ('V', r, c, 1)
                            }
                            for d_name in ['L', 'R', 'U', 'D']:
                                et, er, ec, d_val = dir_map[d_name]
                                is_target = (d_name in p)
                                if et == 'H':
                                    if is_target:
                                        if H[er][ec] == 0:
                                            H[er][ec] = 1
                                            nr, nc = r, c + d_val
                                            degrees[nr][nc] += 1
                                            changed = True
                                        elif H[er][ec] == -1:
                                            return False
                                    else:
                                        if H[er][ec] == 0:
                                            H[er][ec] = -1
                                            changed = True
                                        elif H[er][ec] == 1:
                                            return False
                                else:
                                    if is_target:
                                        if V[er][ec] == 0:
                                            V[er][ec] = 1
                                            nr, nc = r + d_val, c
                                            degrees[nr][nc] += 1
                                            changed = True
                                        elif V[er][ec] == -1:
                                            return False
                                    else:
                                        if V[er][ec] == 0:
                                            V[er][ec] = -1
                                            changed = True
                                        elif V[er][ec] == 1:
                                            return False
                        elif len(valid_pairs) == 0:
                            return False

            # 3. Number Constraints (Basic Pruning)
            # Check if any clue exceeds k
            for (r, c), (ctype, k) in clues.items():
                if degrees[r][c] < 2:
                    continue

                # Get segment lengths
                # For W: One straight line.
                # For B: Two perpendicular segments.

                # Identify active edges
                active_dirs = []
                for et, er, ec, d in get_edges(r, c):
                    val = H[er][ec] if et == 'H' else V[er][ec]
                    if val == 1:
                        active_dirs.append((et, d))

                if ctype == 'W':
                    # Must be collinear
                    if len(active_dirs) == 2:
                        # Check collinearity
                        if active_dirs[0][0] != active_dirs[1][0]:
                            return False # Not collinear
                        # Calculate length
                        # Direction d1 and d2 (opposite)
                        d1 = active_dirs[0][1]
                        # Length in d1
                        len1 = count_straight(r, c, active_dirs[0][0], d1)
                        len2 = count_straight(r, c, active_dirs[1][0], active_dirs[1][1])
                        total = len1 + len2
                        if total > k:
                            return False
                        # If segments are closed, check equality
                        if is_segment_closed(r, c, active_dirs[0][0], d1) and is_segment_closed(r, c, active_dirs[1][0], active_dirs[1][1]):
                            if total != k:
                                return False
                else: # B
                    if len(active_dirs) == 2:
                        # Must be perpendicular
                        if active_dirs[0][0] == active_dirs[1][0]:
                            return False # Collinear, but B must turn
                        len1 = count_straight(r, c, active_dirs[0][0], active_dirs[0][1])
                        len2 = count_straight(r, c, active_dirs[1][0], active_dirs[1][1])
                        total = len1 + len2
                        if total > k:
                            return False
                        if is_segment_closed(r, c, active_dirs[0][0], active_dirs[0][1]) and is_segment_closed(r, c, active_dirs[1][0], active_dirs[1][1]):
                            if total != k:
                                return False

        return True

    def count_straight(r, c, etype, d):
        # Count edges starting from (r,c) in direction d (etype)
        # d is -1 or 1.
        # etype 'H' or 'V'
        count = 0
        curr_r, curr_c = r, c
        while True:
            if etype == 'H':
                if d == 1:
                    if curr_c >= C - 1: break
                    if H[curr_r][curr_c] == 1:
                        count += 1
                        curr_c += 1
                    else:
                        break
                else: # d == -1
                    if curr_c <= 0: break
                    if H[curr_r][curr_c - 1] == 1:
                        count += 1
                        curr_c -= 1
                    else:
                        break
            else: # V
                if d == 1:
                    if curr_r >= R - 1: break
                    if V[curr_r][curr_c] == 1:
                        count += 1
                        curr_r += 1
                    else:
                        break
                else:
                    if curr_r <= 0: break
                    if V[curr_r - 1][curr_c] == 1:
                        count += 1
                        curr_r -= 1
                    else:
                        break
        return count

    def is_segment_closed(r, c, etype, d):
        # Check if the segment in direction d from (r,c) is bounded by a turn or boundary
        # Traverse to the end of the straight segment
        curr_r, curr_c = r, c
        # Move one step
        if etype == 'H':
            if d == 1:
                if curr_c >= C - 1: return True # Boundary
                if H[curr_r][curr_c] != 1: return True # Edge off/unknown (treat as closed for now? No, if unknown, not closed)
                curr_c += 1
            else:
                if curr_c <= 0: return True
                if H[curr_r][curr_c - 1] != 1: return True
                curr_c -= 1
        else:
            if d == 1:
                if curr_r >= R - 1: return True
                if V[curr_r][curr_c] != 1: return True
                curr_r += 1
            else:
                if curr_r <= 0: return True
                if V[curr_r - 1][curr_c] != 1: return True
                curr_r -= 1

        # Now at the next node. Check if it's a turn.
        # A node is a turn if degree is 2 and the other edge is not collinear.
        # Or if degree < 2 (endpoint), it's not closed (loop not finished).
        # Wait, "closed" means we know the length is fixed.
        # If we hit a node with degree 2, and the edges are not collinear, it's a turn -> Closed.
        # If we hit a node with degree 2, and edges ARE collinear, continue.
        # If we hit degree < 2, not closed.

        # Actually, simpler:
        # Traverse until we hit a non-collinear edge or boundary.
        # If we hit an unknown edge, not closed.

        # Let's re-traverse properly
        curr_r, curr_c = r, c
        while True:
            # Check next edge
            next_edge_on = False
            next_edge_unknown = False

            if etype == 'H':
                if d == 1:
                    if curr_c >= C - 1: return True # Boundary
                    val = H[curr_r][curr_c]
                    if val == 1: next_edge_on = True
                    elif val == 0: next_edge_unknown = True
                else:
                    if curr_c <= 0: return True
                    val = H[curr_r][curr_c - 1]
                    if val == 1: next_edge_on = True
                    elif val == 0: next_edge_unknown = True
            else:
                if d == 1:
                    if curr_r >= R - 1: return True
                    val = V[curr_r][curr_c]
                    if val == 1: next_edge_on = True
                    elif val == 0: next_edge_unknown = True
                else:
                    if curr_r <= 0: return True
                    val = V[curr_r - 1][curr_c]
                    if val == 1: next_edge_on = True
                    elif val == 0: next_edge_unknown = True

            if next_edge_unknown:
                return False # Not closed

            if not next_edge_on:
                return True # Edge off -> Closed (length ends here)

            # Move to next node
            if etype == 'H':
                curr_c += d
            else:
                curr_r += d

            # Check if this node is a turn
            # Get edges at this node
            node_edges = []
            for et, er, ec, dd in get_edges(curr_r, curr_c):
                val = H[er][ec] if et == 'H' else V[er][ec]
                if val == 1:
                    node_edges.append((et, dd))

            if len(node_edges) == 2:
                # Check collinearity with incoming direction
                # Incoming was etype, d.
                # If one of node_edges is (etype, d) [continuing], then not a turn.
                # If one is (etype, -d) [back], impossible in loop.
                # So must be perpendicular.
                is_collinear = False
                for et, dd in node_edges:
                    if et == etype and dd == d:
                        is_collinear = True
                        break
                if not is_collinear:
                    return True # Turn detected -> Closed
            elif len(node_edges) < 2:
                return False # Path ends -> Not closed (unless it's the start, but we are checking segment length)
            # If len > 2, invalid state, but handled elsewhere.

    # Backtracking
    # State is global H, V, degrees, parent

    # We need to save state for backtracking
    # Since H, V are small, we can copy them? Or use a stack of changes.
    # Stack of changes is better.

    changes_stack = []

    def set_edge(etype, r, c, val):
        # val: 1 or -1
        # Returns list of changes made to undo later
        changes = []
        if etype == 'H':
            if H[r][c] == 0:
                H[r][c] = val
                changes.append(('H', r, c, 0))
                # Update degrees
                if val == 1:
                    degrees[r][c] += 1
                    changes.append(('deg', r, c, degrees[r][c] - 1))
                    degrees[r][c+1] += 1
                    changes.append(('deg', r, c+1, degrees[r][c+1] - 1))

                    # Union-Find
                    u = idx(r, c)
                    v = idx(r, c+1)
                    if find(u) != find(v):
                        union(u, v)
                        changes.append(('uf', u, v, parent[u])) # Store old parent? No, just mark that union happened?
                        # Actually, undoing union is hard.
                        # Alternative: Don't use Union-Find for cycle detection in backtracking?
                        # Or re-compute connectivity?
                        # Given grid size, maybe simple BFS/DFS for cycle check is okay?
                        # Or just track components.
                        # Let's skip Union-Find undo for now and rely on "No small cycles" check via DFS.
                    else:
                        # Cycle detected.
                        changes.append(('cycle', True))
                else: # val == -1
                    pass # Degree doesn't change
            elif H[r][c] == val:
                pass # Already set
            else:
                return None # Contradiction
        else: # V
            if V[r][c] == 0:
                V[r][c] = val
                changes.append(('V', r, c, 0))
                if val == 1:
                    degrees[r][c] += 1
                    changes.append(('deg', r, c, degrees[r][c] - 1))
                    degrees[r+1][c] += 1
                    changes.append(('deg', r+1, c, degrees[r+1][c] - 1))

                    u = idx(r, c)
                    v = idx(r+1, c)
                    if find(u) != find(v):
                        union(u, v)
                        changes.append(('uf', u, v, parent[u]))
                    else:
                        changes.append(('cycle', True))
            elif V[r][c] == val:
                pass
            else:
                return None

        return changes

    def undo_changes(changes):
        for change in reversed(changes):
            if change[0] == 'H':
                _, r, c, old_val = change
                H[r][c] = old_val
            elif change[0] == 'V':
                _, r, c, old_val = change
                V[r][c] = old_val
            elif change[0] == 'deg':
                _, r, c, old_val = change
                degrees[r][c] = old_val
            elif change[0] == 'uf':
                _, u, v, old_parent = change
                parent[u] = old_parent # This is tricky. parent[root_i] = root_j.
                # We need to restore parent[root_i].
                # In union(i, j), we did parent[root_i] = root_j.
                # So we need to set parent[root_i] back to root_i.
                # But we stored parent[u] which is root_i?
                # In union: root_i = find(i). parent[root_i] = root_j.
                # So we need to store root_i.
                # Let's fix union to return root_i.
                pass 
            elif change[0] == 'cycle':
                pass

    # Fix union to support undo
    def union_undoable(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return root_i # Return the node that changed
        return None

    # Redefine set_edge to use union_undoable
    def set_edge_v2(etype, r, c, val):
        changes = []
        if etype == 'H':
            if H[r][c] == 0:
                H[r][c] = val
                changes.append(('H', r, c, 0))
                if val == 1:
                    degrees[r][c] += 1
                    changes.append(('deg', r, c, degrees[r][c] - 1))
                    degrees[r][c+1] += 1
                    changes.append(('deg', r, c+1, degrees[r][c+1] - 1))

                    u = idx(r, c)
                    v = idx(r, c+1)
                    root_i = find(u)
                    root_j = find(v)
                    if root_i != root_j:
                        parent[root_i] = root_j
                        changes.append(('uf', root_i, root_i)) # Store node and its old parent (itself)
                    else:
                        changes.append(('cycle', True))
            elif H[r][c] == val:
                pass
            else:
                return None
        else:
            if V[r][c] == 0:
                V[r][c] = val
                changes.append(('V', r, c, 0))
                if val == 1:
                    degrees[r][c] += 1
                    changes.append(('deg', r, c, degrees[r][c] - 1))
                    degrees[r+1][c] += 1
                    changes.append(('deg', r+1, c, degrees[r+1][c] - 1))

                    u = idx(r, c)
                    v = idx(r+1, c)
                    root_i = find(u)
                    root_j = find(v)
                    if root_i != root_j:
                        parent[root_i] = root_j
                        changes.append(('uf', root_i, root_i))
                    else:
                        changes.append(('cycle', True))
            elif V[r][c] == val:
                pass
            else:
                return None
        return changes

    def undo_changes_v2(changes):
        for change in reversed(changes):
            if change[0] == 'H':
                _, r, c, old_val = change
                H[r][c] = old_val
            elif change[0] == 'V':
                _, r, c, old_val = change
                V[r][c] = old_val
            elif change[0] == 'deg':
                _, r, c, old_val = change
                degrees[r][c] = old_val
            elif change[0] == 'uf':
                _, node, old_val = change
                parent[node] = old_val
            elif change[0] == 'cycle':
                pass

    def is_solved():
        # 1. All clues degree 2
        for (r, c) in clues:
            if degrees[r][c] != 2:
                return False

        # 2. Single loop
        # Count edges
        total_edges = 0
        for r in range(R):
            for c in range(C-1):
                if H[r][c] == 1: total_edges += 1
        for r in range(R-1):
            for c in range(C):
                if V[r][c] == 1: total_edges += 1

        # Count nodes with degree > 0
        nodes_in_loop = 0
        first_node = None
        for r in range(R):
            for c in range(C):
                if degrees[r][c] > 0:
                    nodes_in_loop += 1
                    if first_node is None:
                        first_node = (r, c)

        if nodes_in_loop == 0: return False

        # Check connectivity of nodes_in_loop
        # BFS from first_node
        visited = set()
        queue = [first_node]
        visited.add(first_node)
        while queue:
            curr = queue.pop(0)
            r, c = curr
            for et, er, ec, d in get_edges(r, c):
                val = H[er][ec] if et == 'H' else V[er][ec]
                if val == 1:
                    nr, nc = r, c
                    if et == 'H':
                        nc += d
                    else:
                        nr += d
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        if len(visited) != nodes_in_loop:
            return False # Disconnected components

        # 3. Check number constraints fully
        for (r, c), (ctype, k) in clues.items():
            active_dirs = []
            for et, er, ec, d in get_edges(r, c):
                val = H[er][ec] if et == 'H' else V[er][ec]
                if val == 1:
                    active_dirs.append((et, d))

            if ctype == 'W':
                if len(active_dirs) != 2: return False
                if active_dirs[0][0] != active_dirs[1][0]: return False
                len1 = count_straight(r, c, active_dirs[0][0], active_dirs[0][1])
                len2 = count_straight(r, c, active_dirs[1][0], active_dirs[1][1])
                if len1 + len2 != k: return False
            else:
                if len(active_dirs) != 2: return False
                if active_dirs[0][0] == active_dirs[1][0]: return False
                len1 = count_straight(r, c, active_dirs[0][0], active_dirs[0][1])
                len2 = count_straight(r, c, active_dirs[1][0], active_dirs[1][1])
                if len1 + len2 != k: return False

        return True

    def get_next_variable():
        # Heuristic: Edge adjacent to clue or degree 1 node
        # Or just first unknown edge
        best_edge = None
        best_score = -1

        for r in range(R):
            for c in range(C-1):
                if H[r][c] == 0:
                    score = 0
                    if (r, c) in clues: score += 10
                    if (r, c+1) in clues: score += 10
                    if degrees[r][c] == 1: score += 5
                    if degrees[r][c+1] == 1: score += 5
                    if score > best_score:
                        best_score = score
                        best_edge = ('H', r, c)

        for r in range(R-1):
            for c in range(C):
                if V[r][c] == 0:
                    score = 0
                    if (r, c) in clues: score += 10
                    if (r+1, c) in clues: score += 10
                    if degrees[r][c] == 1: score += 5
                    if degrees[r+1][c] == 1: score += 5
                    if score > best_score:
                        best_score = score
                        best_edge = ('V', r, c)

        if best_edge is None:
            # Fallback: any unknown
            for r in range(R):
                for c in range(C-1):
                    if H[r][c] == 0: return ('H', r, c)
            for r in range(R-1):
                for c in range(C):
                    if V[r][c] == 0: return ('V', r, c)
        return best_edge

    def backtrack():
        if not propagate():
            return False

        if is_solved():
            return True

        var = get_next_variable()
        if var is None:
            return False # No unknowns but not solved

        etype, r, c = var

        # Try On
        changes = set_edge_v2(etype, r, c, 1)
        if changes is not None:
            has_cycle = any(ch[0] == 'cycle' for ch in changes)
            if not has_cycle:
                if backtrack():
                    return True
            undo_changes_v2(changes)

        # Try Off
        changes = set_edge_v2(etype, r, c, -1)
        if changes is not None:
            if backtrack():
                return True
            undo_changes_v2(changes)

        return False

    if backtrack():
        # Construct path
        # Find start node (any with degree 2)
        start = None
        for r in range(R):
            for c in range(C):
                if degrees[r][c] == 2:
                    start = (r, c)
                    break
            if start: break

        if not start:
            return "No Solution"

        path = [start]
        curr = start
        prev = None

        while True:
            r, c = curr
            found_next = False
            for et, er, ec, d in get_edges(r, c):
                val = H[er][ec] if et == 'H' else V[er][ec]
                if val == 1:
                    nr, nc = r, c
                    if et == 'H': nc += d
                    else: nr += d

                    if (nr, nc) != prev:
                        path.append((nr, nc))
                        prev = curr
                        curr = (nr, nc)
                        found_next = True
                        break
            if not found_next:
                break
            if curr == start:
                break

        return path
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
