OBSERVATION = {'U': [0, 0, 0, 0], 'D': [0, 0, 0, 0], 'L': [0, 0, 2, 0], 'R': [0, 1, 0, 3]}

def solve(obs):
    """
    Solves the Skyscrapers puzzle using backtracking with constraint propagation.
    Mimics human logic:
    1. Deduce obvious placements (Clue 1 -> Max height, Clue N -> Sequence).
    2. Maintain domains (possible values) for each cell.
    3. Use MRV (Minimum Remaining Values) heuristic for search.
    4. Prune using visibility constraints (min/max possible visible buildings).
    """
    N = len(obs['U'])
    grid = [[0] * N for _ in range(N)]
    U, D, L, R = obs['U'], obs['D'], obs['L'], obs['R']

    # Domains: domains[r][c] is the set of possible values for cell (r, c)
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    def set_val(r, c, val):
        """Sets grid[r][c] to val and removes val from row/col domains."""
        grid[r][c] = val
        domains[r][c] = {val} # Effectively fixed
        for j in range(N):
            if j != c: 
                domains[r][j].discard(val)
        for i in range(N):
            if i != r: 
                domains[i][c].discard(val)

    # --- Initial Deductions (Human-like Step 1) ---

    # Clue 1: The tallest building (N) must be at the edge.
    for c in range(N):
        if U[c] == 1: set_val(0, c, N)
        if D[c] == 1: set_val(N - 1, c, N)
    for r in range(N):
        if L[r] == 1: set_val(r, 0, N)
        if R[r] == 1: set_val(r, N - 1, N)

    # Clue N: Buildings must be in increasing order 1..N from the clue.
    for c in range(N):
        if U[c] == N:
            for i in range(N): set_val(i, c, i + 1)
        if D[c] == N:
            for i in range(N): set_val(N - 1 - i, c, i + 1)
    for r in range(N):
        if L[r] == N:
            for j in range(N): set_val(r, j, j + 1)
        if R[r] == N:
            for j in range(N): set_val(r, N - 1 - j, j + 1)

    # --- Visibility Check Logic (Human-like Step 4: Pruning) ---

    def check_line(line, clue):
        """
        Checks if a line (row or col) is consistent with the clue.
        Handles partial lines by estimating min/max possible visibility.
        """
        if clue == 0: return True

        curr_vis = 0
        max_h = 0
        zeros = 0

        for h in line:
            if h == 0:
                zeros += 1
                continue
            if h > max_h:
                max_h = h
                curr_vis += 1

        # If line is full, check exact match
        if zeros == 0:
            return curr_vis == clue

        # Pruning Logic:
        # Min possible visible:
        # If we haven't seen N yet (max_h < N), we MUST see N later.
        # So min_vis is at least curr_vis + 1.
        # If we have seen N, min_vis is curr_vis (assuming rest are hidden).
        min_vis = curr_vis + (1 if max_h < N else 0)

        # Max possible visible:
        # Optimistic: every remaining building is visible.
        max_vis = curr_vis + zeros

        return min_vis <= clue <= max_vis

    def is_consistent():
        """Checks all clues against current grid state."""
        for r in range(N):
            if not check_line(grid[r], L[r]): return False
            if not check_line(grid[r][::-1], R[r]): return False
        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            if not check_line(col, U[c]): return False
            if not check_line(col[::-1], D[c]): return False
        return True

    # --- Backtracking Search (Human-like Step 2 & 3) ---

    def get_best_cell():
        """MRV Heuristic: Find empty cell with fewest possibilities."""
        best = None
        min_len = N + 1
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    l = len(domains[r][c])
                    if l < min_len:
                        min_len = l
                        best = (r, c)
                    if l == 1: 
                        # Should have been filled by propagation, but if not, prioritize
                        pass 
        return best

    def search():
        cell = get_best_cell()
        if not cell: 
            return True # Solved

        r, c = cell
        # Try values in sorted order (deterministic)
        for val in sorted(list(domains[r][c])):
            # Fast uniqueness check
            row_conflict = any(grid[r][j] == val for j in range(N) if j != c)
            if row_conflict: continue

            col_conflict = any(grid[i][c] == val for i in range(N) if i != r)
            if col_conflict: continue

            # Place value
            grid[r][c] = val

            # Propagate constraints (Forward Checking)
            removed = []
            for j in range(N):
                if j != c and val in domains[r][j]:
                    domains[r][j].discard(val)
                    removed.append(('r', r, j))
            for i in range(N):
                if i != r and val in domains[i][c]:
                    domains[i][c].discard(val)
                    removed.append(('c', i, c))

            # Check consistency and recurse
            if is_consistent() and search():
                return True

            # Backtrack
            grid[r][c] = 0
            for item in removed:
                if item[0] == 'r':
                    domains[item[1]][item[2]].add(val)
                else:
                    domains[item[1]][item[2]].add(val)

        return False

    if search():
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
