def solve(observation):
    data = observation['data']
    N = len(data)

    # Precompute conflicts: for each row/col and value, list the indices
    # row_vals[r][val] = [c1, c2, ...]
    row_vals = {}
    col_vals = {}
    for r in range(N):
        row_vals[r] = {}
        for c in range(N):
            v = data[r][c]
            if v not in row_vals[r]: row_vals[r][v] = []
            row_vals[r][v].append(c)

    for c in range(N):
        col_vals[c] = {}
        for r in range(N):
            v = data[r][c]
            if v not in col_vals[c]: col_vals[c][v] = []
            col_vals[c][v].append(r)

    # Mask states: 0=Unknown, 1=White (Unshaded), 2=Black (Shaded)
    initial_mask = [[0]*N for _ in range(N)]

    def get_white_components(mask):
        visited = [[False]*N for _ in range(N)]
        components = []
        for r in range(N):
            for c in range(N):
                if mask[r][c] == 1 and not visited[r][c]:
                    comp = []
                    stack = [(r,c)]
                    visited[r][c] = True
                    while stack:
                        cr, cc = stack.pop()
                        comp.append((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0<=nr<N and 0<=nc<N and mask[nr][nc]==1 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                    components.append(comp)
        return components

    def propagate(mask):
        # Returns (success, new_mask)
        # Iterative propagation until stable
        curr = [row[:] for row in mask]

        while True:
            changes_made = False

            # Rule A: White forces Black (Uniqueness constraint)
            # If a cell is White, all other cells with same value in same row/col must be Black
            for r in range(N):
                for c in range(N):
                    if curr[r][c] == 1: # White
                        val = data[r][c]
                        # Check row duplicates
                        for c2 in row_vals[r].get(val, []):
                            if c2 != c:
                                if curr[r][c2] == 1:
                                    return False, None # Contradiction: Two whites with same value
                                if curr[r][c2] == 0:
                                    curr[r][c2] = 2
                                    changes_made = True
                        # Check col duplicates
                        for r2 in col_vals[c].get(val, []):
                            if r2 != r:
                                if curr[r2][c] == 1:
                                    return False, None
                                if curr[r2][c] == 0:
                                    curr[r2][c] = 2
                                    changes_made = True

            # Rule B: Black forces White (Adjacency constraint)
            # If a cell is Black, orthogonal neighbors must be White
            for r in range(N):
                for c in range(N):
                    if curr[r][c] == 2: # Black
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<N and 0<=nc<N:
                                if curr[nr][nc] == 2:
                                    return False, None # Contradiction: Adjacent blacks
                                if curr[nr][nc] == 0:
                                    curr[nr][nc] = 1
                                    changes_made = True

            if not changes_made:
                break

        return True, curr

    def solve_recursive(mask):
        # 1. Propagate constraints
        success, curr_mask = propagate(mask)
        if not success:
            return None

        # 2. Identify unknowns
        unknowns = []
        for r in range(N):
            for c in range(N):
                if curr_mask[r][c] == 0:
                    unknowns.append((r,c))

        # 3. Base case: No unknowns left
        if not unknowns:
            # Check connectivity of white cells
            comps = get_white_components(curr_mask)
            # Valid if 0 or 1 component (0 components means all black, which is technically connected but unlikely intended)
            # Usually puzzles imply at least one white cell, but "at most once" allows all black if no conflicts?
            # Actually, if all black, no unshaded numbers, so constraints 1 & 2 are vacuously true.
            # Constraint 3 (no adjacent black) would be violated if N>1.
            # So all black is impossible for N>1 due to Rule 3.
            if len(comps) <= 1:
                return curr_mask
            else:
                return None

        # 4. Heuristic: Pick best unknown to branch on
        # Prioritize cells that are part of many conflicts (high impact if set to White)
        best_r, best_c = -1, -1
        max_score = -1

        for r, c in unknowns:
            val = data[r][c]
            # Score based on number of duplicates in row and col
            score = len(row_vals[r].get(val, [])) + len(col_vals[c].get(val, []))
            if score > max_score:
                max_score = score
                best_r, best_c = r, c

        # Try setting to White (1) first (usually we want to keep cells unshaded)
        mask_white = [row[:] for row in curr_mask]
        mask_white[best_r][best_c] = 1
        res = solve_recursive(mask_white)
        if res is not None:
            return res

        # Try setting to Black (2)
        mask_black = [row[:] for row in curr_mask]
        mask_black[best_r][best_c] = 2
        res = solve_recursive(mask_black)
        if res is not None:
            return res

        return None

    final_mask = solve_recursive(initial_mask)

    if final_mask is None:
        return "No Solution"

    # Format output: 'B' for Black, None for White
    result = []
    for r in range(N):
        row_res = []
        for c in range(N):
            if final_mask[r][c] == 2:
                row_res.append('B')
            else:
                row_res.append(None)
        result.append(row_res)
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
