            # Everything after N is hidden. We only care about the prefix ending at N.
            prefix = line[:n_pos+1]
            sub_line = prefix[:-1] # Part before N

            # Calculate current visibility in the part before N
            curr_vis = 0
            max_h = 0
            for x in sub_line:
                if x == 0: continue
                if x > max_h:
                    max_h = x
                    curr_vis += 1

            # N is always visible. So we need (clue - 1) visible buildings in sub_line.
            needed = (clue - 1) - curr_vis
            empty_count = sub_line.count(0)

            if needed < 0: return False # Too many visible already
            if needed > empty_count: return False # Not enough space

            # Check if we have enough numbers larger than current max_h to fill the needed spots
            used_in_prefix = set(prefix) - {0}
            # Available numbers must be > max_h and not used. N is used, so excluded.
            available_high = [x for x in range(max_h + 1, N + 1) if x not in used_in_prefix]

            if len(available_high) < needed:
                return False
            return True

        # 4. If N is NOT present
        curr_vis = 0
        max_h = 0
        for x in line:
            if x == 0: continue
            if x > max_h:
                max_h = x
                curr_vis += 1

        needed = clue - curr_vis

        # If we already see >= clue buildings, and N is not there, 
        # adding N will increase count further -> invalid.
        if needed <= 0: 
            return False

        empty_count = line.count(0)
        if empty_count < needed:
            return False

        # Check availability of numbers
        used_in_line = set(line) - {0}
        # We need 'needed' numbers > max_h. One of them will be N.
        available_high = [x for x in range(max_h + 1, N + 1) if x not in used_in_line]

        if len(available_high) < needed:
            return False
        return True

    # Apply immediate deductions for Clue 1 and Clue N
    for c in range(N):
        if U[c] == 1: grid[0][c] = N
        if D[c] == 1: grid[N-1][c] = N
    for r in range(N):
        if L[r] == 1: grid[r][0] = N
        if R[r] == 1: grid[r][N-1] = N

    for c in range(N):
        if U[c] == N:
            for r in range(N): grid[r][c] = r + 1
        if D[c] == N:
            for r in range(N): grid[N-1-r][c] = r + 1
    for r in range(N):
        if L[r] == N:
            for c in range(N): grid[r][c] = c + 1
        if R[r] == N:
            for c in range(N): grid[r][N-1-c] = c + 1

    # Constraint Propagation
    def update_domains(current_domains):
        while True:
            changed = False
            for r in range(N):
                for c in range(N):
                    if grid[r][c] != 0:
                        val = grid[r][c]
                        # Remove from row
                        for cc in range(N):
                            if cc != c and val in current_domains[r][cc]:
                                current_domains[r][cc].discard(val)
                                changed = True
                        # Remove from col
                        for rr in range(N):
                            if rr != r and val in current_domains[rr][c]:
                                current_domains[rr][c].discard(val)
                                changed = True
                    else:
                        # If domain has only 1 value, place it
                        if len(current_domains[r][c]) == 1:
                            val = next(iter(current_domains[r][c]))
                            grid[r][c] = val
                            changed = True
                        elif len(current_domains[r][c]) == 0:
                            return False # Contradiction

            # Check line validity after changes
            for r in range(N):
                if not is_line_valid(grid[r], L[r]) or not is_line_valid(grid[r][::-1], R[r]):
                    return False
            for c in range(N):
                col = [grid[rr][c] for rr in range(N)]
                if not is_line_valid(col, U[c]) or not is_line_valid(col[::-1], D[c]):
                    return False

            if not changed:
                break
        return True

    if not update_domains(domains):
        return "No Solution"

    # Backtracking Solver
    def solve_recursive(current_domains):
        # MRV Heuristic: Pick cell with smallest domain
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    size = len(current_domains[r][c])
                    if size < min_size:
                        min_size = size
                        best_cell = (r, c)

        if best_cell is None:
            # Grid full, verify solution
            for r in range(N):
                if count_visible(grid[r]) != L[r]: return False
                if count_visible(grid[r][::-1]) != R[r]: return False
            for c in range(N):
                col = [grid[r][c] for r in range(N)]
                if count_visible(col) != U[c]: return False
                if count_visible(col[::-1]) != D[c]: return False
            return True

        r, c = best_cell
        for val in sorted(list(current_domains[r][c])):
            grid[r][c] = val

            # Check validity of affected row and column
            row_vals = grid[r]
            col_vals = [grid[rr][c] for rr in range(N)]

            if is_line_valid(row_vals, L[r]) and is_line_valid(row_vals[::-1], R[r]) and \
               is_line_valid(col_vals, U[c]) and is_line_valid(col_vals[::-1], D[c]):

                # Create new domains for next level
                next_domains = [[s.copy() for s in row] for row in current_domains]

                # Remove val from row/col domains
                for cc in range(N):
                    if cc != c: next_domains[r][cc].discard(val)
                for rr in range(N):
                    if rr != r: next_domains[rr][c].discard(val)

                # Check for empty domains (forward checking)
                possible = True
                for rr in range(N):
                    for cc in range(N):
                        if grid[rr][cc] == 0 and len(next_domains[rr][cc]) == 0:
                            possible = False; break
                    if not possible: break

                if possible:
                    if solve_recursive(next_domains):
                        return True

            grid[r][c] = 0 # Backtrack
        return False

    if solve_recursive(domains):
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
