import copy

def solve(observation):
    # Deep copy to avoid modifying original
    grid = [row[:] for row in observation['data']]
    N = len(grid)

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    def sees_bulb(r, c, g):
        # Check Up
        for i in range(r-1, -1, -1):
            val = g[i][c]
            if val == 'B': return True
            if isinstance(val, int): break
        # Check Down
        for i in range(r+1, N):
            val = g[i][c]
            if val == 'B': return True
            if isinstance(val, int): break
        # Check Left
        for j in range(c-1, -1, -1):
            val = g[r][j]
            if val == 'B': return True
            if isinstance(val, int): break
        # Check Right
        for j in range(c+1, N):
            val = g[r][j]
            if val == 'B': return True
            if isinstance(val, int): break
        return False

    def is_lit(r, c, g):
        # Check Up
        for i in range(r-1, -1, -1):
            val = g[i][c]
            if val == 'B': return True
            if isinstance(val, int): break
        # Check Down
        for i in range(r+1, N):
            val = g[i][c]
            if val == 'B': return True
            if isinstance(val, int): break
        # Check Left
        for j in range(c-1, -1, -1):
            val = g[r][j]
            if val == 'B': return True
            if isinstance(val, int): break
        # Check Right
        for j in range(c+1, N):
            val = g[r][j]
            if val == 'B': return True
            if isinstance(val, int): break
        return False

    def propagate(g):
        changed = True
        while changed:
            changed = False

            # Rule 1: Clues (0-clues, Saturated, Forced)
            for r in range(N):
                for c in range(N):
                    val = g[r][c]
                    if isinstance(val, int) and val >= 0:
                        bulbs = 0
                        unknowns = 0
                        neighbors = get_neighbors(r, c)
                        for nr, nc in neighbors:
                            nval = g[nr][nc]
                            if nval == 'B':
                                bulbs += 1
                            elif nval is None:
                                unknowns += 1

                        if bulbs > val:
                            return False
                        if bulbs == val:
                            for nr, nc in neighbors:
                                if g[nr][nc] is None:
                                    g[nr][nc] = '.'
                                    changed = True
                        if bulbs + unknowns == val:
                            for nr, nc in neighbors:
                                if g[nr][nc] is None:
                                    if sees_bulb(nr, nc, g):
                                        return False
                                    g[nr][nc] = 'B'
                                    changed = True

            # Rule 2: Visibility (Bulbs mark line of sight as empty)
            for r in range(N):
                for c in range(N):
                    if g[r][c] == 'B':
                        # Up
                        for i in range(r-1, -1, -1):
                            val = g[i][c]
                            if val == 'B': return False
                            if val is None:
                                g[i][c] = '.'
                                changed = True
                            if isinstance(val, int): break
                        # Down
                        for i in range(r+1, N):
                            val = g[i][c]
                            if val == 'B': return False
                            if val is None:
                                g[i][c] = '.'
                                changed = True
                            if isinstance(val, int): break
                        # Left
                        for j in range(c-1, -1, -1):
                            val = g[r][j]
                            if val == 'B': return False
                            if val is None:
                                g[r][j] = '.'
                                changed = True
                            if isinstance(val, int): break
                        # Right
                        for j in range(c+1, N):
                            val = g[r][j]
                            if val == 'B': return False
                            if val is None:
                                g[r][j] = '.'
                                changed = True
                            if isinstance(val, int): break

            # Rule 3: Unlit cells (Heuristic deduction)
            if not changed:
                unlit_cells = []
                for r in range(N):
                    for c in range(N):
                        if g[r][c] is None or g[r][c] == '.':
                            if not is_lit(r, c, g):
                                unlit_cells.append((r,c))

                for r, c in unlit_cells:
                    valid_spots = []
                    # Row segment
                    for j in range(c-1, -1, -1):
                        val = g[r][j]
                        if isinstance(val, int): break
                        if val is None: valid_spots.append((r,j))
                    for j in range(c+1, N):
                        val = g[r][j]
                        if isinstance(val, int): break
                        if val is None: valid_spots.append((r,j))
                    # Col segment
                    for i in range(r-1, -1, -1):
                        val = g[i][c]
                        if isinstance(val, int): break
                        if val is None: valid_spots.append((i,c))
                    for i in range(r+1, N):
                        val = g[i][c]
                        if isinstance(val, int): break
                        if val is None: valid_spots.append((i,c))

                    real_valid = []
                    for sr, sc in valid_spots:
                        if not sees_bulb(sr, sc, g):
                            real_valid.append((sr, sc))

                    if len(real_valid) == 0:
                        return False
                    if len(real_valid) == 1:
                        sr, sc = real_valid[0]
                        g[sr][sc] = 'B'
                        changed = True
                        break 
                if changed: continue

        return True

    def is_solved(g):
        for r in range(N):
            for c in range(N):
                val = g[r][c]
                if val is None: return False
                if val == '.':
                    if not is_lit(r, c, g): return False
                if isinstance(val, int) and val >= 0:
                    bulbs = 0
                    for nr, nc in get_neighbors(r, c):
                        if g[nr][nc] == 'B':
                            bulbs += 1
                    if bulbs != val: return False
        return True

    def backtrack(g):
        if not propagate(g):
            return None
        if is_solved(g):
            return g

        r, c = -1, -1
        for i in range(N):
            for j in range(N):
                if g[i][j] is None:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1: return None

        # Try 'B'
        if not sees_bulb(r, c, g):
            ng = copy.deepcopy(g)
            ng[r][c] = 'B'
            res = backtrack(ng)
            if res: return res

        # Try '.'
        ng = copy.deepcopy(g)
        ng[r][c] = '.'
        res = backtrack(ng)
        if res: return res

        return None

    res = backtrack(grid)
    if res:
        out = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if res[r][c] == 'B':
                    out[r][c] = 'B'
        return out
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
