                    if g[r][c] == 'B' and g[r][c+1] == 'B' and g[r][c+2] is None:
                        g[r][c+2] = 'W'
                        changed = True
                    # ? B B -> W
                    if g[r][c] is None and g[r][c+1] == 'B' and g[r][c+2] == 'B':
                        g[r][c] = 'W'
                        changed = True
                    # B ? B -> W
                    if g[r][c] == 'B' and g[r][c+1] is None and g[r][c+2] == 'B':
                        g[r][c+1] = 'W'
                        changed = True

                    # W W ? -> B
                    if g[r][c] == 'W' and g[r][c+1] == 'W' and g[r][c+2] is None:
                        g[r][c+2] = 'B'
                        changed = True
                    # ? W W -> B
