                    if g[r][c] == 'B' and g[r+1][c] is None and g[r+2][c] == 'B':
                        g[r+1][c] = 'W'
                        changed = True

                    if g[r][c] == 'W' and g[r+1][c] == 'W' and g[r+2][c] is None:
                        g[r+2][c] = 'B'
                        changed = True
                    if g[r][c] is None and g[r+1][c] == 'W' and g[r+2][c] == 'W':
                        g[r][c] = 'B'
                        changed = True
                    if g[r][c] == 'W' and g[r+1][c] is None and g[r+2][c] == 'W':
                        g[r+1][c] = 'B'
