            for (r, c), typ in h_cons.items():
                if c < N-1:
                    v1, v2 = g[r][c], g[r][c+1]
                    if typ == '=':
                        if v1 and not v2:
                            g[r][c+1] = v1
                            changed = True
                        elif v2 and not v1:
                            g[r][c] = v2
                            changed = True
                        elif v1 and v2 and v1 != v2:
                            return None
                    elif typ == 'x':
                        if v1 and not v2:
                            g[r][c+1] = 'W' if v1 == 'B' else 'B'
                            changed = True
                        elif v2 and not v1:
                            g[r][c] = 'W' if v2 == 'B' else 'B'
                            changed = True
                        elif v1 and v2 and v1 == v2:
                            return None

            for (r, c), typ in v_cons.items():
                if r < N-1:
                    v1, v2 = g[r][c], g[r+1][c]
                    if typ == '=':
                        if v1 and not v2:
                            g[r+1][c] = v1
                            changed = True
                        elif v2 and not v1:
                            g[r][c] = v2
                            changed = True
