    def get_next_cell(g):
        best_cell = None
        max_filled = -1
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    row_filled = sum(1 for x in g[r] if x is not None)
                    col_filled = sum(1 for row in g if row[c] is not None)
                    score = row_filled + col_filled
                    if score > max_filled:
                        max_filled = score
                        best_cell = (r, c)
        return best_cell

    def backtrack(g):
        g = apply_constraints(g)
        if g is None:
            return None
        if is_solved(g):
            return g

        cell = get_next_cell(g)
        if cell is None:
            return g

        r, c = cell

        # Try B
        g_copy_b = [row[:] for row in g]
        g_copy_b[r][c] = 'B'
        res_b = backtrack(g_copy_b)
        if res_b:
            return res_b

        # Try W
        g_copy_w = [row[:] for row in g]
        g_copy_w[r][c] = 'W'
        res_w = backtrack(g_copy_w)
        if res_w:
            return res_w

        return None

    final_grid = backtrack(grid)
    if final_grid:
        return final_grid
    return "No Solution"

