import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    unit_str = observation['unit']

    # Parse unit dimensions
    if 'x' in unit_str:
        r_unit, c_unit = map(int, unit_str.split('x'))
    else:
        val = int(unit_str)
        r_unit, c_unit = val, val

    S = r_unit * c_unit
    N = len(data)

    # Validate grid size
    if N != S:
        # Fallback or error, but assuming valid input per prompt
        pass

    all_values = set(range(1, S + 1))

    # Precompute units and peers
    units = []

    # Rows
    for r in range(S):
        units.append([(r, c) for c in range(S)])

    # Cols
    for c in range(S):
        units.append([(r, c) for r in range(S)])

    # Boxes
    num_box_rows = S // r_unit
    num_box_cols = S // c_unit

    for br in range(num_box_rows):
        for bc in range(num_box_cols):
            box_cells = []
            for r in range(br * r_unit, (br + 1) * r_unit):
                for c in range(bc * c_unit, (bc + 1) * c_unit):
                    box_cells.append((r, c))
            units.append(box_cells)

    # Map cell to units
    cell_units = {}
    for r in range(S):
        for c in range(S):
            cell_units[(r, c)] = []

    for i, unit in enumerate(units):
        for cell in unit:
            cell_units[cell].append(i)

    # Peers
    peers = {}
    for r in range(S):
        for c in range(S):
            p = set()
            for u_idx in cell_units[(r, c)]:
                for cell in units[u_idx]:
                    if cell != (r, c):
                        p.add(cell)
            peers[(r, c)] = p

    # Initialize domains
    domains = {}
    for r in range(S):
        for c in range(S):
            val = data[r][c]
            if val is not None:
                domains[(r, c)] = {val}
            else:
                domains[(r, c)] = all_values.copy()

    # Constraint Propagation
    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles (Elimination)
            # Find cells with only 1 possibility and eliminate from peers
            cells_to_check = list(domains.keys())
            for cell in cells_to_check:
                d = domains[cell]
                if len(d) == 1:
                    val = next(iter(d))
                    for peer in peers[cell]:
                        if val in domains[peer]:
                            domains[peer].remove(val)
                            changed = True
                            if len(domains[peer]) == 0:
                                return None # Contradiction

            # 2. Hidden Singles (Only Choice)
            for u_idx, unit in enumerate(units):
                # For each value, check if it has only one place in this unit
                for v in all_values:
                    candidates = []
                    for cell in unit:
                        if v in domains[cell]:
                            candidates.append(cell)

                    if len(candidates) == 1:
                        cell = candidates[0]
                        if len(domains[cell]) > 1:
                            domains[cell] = {v}
                            changed = True
                            # The new singleton will be processed in the next while loop iteration

        return domains

    # Initial propagation
    domains = propagate(domains)
    if domains is None:
        return "No Solution"

    def is_solved(domains):
        return all(len(d) == 1 for d in domains.values())

    if is_solved(domains):
        res = [[None]*S for _ in range(S)]
        for (r, c), d in domains.items():
            res[r][c] = next(iter(d))
        return res

    # Search with MRV
    def search(domains):
        if any(len(d) == 0 for d in domains.values()):
            return None

        if is_solved(domains):
            res = [[None]*S for _ in range(S)]
            for (r, c), d in domains.items():
                res[r][c] = next(iter(d))
            return res

        # MRV: Select unassigned variable with fewest legal values
        unsolved = [(cell, d) for cell, d in domains.items() if len(d) > 1]
        if not unsolved:
            return None 

        # Sort by number of possibilities
        unsolved.sort(key=lambda x: len(x[1]))
        cell, d = unsolved[0]

        # Try values
        for val in sorted(list(d)):
            new_domains = {k: v.copy() for k, v in domains.items()}
            new_domains[cell] = {val}

            res_domains = propagate(new_domains)
            if res_domains is not None:
                result = search(res_domains)
                if result is not None:
                    return result

        return None

    final_domains = search(domains)
    if final_domains is None:
        return "No Solution"

    res_grid = [[None]*S for _ in range(S)]
    for (r, c), d in final_domains.items():
        res_grid[r][c] = next(iter(d))
    return res_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
