def solve(observation):
    data = observation['data']
    N = len(data)

    # Grid Representation:
    # None: Unknown White
    # 'B': Bulb
    # 'E': Empty White (No bulb)
    # int (0-4): Black Clue
    # -1: Black Wall
    grid = [row[:] for row in data]

    def propagate(g):
        changed = True
        while changed:
            changed = False

            # 1. Clue Logic
            for r in range(N):
                for c in range(N):
                    val = g[r][c]
                    if isinstance(val, int) and val >= 0:
                        neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
                        bulbs = 0
                        unknowns = 0
                        valid_neighbors = []

                        for nr, nc in neighbors:
                            if 0 <= nr < N and 0 <= nc < N:
                                cell = g[nr][nc]
                                if cell == 'B':
                                    bulbs += 1
                                elif cell is None:
                                    unknowns += 1
                                    valid_neighbors.append((nr, nc))

                        if bulbs > val:
                            return False
                        if bulbs == val:
                            for nr, nc in valid_neighbors:
                                if g[nr][nc] is None:
                                    g[nr][nc] = 'E'
                                    changed = True
                        if bulbs + unknowns == val:
                            for nr, nc in valid_neighbors:
                                if g[nr][nc] is None:
                                    g[nr][nc] = 'B'
                                    changed = True

            # 2. Bulb Line of Sight Logic
            # Scan all bulbs and enforce constraints
            # We collect bulbs first to avoid modification issues during iteration if we were iterating,
            # but here we iterate range(N) so it's safe, but we need to detect changes.

            # To ensure we catch all, we can just loop. 
            # Optimization: Only process if we find a conflict or a None to mark.

            # Check for bulb conflicts and mark LOS
            for r in range(N):
                for c in range(N):
                    if g[r][c] == 'B':
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            while 0 <= nr < N and 0 <= nc < N:
                                cell = g[nr][nc]
                                if cell == -1 or isinstance(cell, int):
                                    break
                                if cell == 'B':
                                    return False # Conflict
                                if cell is None:
                                    g[nr][nc] = 'E'
                                    changed = True
                                nr += dr
                                nc += dc
        return True

    def is_solved(g):
        for r in range(N):
            for c in range(N):
                cell = g[r][c]
                if cell is None:
                    return False

                if cell == 'E' or cell == 'B':
                    illuminated = False
                    if cell == 'B':
                        illuminated = True
                    else:
                        # Check Row Left
                        for cc in range(c-1, -1, -1):
                            if g[r][cc] == 'B': illuminated = True; break
                            if g[r][cc] == -1 or isinstance(g[r][cc], int): break
                        if illuminated: continue
                        # Check Row Right
                        for cc in range(c+1, N):
                            if g[r][cc] == 'B': illuminated = True; break
                            if g[r][cc] == -1 or isinstance(g[r][cc], int): break
                        if illuminated: continue
                        # Check Col Up
                        for rr in range(r-1, -1, -1):
                            if g[rr][c] == 'B': illuminated = True; break
                            if g[rr][c] == -1 or isinstance(g[rr][c], int): break
                        if illuminated: continue
                        # Check Col Down
                        for rr in range(r+1, N):
                            if g[rr][c] == 'B': illuminated = True; break
                            if g[rr][c] == -1 or isinstance(g[rr][c], int): break

                    if not illuminated:
                        return False

        # Check clues satisfied
        for r in range(N):
            for c in range(N):
                val = g[r][c]
                if isinstance(val, int) and val >= 0:
                    bulbs = 0
                    for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
                        if 0 <= nr < N and 0 <= nc < N and g[nr][nc] == 'B':
                            bulbs += 1
                    if bulbs != val:
                        return False
        return True

    def get_unilluminated_any(g):
        for r in range(N):
            for c in range(N):
                cell = g[r][c]
                if cell == 'B': continue
                if cell == -1 or isinstance(cell, int): continue

                # White cell (None or E)
                illuminated = False
                # Left
                for cc in range(c-1, -1, -1):
                    if g[r][cc] == 'B': illuminated = True; break
                    if g[r][cc] == -1 or isinstance(g[r][cc], int): break
                if illuminated: continue
                # Right
                for cc in range(c+1, N):
                    if g[r][cc] == 'B': illuminated = True; break
                    if g[r][cc] == -1 or isinstance(g[r][cc], int): break
                if illuminated: continue
                # Up
                for rr in range(r-1, -1, -1):
                    if g[rr][c] == 'B': illuminated = True; break
                    if g[rr][c] == -1 or isinstance(g[rr][c], int): break
                if illuminated: continue
                # Down
                for rr in range(r+1, N):
                    if g[rr][c] == 'B': illuminated = True; break
                    if g[rr][c] == -1 or isinstance(g[rr][c], int): break

                if not illuminated:
                    return (r, c)
        return None

    def solve_recursive(g):
        if not propagate(g):
            return None

        if is_solved(g):
            return g

        target = get_unilluminated_any(g)

        if target is None:
            # All white cells illuminated, but maybe some None left?
            # is_solved checks for None, so if we are here, is_solved is False.
            # So there must be None cells.
            for r in range(N):
                for c in range(N):
                    if g[r][c] is None:
                        target = (r, c)
                        break
                if target: break

            if target is None:
                return None # Should be caught by is_solved

        r, c = target
        cell_val = g[r][c]

        candidates = []
        if cell_val is None:
            candidates.append((r, c))

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N:
                val = g[nr][nc]
                if val == -1 or isinstance(val, int): break
                if val is None:
                    candidates.append((nr, nc))
                nr += dr
                nc += dc

        # Try candidates
        # To improve efficiency, we can shuffle or sort, but deterministic is fine.
        for cr, cc in candidates:
            g_copy = [row[:] for row in g]
            g_copy[cr][cc] = 'B'
            res = solve_recursive(g_copy)
            if res:
                return res

        return None

    result = solve_recursive(grid)

    if result:
        out_grid = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if result[r][c] == 'B':
                    out_grid[r][c] = 'B'
        return out_grid
    else:
        return "No Solution"

