OBSERVATION = {'data': [[None, None, 0, None, 0, None], [2, None, None, None, None, None], [None, None, 2, None, None, 2], [2, 2, None, 2, 1, None], [0, None, None, None, None, 0], [None, None, 0, None, 1, None]]}

import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data) - 1  # Grid size N x N cells, (N+1)x(N+1) dots

    # Board: 0=unknown, 1='/', 2='\'
    board = [[0] * N for _ in range(N)]

    # DSU for dots
    num_dots = (N + 1) * (N + 1)

    def dot_idx(r, c):
        return r * (N + 1) + c

    # Map: dot (r, c) -> list of (cell_r, cell_c, connects_if_val)
    # connects_if_val: 1 for '/', 2 for '\'
    dot_cells = {}
    for r in range(N + 1):
        for c in range(N + 1):
            neighbors = []
            # TL: cell (r-1, c-1), connects if '\' (2)
            if r > 0 and c > 0:
                neighbors.append((r-1, c-1, 2))
            # TR: cell (r-1, c), connects if '/' (1)
            if r > 0 and c < N:
                neighbors.append((r-1, c, 1))
            # BL: cell (r, c-1), connects if '/' (1)
            if r < N and c > 0:
                neighbors.append((r, c-1, 1))
            # BR: cell (r, c), connects if '\' (2)
            if r < N and c < N:
                neighbors.append((r, c, 2))
            dot_cells[(r, c)] = neighbors

    def get_connected_dots(cell_r, cell_c, val):
        if val == 1:  # '/' connects (r+1, c) and (r, c+1)
            return (dot_idx(cell_r + 1, cell_c), dot_idx(cell_r, cell_c + 1))
        elif val == 2:  # '\' connects (r, c) and (r+1, c+1)
            return (dot_idx(cell_r, cell_c), dot_idx(cell_r + 1, cell_c + 1))
        return None

    def find(parent, i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(parent, i, j):
        root_i = find(parent, i)
        root_j = find(parent, j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    def propagate(board, parent, clues):
        changed = True
        while changed:
            changed = False
            for r in range(N + 1):
                for c in range(N + 1):
                    clue = clues[r][c]
                    if clue is None:
                        continue

                    neighbors = dot_cells[(r, c)]
                    connected_count = 0
                    unknown_cells = []

                    for cr, cc, req_val in neighbors:
                        val = board[cr][cc]
                        if val == req_val:
                            connected_count += 1
                        elif val == 0:
                            unknown_cells.append((cr, cc, req_val))

                    # If connected_count == clue, all unknowns must NOT connect to this dot.
                    # This means they must take the value that does NOT match req_val.
                    if connected_count == clue:
                        for cr, cc, req_val in unknown_cells:
                            forced_val = 2 if req_val == 1 else 1
                            if board[cr][cc] == 0:
                                # Even though it doesn't connect to the current dot, 
                                # it connects two other dots, so we must check for loops.
                                u, v = get_connected_dots(cr, cc, forced_val)
                                root_u = find(parent, u)
                                root_v = find(parent, v)
                                if root_u == root_v:
                                    return False, None, None  # Loop detected

                                board[cr][cc] = forced_val
                                union(parent, u, v)
                                changed = True
                            elif board[cr][cc] != forced_val:
                                return False, None, None

                    # If connected_count + len(unknowns) == clue, all unknowns MUST connect.
                    elif connected_count + len(unknown_cells) == clue:
                        for cr, cc, req_val in unknown_cells:
                            forced_val = req_val
                            if board[cr][cc] == 0:
                                u, v = get_connected_dots(cr, cc, forced_val)
                                root_u = find(parent, u)
                                root_v = find(parent, v)
                                if root_u == root_v:
                                    return False, None, None  # Loop detected

                                board[cr][cc] = forced_val
                                union(parent, u, v)
                                changed = True
                            elif board[cr][cc] != forced_val:
                                return False, None, None
        return True, board, parent

    parent = list(range(num_dots))
    success, board, parent = propagate(board, parent, data)
    if not success:
        return "No Solution"

    def get_empty_cell(b):
        for r in range(N):
            for c in range(N):
                if b[r][c] == 0:
                    return r, c
        return None

    def solve_recursive(b, p):
        pos = get_empty_cell(b)
        if pos is None:
            return b

        r, c = pos

        # Try 1 ('/')
        b1 = [row[:] for row in b]
        b1[r][c] = 1
        p1 = list(p)
        u, v = get_connected_dots(r, c, 1)
        root_u = find(p1, u)
        root_v = find(p1, v)

        if root_u != root_v:
            union(p1, u, v)
            success, res_b, res_p = propagate(b1, p1, data)
            if success:
                res = solve_recursive(res_b, res_p)
                if res:
                    return res

        # Try 2 ('\')
        b2 = [row[:] for row in b]
        b2[r][c] = 2
        p2 = list(p)
        u, v = get_connected_dots(r, c, 2)
        root_u = find(p2, u)
        root_v = find(p2, v)

        if root_u != root_v:
            union(p2, u, v)
            success, res_b, res_p = propagate(b2, p2, data)
            if success:
                res = solve_recursive(res_b, res_p)
                if res:
                    return res

        return None

    final_board = solve_recursive(board, parent)

    if final_board:
        res = []
        for r in range(N):
            row_str = []
            for c in range(N):
                if final_board[r][c] == 1:
                    row_str.append('/')
                else:
                    row_str.append('\\')
            res.append(row_str)
        return res
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
