sys.setrecursionlimit(3000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # State: 0 = Unknown, 1 = White, 2 = Black
    initial_state = [[0 for _ in range(N)] for _ in range(N)]

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    def propagate(state):
        # Returns True if consistent, False if contradiction
        # Modifies state in place

        changed = True
        while changed:
            changed = False

            # 1. Check Adjacent Blacks (Contradiction)
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 2:
                        for nr, nc in get_neighbors(r, c):
                            if state[nr][nc] == 2:
                                return False

            # 2. Check Duplicate Whites in Row/Col (Contradiction)
            for r in range(N):
                seen = {}
                for c in range(N):
                    if state[r][c] == 1:
                        val = data[r][c]
                        if val in seen:
                            return False
                        seen[val] = c

            for c in range(N):
                seen = {}
                for r in range(N):
                    if state[r][c] == 1:
                        val = data[r][c]
                        if val in seen:
                            return False
                        seen[val] = r

            # 3. Apply Rules
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 2: # Black
                        # Neighbors must be White
                        for nr, nc in get_neighbors(r, c):
                            if state[nr][nc] == 0:
                                state[nr][nc] = 1
                                changed = True
                            elif state[nr][nc] == 2:
                                return False 

                    elif state[r][c] == 1: # White
                        val = data[r][c]

                        # Row duplicates must be Black
                        for c2 in range(N):
                            if c2 != c and data[r][c2] == val:
                                if state[r][c2] == 0:
                                    state[r][c2] = 2
                                    changed = True
                                elif state[r][c2] == 1:
                                    return False 

                        # Col duplicates must be Black
                        for r2 in range(N):
                            if r2 != r and data[r2][c] == val:
                                if state[r2][c] == 0:
                                    state[r2][c] = 2
                                    changed = True
                                elif state[r2][c] == 1:
                                    return False
        return True

    def is_connected(state):
        white_cells = []
        for r in range(N):
            for c in range(N):
                if state[r][c] == 1:
                    white_cells.append((r, c))

        if not white_cells:
            return True 

        start_r, start_c = white_cells[0]
        visited = set()
        queue = [(start_r, start_c)]
        visited.add((start_r, start_c))

        idx = 0
        while idx < len(queue):
            r, c = queue[idx]
            idx += 1
            for nr, nc in get_neighbors(r, c):
                if state[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(white_cells)

    def backtrack(state):
        # Propagate constraints
        if not propagate(state):
            return None

        # Check for unknowns
        unknowns = []
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    unknowns.append((r, c))

        if not unknowns:
            if is_connected(state):
                res = []
                for r in range(N):
                    row_res = []
                    for c in range(N):
                        if state[r][c] == 2:
                            row_res.append('B')
                        else:
                            row_res.append(None)
                    res.append(row_res)
                return res
            else:
                return None

        # Heuristic: Pick cell with most potential conflicts to prune faster
        best_cell = None
        max_conflicts = -1

        for r, c in unknowns:
            val = data[r][c]
            conflicts = 0
            # Count duplicates in row (that are not Black)
            for c2 in range(N):
                if c2 != c and state[r][c2] != 2: 
                     if data[r][c2] == val:
                         conflicts += 1
            # Count duplicates in col (that are not Black)
            for r2 in range(N):
                if r2 != r and state[r2][c] != 2:
                     if data[r2][c] == val:
                         conflicts += 1

            if conflicts > max_conflicts:
                max_conflicts = conflicts
                best_cell = (r, c)

        if best_cell:
            r, c = best_cell
        else:
            r, c = unknowns[0]

        # Try Black
        state_black = [row[:] for row in state]
        state_black[r][c] = 2
        res = backtrack(state_black)
        if res:
            return res

        # Try White
        state_white = [row[:] for row in state]
        state_white[r][c] = 1
        res = backtrack(state_white)
        if res:
            return res

        return None

    result = backtrack(initial_state)
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
