OBSERVATION = {'data': [[None, None, None, None], [None, None, None, None], [None, None, None, None], [None, None, None, None]], 'horizontal': {"(0, 1.5)": "<", "(0, 2.5)": ">"}, 'vertical': {"(1.5, 1)": "v", "(2.5, 0)": "v", "(2.5, 1)": "v", "(2.5, 3)": "v"}}

import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    horizontal = observation.get('horizontal', {})
    vertical = observation.get('vertical', {})

    # Initialize domains: each cell can be 1..N
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Apply givens from data
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Helper to parse keys from the observation dictionary
    def parse_h_key(key):
        # Format: '(row, col+0.5)'
        content = key.strip("()")
        parts = content.split(",")
        r = int(parts[0].strip())
        c_val = float(parts[1].strip())
        c = int(c_val - 0.5) # The column index to the left of the sign
        return r, c

    def parse_v_key(key):
        # Format: '(row+0.5, col)'
        content = key.strip("()")
        parts = content.split(",")
        r_val = float(parts[0].strip())
        r = int(r_val - 0.5) # The row index above the sign
        c = int(parts[1].strip())
        return r, c

    # Constraint Propagation (AC-3 style + Hidden Singles)
    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1. Inequality Constraints
            # Horizontal inequalities
            for key, op in horizontal.items():
                r, c = parse_h_key(key)
                # Relation between (r, c) and (r, c+1)
                dom_left = domains[r][c]
                dom_right = domains[r][c+1]

                if not dom_left or not dom_right: continue 

                if op == '<':
                    # left < right
                    # Values in left must be < max(right)
                    max_r = max(dom_right)
                    to_remove_l = [v for v in dom_left if v >= max_r]
                    # Values in right must be > min(left)
                    min_l = min(dom_left)
                    to_remove_r = [v for v in dom_right if v <= min_l]

                    if to_remove_l:
                        domains[r][c] -= set(to_remove_l)
                        changed = True
                    if to_remove_r:
                        domains[r][c+1] -= set(to_remove_r)
                        changed = True

                elif op == '>':
                    # left > right
                    # Values in left must be > min(right)
                    min_r = min(dom_right)
                    to_remove_l = [v for v in dom_left if v <= min_r]
                    # Values in right must be < max(left)
                    max_l = max(dom_left)
                    to_remove_r = [v for v in dom_right if v >= max_l]

                    if to_remove_l:
                        domains[r][c] -= set(to_remove_l)
                        changed = True
                    if to_remove_r:
                        domains[r][c+1] -= set(to_remove_r)
                        changed = True

            # Vertical inequalities
            for key, op in vertical.items():
                r, c = parse_v_key(key)
                # Relation between (r, c) and (r+1, c)
                dom_top = domains[r][c]
                dom_bottom = domains[r+1][c]

                if not dom_top or not dom_bottom: continue

                if op == 'v': # Wide part top: Top > Bottom
                    # Top must be > min(Bottom)
                    min_b = min(dom_bottom)
                    to_remove_t = [v for v in dom_top if v <= min_b]
                    # Bottom must be < max(Top)
                    max_t = max(dom_top)
                    to_remove_b = [v for v in dom_bottom if v >= max_t]

                    if to_remove_t:
                        domains[r][c] -= set(to_remove_t)
                        changed = True
                    if to_remove_b:
                        domains[r+1][c] -= set(to_remove_b)
                        changed = True

                elif op == '^': # Wide part bottom: Top < Bottom
                    # Top must be < max(Bottom)
                    max_b = max(dom_bottom)
                    to_remove_t = [v for v in dom_top if v >= max_b]
                    # Bottom must be > min(Top)
                    min_t = min(dom_top)
                    to_remove_b = [v for v in dom_bottom if v <= min_t]

                    if to_remove_t:
                        domains[r][c] -= set(to_remove_t)
                        changed = True
                    if to_remove_b:
                        domains[r+1][c] -= set(to_remove_b)
                        changed = True

            # 2. Latin Square Constraints (Uniqueness)
            # If a cell is fixed (domain size 1), remove that value from peers
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        # Row peers
                        for cc in range(N):
                            if cc != c and val in domains[r][cc]:
                                domains[r][cc].discard(val)
                                changed = True
                        # Col peers
                        for rr in range(N):
                            if rr != r and val in domains[rr][c]:
                                domains[rr][c].discard(val)
                                changed = True

            # 3. Hidden Singles (Human-like deduction)
            # For each row, if a value can only go in one cell, fix it.
            for r in range(N):
                for val in range(1, N + 1):
                    possible_cols = [c for c in range(N) if val in domains[r][c]]
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            # For each col, if a value can only go in one cell, fix it.
            for c in range(N):
                for val in range(1, N + 1):
                    possible_rows = [r for r in range(N) if val in domains[r][c]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

        return domains

    def is_valid(domains):
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) == 0:
                    return False
        return True

    def backtrack(domains):
        # Propagate constraints first
        domains = propagate(domains)

        # Check for failure (empty domain)
        if not is_valid(domains):
            return None

        # Check if solved (all domains size 1)
        solved = True
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    solved = False
                    break
            if not solved: break

        if solved:
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        # MRV Heuristic: Pick cell with minimum remaining values
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                l = len(domains[r][c])
                if 1 < l < min_len:
                    min_len = l
                    best_cell = (r, c)

        if best_cell is None: 
            return None 

        r, c = best_cell
        # Try values in sorted order
        for val in sorted(list(domains[r][c])):
            new_domains = copy.deepcopy(domains)
            new_domains[r][c] = {val}
            res = backtrack(new_domains)
            if res:
                return res
        return None

    # Initial propagation
    domains = propagate(domains)
    if not is_valid(domains):
        return "No Solution"

    result = backtrack(domains)
    return result

