    peers = {}
    for r in range(rows):
        for c in range(cols):
            p_set = set()
            # Row peers
            for k in range(cols):
                if k != c: p_set.add((r, k))
            # Col peers
            for k in range(rows):
                if k != r: p_set.add((k, c))
            # Box peers
            box_r_start = (r // unit_r) * unit_r
            box_c_start = (c // unit_c) * unit_c
            for dr in range(unit_r):
                for dc in range(unit_c):
                    nr, nc = box_r_start + dr, box_c_start + dc
                    if (nr, nc) != (r, c):
                        p_set.add((nr, nc))
            peers[(r, c)] = p_set

    # Initialize possibilities
    # values[(r,c)] = set of possible numbers
    values = {}
    all_digits = set(range(1, N + 1))

    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is not None:
                values[(r, c)] = {val}
            else:
                values[(r, c)] = set(all_digits)

    def solve_recursive(values):
        # Constraint Propagation Loop (Human-like deduction)
        while True:
            changed = False

            # 1. Naked Singles: If a cell has only 1 possibility, eliminate it from peers
            for r in range(rows):
                for c in range(cols):
                    if len(values[(r, c)]) == 1:
                        d = next(iter(values[(r, c)]))
                        for pr, pc in peers[(r, c)]:
                            if d in values[(pr, pc)]:
                                values[(pr, pc)].remove(d)
                                changed = True
                                if len(values[(pr, pc)]) == 0:
                                    return None # Contradiction: a cell has no possibilities

            # 2. Hidden Singles: If a digit has only 1 possible location in a unit, place it there
            # Check Rows
            for r in range(rows):
                for d in range(1, N + 1):
                    places = [(r, c) for c in range(cols) if d in values[(r, c)]]
                    if len(places) == 0: return None # Contradiction: digit d has nowhere to go in this row
                    if len(places) == 1:
                        pr, pc = places[0]
                        if len(values[(pr, pc)]) > 1:
                            values[(pr, pc)] = {d}
                            changed = True

            # Check Cols
            for c in range(cols):
                for d in range(1, N + 1):
                    places = [(r, c) for r in range(rows) if d in values[(r, c)]]
                    if len(places) == 0: return None
                    if len(places) == 1:
                        pr, pc = places[0]
                        if len(values[(pr, pc)]) > 1:
                            values[(pr, pc)] = {d}
                            changed = True

            # Check Boxes
            for br in range(0, rows, unit_r):
                for bc in range(0, cols, unit_c):
                    for d in range(1, N + 1):
                        places = []
                        for dr in range(unit_r):
                            for dc in range(unit_c):
                                r, c = br + dr, bc + dc
                                if d in values[(r, c)]:
                                    places.append((r, c))
                        if len(places) == 0: return None
                        if len(places) == 1:
                            pr, pc = places[0]
                            if len(values[(pr, pc)]) > 1:
                                values[(pr, pc)] = {d}
                                changed = True

            if not changed:
                break

        # Check if solved (all cells have exactly 1 value)
        if all(len(values[(r, c)]) == 1 for r in range(rows) for c in range(cols)):
            return values

        # Check for empty possibilities (should be caught by propagation, but safe check)
        if any(len(values[(r, c)]) == 0 for r in range(rows) for c in range(cols)):
            return None

        # MRV Heuristic: Choose the empty cell with the fewest possibilities to minimize branching
        min_len = N + 1
        target_cell = None
        for r in range(rows):
            for c in range(cols):
                l = len(values[(r, c)])
                if 1 < l < min_len:
                    min_len = l
                    target_cell = (r, c)

        if target_cell is None:
            return None # Should not happen if not solved and no empty sets

        r, c = target_cell
        possible_values = sorted(list(values[(r, c)]))

        for d in possible_values:
            # Create a deep copy of the state for branching
            new_values = {k: v.copy() for k, v in values.items()}
            new_values[(r, c)] = {d}

            result = solve_recursive(new_values)
            if result is not None:
                return result

        return None

    final_values = solve_recursive(values)

    if final_values is None:
        return "No Solution"

    # Construct output grid from the solved values dictionary
    result_grid = []
    for r in range(rows):
        row_vals = []
        for c in range(cols):
            row_vals.append(next(iter(final_values[(r, c)])))
        result_grid.append(row_vals)

    return result_grid

