OBSERVATION = {'data': [[None, None, None, None, None, None], [None, 3, 2, 2, 1, None], [None, None, 3, None, 3, None], [1, 2, None, 2, None, 1], [1, None, 3, 2, None, 1], [None, None, 1, None, 1, None]]}

import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(3000)

def solve(observation):
    data = observation['data']
    # N is the grid size (N x N cells)
    # data is (N+1) x (N+1) dots
    N = len(data) - 1

    # Grid state: None, '/', '\'
    grid = [[None for _ in range(N)] for _ in range(N)]
    dot_clues = data

    # Precompute incident cells for each dot
    # dot (r, c) is incident to up to 4 cells.
    # We store (cell_r, cell_c, required_diagonal_to_connect)
    incident_cells = {}
    for r in range(N + 1):
        for c in range(N + 1):
            cells = []
            # Top-Left cell: (r-1, c-1). Diagonal '\' connects (r-1, c-1) and (r, c).
            if r > 0 and c > 0:
                cells.append((r - 1, c - 1, '\\'))
            # Top-Right cell: (r-1, c). Diagonal '/' connects (r, c) and (r-1, c+1).
            if r > 0 and c < N:
                cells.append((r - 1, c, '/'))
            # Bottom-Left cell: (r, c-1). Diagonal '/' connects (r+1, c-1) and (r, c).
            if r < N and c > 0:
                cells.append((r, c - 1, '/'))
            # Bottom-Right cell: (r, c). Diagonal '\' connects (r, c) and (r+1, c+1).
            if r < N and c < N:
                cells.append((r, c, '\\'))
            incident_cells[(r, c)] = cells

    # Adjacency list for loop detection (Graph of dots)
    adj = [[[] for _ in range(N + 1)] for _ in range(N + 1)]

    def add_edge(r1, c1, r2, c2):
        adj[r1][c1].append((r2, c2))
        adj[r2][c2].append((r1, c1))

    def remove_edge(r1, c1, r2, c2):
        # Safe removal
        if (r2, c2) in adj[r1][c1]:
            adj[r1][c1].remove((r2, c2))
        if (r1, c1) in adj[r2][c2]:
            adj[r2][c2].remove((r1, c1))

    def is_connected(r1, c1, r2, c2):
        # BFS to check connectivity
        if r1 == r2 and c1 == c2:
            return True
        queue = [(r1, c1)]
        visited = {(r1, c1)}
        while queue:
            cr, cc = queue.pop(0)
            if cr == r2 and cc == c2:
                return True
            for nr, nc in adj[cr][cc]:
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return False

    # Constraint Propagation
    # Returns True if consistent, False if contradiction.
    # Appends changed cells to 'changes' list for backtracking.
    def propagate(changes):
        changed = True
        while changed:
            changed = False
            for r in range(N + 1):
                for c in range(N + 1):
                    clue = dot_clues[r][c]
                    if clue is None:
                        continue

                    current_conn = 0
                    unknown_cells = []

                    for cr, cc, diag in incident_cells[(r, c)]:
                        val = grid[cr][cc]
                        if val == diag:
                            current_conn += 1
                        elif val is None:
                            unknown_cells.append((cr, cc, diag))

                    needed = clue - current_conn

                    # Contradiction checks
                    if needed < 0:
                        return False
                    if needed > len(unknown_cells):
                        return False

                    # Forced moves
                    if needed == 0:
                        # All unknown cells must NOT connect (must take other diagonal)
                        for cr, cc, diag in unknown_cells:
                            other = '/' if diag == '\\' else '\\'
                            if grid[cr][cc] is None:
                                changes.append((cr, cc))
                                grid[cr][cc] = other
                                changed = True

                                # Check for loop
                                if other == '\\':
                                    if is_connected(cr, cc, cr + 1, cc + 1):
                                        return False
                                    add_edge(cr, cc, cr + 1, cc + 1)
                                else:
                                    if is_connected(cr + 1, cc, cr, cc + 1):
                                        return False
                                    add_edge(cr + 1, cc, cr, cc + 1)

                    elif needed == len(unknown_cells):
                        # All unknown cells MUST connect
                        for cr, cc, diag in unknown_cells:
                            if grid[cr][cc] is None:
                                changes.append((cr, cc))
                                grid[cr][cc] = diag
                                changed = True

                                # Check for loop
                                if diag == '\\':
                                    if is_connected(cr, cc, cr + 1, cc + 1):
                                        return False
                                    add_edge(cr, cc, cr + 1, cc + 1)
                                else:
                                    if is_connected(cr + 1, cc, cr, cc + 1):
                                        return False
                                    add_edge(cr + 1, cc, cr, cc + 1)
        return True

    def revert(changes):
        # Revert changes in reverse order
        for cr, cc in reversed(changes):
            val = grid[cr][cc]
            grid[cr][cc] = None
            if val == '/':
                remove_edge(cr + 1, cc, cr, cc + 1)
            elif val == '\\':
                remove_edge(cr, cc, cr + 1, cc + 1)

    def solve_recursive():
        changes = []
        if not propagate(changes):
            revert(changes)
            return False

        # Find an empty cell
        # Heuristic: Could pick most constrained, but simple scan is fast for N=5
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    best_cell = (r, c)
                    break
            if best_cell:
                break

        if best_cell is None:
            return True # Solved

        r, c = best_cell

        # Try '/'
        # '/' connects (r+1, c) and (r, c+1)
        grid[r][c] = '/'
        if not is_connected(r + 1, c, r, c + 1):
            add_edge(r + 1, c, r, c + 1)
            if solve_recursive():
                return True
            remove_edge(r + 1, c, r, c + 1)

        # Try '\'
        # '\' connects (r, c) and (r+1, c+1)
        grid[r][c] = '\\'
        if not is_connected(r, c, r + 1, c + 1):
            add_edge(r, c, r + 1, c + 1)
            if solve_recursive():
                return True
            remove_edge(r, c, r + 1, c + 1)

        # Backtrack
        grid[r][c] = None
        revert(changes)
        return False

    if solve_recursive():
        return grid
    return "No Solution"

if __name__ == "__main__":
    result = solve(OBSERVATION)
    if result == "No Solution":
        print("No Solution")
    else:
        # Format output as list of lists of strings
        print(result)
