import copy

def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']

    N = len(data)

    # Domains: dictionary (r, c) -> set of possible values
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Parse constraints
    h_constraints = []
    for key, symbol in horizontal.items():
        parts = key.strip("()").split(",")
        r = int(parts[0])
        c_float = float(parts[1])
        c = int(c_float)
        h_constraints.append((r, c, symbol))

    v_constraints = []
    for key, symbol in vertical.items():
        parts = key.strip("()").split(",")
        r_float = float(parts[0])
        c = int(parts[1])
        r = int(r_float)
        v_constraints.append((r, c, symbol))

    def is_consistent(domains):
        for d in domains.values():
            if not d:
                return False
        return True

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1. Latin Square Propagation
            fixed_cells = [(r, c) for (r, c), d in domains.items() if len(d) == 1]
            for r, c in fixed_cells:
                val = list(domains[(r, c)])[0]
                for cc in range(N):
                    if cc != c:
                        if val in domains[(r, cc)]:
                            domains[(r, cc)].remove(val)
                            changed = True
                for rr in range(N):
                    if rr != r:
                        if val in domains[(rr, c)]:
                            domains[(rr, c)].remove(val)
                            changed = True

            if not is_consistent(domains):
                return False

            # 2. Inequality Propagation
            for r, c, symbol in h_constraints:
                d1 = domains[(r, c)]
                d2 = domains[(r, c+1)]

                new_d1 = set()
                new_d2 = set()

                if symbol == '<':
                    for x in d1:
                        if any(x < y for y in d2):
                            new_d1.add(x)
                    for y in d2:
                        if any(x < y for x in d1):
                            new_d2.add(y)
                elif symbol == '>':
                    for x in d1:
                        if any(x > y for y in d2):
                            new_d1.add(x)
                    for y in d2:
                        if any(x > y for x in d1):
                            new_d2.add(y)

                if new_d1 != d1 or new_d2 != d2:
                    domains[(r, c)] = new_d1
                    domains[(r, c+1)] = new_d2
                    changed = True

            for r, c, symbol in v_constraints:
                d1 = domains[(r, c)]
                d2 = domains[(r+1, c)]

                new_d1 = set()
                new_d2 = set()

                if symbol == 'v': 
                    for x in d1:
                        if any(x < y for y in d2):
                            new_d1.add(x)
                    for y in d2:
                        if any(x < y for x in d1):
                            new_d2.add(y)
                elif symbol == '^': 
                    for x in d1:
                        if any(x > y for y in d2):
                            new_d1.add(x)
                    for y in d2:
                        if any(x > y for x in d1):
                            new_d2.add(y)

                if new_d1 != d1 or new_d2 != d2:
                    domains[(r, c)] = new_d1
                    domains[(r+1, c)] = new_d2
                    changed = True

            if not is_consistent(domains):
                return False

        return True

    if not propagate(domains):
        return "No Solution"

    def get_unassigned(domains):
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[(r, c)]) > 1:
                    if len(domains[(r, c)]) < min_len:
                        min_len = len(domains[(r, c)])
                        best_cell = (r, c)
        return best_cell

    def backtrack(domains):
        if all(len(d) == 1 for d in domains.values()):
            sol = [[0]*N for _ in range(N)]
            for (r, c), d in domains.items():
                sol[r][c] = list(d)[0]
            return sol

        cell = get_unassigned(domains)
        if cell is None:
            return None

        r, c = cell
        for val in sorted(list(domains[cell])):
            new_domains = copy.deepcopy(domains)
            new_domains[cell] = {val}

            if propagate(new_domains):
                result = backtrack(new_domains)
                if result:
                    return result

        return None

    result = backtrack(domains)
    if result:
        return result
    return "No Solution"

