    cols = len(observation['tree'][0])

    # Grid state: 0 = Empty/Unknown, 1 = Tree, 2 = Tent, 3 = Grass (No Tent)
    # We use a separate grid for state to avoid modifying the tree map directly if needed, 
    # but here we can just overlay.
    # Let's use a grid where:
