    # '.' = Unknown

    grid = [['.' for _ in range(cols)] for _ in range(rows)]
    tree_positions = []

    for r in range(rows):
        for c in range(cols):
            if observation['tree'][r][c] == 'T':
                grid[r][c] = 'T'
                tree_positions.append((r, c))

    row_counts = observation['row_tent_counts']
    col_counts = observation['col_tent_counts']

    # Helper to get neighbors
    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        return neighs

    def get_orthogonal_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                neighs.append((nr, nc))
        return neighs

    def count_tents_in_row(r):
        return sum(1 for c in range(cols) if grid[r][c] == 't')

    def count_tents_in_col(c):
        return sum(1 for r in range(rows) if grid[r][c] == 't')

    def count_empty_in_row(r):
        return sum(1 for c in range(cols) if grid[r][c] == '.')

    def count_empty_in_col(c):
        return sum(1 for r in range(rows) if grid[r][c] == '.')

    def is_valid_tent_placement(r, c):
        # Check if placing a tent at r,c violates adjacency with other tents
        for nr, nc in get_neighbors(r, c):
            if grid[nr][nc] == 't':
                return False
        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            # Rule 1: If a row/col has reached its count, mark remaining empty as Grass
            for r in range(rows):
                if count_tents_in_row(r) == row_counts[r]:
