            row_str = []
            for c in range(N):
                if grid[r][c] == 1:
                    row_str.append('S')
                else:
                    row_str.append('.') # Unshaded
            result.append("".join(row_str))
        return "\n".join(result)
    else:
        return "No Solution"

if __name__ == "__main__":
