import copy

def solve(observation):
    data = observation['data']
    N = len(data) - 1

    # Grid of cells, N x N. None means undecided.
    grid = [[None for _ in range(N)] for _ in range(N)]

    # DSU for dots. (N+1) x (N+1) dots.
    # Dot (r, c) is indexed as r * (N+1) + c
    num_dots = (N + 1) * (N + 1)
    parent = list(range(num_dots))

    def find(i, p):
        path = []
        while p[i] != i:
            path.append(i)
            i = p[i]
        for node in path:
            p[node] = i
        return i

    def union(i, j, p):
        root_i = find(i, p)
        root_j = find(j, p)
        if root_i != root_j:
            p[root_i] = root_j
            return True
        return False

    # Get cells adjacent to dot (r, c)
    # Returns list of (cell_r, cell_c, diagonal_that_connects)
    def get_neighbors(r, c):
        cells = []
        # Top-Left cell: (r-1, c-1). Connects to BR (r,c) if '\'
        if r > 0 and c > 0:
            cells.append((r-1, c-1, '\\')) 
        # Top-Right cell: (r-1, c). Connects to BL (r,c) if '/'
        if r > 0 and c < N:
            cells.append((r-1, c, '/'))
        # Bottom-Left cell: (r, c-1). Connects to TR (r,c) if '/'
        if r < N and c > 0:
            cells.append((r, c-1, '/'))
        # Bottom-Right cell: (r, c). Connects to TL (r,c) if '\'
        if r < N and c < N:
            cells.append((r, c, '\\'))
        return cells

    def propagate(grid, parent):
        changed = True
        while changed:
            changed = False

            # Rule 1: Dot Constraints
            for r in range(N + 1):
                for c in range(N + 1):
                    clue = data[r][c]
                    if clue is None:
                        continue

                    neighbors = get_neighbors(r, c)
                    connected_count = 0
                    unknown_cells = []

                    for cr, cc, diag in neighbors:
                        val = grid[cr][cc]
                        if val == diag:
                            connected_count += 1
                        elif val is None:
                            unknown_cells.append((cr, cc, diag))

                    # Contradiction checks
                    if connected_count > clue:
                        return False, grid, parent
                    if connected_count + len(unknown_cells) < clue:
                        return False, grid, parent

                    # Deductions
                    if connected_count == clue:
                        # All unknowns must NOT connect -> must be other diagonal
                        for cr, cc, diag in unknown_cells:
                            other_diag = '/' if diag == '\\' else '\\'
                            if grid[cr][cc] is None:
                                grid[cr][cc] = other_diag
                                changed = True
                                # Update DSU
                                if other_diag == '/':
                                    u = (cr + 1) * (N + 1) + cc
                                    v = cr * (N + 1) + (cc + 1)
                                else:
                                    u = cr * (N + 1) + cc
                                    v = (cr + 1) * (N + 1) + (cc + 1)

                                if find(u, parent) == find(v, parent):
                                    return False, grid, parent
                                union(u, v, parent)
                            elif grid[cr][cc] == diag:
                                return False, grid, parent

                    elif connected_count + len(unknown_cells) == clue:
                        # All unknowns MUST connect
                        for cr, cc, diag in unknown_cells:
                            if grid[cr][cc] is None:
                                grid[cr][cc] = diag
                                changed = True
                                # Update DSU
                                if diag == '/':
                                    u = (cr + 1) * (N + 1) + cc
                                    v = cr * (N + 1) + (cc + 1)
                                else:
                                    u = cr * (N + 1) + cc
                                    v = (cr + 1) * (N + 1) + (cc + 1)

                                if find(u, parent) == find(v, parent):
                                    return False, grid, parent
                                union(u, v, parent)
                            elif grid[cr][cc] != diag:
                                return False, grid, parent

            # Rule 2: Loop Avoidance
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is not None:
                        continue

                    # Option 1: '/' connects (r+1, c) and (r, c+1)
                    u1 = (r + 1) * (N + 1) + c
                    v1 = r * (N + 1) + (c + 1)
                    loop1 = (find(u1, parent) == find(v1, parent))

                    # Option 2: '\' connects (r, c) and (r+1, c+1)
                    u2 = r * (N + 1) + c
                    v2 = (r + 1) * (N + 1) + (c + 1)
                    loop2 = (find(u2, parent) == find(v2, parent))

                    if loop1 and loop2:
                        return False, grid, parent

                    if loop1 and not loop2:
                        grid[r][c] = '\\'
                        changed = True
                        union(u2, v2, parent)
                    elif loop2 and not loop1:
                        grid[r][c] = '/'
                        changed = True
                        union(u1, v1, parent)

        return True, grid, parent

    def is_full(grid):
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    return False
        return True

    def backtrack(grid, parent):
        success, grid, parent = propagate(grid, parent)
        if not success:
            return None
        if is_full(grid):
            return grid

        # Find first empty cell
        r, c = -1, -1
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    r, c = i, j
                    break
            if r != -1: break

        # Save state for backtracking
        saved_grid = [row[:] for row in grid]
        saved_parent = parent[:]

        # Try '/'
        u = (r + 1) * (N + 1) + c
        v = r * (N + 1) + (c + 1)
        if find(u, parent) != find(v, parent):
            grid[r][c] = '/'
            union(u, v, parent)
            res = backtrack(grid, parent)
            if res:
                return res
            # Restore state
            grid = [row[:] for row in saved_grid]
            parent = saved_parent[:]

        # Try '\'
        u = r * (N + 1) + c
        v = (r + 1) * (N + 1) + (c + 1)
        if find(u, parent) != find(v, parent):
            grid[r][c] = '\\'
            union(u, v, parent)
            res = backtrack(grid, parent)
            if res:
                return res

        return None

    # Initial propagation
    success, grid, parent = propagate(grid, parent)
    if not success:
        return "No Solution"

    result = backtrack(grid, parent)
    if result:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
