            min_r = min(x[0] for x in reflected)
            min_c = min(x[1] for x in reflected)
            reflected_cells = sorted([(x[0]-min_r, x[1]-min_c) for x in reflected])

            current_cells = reflected_cells
            for _ in range(4):
                variants.add(tuple(sorted(current_cells)))
                rotated = []
                for r, c in current_cells:
                    rotated.append((c, -r))
                min_r = min(x[0] for x in rotated)
                min_c = min(x[1] for x in rotated)
                current_cells = sorted([(x[0]-min_r, x[1]-min_c) for x in rotated])

            for v in variants:
                all_placements.append((name, list(v)))

        return all_placements

    tetrominoes = get_tetrominoes()

    # Precompute valid placements for each region
    # A placement is valid if all cells are within the region
    region_placements = {}
    for rid, cells in regions.items():
        cell_set = set(cells)
        valid = []
        for t_name, t_cells in tetrominoes:
            # Try to place t_cells at every offset in the grid
            # But we only care if the placed cells are a subset of the region cells
            # Since region cells are scattered, we can't just slide.
            # We need to check if there exists a translation (dr, dc) such that
            # {(r+dr, c+dc) for r,c in t_cells} is a subset of cell_set.

            # Optimization: Pick the first cell of t_cells, try to match it with every cell in region
            if not t_cells: continue
            r0, c0 = t_cells[0]
            for tr, tc in cells:
                dr, dc = tr - r0, tc - c0
                placed = [(r + dr, c + dc) for r, c in t_cells]
                if all((pr, pc) in cell_set for pr, pc in placed):
                    valid.append((t_name, placed))
        region_placements[rid] = valid

    # Adjacency graph of regions
    region_neighbors = {rid: set() for rid in region_ids}
    for r in range(N):
        for c in range(M):
            rid = grid[r][c]
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < M:
                    nrid = grid[nr][nc]
                    if nrid != rid:
                        region_neighbors[rid].add(nrid)
                        region_neighbors[nrid].add(rid)

    # Backtracking
    # State: assignment[rid] = (type, cells)
    assignment = {}

    # Order regions by number of placements (MRV)
    sorted_regions = sorted(region_ids, key=lambda rid: len(region_placements[rid]))

    # Global shaded cells set for connectivity check
    # But we check connectivity at the end or incrementally?
    # Incremental connectivity is hard. Check at end.
    # However, we can check 2x2 constraint incrementally.

    shaded_grid = [[False] * M for _ in range(N)]

    def is_valid_2x2(r, c):
        # Check if 2x2 block at (r,c) is fully shaded
        if r + 1 < N and c + 1 < M:
            if shaded_grid[r][c] and shaded_grid[r+1][c] and shaded_grid[r][c+1] and shaded_grid[r+1][c+1]:
                return False
        return True

    def check_2x2_global():
        for r in range(N - 1):
            for c in range(M - 1):
                if shaded_grid[r][c] and shaded_grid[r+1][c] and shaded_grid[r][c+1] and shaded_grid[r+1][c+1]:
                    return False
        return True

    def check_connectivity():
        # Find first shaded cell
        start = None
        count = 0
        for r in range(N):
            for c in range(M):
                if shaded_grid[r][c]:
                    if start is None:
                        start = (r, c)
                    count += 1

        if count == 0: return True # Should not happen if we filled all regions

        # BFS
        visited = set()
        queue = [start]
        visited.add(start)
        while queue:
            curr = queue.pop(0)
            r, c = curr
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < M:
                    if shaded_grid[nr][nc] and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        return len(visited) == count

    def solve_recursive(idx):
        if idx == len(sorted_regions):
            # All regions assigned
            if not check_2x2_global():
                return False
            if not check_connectivity():
                return False
            return True

        rid = sorted_regions[idx]

        for t_name, cells in region_placements[rid]:
            # Check adjacency constraint
            conflict = False
            for nrid in region_neighbors[rid]:
                if nrid in assignment:
                    n_type, _ = assignment[nrid]
                    if n_type == t_name:
                        conflict = True
                        break
            if conflict:
                continue

            # Check 2x2 constraint locally (optimization)
            # Mark cells
            to_unmark = []
            possible = True
            for r, c in cells:
                if shaded_grid[r][c]:
                    possible = False
                    break
                shaded_grid[r][c] = True
                to_unmark.append((r, c))

            if not possible:
                for r, c in to_unmark:
                    shaded_grid[r][c] = False
                continue

            # Check local 2x2
            local_2x2_ok = True
            for r, c in cells:
                # Check 2x2 blocks involving this cell
                # Top-left of 2x2 can be (r-1, c-1), (r-1, c), (r, c-1), (r, c)
                for dr in [-1, 0]:
                    for dc in [-1, 0]:
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < N - 1 and 0 <= cc < M - 1:
                            if shaded_grid[rr][cc] and shaded_grid[rr+1][cc] and shaded_grid[rr][cc+1] and shaded_grid[rr+1][cc+1]:
                                local_2x2_ok = False
                                break
                    if not local_2x2_ok: break
                if not local_2x2_ok: break

            if not local_2x2_ok:
                for r, c in to_unmark:
                    shaded_grid[r][c] = False
                continue

            assignment[rid] = (t_name, cells)

            if solve_recursive(idx + 1):
                return True

            del assignment[rid]
            for r, c in to_unmark:
                shaded_grid[r][c] = False

        return False

    if solve_recursive(0):
        # Construct output
        result = [[None] * M for _ in range(N)]
        for rid, (t_name, cells) in assignment.items():
            for r, c in cells:
                result[r][c] = t_name
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
