            for r in range(N):
                fixed_vals = []
                for c in range(N):
                    if len(domains[(r,c)]) == 1:
                        fixed_vals.append(list(domains[(r,c)])[0])

                for c in range(N):
                    if len(domains[(r,c)]) > 1:
                        for val in fixed_vals:
                            if val in domains[(r,c)]:
                                domains[(r,c)].remove(val)
                                changed = True
                                if not domains[(r,c)]: return False

            for c in range(N):
                fixed_vals = []
                for r in range(N):
                    if len(domains[(r,c)]) == 1:
                        fixed_vals.append(list(domains[(r,c)])[0])

                for r in range(N):
                    if len(domains[(r,c)]) > 1:
                        for val in fixed_vals:
                            if val in domains[(r,c)]:
                                domains[(r,c)].remove(val)
                                changed = True
                                if not domains[(r,c)]: return False

            # 2. Inequality constraints (Arc Consistency)
            # Horizontal
            for r, c1, c2, op in h_constraints:
                d1 = domains[(r, c1)]
                d2 = domains[(r, c2)]

                # Prune d1 (left cell)
                new_d1 = set()
                for v1 in d1:
                    valid = False
                    for v2 in d2:
                        if op == '>' and v1 > v2: valid = True; break
                        if op == '<' and v1 < v2: valid = True; break
                    if valid: new_d1.add(v1)

                if new_d1 != d1:
                    domains[(r, c1)] = new_d1
                    changed = True
                    if not new_d1: return False

                # Prune d2 (right cell)
                new_d2 = set()
                for v2 in d2:
