                    if not new_d2: return False

            # Vertical
            for r1, r2, c, op in v_constraints:
                d1 = domains[(r1, c)] # Top
                d2 = domains[(r2, c)] # Bottom

                # Prune d1 (top)
                new_d1 = set()
                for v1 in d1:
                    valid = False
                    for v2 in d2:
                        # 'v' means Top > Bottom (open side up)
                        # '^' means Bottom > Top (open side down)
                        if op == 'v' and v1 > v2: valid = True; break
                        if op == '^' and v1 < v2: valid = True; break
                    if valid: new_d1.add(v1)

                if new_d1 != d1:
                    domains[(r1, c)] = new_d1
                    changed = True
                    if not new_d1: return False

                # Prune d2 (bottom)
                new_d2 = set()
                for v2 in d2:
                    valid = False
                    for v1 in domains[(r1, c)]: # Use updated d1
                        if op == 'v' and v1 > v2: valid = True; break
                        if op == '^' and v1 < v2: valid = True; break
                    if valid: new_d2.add(v2)

                if new_d2 != d2:
                    domains[(r2, c)] = new_d2
                    changed = True
                    if not new_d2: return False

        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Backtracking Search with MRV (Minimum Remaining Values)
    def get_unassigned():
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[(r,c)]) > 1:
                    if len(domains[(r,c)]) < min_size:
                        min_size = len(domains[(r,c)])
                        best_cell = (r,c)
        return best_cell

    def backtrack():
        cell = get_unassigned()
        if cell is None:
            # Solved: construct grid
            solution = [[0]*N for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    solution[r][c] = list(domains[(r,c)])[0]
            return solution

        r, c = cell
        # Try values in sorted order (deterministic)
        for val in sorted(list(domains[cell])):
            # Save state for backtracking
            saved_domains = {k: v.copy() for k, v in domains.items()}

            domains[cell] = {val}

            # Propagate constraints after assignment
            if propagate():
                res = backtrack()
                if res:
                    return res

            # Restore state
            for k, v in saved_domains.items():
                domains[k] = v

        return None

    result = backtrack()
    if result:
        return result
    return "No Solution"

