def solve(observation):
    data = observation['data']
    H = len(data) - 1
    W = len(data[0]) - 1

    # Precompute incident cells for each dot
    # incident_map[r][c] = list of ((cell_r, cell_c), required_dir_to_connect)
    incident_map = [[[] for _ in range(W + 1)] for _ in range(H + 1)]
    for r in range(H + 1):
        for c in range(W + 1):
            # Top-Left cell (r-1, c-1) connects if '\'
            if r > 0 and c > 0:
                incident_map[r][c].append(((r-1, c-1), '\\'))
            # Top-Right cell (r-1, c) connects if '/'
            if r > 0 and c < W:
                incident_map[r][c].append(((r-1, c), '/'))
            # Bottom-Left cell (r, c-1) connects if '/'
            if r < H and c > 0:
                incident_map[r][c].append(((r, c-1), '/'))
            # Bottom-Right cell (r, c) connects if '\'
            if r < H and c < W:
                incident_map[r][c].append(((r, c), '\\'))

    def get_dot_index(r, c):
        return r * (W + 1) + c

    def find(i, parent):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j, parent):
        pi = find(i, parent)
        pj = find(j, parent)
        if pi != pj:
            parent[pi] = pj
            return True
        return False

    def propagate(grid, degrees, parent):
        changed = True
        while changed:
            changed = False
            for r in range(H + 1):
                for c in range(W + 1):
                    clue = data[r][c]
                    if clue is None:
                        continue

                    current_deg = degrees[r][c]
                    if current_deg > clue:
                        return None, None, None

                    needed = clue - current_deg

                    # Get unknown incident cells
                    unknown_cells = []
                    for (cr, cc), req_dir in incident_map[r][c]:
                        if grid[cr][cc] is None:
                            unknown_cells.append(((cr, cc), req_dir))

                    if needed == 0:
                        # All unknown cells must NOT connect
                        for (cr, cc), req_dir in unknown_cells:
                            forced_dir = '/' if req_dir == '\\' else '\\'
                            if grid[cr][cc] is None:
                                # Check loop
                                if forced_dir == '/':
                                    u, v = get_dot_index(cr+1, cc), get_dot_index(cr, cc+1)
                                else:
                                    u, v = get_dot_index(cr, cc), get_dot_index(cr+1, cc+1)

                                if find(u, parent) == find(v, parent):
                                    return None, None, None

                                grid[cr][cc] = forced_dir
                                if forced_dir == '/':
                                    degrees[cr+1][cc] += 1
                                    degrees[cr][cc+1] += 1
                                    union(u, v, parent)
                                else:
                                    degrees[cr][cc] += 1
                                    degrees[cr+1][cc+1] += 1
                                    union(u, v, parent)
                                changed = True

                    elif needed == len(unknown_cells):
                        # All unknown cells MUST connect
                        for (cr, cc), req_dir in unknown_cells:
                            forced_dir = req_dir
                            if grid[cr][cc] is None:
                                if forced_dir == '/':
                                    u, v = get_dot_index(cr+1, cc), get_dot_index(cr, cc+1)
                                else:
                                    u, v = get_dot_index(cr, cc), get_dot_index(cr+1, cc+1)

                                if find(u, parent) == find(v, parent):
                                    return None, None, None

                                grid[cr][cc] = forced_dir
                                if forced_dir == '/':
                                    degrees[cr+1][cc] += 1
                                    degrees[cr][cc+1] += 1
                                    union(u, v, parent)
                                else:
                                    degrees[cr][cc] += 1
                                    degrees[cr+1][cc+1] += 1
                                    union(u, v, parent)
                                changed = True
                    elif needed > len(unknown_cells):
                        # Impossible to satisfy
                        return None, None, None
        return grid, degrees, parent

    def solve_recursive(grid, degrees, parent, start_idx):
        # Propagate constraints
        grid, degrees, parent = propagate(grid, degrees, parent)
        if grid is None:
            return None

        # Find next empty cell
        idx = start_idx
        while idx < H * W:
            r, c = divmod(idx, W)
            if grid[r][c] is None:
                break
            idx += 1

        if idx == H * W:
            # Check if all clues satisfied (propagation should ensure this, but double check)
            for r in range(H + 1):
                for c in range(W + 1):
                    if data[r][c] is not None:
                        if degrees[r][c] != data[r][c]:
                            return None
            return grid

        r, c = divmod(idx, W)

        # Try '/'
        # Connects (r+1, c) and (r, c+1)
        u, v = get_dot_index(r+1, c), get_dot_index(r, c+1)
        if find(u, parent) != find(v, parent):
            # Check degrees
            valid = True
            if data[r+1][c] is not None and degrees[r+1][c] + 1 > data[r+1][c]: valid = False
            if data[r][c+1] is not None and degrees[r][c+1] + 1 > data[r][c+1]: valid = False

            if valid:
                # Copy state
                new_grid = [row[:] for row in grid]
                new_degrees = [row[:] for row in degrees]
                new_parent = parent[:]

                new_grid[r][c] = '/'
                new_degrees[r+1][c] += 1
                new_degrees[r][c+1] += 1
                union(u, v, new_parent)

                res = solve_recursive(new_grid, new_degrees, new_parent, idx + 1)
                if res:
                    return res

        # Try '\'
        # Connects (r, c) and (r+1, c+1)
        u, v = get_dot_index(r, c), get_dot_index(r+1, c+1)
        if find(u, parent) != find(v, parent):
            valid = True
            if data[r][c] is not None and degrees[r][c] + 1 > data[r][c]: valid = False
            if data[r+1][c+1] is not None and degrees[r+1][c+1] + 1 > data[r+1][c+1]: valid = False

            if valid:
                new_grid = [row[:] for row in grid]
                new_degrees = [row[:] for row in degrees]
                new_parent = parent[:]

                new_grid[r][c] = '\\'
                new_degrees[r][c] += 1
                new_degrees[r+1][c+1] += 1
                union(u, v, new_parent)

                res = solve_recursive(new_grid, new_degrees, new_parent, idx + 1)
                if res:
                    return res

        return None

    # Initial state
    grid = [[None for _ in range(W)] for _ in range(H)]
    degrees = [[0 for _ in range(W + 1)] for _ in range(H + 1)]
    parent = list(range((H + 1) * (W + 1)))

    result = solve_recursive(grid, degrees, parent, 0)
    return result

