import sys

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']

    N = len(data)

    # Initialize domains for each cell
    # If a cell has a given value, its domain is just that value.
    # Otherwise, it's all numbers from 1 to N.
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Parse constraints into a structured list for efficient iteration
    constraints = []

    # Parse horizontal inequalities
    for key, op in horizontal.items():
        # key format: '(row, col+0.5)' e.g., '(0, 0.5)'
        content = key.strip('()')
        parts = content.split(',')
        r = int(parts[0].strip())
        c_val = float(parts[1].strip())
        c_left = int(c_val - 0.5)
        c_right = c_left + 1
        constraints.append(('h', r, c_left, c_right, op))

    # Parse vertical inequalities
    for key, op in vertical.items():
        # key format: '(row+0.5, col)' e.g., '(0.5, 1)'
        content = key.strip('()')
        parts = content.split(',')
        r_val = float(parts[0].strip())
        c = int(parts[1].strip())
        r_top = int(r_val - 0.5)
        r_bottom = r_top + 1
        constraints.append(('v', r_top, r_bottom, c, op))

    # Function to prune domains based on inequality constraints (Arc Consistency light)
    # Returns False if any domain becomes empty (contradiction)
    def prune(domains):
        changed = True
        while changed:
            changed = False
            for ctype, *args in constraints:
                if ctype == 'h':
                    r, c1, c2, op = args
                    d1 = domains[(r, c1)]
                    d2 = domains[(r, c2)]

                    if not d1 or not d2:
                        return False

                    if op == '<':
                        # d1 < d2
                        # Values in d1 must be less than max(d2)
                        max_d2 = max(d2)
                        rem1 = {v for v in d1 if v >= max_d2}
                        if rem1:
                            domains[(r, c1)] -= rem1
                            changed = True
                            if not domains[(r, c1)]: return False

                        # Values in d2 must be greater than min(d1)
                        min_d1 = min(d1)
                        rem2 = {v for v in d2 if v <= min_d1}
                        if rem2:
                            domains[(r, c2)] -= rem2
                            changed = True
                            if not domains[(r, c2)]: return False

                    elif op == '>':
                        # d1 > d2
                        # Values in d1 must be greater than min(d2)
                        min_d2 = min(d2)
                        rem1 = {v for v in d1 if v <= min_d2}
                        if rem1:
                            domains[(r, c1)] -= rem1
                            changed = True
                            if not domains[(r, c1)]: return False

                        # Values in d2 must be less than max(d1)
                        max_d1 = max(d1)
                        rem2 = {v for v in d2 if v >= max_d1}
                        if rem2:
                            domains[(r, c2)] -= rem2
                            changed = True
                            if not domains[(r, c2)]: return False

                elif ctype == 'v':
                    r1, r2, c, op = args
                    d1 = domains[(r1, c)]
                    d2 = domains[(r2, c)]

                    if not d1 or not d2:
                        return False

                    if op == '^':
                        # r1 < r2 (bottom cell is larger)
                        max_d2 = max(d2)
                        rem1 = {v for v in d1 if v >= max_d2}
                        if rem1:
                            domains[(r1, c)] -= rem1
                            changed = True
                            if not domains[(r1, c)]: return False

                        min_d1 = min(d1)
                        rem2 = {v for v in d2 if v <= min_d1}
                        if rem2:
                            domains[(r2, c)] -= rem2
                            changed = True
                            if not domains[(r2, c)]: return False

                    elif op == 'v':
                        # r1 > r2 (top cell is larger)
                        min_d2 = min(d2)
                        rem1 = {v for v in d1 if v <= min_d2}
                        if rem1:
                            domains[(r1, c)] -= rem1
                            changed = True
                            if not domains[(r1, c)]: return False

                        max_d1 = max(d1)
                        rem2 = {v for v in d2 if v >= max_d1}
                        if rem2:
                            domains[(r2, c)] -= rem2
                            changed = True
                            if not domains[(r2, c)]: return False
        return True

    # Initial pruning to reduce search space
    if not prune(domains):
        return "No Solution"

    # Backtracking solver with MRV (Minimum Remaining Values) and Forward Checking
    def solve_bt(current_domains):
        # Find unassigned cell with Minimum Remaining Values (MRV)
        cell = None
        min_len = N + 1
        for r in range(N):
            for c in range(N):
                if len(current_domains[(r, c)]) > 1:
                    l = len(current_domains[(r, c)])
                    if l < min_len:
                        min_len = l
                        cell = (r, c)

        # If no unassigned cells (all domains size 1), we have a solution
        if cell is None:
            sol = [[0]*N for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    sol[r][c] = list(current_domains[(r, c)])[0]
            return sol

        r, c = cell

        # Try values in sorted order (deterministic)
        for val in sorted(list(current_domains[(r, c)])):
            # Create a new state (deep copy of domains structure)
            new_domains = {k: v.copy() for k, v in current_domains.items()}
            new_domains[(r, c)] = {val}

            # Forward Checking:
            # 1. Remove val from row and column domains (Latin Square constraint)
            consistent = True

            # Row r
            for cc in range(N):
                if cc != c:
                    if val in new_domains[(r, cc)]:
                        new_domains[(r, cc)].remove(val)
                        if not new_domains[(r, cc)]:
                            consistent = False
                            break
            if not consistent: continue

            # Col c
            for rr in range(N):
                if rr != r:
                    if val in new_domains[(rr, c)]:
                        new_domains[(rr, c)].remove(val)
                        if not new_domains[(rr, c)]:
                            consistent = False
                            break
            if not consistent: continue

            # 2. Propagate inequality constraints to further prune domains
            if not prune(new_domains):
                continue

            # Recurse
            res = solve_bt(new_domains)
            if res:
                return res

        return None

    return solve_bt(domains)

