import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Grid state: None (Unknown), 'W' (White), 'B' (Black)
    grid = [[None for _ in range(C)] for _ in range(R)]
    numbers = {}

    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val is not None:
                grid[r][c] = 'W'
                numbers[(r, c)] = val

    # Helper to get connected white component
    def get_component(r, c, current_grid):
        if current_grid[r][c] != 'W':
            return set()
        comp = set()
        stack = [(r, c)]
        visited = set()
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited: continue
            visited.add((cr, cc))
            comp.add((cr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < R and 0 <= nc < C and current_grid[nr][nc] == 'W' and (nr, nc) not in visited:
                    stack.append((nr, nc))
        return comp

    # Helper to get number in component
    def get_number_in_comp(comp):
        nums = []
        for r, c in comp:
            if (r, c) in numbers:
                nums.append(numbers[(r, c)])
        return nums

    # Propagate constraints
    def propagate(current_grid):
        changed = True
        while changed:
            changed = False

            # Rule: 2x2 Black -> 4th is White
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    blacks = [cell for cell in cells if current_grid[cell[0]][cell[1]] == 'B']
                    whites = [cell for cell in cells if current_grid[cell[0]][cell[1]] == 'W']

                    if len(blacks) == 4:
                        return False # Invalid 2x2 black
                    if len(blacks) == 3 and len(whites) == 0:
                        # Find the None cell
                        for cell in cells:
                            if current_grid[cell[0]][cell[1]] is None:
                                current_grid[cell[0]][cell[1]] = 'W'
                                changed = True

            # Rule: Island Size Limit and Separation
            # Collect all components
            visited_global = set()
            components = []
            for r in range(R):
                for c in range(C):
                    if current_grid[r][c] == 'W' and (r, c) not in visited_global:
                        comp = get_component(r, c, current_grid)
                        components.append(comp)
                        visited_global.update(comp)

            for comp in components:
                nums = get_number_in_comp(comp)
                if len(nums) > 1:
                    return False # Two numbers in one island

                if len(nums) == 1:
                    target_size = nums[0]
                    current_size = len(comp)

                    if current_size > target_size:
                        return False # Island too big

                    if current_size == target_size:
                        # All neighbors must be Black
                        for r, c in comp:
                            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < R and 0 <= nc < C:
                                    if current_grid[nr][nc] is None:
                                        current_grid[nr][nc] = 'B'
                                        changed = True
                                    # If neighbor is W, it's in comp, so ignore.
                                    # If neighbor is B, ok.

                # Rule: Unnumbered islands must not be closed off
                if len(nums) == 0:
                    is_closed = True
                    for r, c in comp:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if current_grid[nr][nc] is None:
                                    is_closed = False
                                    break
                                # If neighbor is W, it's in comp (checked by loop structure)
                                # If neighbor is B, it's a wall.
                        if not is_closed: break

                    if is_closed:
                        return False # Unnumbered island closed off

        return True

    # Check global validity (Sea connectivity)
    def is_valid_final(current_grid):
        # 1. Sea Connectivity
        start_b = None
        black_count = 0
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] == 'B':
                    black_count += 1
                    if start_b is None:
                        start_b = (r, c)

        if black_count == 0:
            # If no black cells, valid only if single island (which implies 1 number)
            if len(numbers) > 1:
                return False
            return True 

        # BFS for sea connectivity
        q = [start_b]
        visited_b = set([start_b])
        count_visited = 0
        while q:
            r, c = q.pop(0)
            count_visited += 1
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and current_grid[nr][nc] == 'B' and (nr, nc) not in visited_b:
                    visited_b.add((nr, nc))
                    q.append((nr, nc))

        if count_visited != black_count:
            return False # Sea not connected

        # 2. Island Validity (Size and Number count)
        visited_w = set()
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] == 'W' and (r, c) not in visited_w:
                    comp = get_component(r, c, current_grid)
                    visited_w.update(comp)
                    nums = get_number_in_comp(comp)
                    if len(nums) != 1:
                        return False
                    target = nums[0]
                    if len(comp) != target:
                        return False

        return True

    # Main Solver
    def backtrack(current_grid):
        # Propagate
        if not propagate(current_grid):
            return None

        # Check if full
        unknown_cell = None
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] is None:
                    unknown_cell = (r, c)
                    break
            if unknown_cell: break

        if unknown_cell is None:
            if is_valid_final(current_grid):
                return current_grid
            else:
                return None

        r, c = unknown_cell

        # Try Black
        current_grid[r][c] = 'B'
        res = backtrack(current_grid)
        if res: return res
        current_grid[r][c] = None

        # Try White
        current_grid[r][c] = 'W'
        res = backtrack(current_grid)
        if res: return res
        current_grid[r][c] = None

        return None

    # Initial Propagate
    if not propagate(grid):
        return "No Solution"

    final_grid = backtrack(grid)

    if final_grid is None:
        return "No Solution"

    # Format output
    ans_grid = []
    for r in range(R):
        row_ans = []
        for c in range(C):
            if final_grid[r][c] == 'B':
                row_ans.append('B')
            else:
                row_ans.append(None)
        ans_grid.append(row_ans)

    return ans_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
