                touching[i].add(j)
                touching[j].add(i)

    # Map region to list of dominoes that cover it
    region_to_doms = {rid: [] for rid in region_ids}
    for i, info in enumerate(dom_info):
        for rid in info:
            region_to_doms[rid].append(i)

    # Backtracking solver
    # State: current_counts, selected_doms, forbidden_doms
    # We use a list for selected_doms to return the solution

    # Optimization: Order regions by number of available dominoes?
    # Or just pick the first unsatisfied region.

    # To speed up, we can maintain current_counts as a list or dict
    # And forbidden as a boolean array or set

    current_counts = {rid: 0 for rid in region_ids}
    selected = []
    forbidden = set()

    # Sort region_ids to have a deterministic order for picking
    # Pick region with fewest remaining options?
    # For now, just pick first unsatisfied.

    def is_satisfied():
        for rid in region_ids:
            if current_counts[rid] != 2:
                return False
        return True

    def get_next_region():
        # Heuristic: Pick region with count < 2 that has fewest valid dominoes
        best_rid = None
        min_options = float('inf')

        for rid in region_ids:
            if current_counts[rid] < 2:
                # Count valid dominoes
                count = 0
                for d_idx in region_to_doms[rid]:
                    if d_idx not in forbidden and d_idx not in selected_set: # selected_set not defined, use logic
                        # Check if adding this domino exceeds counts
                        valid = True
                        for r, c_val in dom_info[d_idx].items():
                            if current_counts[r] + c_val > 2:
                                valid = False
                                break
                        if valid:
                            count += 1
                if count < min_options:
                    min_options = count
                    best_rid = rid
        return best_rid

    # Use a set for selected for O(1) lookup
    selected_set = set()

    def backtrack():
        if is_satisfied():
            return True

        rid = get_next_region()
        if rid is None:
            # Should not happen if is_satisfied is false
            return False

        # Try dominoes for this region
        # Sort dominoes? Maybe by how many regions they satisfy
        candidates = region_to_doms[rid]

        # Filter candidates
        valid_candidates = []
        for d_idx in candidates:
            if d_idx in selected_set or d_idx in forbidden:
                continue

            # Check counts
            info = dom_info[d_idx]
            ok = True
            for r, val in info.items():
                if current_counts[r] + val > 2:
                    ok = False
                    break
            if ok:
                valid_candidates.append(d_idx)

        # Sort candidates: prefer those that cover the region fully (val=2) or cover multiple needed regions?
        # Simple sort: by number of regions covered
        valid_candidates.sort(key=lambda idx: -len(dom_info[idx]))

        for d_idx in valid_candidates:
            # Select
            selected_set.add(d_idx)
            selected.append(d_idx)

            # Update counts
            info = dom_info[d_idx]
            for r, val in info.items():
                current_counts[r] += val

            # Update forbidden
            new_forbidden = touching[d_idx]
            added_forbidden = []
            for f in new_forbidden:
                if f not in forbidden:
                    forbidden.add(f)
                    added_forbidden.append(f)

            # Recurse
            if backtrack():
                return True

            # Backtrack
            selected_set.remove(d_idx)
            selected.pop()
            for r, val in info.items():
                current_counts[r] -= val
            for f in added_forbidden:
                forbidden.remove(f)

        return False

    if backtrack():
        # Construct output grid
        res_grid = [[None for _ in range(C)] for _ in range(R)]
        for d_idx in selected:
            (r1, c1), (r2, c2) = dominoes[d_idx]
            res_grid[r1][c1] = 'S'
            res_grid[r2][c2] = 'S'
        return res_grid
    else:
        return "No Solution"

