import sys

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    islands = []
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                islands.append((r, c, data[r][c]))

    # State variables
    # current_bridges: dict mapping ((r1,c1), (r2,c2)) -> count (1 or 2)
    current_bridges = {} 
    # island_bridge_counts: dict mapping (r,c) -> current number of connected bridges
    island_bridge_counts = { (r,c): 0 for r,c,_ in islands }

    # Precompute visible neighbors for each island
    visible_neighbors = {}
    for r, c, val in islands:
        neighbors = []
        # Up
        for nr in range(r-1, -1, -1):
            if data[nr][c] is not None:
                neighbors.append((nr, c))
                break
        # Down
        for nr in range(r+1, rows):
            if data[nr][c] is not None:
                neighbors.append((nr, c))
                break
        # Left
        for nc in range(c-1, -1, -1):
            if data[r][nc] is not None:
                neighbors.append((r, nc))
                break
        # Right
        for nc in range(c+1, cols):
            if data[r][nc] is not None:
                neighbors.append((r, nc))
                break
        visible_neighbors[(r,c)] = neighbors

    def get_key(p1, p2):
        if p1 < p2: return (p1, p2)
        return (p2, p1)

    def get_bridge_count(p1, p2):
        return current_bridges.get(get_key(p1, p2), 0)

    def is_satisfied(r, c):
        return island_bridge_counts[(r,c)] == data[r][c]

    def get_remaining_needed(r, c):
        return data[r][c] - island_bridge_counts[(r,c)]

    def is_path_clear(r1, c1, r2, c2):
        if r1 == r2:
            min_c, max_c = min(c1, c2), max(c1, c2)
            for c in range(min_c + 1, max_c):
                if data[r1][c] is not None:
                    return False
            return True
        elif c1 == c2:
            min_r, max_r = min(r1, r2), max(r1, r2)
            for r in range(min_r + 1, max_r):
                if data[r][c1] is not None:
                    return False
            return True
        return False

    def add_bridge_force(p1, p2, count):
        key = get_key(p1, p2)
        current_bridges[key] = current_bridges.get(key, 0) + count
        island_bridge_counts[p1] += count
        island_bridge_counts[p2] += count

    def remove_bridge_force(p1, p2, count):
        key = get_key(p1, p2)
        current_bridges[key] -= count
        if current_bridges[key] == 0:
            del current_bridges[key]
        island_bridge_counts[p1] -= count
        island_bridge_counts[p2] -= count

    def check_connectivity_feasibility():
        # Check if the current graph structure allows for a single connected component at the end
        island_map = { (r,c): i for i, (r,c,_) in enumerate(islands) }
        parent = list(range(len(islands)))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            pi, pj = find(i), find(j)
            if pi != pj:
                parent[pi] = pj

        for (p1, p2), count in current_bridges.items():
            if count > 0:
                i1 = island_map[p1]
                i2 = island_map[p2]
                union(i1, i2)

        components = {}
        for i in range(len(islands)):
            root = find(i)
            if root not in components:
                components[root] = []
            components[root].append(i)

        # If already connected, good
        if len(components) == 1:
            return True

        # If multiple components, check if any component is "closed" (all islands satisfied)
        # If a closed component is disconnected from others, it's a fail.
        for comp_indices in components.values():
            all_satisfied = True
            for idx in comp_indices:
                r, c, _ = islands[idx]
                if not is_satisfied(r, c):
                    all_satisfied = False
                    break
            if all_satisfied:
                if len(components) > 1:
                    return False

        # Check if components can potentially be connected
        comp_list = list(components.values())
        for i in range(len(comp_list)):
            for j in range(i + 1, len(comp_list)):
                can_connect = False
                for idx1 in comp_list[i]:
                    r1, c1, _ = islands[idx1]
                    for idx2 in comp_list[j]:
                        r2, c2, _ = islands[idx2]
                        # Check if a bridge is possible
                        if r1 == r2 or c1 == c2:
                            if get_remaining_needed(r1, c1) > 0 and get_remaining_needed(r2, c2) > 0:
                                if get_bridge_count((r1,c1), (r2,c2)) < 2:
                                    if is_path_clear(r1, c1, r2, c2):
                                        can_connect = True
                                        break
                    if can_connect: break
                if not can_connect:
                    return False # Two components cannot be connected

        return True

    def apply_logic():
        changed = True
        while changed:
            changed = False

            for r, c, val in islands:
                if is_satisfied(r, c):
                    continue

                needed = get_remaining_needed(r, c)

                # Get available neighbors (not satisfied, and < 2 bridges)
                available = []
                max_p = 0
                for nr, nc in visible_neighbors[(r,c)]:
                    if is_satisfied(nr, nc):
                        continue
                    current_b = get_bridge_count((r,c), (nr, nc))
                    if current_b >= 2:
                        continue

                    # Max we can add to this neighbor
                    can_add = min(2 - current_b, get_remaining_needed(nr, nc))
                    max_p += can_add
                    available.append((nr, nc, can_add))

                if not available:
                    if needed > 0:
                        return False # Impossible to satisfy
                    continue

                # Rule 1: If needed == max_p, force all connections
                if needed == max_p:
                    for nr, nc, can_add in available:
                        if can_add > 0:
                            add_bridge_force((r,c), (nr, nc), can_add)
                            changed = True
                    continue 

                # Rule 2: If only 1 available neighbor, force connection
                if len(available) == 1:
                    nr, nc, can_add = available[0]
                    to_add = needed # Must add all needed
                    if to_add > can_add:
                        return False # Impossible
                    if to_add > 0:
                        add_bridge_force((r,c), (nr, nc), to_add)
                        changed = True
                    continue

            # Global connectivity check
            if not check_connectivity_feasibility():
                return False

        return True

    def solve_recursive():
        # Apply logical deductions first
        if not apply_logic():
            return False

        # Check if solved
        solved = True
        for r, c, val in islands:
            if not is_satisfied(r, c):
                solved = False
                break

        if solved:
            # Final strict connectivity check
            island_map = { (r,c): i for i, (r,c,_) in enumerate(islands) }
            parent = list(range(len(islands)))
            def find(i):
                if parent[i] != i: parent[i] = find(parent[i])
                return parent[i]
            def union(i, j):
                pi, pj = find(i), find(j)
                if pi != pj: parent[pi] = pj

            for (p1, p2), count in current_bridges.items():
                if count > 0:
                    union(island_map[p1], island_map[p2])

            roots = set(find(i) for i in range(len(islands)))
            return len(roots) == 1

        # Heuristic: Pick unsatisfied island with fewest available neighbors (Most Constrained Variable)
        best_island = None
        min_options = float('inf')

        for r, c, val in islands:
            if is_satisfied(r, c): continue

            options = 0
            for nr, nc in visible_neighbors[(r,c)]:
                if is_satisfied(nr, nc): continue
                if get_bridge_count((r,c), (nr, nc)) < 2:
                    options += 1

            if options < min_options:
                min_options = options
                best_island = (r, c)
                if options == 1: break 

        if best_island is None or min_options == 0:
            return False

        r, c = best_island

        # Collect possible moves (connections to neighbors)
        moves = []
        for nr, nc in visible_neighbors[(r,c)]:
            if is_satisfied(nr, nc): continue
            current_b = get_bridge_count((r,c), (nr, nc))
            if current_b >= 2: continue

            max_add = min(2 - current_b, get_remaining_needed(nr, nc), get_remaining_needed(r, c))
            if max_add > 0:
                moves.append(((nr, nc), max_add))

        # Try moves
        for (nr, nc), max_add in moves:
            current_b = get_bridge_count((r,c), (nr, nc))

            # Try adding k bridges (1 to max_add)
            # Note: This branches on the number of bridges for this specific pair.
            for k in range(1, max_add + 1):
                add_bridge_force((r,c), (nr, nc), k)
                if solve_recursive():
                    return True
                remove_bridge_force((r,c), (nr, nc), k)

        return False

    # Initial logic application
    if not apply_logic():
        return "No Solution"

    if solve_recursive():
        result = {}
        for (p1, p2), count in current_bridges.items():
            if count > 0:
                result[(p1, p2)] = count
        return result
    else:
        return "No Solution"

OBSERVATION = {'data': [[None, 2, None, 3, None, 1, None], [2, None, None, None, None, None, None], [None, None, None, None, 4, None, 4], [None, None, None, None, None, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, 2, None, None], [3, None, None, 3, None, None, 3]]}

if __name__ == "__main__":
    print(solve(OBSERVATION))
