import sys

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])

    islands = []
    island_map = {} # (r, c) -> index

    # Parse islands
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val is not None:
                island_map[(r, c)] = len(islands)
                islands.append({'r': r, 'c': c, 'val': val, 'id': len(islands)})

    n_islands = len(islands)

    # Identify potential bridges (orthogonal connections with no islands in between)
    potential_bridges = [] 
    bridge_index_map = {} 

    # Horizontal bridges
    for r in range(rows):
        last_island_idx = None
        for c in range(cols):
            if (r, c) in island_map:
                idx = island_map[(r, c)]
                if last_island_idx is not None:
                    u, v = sorted((last_island_idx, idx))
                    if (u, v) not in bridge_index_map:
                        bridge_index_map[(u, v)] = len(potential_bridges)
                        potential_bridges.append((u, v))
                last_island_idx = idx

    # Vertical bridges
    for c in range(cols):
        last_island_idx = None
        for r in range(rows):
            if (r, c) in island_map:
                idx = island_map[(r, c)]
                if last_island_idx is not None:
                    u, v = sorted((last_island_idx, idx))
                    if (u, v) not in bridge_index_map:
                        bridge_index_map[(u, v)] = len(potential_bridges)
                        potential_bridges.append((u, v))
                last_island_idx = idx

    n_bridges = len(potential_bridges)

    # Adjacency list for islands: island_idx -> list of (bridge_idx, other_island_idx)
    island_adj = [[] for _ in range(n_islands)]
    for b_idx, (u, v) in enumerate(potential_bridges):
        island_adj[u].append((b_idx, v))
        island_adj[v].append((b_idx, u))

    # Domains for each bridge: initially {0, 1, 2}
    # We use sets to represent possible values
    domains = [ {0, 1, 2} for _ in range(n_bridges) ]

    def propagate(doms):
        # Constraint propagation loop
        changed = True
        while changed:
            changed = False

            # 1. Check island degree constraints
            for i_idx in range(n_islands):
                val = islands[i_idx]['val']

                min_deg = 0
                max_deg = 0
                incident_bridges = []

                for b_idx, _ in island_adj[i_idx]:
                    d = doms[b_idx]
                    if not d: return None # Empty domain -> contradiction
                    min_deg += min(d)
                    max_deg += max(d)
                    incident_bridges.append(b_idx)

                # Contradiction checks
                if min_deg > val or max_deg < val:
                    return None

                # Rule: If min_deg == val, all incident bridges must be at their minimum possible value
                if min_deg == val:
                    for b_idx in incident_bridges:
                        min_val = min(doms[b_idx])
                        if doms[b_idx] != {min_val}:
                            doms[b_idx] = {min_val}
                            changed = True

                # Rule: If max_deg == val, all incident bridges must be at their maximum possible value
                if max_deg == val:
                    for b_idx in incident_bridges:
                        max_val = max(doms[b_idx])
                        if doms[b_idx] != {max_val}:
                            doms[b_idx] = {max_val}
                            changed = True

            # 2. Connectivity Check (Pruning)
            # If the graph of "possible bridges" (bridges where max(domain) > 0) is disconnected, 
            # then it's impossible to connect all islands.
            parent = list(range(n_islands))
            def find(i):
                path = []
                while parent[i] != i:
                    path.append(i)
                    i = parent[i]
                for node in path:
                    parent[node] = i
                return i

            def union(i, j):
                pi, pj = find(i), find(j)
                if pi != pj:
                    parent[pi] = pj

            for b_idx, (u, v) in enumerate(potential_bridges):
                if max(doms[b_idx]) > 0:
                    union(u, v)

            if n_islands > 0:
                root = find(0)
                for i in range(1, n_islands):
                    if find(i) != root:
                        return None # Disconnected potential graph

        return doms

    # Initial propagation
    domains = propagate(domains)
    if domains is None:
        return "No Solution"

    # Backtracking search
    def solve_recursive(doms):
        # Check if solved (all domains size 1)
        solved = True
        for d in doms:
            if len(d) > 1:
                solved = False
                break

        if solved:
            # Final connectivity check with actual bridges (val > 0)
            parent = list(range(n_islands))
            def find(i):
                path = []
                while parent[i] != i:
                    path.append(i)
                    i = parent[i]
                for node in path:
                    parent[node] = i
                return i
            def union(i, j):
                pi, pj = find(i), find(j)
                if pi != pj: parent[pi] = pj

            for b_idx, (u, v) in enumerate(potential_bridges):
                val = list(doms[b_idx])[0]
                if val > 0:
                    union(u, v)

            if n_islands > 0:
                root = find(0)
                for i in range(1, n_islands):
                    if find(i) != root:
                        return None
            return doms

        # MRV Heuristic: Pick the bridge with the smallest domain size > 1
        best_b_idx = -1
        min_size = 10

        for b_idx in range(n_bridges):
            if len(doms[b_idx]) > 1:
                if len(doms[b_idx]) < min_size:
                    min_size = len(doms[b_idx])
                    best_b_idx = b_idx

        if best_b_idx == -1:
            return None 

        # Try values. Heuristic: Try larger values first (2, 1, 0) to establish connections early.
        for val in sorted(list(doms[best_b_idx]), reverse=True):
            new_doms = [d.copy() for d in doms]
            new_doms[best_b_idx] = {val}

            res = propagate(new_doms)
            if res is not None:
                final_res = solve_recursive(res)
                if final_res is not None:
                    return final_res

        return None

    final_domains = solve_recursive(domains)

    if final_domains is None:
        return "No Solution"

    # Format output as dictionary
    result = {}
    for b_idx, (u, v) in enumerate(potential_bridges):
        val = list(final_domains[b_idx])[0]
        if val > 0:
            r1, c1 = islands[u]['r'], islands[u]['c']
            r2, c2 = islands[v]['r'], islands[v]['c']
            # Ensure consistent key ordering (top-left to bottom-right)
            key = ((r1, c1), (r2, c2))
            if (r1, c1) > (r2, c2):
                key = ((r2, c2), (r1, c1))
            result[key] = val

    return result

