OBSERVATION = {'tree': [['T', None, None, None, None, None], [None, None, None, None, 'T', None], ['T', None, None, None, None, None], [None, None, None, None, None, 'T'], ['T', None, 'T', None, None, 'T'], [None, None, None, None, None, None]], 'row_tent_counts': [1, 1, 1, 2, 1, 1], 'col_tent_counts': [2, 1, 1, 1, 1, 1]}

UNKNOWN = 0
TENT = 1
GRASS = 2
TREE = 3

def solve(observation):
    tree_grid = observation['tree']
    row_clues = observation['row_tent_counts']
    col_clues = observation['col_tent_counts']

    R = len(tree_grid)
    C = len(tree_grid[0])

    # State grid: 0=Unknown, 1=Tent, 2=Grass, 3=Tree
    state = [[UNKNOWN for _ in range(C)] for _ in range(R)]
    trees = []

    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                trees.append((r, c))
                state[r][c] = TREE 

    # Pre-processing: Valid tent spots must be adjacent to exactly one tree.
    # This is a deduction from Rule 1: "Each tent must be orthogonally adjacent to its paired tree."
    for r in range(R):
        for c in range(C):
            if state[r][c] == UNKNOWN:
                adj_trees = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        if tree_grid[nr][nc] == 'T':
                            adj_trees += 1
                if adj_trees != 1:
                    state[r][c] = GRASS

    def propagate(state):
