        while changed:
            changed = False

            # 1. Row/Col Counts
            for r in range(R):
                tents = sum(1 for c in range(C) if state[r][c] == TENT)
                unknowns = [(r, c) for c in range(C) if state[r][c] == UNKNOWN]
                needed = row_clues[r] - tents

                if needed < 0: return False
                if needed == 0:
                    for c in range(C):
                        if state[r][c] == UNKNOWN:
                            state[r][c] = GRASS
                            changed = True
                elif len(unknowns) == needed:
                    for (ur, uc) in unknowns:
                        state[ur][uc] = TENT
                        changed = True

            for c in range(C):
                tents = sum(1 for r in range(R) if state[r][c] == TENT)
                unknowns = [(r, c) for r in range(R) if state[r][c] == UNKNOWN]
                needed = col_clues[c] - tents

                if needed < 0: return False
                if needed == 0:
                    for r in range(R):
                        if state[r][c] == UNKNOWN:
                            state[r][c] = GRASS
                            changed = True
                elif len(unknowns) == needed:
                    for (ur, uc) in unknowns:
                        state[ur][uc] = TENT
                        changed = True

            # 2. Tent Separation (Tents cannot touch, including diagonally)
            for r in range(R):
                for c in range(C):
                    if state[r][c] == TENT:
                        for dr in [-1, 0, 1]:
                            for dc in [-1, 0, 1]:
                                if dr == 0 and dc == 0: continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < R and 0 <= nc < C:
                                    if state[nr][nc] == UNKNOWN:
                                        state[nr][nc] = GRASS
                                        changed = True

            # 3. Tree Logic (Each tree paired with exactly one tent)
            for tr, tc in trees:
                adj_tents = []
                adj_unknowns = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = tr + dr, tc + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        val = state[nr][nc]
                        if val == TENT:
                            adj_tents.append((nr, nc))
                        elif val == UNKNOWN:
                            adj_unknowns.append((nr, nc))

                # If a tree is adjacent to >1 tents, it's invalid.
                if len(adj_tents) > 1:
                    return False 

                # If a tree has no tents and no unknown neighbors, it can't be satisfied.
                if len(adj_tents) == 0 and len(adj_unknowns) == 0:
                    return False 

                # If a tree already has a tent, all other unknown neighbors must be Grass.
                if len(adj_tents) == 1:
                    for ur, uc in adj_unknowns:
                        if state[ur][uc] == UNKNOWN: 
                            state[ur][uc] = GRASS
                            changed = True

                # If a tree has exactly one unknown neighbor and no tents, that neighbor MUST be a tent.
                if len(adj_tents) == 0 and len(adj_unknowns) == 1:
                    ur, uc = adj_unknowns[0]
                    state[ur][uc] = TENT
                    changed = True

        return True

    def is_valid(state):
        # Check counts not exceeded
        for r in range(R):
            count = sum(1 for c in range(C) if state[r][c] == TENT)
            if count > row_clues[r]: return False
        for c in range(C):
            count = sum(1 for r in range(R) if state[r][c] == TENT)
            if count > col_clues[c]: return False

        # Check tents don't touch
        for r in range(R):
            for c in range(C):
                if state[r][c] == TENT:
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0: continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if state[nr][nc] == TENT:
                                    return False
        return True

    def is_solved(state):
        if not is_valid(state): return False

        # Check counts match exactly
        for r in range(R):
            count = sum(1 for c in range(C) if state[r][c] == TENT)
            if count != row_clues[r]: return False
        for c in range(C):
            count = sum(1 for r in range(R) if state[r][c] == TENT)
            if count != col_clues[c]: return False

        # Check every tree has exactly one tent
        for tr, tc in trees:
            adj_tents = 0
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = tr + dr, tc + dc
                if 0 <= nr < R and 0 <= nc < C:
                    if state[nr][nc] == TENT:
                        adj_tents += 1
            if adj_tents != 1: 
                 return False

        return True

    def backtrack(state):
        # Apply logical deductions
        if not propagate(state):
            return None

        # Check if solved
        if is_solved(state):
            return state

        # Check validity (redundant if propagate is perfect, but safe)
        if not is_valid(state):
            return None

        # Find an unknown cell to branch on
        target = None
        for r in range(R):
            for c in range(C):
                if state[r][c] == UNKNOWN:
                    target = (r, c)
                    break
            if target: break

        if not target:
            return None 

        r, c = target

        # Try placing a Tent
        state_tent = [row[:] for row in state]
        state_tent[r][c] = TENT
        res = backtrack(state_tent)
        if res: return res

        # Try placing Grass (No Tent)
        state_grass = [row[:] for row in state]
        state_grass[r][c] = GRASS
        res = backtrack(state_grass)
        if res: return res

        return None

    # Initial propagation
    if not propagate(state):
        return "No Solution"

    final_state = backtrack(state)

    if final_state is None:
        return "No Solution"

    # Format output as list of lists with 't' and None
    result_grid = []
    for r in range(R):
        row_res = []
        for c in range(C):
            if final_state[r][c] == TENT:
                row_res.append('t')
            else:
                row_res.append(None)
        result_grid.append(row_res)

    return str(result_grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))
