def solve(observation):
    region_map = observation['region']
    data = observation['data']
    N = len(data)

    # Identify regions
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = region_map[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Constraints
    # 1. Row constraints
    row_constraints = {}
    for r in range(N):
        row_constraints[r] = [(r, c) for c in range(N)]

    # 2. Col constraints
    col_constraints = {}
    for c in range(N):
        col_constraints[c] = [(r, c) for r in range(N)]

    # 3. Region constraints
    region_constraints = regions

    all_constraints = []
    for r in range(N):
        all_constraints.append(row_constraints[r])
    for c in range(N):
        all_constraints.append(col_constraints[c])
    for rid in regions:
        all_constraints.append(region_constraints[rid])

    # AC-3 Algorithm
    queue = []
    for constraint in all_constraints:
        for i in range(len(constraint)):
            for j in range(i + 1, len(constraint)):
                queue.append((constraint[i], constraint[j]))
                queue.append((constraint[j], constraint[i]))

    def revise(domains, xi, xj):
        revised = False
        for x in list(domains[xi]):
            if not any(y != x for y in domains[xj]):
                domains[xi].remove(x)
                revised = True
        return revised

    while queue:
        xi, xj = queue.pop(0)
        if revise(domains, xi, xj):
            if not domains[xi]:
                return "No Solution"
            # Add neighbors
            # Find constraints containing xi
            for constraint in all_constraints:
                if xi in constraint:
                    for xk in constraint:
                        if xk != xi and xk != xj:
                            queue.append((xk, xi))

    # Backtracking with MRV
    assignment = {}

    def is_consistent(var, value, assignment, domains):
        # Check against assigned values in same row, col, region
        r, c = var
        rid = region_map[r][c]

        # Check row
        for cc in range(N):
            if (r, cc) in assignment and assignment[(r, cc)] == value:
                return False
        # Check col
        for rr in range(N):
            if (rr, c) in assignment and assignment[(rr, c)] == value:
                return False
        # Check region
        for rr, cc in regions[rid]:
            if (rr, cc) in assignment and assignment[(rr, cc)] == value:
                return False
        return True

    def select_unassigned_variable(assignment, domains):
        # MRV
        unassigned = [(r, c) for r in range(N) for c in range(N) if (r, c) not in assignment]
        return min(unassigned, key=lambda var: len(domains[var]))

    def backtrack(assignment, domains):
        if len(assignment) == N * N:
            return assignment

        var = select_unassigned_variable(assignment, domains)
        r, c = var

        # LCV (Least Constraining Value) - sort by number of conflicts
        # For simplicity, just iterate sorted
        for value in sorted(list(domains[var])):
            if is_consistent(var, value, assignment, domains):
                assignment[var] = value

                # Forward checking
                removed = []
                success = True

                # Check neighbors
                neighbors = []
                rid = region_map[r][c]
                for cc in range(N):
                    if (r, cc) != var and (r, cc) not in assignment:
                        neighbors.append((r, cc))
                for rr in range(N):
                    if (rr, c) != var and (rr, c) not in assignment:
                        neighbors.append((rr, c))
                for rr, cc in regions[rid]:
                    if (rr, cc) != var and (rr, cc) not in assignment:
                        neighbors.append((rr, cc))

                for neighbor in neighbors:
                    if value in domains[neighbor]:
                        domains[neighbor].remove(value)
                        removed.append((neighbor, value))
                        if not domains[neighbor]:
                            success = False
                            break

                if success:
                    result = backtrack(assignment, domains)
                    if result is not None:
                        return result

                # Undo
                assignment.pop(var)
                for neighbor, val in removed:
                    domains[neighbor].add(val)

        return None

    # Pre-fill assignment with givens
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                assignment[(r, c)] = data[r][c]

    result = backtrack(assignment, domains)

    if result is None:
        return "No Solution"

    # Format output
    grid = [[0] * N for _ in range(N)]
    for (r, c), val in result.items():
        grid[r][c] = val

    return grid

