def solve(observation):
    # Extract targets
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    R = len(row_targets)
    C = len(col_targets)

    # Based on the image, weights are 1, 2, 3, 4... corresponding to indices + 1
    # Column weights (above board): 1, 2, 3, 4
    col_weights = list(range(1, C + 1))
    # Row weights (left of board): 1, 2, 3, 4
    row_weights = list(range(1, R + 1))

    # Precompute valid bitmasks for each row
    # A mask represents the configuration of a row (bit j set means cell (r, j) is black)
    # The value of the mask is sum(col_weights[j]) for set bits
    valid_row_masks = []
    for r in range(R):
        target = row_targets[r]
        masks = []
        # Iterate all possible subsets of columns
        for m in range(1 << C):
            current_sum = 0
            for c in range(C):
                if (m >> c) & 1:
                    current_sum += col_weights[c]
            if current_sum == target:
                masks.append(m)
        valid_row_masks.append(masks)

    # Precompute valid bitmasks for each column
    # A mask represents the configuration of a column (bit i set means cell (i, c) is black)
    # The value of the mask is sum(row_weights[i]) for set bits
    valid_col_masks = []
    for c in range(C):
        target = col_targets[c]
        masks = []
        # Iterate all possible subsets of rows
        for m in range(1 << R):
            current_sum = 0
            for r in range(R):
                if (m >> r) & 1:
                    current_sum += row_weights[r]
            if current_sum == target:
                masks.append(m)
        valid_col_masks.append(masks)

    # Pruning: If any row or column has no valid masks, no solution exists
    for r in range(R):
        if not valid_row_masks[r]:
            return "No Solution"
    for c in range(C):
        if not valid_col_masks[c]:
            return "No Solution"

    # Backtracking solver with constraint propagation (Forward Checking)
    # We select a valid mask for each row, ensuring it is consistent with possible column masks.

    # current_col_constraints[c] holds the list of valid column masks for column c
    # that are consistent with the row choices made so far.
    current_col_constraints = [list(masks) for masks in valid_col_masks]

    solution_row_masks = [0] * R

    def backtrack(r_idx, col_constraints):
        # Base case: All rows have been assigned a valid mask
        if r_idx == R:
            return True

        # Try each valid mask for the current row
        for r_mask in valid_row_masks[r_idx]:
            # Check consistency with column constraints and propagate
            next_col_constraints = []
            is_consistent = True

            for c in range(C):
                # Determine if cell (r_idx, c) is black in this row mask
                cell_is_black = ((r_mask >> c) & 1) == 1

                # Filter column masks for column c
                # A column mask is valid only if its bit at r_idx matches cell_is_black
                filtered_masks = []
                for c_mask in col_constraints[c]:
                    if ((c_mask >> r_idx) & 1) == (1 if cell_is_black else 0):
                        filtered_masks.append(c_mask)

                if not filtered_masks:
                    is_consistent = False
                    break
                next_col_constraints.append(filtered_masks)

            if is_consistent:
                solution_row_masks[r_idx] = r_mask
                if backtrack(r_idx + 1, next_col_constraints):
                    return True

        return False

    if backtrack(0, current_col_constraints):
        # Reconstruct the grid from the solution masks
        grid = []
        for r in range(R):
            row_data = []
            mask = solution_row_masks[r]
            for c in range(C):
                if (mask >> c) & 1:
                    row_data.append('B')
                else:
                    row_data.append(None)
            grid.append(row_data)
        return grid
    else:
        return "No Solution"

