import sys
sys.setrecursionlimit(2000)

def solve(observation):
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0]) if R > 0 else 0

    # Identify regions and their cells
    regions = {}
    for r in range(R):
        for c in range(C):
            rid = grid_data[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_ids = list(regions.keys())

    # Define tetromino shapes (relative coordinates)
    # L type includes L and J
    # S type includes S and Z
    def get_shapes():
        shapes = {
            'L': [],
            'I': [],
            'T': [],
            'S': []
        }

        # Base shapes
        base_L = [(0,0), (1,0), (2,0), (2,1)] # L
        base_J = [(0,1), (1,1), (2,1), (2,0)] # J
        base_I = [(0,0), (1,0), (2,0), (3,0)]
        base_T = [(0,0), (0,1), (0,2), (1,1)]
        base_S = [(0,1), (0,2), (1,0), (1,1)] # S
        base_Z = [(0,0), (0,1), (1,1), (1,2)] # Z

        def rotate(shape):
            return [(-c, r) for r, c in shape]

        def reflect(shape):
            return [(r, -c) for r, c in shape]

        def normalize(shape):
            min_r = min(r for r, c in shape)
            min_c = min(c for r, c in shape)
            return sorted([(r-min_r, c-min_c) for r, c in shape])

        def generate_orientations(base):
            orients = set()
            s = base
            for _ in range(4):
                orients.add(tuple(normalize(s)))
                s = rotate(s)
            s = reflect(base)
            for _ in range(4):
                orients.add(tuple(normalize(s)))
                s = rotate(s)
            return [list(o) for o in orients]

        shapes['L'] = generate_orientations(base_L)
        shapes['I'] = generate_orientations(base_I)
        shapes['T'] = generate_orientations(base_T)
        shapes['S'] = generate_orientations(base_S) # Includes Z via reflection

        return shapes

    tetrominoes = get_shapes()

    # Precompute valid placements for each region
    # A placement is (type, set of cells)
    region_placements = {}
    for rid in region_ids:
        cells = set(regions[rid])
        placements = []
        for t_type, shapes in tetrominoes.items():
            for shape in shapes:
                # Try to fit shape in region
                # Anchor at each cell in region
                for r, c in cells:
                    placed_cells = []
                    valid = True
                    for dr, dc in shape:
                        nr, nc = r + dr, c + dc
                        if (nr, nc) not in cells:
                            valid = False
                            break
                        placed_cells.append((nr, nc))
                    if valid:
                        placements.append((t_type, frozenset(placed_cells)))
        # Remove duplicates
        seen = set()
        unique_placements = []
        for p in placements:
            key = (p[0], p[1])
            if key not in seen:
                seen.add(key)
                unique_placements.append(p)
        region_placements[rid] = unique_placements

    # Compute region adjacency
    region_neighbors = {rid: set() for rid in region_ids}
    for rid in region_ids:
        for r, c in regions[rid]:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    nrid = grid_data[nr][nc]
                    if nrid != rid:
                        region_neighbors[rid].add(nrid)

    # Backtracking solver
    solution = {} # rid -> (type, cells)
    shaded_cells = set()

    def is_connected(shaded):
        if not shaded:
            return True
        start = next(iter(shaded))
        visited = set()
        stack = [start]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            r, c = curr
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in shaded and (nr, nc) not in visited:
                    stack.append((nr, nc))
        return len(visited) == len(shaded)

    def has_2x2(shaded):
        for r, c in shaded:
            # Check 2x2 blocks where (r,c) is top-left
            if (r+1, c) in shaded and (r, c+1) in shaded and (r+1, c+1) in shaded:
                return True
            # Check other corners? No, iterating all cells covers all 2x2s
        return False

    def check_2x2_incremental(new_cells):
        # Check if adding new_cells creates a 2x2 with existing shaded_cells
        for r, c in new_cells:
            # Check 2x2 where (r,c) is top-left
            if (r+1, c) in shaded_cells and (r, c+1) in shaded_cells and (r+1, c+1) in shaded_cells:
                return False
            # Check 2x2 where (r,c) is top-right
            if (r+1, c) in shaded_cells and (r, c-1) in shaded_cells and (r+1, c-1) in shaded_cells:
                return False
            # Check 2x2 where (r,c) is bottom-left
            if (r-1, c) in shaded_cells and (r, c+1) in shaded_cells and (r-1, c+1) in shaded_cells:
                return False
            # Check 2x2 where (r,c) is bottom-right
            if (r-1, c) in shaded_cells and (r, c-1) in shaded_cells and (r-1, c-1) in shaded_cells:
                return False
        return True

    def backtrack(order):
        if not order:
            # Check connectivity
            if is_connected(shaded_cells):
                return True
            return False

        # MRV: Choose region with fewest remaining valid placements
        # Filter placements based on current state
        best_rid = None
        best_options = None
        min_len = float('inf')

        for rid in order:
            options = []
            for t_type, cells in region_placements[rid]:
                # Check adjacency constraint
                conflict = False
                for nrid in region_neighbors[rid]:
                    if nrid in solution:
                        if solution[nrid][0] == t_type:
                            conflict = True
                            break
                if conflict:
                    continue
                # Check 2x2 constraint
                if not check_2x2_incremental(cells):
                    continue
                options.append((t_type, cells))

            if len(options) == 0:
                return False # Dead end

            if len(options) < min_len:
                min_len = len(options)
                best_rid = rid
                best_options = options
                if min_len == 1:
                    break

        if best_rid is None:
            return False

        new_order = [r for r in order if r != best_rid]

        for t_type, cells in best_options:
            # Place
            solution[best_rid] = (t_type, cells)
            old_shaded = shaded_cells.copy()
            shaded_cells.update(cells)

            if backtrack(new_order):
                return True

            # Unplace
            del solution[best_rid]
            shaded_cells.clear()
            shaded_cells.update(old_shaded)

        return False

    # Sort initial order by number of placements (static MRV)
    initial_order = sorted(region_ids, key=lambda rid: len(region_placements[rid]))

    if backtrack(initial_order):
        # Construct output grid
        result_grid = [[None for _ in range(C)] for _ in range(R)]
        for rid, (t_type, cells) in solution.items():
            for r, c in cells:
                result_grid[r][c] = t_type
        return result_grid
    else:
        return "No Solution"

