                if dr == 0 and dc == 0: continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < R and 0 <= nc < C:
                    res.append((nr, nc))
        return res

    def apply_rules(g, rc, cc, tt):
        changed = True
        while changed:
            changed = False

            # 1. Zero clues -> Grass
            for r in range(R):
                if row_clues[r] == 0:
                    for c in range(C):
                        if g[r][c] == 0:
                            g[r][c] = 3
                            changed = True
            for c in range(C):
                if col_clues[c] == 0:
                    for r in range(R):
                        if g[r][c] == 0:
                            g[r][c] = 3
                            changed = True

            # 2. Tent placed -> Neighbors Grass (including diagonal)
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 2:
                        for nr, nc in get_all(r, c):
                            if g[nr][nc] == 0:
                                g[nr][nc] = 3
                                changed = True

            # 3. Tree paired -> Other neighbors Grass
            for i, (tr, tc) in enumerate(trees):
                if tt[i] is not None:
                    for nr, nc in get_ortho(tr, tc):
                        if g[nr][nc] == 0:
                            g[nr][nc] = 3
                            changed = True

            # 4. Row/Col Full -> Rest Grass
            for r in range(R):
                if rc[r] == row_clues[r]:
                    for c in range(C):
                        if g[r][c] == 0:
                            g[r][c] = 3
                            changed = True
            for c in range(C):
                if cc[c] == col_clues[c]:
                    for r in range(R):
                        if g[r][c] == 0:
                            g[r][c] = 3
                            changed = True

            # 5. Tree has only 1 option -> Place Tent
            for i, (tr, tc) in enumerate(trees):
                if tt[i] is not None: continue
                options = []
                for nr, nc in get_ortho(tr, tc):
                    if g[nr][nc] == 0:
                        options.append((nr, nc))

                if len(options) == 1:
                    nr, nc = options[0]
                    g[nr][nc] = 2
                    rc[nr] += 1
                    cc[nc] += 1
                    tt[i] = (nr, nc)
                    changed = True
                elif len(options) == 0:
                    return 'CONTRADICTION', g, rc, cc, tt

            # 6. Row/Col Remaining == Empty Spots -> Fill
            for r in range(R):
                needed = row_clues[r] - rc[r]
                if needed < 0: return 'CONTRADICTION', g, rc, cc, tt
                spots = [(r, c) for c in range(C) if g[r][c] == 0]
                if len(spots) == needed and needed > 0:
                    for nr, nc in spots:
                        g[nr][nc] = 2
                        rc[nr] += 1
                        cc[nc] += 1
                        for i, (tr, tc) in enumerate(trees):
                            if tt[i] is None and abs(tr-nr) + abs(tc-nc) == 1:
                                tt[i] = (nr, nc)
                                break
                    changed = True

            for c in range(C):
                needed = col_clues[c] - cc[c]
                if needed < 0: return 'CONTRADICTION', g, rc, cc, tt
                spots = [(r, c) for r in range(R) if g[r][c] == 0]
                if len(spots) == needed and needed > 0:
                    for nr, nc in spots:
                        g[nr][nc] = 2
                        rc[nr] += 1
                        cc[nc] += 1
                        for i, (tr, tc) in enumerate(trees):
                            if tt[i] is None and abs(tr-nr) + abs(tc-nc) == 1:
                                tt[i] = (nr, nc)
                                break
                    changed = True

        # Check solved
        if all(rc[r] == row_clues[r] for r in range(R)) and \
           all(cc[c] == col_clues[c] for c in range(C)) and \
           all(tt[i] is not None for i in range(len(trees))):
            return 'SOLVED', g, rc, cc, tt

        return 'STALLED', g, rc, cc, tt

    def format_output(g):
        res = []
        for r in range(R):
            row = []
            for c in range(C):
                if g[r][c] == 2:
                    row.append('t')
                else:
                    row.append(None)
            res.append(row)
        return res

    def backtrack(g, rc, cc, tt):
        # Find a tree with no tent and fewest options
        min_opts = 100
        best_i = -1
        best_opts = []

        for i, (tr, tc) in enumerate(trees):
            if tt[i] is not None: continue
            opts = []
            for nr, nc in get_ortho(tr, tc):
                if g[nr][nc] == 0:
                    opts.append((nr, nc))
            if len(opts) < min_opts:
                min_opts = len(opts)
                best_i = i
                best_opts = opts

        if best_i == -1:
            if all(rc[r] == row_clues[r] for r in range(R)) and \
               all(cc[c] == col_clues[c] for c in range(C)):
                return format_output(g)
            return "No Solution"

        tr, tc = trees[best_i]

        for nr, nc in best_opts:
            new_grid = [row[:] for row in g]
            new_rc = rc[:]
            new_cc = cc[:]
            new_tt = tt.copy()

            new_grid[nr][nc] = 2
            new_rc[nr] += 1
            new_cc[nc] += 1
            new_tt[best_i] = (nr, nc)

            status, res_g, res_rc, res_cc, res_tt = apply_rules(new_grid, new_rc, new_cc, new_tt)

            if status == 'SOLVED':
                return format_output(res_g)
            if status == 'STALLED':
                res = backtrack(res_g, res_rc, res_cc, res_tt)
                if res != "No Solution":
                    return res

        return "No Solution"

    status, grid, r_counts, c_counts, tree_tent = apply_rules(grid, r_counts, c_counts, tree_tent)

    if status == 'SOLVED':
        return format_output(grid)
    if status == 'CONTRADICTION':
        return "No Solution"

    return backtrack(grid, r_counts, c_counts, tree_tent)

if __name__ == "__main__":
    print(solve(OBSERVATION))
