import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']

    N = len(data)

    # Parse adjacent dots into a set of frozensets for O(1) lookup
    # A dot at (r, c+0.5) connects (r, c) and (r, c+1) -> Horizontal
    # A dot at (r+0.5, c) connects (r, c) and (r+1, c) -> Vertical
    dot_pairs = set()

    for coord in adjacent:
        r, c = coord
        # Check if horizontal or vertical gap based on which coordinate is integer/half-integer
        # Horizontal gap: row is integer, col is x.5
        # Vertical gap: row is x.5, col is integer

        # Using a small epsilon for float comparison safety, though inputs are likely clean
        if abs(r - round(r)) < 1e-5: # Horizontal gap: (row, col+0.5)
            # r is the row index
            # c is col + 0.5. So the left cell is at col = int(c) (since c >= 0.5)
            # Actually, if c=0.5, int(c)=0. Cells (r, 0) and (r, 1).
            c1 = int(c) 
            c2 = c1 + 1
            dot_pairs.add(frozenset([(r, c1), (r, c2)]))
        else: # Vertical gap: (row+0.5, col)
            # r is row + 0.5. So the top cell is at row = int(r)
            r1 = int(r)
            r2 = r1 + 1
            # c is the col index
            dot_pairs.add(frozenset([(r1, c), (r2, c)]))

    # Initialize board with 0 (empty)
    board = [[0] * N for _ in range(N)]

    # Fill initial clues
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                board[r][c] = data[r][c]

    # Precompute neighbors for each cell (Up, Down, Left, Right)
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighs = []
            if r > 0: neighs.append((r-1, c))
            if r < N-1: neighs.append((r+1, c))
            if c > 0: neighs.append((r, c-1))
            if c < N-1: neighs.append((r, c+1))
            neighbors[(r, c)] = neighs

    # Helper to check if a pair of cells has a dot constraint
    def has_dot(cell1, cell2):
        return frozenset([cell1, cell2]) in dot_pairs

    # Function to get valid values for a cell given the current board state
    def get_valid_values(r, c, current_board):
        # If cell is already filled, return its value (consistency check assumed done)
        if current_board[r][c] != 0:
            return [current_board[r][c]]

        possible = []
        for v in range(1, N+1):
            # 1. Check Row and Column uniqueness
            conflict = False
            for k in range(N):
                if current_board[r][k] == v or current_board[k][c] == v:
                    conflict = True
                    break
            if conflict: 
                continue

            # 2. Check Neighbor Constraints (Consecutive / Non-consecutive)
            for nr, nc in neighbors[(r, c)]:
                n_val = current_board[nr][nc]
                if n_val != 0:
                    is_constrained = has_dot((r, c), (nr, nc))
                    if is_constrained:
                        # Must be consecutive
                        if abs(v - n_val) != 1:
                            conflict = True
                            break
                    else:
                        # Must NOT be consecutive
                        if abs(v - n_val) == 1:
                            conflict = True
                            break

            if not conflict:
                possible.append(v)
        return possible

    # Backtracking solver with MRV (Minimum Remaining Values) heuristic
    def solve_recursive():
        best_cell = None
        best_domain = None
        min_len = N + 1

        # Find the empty cell with the fewest valid possibilities
        for r in range(N):
            for c in range(N):
                if board[r][c] == 0:
                    domain = get_valid_values(r, c, board)
                    if len(domain) == 0:
                        return False # Dead end
                    if len(domain) < min_len:
                        min_len = len(domain)
                        best_cell = (r, c)
                        best_domain = domain
                        if min_len == 1: 
                            break # Optimization: if we found a cell with 1 option, pick it immediately
            if min_len == 1: 
                break

        # If no empty cell found, we are done
        if best_cell is None:
            return True

        r, c = best_cell
        # Try each value in the domain
        for val in best_domain:
            board[r][c] = val
            if solve_recursive():
                return True
            board[r][c] = 0 # Backtrack

        return False

    if solve_recursive():
        return board
    else:
        return "No Solution"

