def solve(observation):
    data = observation['data']
    H = len(data)
    W = len(data[0])

    # h_edges[r][c] is horizontal edge at row r, col c (between (r,c) and (r,c+1))
    # v_edges[r][c] is vertical edge at row r, col c (between (r,c) and (r+1,c))
    # Values: 0 (No), 1 (Yes), -1 (Unknown)
    h_edges = [[-1] * W for _ in range(H + 1)]
    v_edges = [[-1] * (W + 1) for _ in range(H)]

    def get_cell_edges(r, c):
        return [('h', r, c), ('h', r + 1, c), ('v', r, c), ('v', r, c + 1)]

    def get_node_edges(r, c):
        edges = []
        if r > 0: edges.append(('v', r - 1, c))
        if r < H: edges.append(('v', r, c))
        if c > 0: edges.append(('h', r, c - 1))
        if c < W: edges.append(('h', r, c))
        return edges

    def set_edge(type, r, c, val):
        if type == 'h':
            if h_edges[r][c] != -1 and h_edges[r][c] != val: return False
            h_edges[r][c] = val
        else:
            if v_edges[r][c] != -1 and v_edges[r][c] != val: return False
            v_edges[r][c] = val
        return True

    def get_edge(type, r, c):
        return h_edges[r][c] if type == 'h' else v_edges[r][c]

    def count_lines(edges_list):
        count = unknown = 0
        for t, r, c in edges_list:
            val = get_edge(t, r, c)
            if val == 1: count += 1
            elif val == -1: unknown += 1
        return count, unknown

    def find_cycles():
        adj = {}
        for r in range(H + 1):
            for c in range(W):
                if h_edges[r][c] == 1:
                    u, v = (r, c), (r, c + 1)
                    adj.setdefault(u, []).append(v)
                    adj.setdefault(v, []).append(u)
        for r in range(H):
            for c in range(W + 1):
                if v_edges[r][c] == 1:
                    u, v = (r, c), (r + 1, c)
                    adj.setdefault(u, []).append(v)
                    adj.setdefault(v, []).append(u)

        visited = set()
        cycles = []
        for start_node in adj:
            if start_node in visited: continue
            component_nodes = []
            stack = [start_node]
            comp_visited = set()
            while stack:
                u = stack.pop()
                if u in comp_visited: continue
                comp_visited.add(u)
                component_nodes.append(u)
                for v in adj.get(u, []):
                    if v not in comp_visited: stack.append(v)
            visited.update(comp_visited)
            is_cycle = all(len(adj.get(u, [])) == 2 for u in component_nodes)
            if is_cycle and component_nodes:
                cycles.append(component_nodes)
        return cycles, adj

    def check_small_loops():
        cycles, adj = find_cycles()
        if not cycles: return True
        total_lines = sum(1 for r in range(H+1) for c in range(W) if h_edges[r][c]==1) + \
                      sum(1 for r in range(H) for c in range(W+1) if v_edges[r][c]==1)
        for cycle_nodes in cycles:
            cycle_lines = sum(len(adj.get(u, [])) for u in cycle_nodes) // 2
            if cycle_lines < total_lines: return False
            if cycle_lines == total_lines:
                for r in range(H):
                    for c in range(W):
                        clue = data[r][c]
                        if clue is None: continue
                        if count_lines(get_cell_edges(r, c))[0] != clue: return False
                return True
        return True

    def apply_rules():
        changed = True
        while changed:
