                    if clue is None: continue
                    edges = get_cell_edges(r, c)
                    lines, unknowns = count_lines(edges)
                    if lines == clue:
                        for t, er, ec in edges:
                            if get_edge(t, er, ec) == -1:
                                if not set_edge(t, er, ec, 0): return False
                                changed = True
                    elif lines + unknowns == clue:
                        for t, er, ec in edges:
                            if get_edge(t, er, ec) == -1:
                                if not set_edge(t, er, ec, 1): return False
                                changed = True
            # Node Rules
            for r in range(H + 1):
                for c in range(W + 1):
                    edges = get_node_edges(r, c)
                    lines, unknowns = count_lines(edges)

                    if lines > 2: return False # Degree > 2 invalid
                    if lines == 2:
                        for t, er, ec in edges:
                            if get_edge(t, er, ec) == -1:
                                if not set_edge(t, er, ec, 0): return False
                                changed = True
                    elif lines == 1 and unknowns == 1:
                        for t, er, ec in edges:
                            if get_edge(t, er, ec) == -1:
                                if not set_edge(t, er, ec, 1): return False
                                changed = True
                    elif lines == 1 and unknowns == 0:
                        return False # Degree 1 invalid
                    elif lines == 0 and unknowns == 1:
                        # If only 1 unknown and rest are X, this unknown must be X (degree 0)
                        # Check if rest are indeed X
                        xs = len(edges) - lines - unknowns
                        if xs == len(edges) - 1:
                            for t, er, ec in edges:
                                if get_edge(t, er, ec) == -1:
                                    if not set_edge(t, er, ec, 0): return False
                                    changed = True
            if not check_small_loops(): return False
        return True

    def is_solved():
        for r in range(H):
            for c in range(W):
                clue = data[r][c]
                if clue is None: continue
                if count_lines(get_cell_edges(r, c))[0] != clue: return False
        for r in range(H + 1):
            for c in range(W):
                if h_edges[r][c] == -1: return False
        for r in range(H):
            for c in range(W + 1):
                if v_edges[r][c] == -1: return False
        return True

    def solve_recursive():
        if not apply_rules(): return False
        if is_solved(): return True
        # Find first unknown edge
        for r in range(H + 1):
            for c in range(W):
                if h_edges[r][c] == -1:
                    h_backup, v_backup = [row[:] for row in h_edges], [row[:] for row in v_edges]
                    h_edges[r][c] = 1
                    if solve_recursive(): return True
                    for i in range(H + 1): h_edges[i] = h_backup[i][:]
                    for i in range(H): v_edges[i] = v_backup[i][:]
                    h_edges[r][c] = 0
