                    return False
        for r in range(H):
            for c in range(W + 1):
                if v_edges[r][c] == -1:
                    h_backup, v_backup = [row[:] for row in h_edges], [row[:] for row in v_edges]
                    v_edges[r][c] = 1
                    if solve_recursive(): return True
                    for i in range(H + 1): h_edges[i] = h_backup[i][:]
                    for i in range(H): v_edges[i] = v_backup[i][:]
                    v_edges[r][c] = 0
                    if solve_recursive(): return True
                    for i in range(H + 1): h_edges[i] = h_backup[i][:]
                    for i in range(H): v_edges[i] = v_backup[i][:]
                    return False
        return False

    if solve_recursive():
        adj = {}
        for r in range(H + 1):
            for c in range(W):
                if h_edges[r][c] == 1:
                    u, v = (r, c), (r, c + 1)
                    adj.setdefault(u, []).append(v)
