        for r in range(H):
            for c in range(W + 1):
                if v_edges[r][c] == 1:
                    u, v = (r, c), (r + 1, c)
                    adj.setdefault(u, []).append(v)
                    adj.setdefault(v, []).append(u)
        if not adj: return []
        start_node = list(adj.keys())[0]
        path = [start_node]
        current, prev = start_node, None
        while True:
            next_node = next((n for n in adj[current] if n != prev), None)
            if next_node is None: break
            if next_node == start_node:
                path.append(start_node)
                break
            path.append(next_node)
            prev, current = current, next_node
        return path
    return "No Solution"

