import copy

def solve(observation):
    tree_grid = observation['tree']
    row_counts = observation['row_tent_counts']
    col_counts = observation['col_tent_counts']

    R = len(tree_grid)
    C = len(tree_grid[0])

    # Grid state: 
    # 0: Unknown
    # 1: Tent
    # 2: Grass (Empty)
    # 3: Tree
    grid = [[0]*C for _ in range(R)]
    trees = []

    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                grid[r][c] = 3
                trees.append((r, c))
            else:
                grid[r][c] = 0 

    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighs.append((nr, nc))
        return neighs

    def get_ortho_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                neighs.append((nr, nc))
        return neighs

    def propagate(g, r_counts, c_counts):
        changed = True
        while changed:
            changed = False

            # 1. Zero clues: Mark all empty cells in row/col as Grass
            for r in range(R):
                if r_counts[r] == 0:
                    for c in range(C):
                        if g[r][c] == 0:
                            g[r][c] = 2
                            changed = True
            for c in range(C):
                if c_counts[c] == 0:
                    for r in range(R):
                        if g[r][c] == 0:
                            g[r][c] = 2
                            changed = True

            # 2. Max clues: Fill if count matches or remaining spots match needed
            for r in range(R):
                current_tents = sum(1 for c in range(C) if g[r][c] == 1)
                unknowns = sum(1 for c in range(C) if g[r][c] == 0)
                if current_tents > r_counts[r]: return False
                if current_tents == r_counts[r]:
                    for c in range(C):
                        if g[r][c] == 0:
                            g[r][c] = 2
                            changed = True
                elif current_tents + unknowns == r_counts[r]:
                    for c in range(C):
                        if g[r][c] == 0:
                            g[r][c] = 1
                            changed = True

            for c in range(C):
                current_tents = sum(1 for r in range(R) if g[r][c] == 1)
                unknowns = sum(1 for r in range(R) if g[r][c] == 0)
                if current_tents > c_counts[c]: return False
                if current_tents == c_counts[c]:
                    for r in range(R):
                        if g[r][c] == 0:
                            g[r][c] = 2
                            changed = True
                elif current_tents + unknowns == c_counts[c]:
                    for r in range(R):
                        if g[r][c] == 0:
                            g[r][c] = 1
                            changed = True

            # 3. Tree Logic: Each tree needs exactly one tent orthogonally adjacent
            for r, c in trees:
                ortho_neighs = get_ortho_neighbors(r, c)
                available_spots = [(nr, nc) for nr, nc in ortho_neighs if g[nr][nc] == 0]
                existing_tents = [(nr, nc) for nr, nc in ortho_neighs if g[nr][nc] == 1]

                # A tree cannot have more than 1 tent adjacent (1-to-1 pairing)
                if len(existing_tents) > 1:
                    return False 

                # If tree has a tent, other unknown neighbors must be grass
                if len(existing_tents) == 1:
                    for nr, nc in available_spots:
                        g[nr][nc] = 2
                        changed = True

                # If tree has no tent and no spots, impossible
                if len(existing_tents) == 0 and len(available_spots) == 0:
                    return False 

                # If tree has only 1 spot, place tent
                if len(existing_tents) == 0 and len(available_spots) == 1:
                    nr, nc = available_spots[0]
                    g[nr][nc] = 1
                    changed = True

            # 4. Tent Logic: Tents cannot touch (including diagonally)
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 1:
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == 1:
                                return False
                            if g[nr][nc] == 0:
                                g[nr][nc] = 2
                                changed = True

            # 5. Tent-Tree Adjacency Rule: Each tent must be orthogonally adjacent to exactly one tree
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 1:
                        tree_neighbors = [(nr, nc) for nr, nc in get_ortho_neighbors(r, c) if g[nr][nc] == 3]
                        if len(tree_neighbors) == 0:
                            return False 
                        if len(tree_neighbors) > 1:
                            return False

        return True

    def solve_recursive(g, r_counts, c_counts):
        # Propagate constraints
        if not propagate(g, r_counts, c_counts):
            return None

        # Check if solved (no unknowns)
        is_solved = True
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            # Final validation of 1-to-1 matching
            tree_tent_map = {} 
            tent_tree_map = {} 

            for r, c in trees:
                adj_tents = [(nr, nc) for nr, nc in get_ortho_neighbors(r, c) if g[nr][nc] == 1]
                if len(adj_tents) != 1:
                    return None 
                tent = adj_tents[0]
                if tent in tent_tree_map:
                     return None 
                tree_tent_map[(r,c)] = tent
                tent_tree_map[tent] = (r,c)

            return g

        # Heuristic: Pick first unknown cell
        best_cell = None
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    best_cell = (r, c)
                    break
            if best_cell: break

        if not best_cell:
             return None 

        r, c = best_cell

        # Try placing Tent
        g1 = copy.deepcopy(g)
        g1[r][c] = 1
        res1 = solve_recursive(g1, r_counts, c_counts)
        if res1: return res1

        # Try placing Grass
        g2 = copy.deepcopy(g)
        g2[r][c] = 2
        res2 = solve_recursive(g2, r_counts, c_counts)
        if res2: return res2

        return None

    # Initial Propagation
    if not propagate(grid, row_counts, col_counts):
        return "No Solution"

    final_grid = solve_recursive(grid, row_counts, col_counts)

    if final_grid is None:
        return "No Solution"

    # Format output: 't' for tent, None otherwise
    result_grid = [[None for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if final_grid[r][c] == 1:
                result_grid[r][c] = 't'

    return result_grid

