    num_cols = len(col_targets)

    # Precompute valid masks for each row
    # A mask is an integer where bit j is 1 if cell (row, j) is black
    valid_row_masks = []
    for r in range(num_rows):
        masks = []
        target = row_targets[r]
        # Iterate all 2^num_cols combinations
        for m in range(1 << num_cols):
            current_sum = 0
            for c in range(num_cols):
                if (m >> c) & 1:
                    current_sum += col_weights[c]
            if current_sum == target:
                masks.append(m)
        valid_row_masks.append(masks)

    # Backtracking solver
    # State: current row index, current column sums accumulated so far
    solution_grid = [[None for _ in range(num_cols)] for _ in range(num_rows)]

    def is_valid_col_partial(col_idx, current_sum, row_idx):
        # Check if current_sum exceeds target
        if current_sum > col_targets[col_idx]:
            return False
        # Check if it's possible to reach target with remaining rows
        # Max possible addition is sum of row_weights for rows > row_idx
        max_possible_addition = sum(row_weights[k] for k in range(row_idx + 1, num_rows))
        if current_sum + max_possible_addition < col_targets[col_idx]:
            return False
        return True

    def solve_recursive(r, current_col_sums):
        if r == num_rows:
            # Check if all column sums match exactly
            for c in range(num_cols):
                if current_col_sums[c] != col_targets[c]:
                    return False
            return True

        # Try each valid mask for the current row
        for mask in valid_row_masks[r]:
            # Calculate new column sums
            new_col_sums = list(current_col_sums)
            possible = True

            # Apply mask
            for c in range(num_cols):
                if (mask >> c) & 1:
                    new_col_sums[c] += row_weights[r]

            # Check column constraints
            for c in range(num_cols):
                if not is_valid_col_partial(c, new_col_sums[c], r):
                    possible = False
                    break

            if possible:
                # Record solution for this row
                for c in range(num_cols):
                    if (mask >> c) & 1:
                        solution_grid[r][c] = 'B'
                    else:
                        solution_grid[r][c] = None # Explicitly None

                if solve_recursive(r + 1, new_col_sums):
                    return True

                # Backtrack (not strictly needed as we overwrite, but good for clarity)
                # solution_grid[r] is overwritten in next iteration

        return False

    initial_col_sums = [0] * num_cols
    if solve_recursive(0, initial_col_sums):
        return solution_grid
    else:
        return "No Solution"

