        sizes = {}
        for pos in nums: sizes[pos] = 0
        for r in range(R):
            for c in range(C):
                if g[r][c] == 1:
                    o = own[r][c]
                    if o: 
                        sizes[o] = sizes.get(o, 0) + 1
                    else:
                        return False # White cell with no owner

