                return False

        # 2. Check no unknown
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    return False

        # 3. Check island separation (no touching different islands)
        for r in range(R):
            for c in range(C):
                if g[r][c] == 1:
                    o1 = own[r][c]
                    for nr, nc in get_neighbors(r, c):
                        if g[nr][nc] == 1:
                            o2 = own[nr][nc]
                            if o1 != o2:
                                return False

        # 4. Check black connectivity
        start = None
        black_count = 0
        for r in range(R):
            for c in range(C):
                if g[r][c] == 2:
                    black_count += 1
                    if not start: start = (r, c)

        if black_count == 0:
            return len(nums) <= 1

        visited = set()
        queue = [start]
        visited.add(start)
        count = 0
        while queue:
            curr = queue.pop(0)
            count += 1
            for nr, nc in get_neighbors(*curr):
                if g[nr][nc] == 2 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return count == black_count

    def solve_recursive(g, own):
        # Propagation Loop
        while True:
            changed = False

            # Rule: Size Limit
            sizes = {}
            for pos in numbers: sizes[pos] = 0
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 1:
                        o = own[r][c]
                        if o: sizes[o] = sizes.get(o, 0) + 1

            for pos, target in numbers.items():
                if sizes[pos] == target:
                    for r in range(R):
                        for c in range(C):
                            if own[r][c] == pos:
                                for nr, nc in get_neighbors(r, c):
                                    if g[nr][nc] == 0:
                                        g[nr][nc] = 2
                                        changed = True
                                    elif g[nr][nc] == 1:
                                        if own[nr][nc] != pos:
                                            return None

            # Rule: 2x2 Black
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    b_count = sum(1 for rr, cc in cells if g[rr][cc] == 2)
                    if b_count == 4:
                        return None
                    if b_count == 3:
                        for rr, cc in cells:
                            if g[rr][cc] == 0:
                                g[rr][cc] = 1
                                owners_found = set()
                                for n_nr, n_nc in get_neighbors(rr, cc):
                                    if g[n_nr][n_nc] == 1:
                                        o = own[n_nr][n_nc]
                                        if o: owners_found.add(o)
                                if len(owners_found) == 1:
                                    own[rr][cc] = list(owners_found)[0]
                                    changed = True
                                elif len(owners_found) > 1:
                                    return None
                                else:
                                    if (rr, cc) not in numbers:
                                        return None

            # Rule: Separation (Pre-emptive Black)
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 0:
                        adj_owners = set()
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == 1:
                                o = own[nr][nc]
                                if o: adj_owners.add(o)
                            elif (nr, nc) in numbers:
                                adj_owners.add((nr, nc))
                        if len(adj_owners) > 1:
                            g[r][c] = 2
                            changed = True

            # Rule: Check existing contradictions (White touching White different owner)
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 1:
                        o1 = own[r][c]
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == 1:
                                o2 = own[nr][nc]
                                if o1 and o2 and o1 != o2:
                                    return None

            if not changed:
                break

        # Check solved
        if is_solved(g, own, numbers):
            return g

        # Check island sizes > target
        sizes = {}
        for pos in numbers: sizes[pos] = 0
        for r in range(R):
            for c in range(C):
                if g[r][c] == 1:
                    o = own[r][c]
                    if o: 
                        sizes[o] = sizes.get(o, 0) + 1
                        if sizes[o] > numbers[o]:
                            return None

        # Find candidates (Unknown cells adjacent to White)
        candidates = []
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    is_frontier = False
                    for nr, nc in get_neighbors(r, c):
                        if g[nr][nc] == 1:
                            is_frontier = True
                            break
                    if is_frontier:
                        candidates.append((r, c))

        if not candidates:
            # Set all remaining to Black
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 0:
                        g[r][c] = 2

            # Check 2x2
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    if all(g[rr][cc] == 2 for rr, cc in cells):
                        return None

            if is_solved(g, own, numbers):
                return g
            return None

        # Pick candidate
        r, c = candidates[0]

        # Branch 1: Black
        g_b = [row[:] for row in g]
        own_b = [row[:] for row in own]
        g_b[r][c] = 2
        res = solve_recursive(g_b, own_b)
        if res: return res

        # Branch 2: White
        white_neighbors = []
        for nr, nc in get_neighbors(r, c):
            if g[nr][nc] == 1:
                white_neighbors.append((nr, nc))

        if not white_neighbors:
            return None 

        owner_candidate = None
        valid = True
        for nr, nc in white_neighbors:
            o = own[nr][nc]
            if owner_candidate is None:
                owner_candidate = o
            elif owner_candidate != o:
                valid = False
                break

        if not valid:
            return None

        # Check size
        count = 0
        for rr in range(R):
            for cc in range(C):
                if own[rr][cc] == owner_candidate:
                    count += 1
        if count + 1 > numbers[owner_candidate]:
            return None

        g_w = [row[:] for row in g]
        own_w = [row[:] for row in own]
        g_w[r][c] = 1
        own_w[r][c] = owner_candidate

        res = solve_recursive(g_w, own_w)
        if res: return res

        return None

    res = solve_recursive(grid, owners)
    if res:
        out = []
        for r in range(R):
            row_out = []
            for c in range(C):
                if res[r][c] == 2:
                    row_out.append('B')
                else:
                    row_out.append(None)
            out.append(row_out)
        return out
    return "No Solution"

