import sys
import copy

# Increase recursion depth just in case
sys.setrecursionlimit(5000)

# Constants
UNKNOWN = 0
LINE = 1
NO_LINE = -1

OBSERVATION = {'data': [
    [None, 3, 2, None, None, None, 2, 2, 3, None],
    [None, None, None, None, None, None, 3, None, 3, None],
    [None, 3, 2, None, 3, 2, None, None, 2, None],
    [3, 2, 0, 2, None, None, None, None, None, 3],
    [2, None, 3, 2, 1, 3, None, None, None, 2],
    [3, 2, 2, None, None, None, 2, 1, 3, None],
    [1, 2, None, 2, None, None, 2, None, None, 2],
    [2, 2, 3, 1, 2, None, None, 2, 1, 3],
    [2, None, None, None, 2, 2, None, None, 1, 2],
    [None, 2, None, None, 1, None, None, None, None, 3]
]}

def solve(observation):
    clues = observation['data']
    if not clues:
        return []

    rows = len(clues)
    cols = len(clues[0])

    # h[r][c] for r in 0..rows, c in 0..cols-1
    # v[r][c] for r in 0..rows-1, c in 0..cols
    h = [[UNKNOWN] * cols for _ in range(rows + 1)]
    v = [[UNKNOWN] * (cols + 1) for _ in range(rows)]

    # Propagate initial constraints
    if not propagate(h, v, clues):
        return "No Solution"

    # Check if solved
    if is_solved(h, v):
        if is_valid(h, v, clues):
            return format_solution(h, v)
        else:
            return "No Solution"

    # Backtrack
    result = backtrack(h, v, clues)
    if result:
        return result
    return "No Solution"

def propagate(h, v, clues):
    rows = len(clues)
    cols = len(clues[0])
    changed = True
    while changed:
        changed = False

        # Cell constraints
        for r in range(rows):
            for c in range(cols):
                k = clues[r][c]
                if k is None: continue

                # Edges: Top h[r][c], Bottom h[r+1][c], Left v[r][c], Right v[r][c+1]
                edges = [
                    ('h', r, c),
                    ('h', r+1, c),
                    ('v', r, c),
                    ('v', r, c+1)
                ]

                lines = 0
                unknowns = 0
                unknown_list = []

                for typ, er, ec in edges:
                    val = h[er][ec] if typ == 'h' else v[er][ec]
                    if val == LINE:
                        lines += 1
                    elif val == UNKNOWN:
                        unknowns += 1
                        unknown_list.append((typ, er, ec))

                if lines > k: return False
                if lines + unknowns < k: return False

                if lines == k:
                    for typ, er, ec in unknown_list:
                        if typ == 'h':
                            if h[er][ec] == LINE: return False
                            if h[er][ec] == UNKNOWN:
                                h[er][ec] = NO_LINE
                                changed = True
                        else:
                            if v[er][ec] == LINE: return False
                            if v[er][ec] == UNKNOWN:
                                v[er][ec] = NO_LINE
                                changed = True
                elif lines + unknowns == k:
                    for typ, er, ec in unknown_list:
                        if typ == 'h':
                            if h[er][ec] == NO_LINE: return False
                            if h[er][ec] == UNKNOWN:
                                h[er][ec] = LINE
                                changed = True
                        else:
                            if v[er][ec] == NO_LINE: return False
                            if v[er][ec] == UNKNOWN:
                                v[er][ec] = LINE
                                changed = True

        # Vertex constraints
        # Vertices (r, c) for r in 0..rows, c in 0..cols
        for r in range(rows + 1):
            for c in range(cols + 1):
                incident = []
                # Top: h[r-1][c]
                if r > 0 and c < cols: incident.append(('h', r-1, c))
                # Bottom: h[r][c]
                if r < rows + 1 and c < cols: incident.append(('h', r, c))
                # Left: v[r][c-1]
                if r < rows and c > 0: incident.append(('v', r, c-1))
                # Right: v[r][c]
                if r < rows and c < cols + 1: incident.append(('v', r, c))

                lines = 0
                x_edges = 0
                unknown_list = []

                for typ, er, ec in incident:
                    val = h[er][ec] if typ == 'h' else v[er][ec]
                    if val == LINE:
                        lines += 1
                    elif val == NO_LINE:
                        x_edges += 1
                    else:
                        unknown_list.append((typ, er, ec))

                if lines > 2: return False

                if lines == 2:
                    for typ, er, ec in unknown_list:
                        if typ == 'h':
                            if h[er][ec] == LINE: return False
                            if h[er][ec] == UNKNOWN:
                                h[er][ec] = NO_LINE
                                changed = True
                        else:
                            if v[er][ec] == LINE: return False
                            if v[er][ec] == UNKNOWN:
                                v[er][ec] = NO_LINE
                                changed = True
                elif x_edges == 3 and len(unknown_list) == 1:
                    # Must be NO_LINE to keep degree 0
                    typ, er, ec = unknown_list[0]
                    if typ == 'h':
                        if h[er][ec] == LINE: return False
                        if h[er][ec] == UNKNOWN:
                            h[er][ec] = NO_LINE
                            changed = True
                    else:
                        if v[er][ec] == LINE: return False
                        if v[er][ec] == UNKNOWN:
                            v[er][ec] = NO_LINE
                            changed = True
                elif lines == 1 and x_edges == 2 and len(unknown_list) == 1:
                    # Must be LINE to make degree 2
                    typ, er, ec = unknown_list[0]
                    if typ == 'h':
                        if h[er][ec] == NO_LINE: return False
                        if h[er][ec] == UNKNOWN:
                            h[er][ec] = LINE
                            changed = True
                    else:
                        if v[er][ec] == NO_LINE: return False
                        if v[er][ec] == UNKNOWN:
                            v[er][ec] = LINE
                            changed = True

    return True

def is_solved(h, v):
    for row in h:
        if UNKNOWN in row: return False
    for row in v:
        if UNKNOWN in row: return False
    return True

def is_valid(h, v, clues):
    rows = len(clues)
    cols = len(clues[0])

    # Check clues
    for r in range(rows):
        for c in range(cols):
            k = clues[r][c]
            if k is None: continue
            count = 0
            if h[r][c] == LINE: count += 1
            if h[r+1][c] == LINE: count += 1
            if v[r][c] == LINE: count += 1
            if v[r][c+1] == LINE: count += 1
            if count != k: return False

    # Check vertex degrees
    for r in range(rows + 1):
        for c in range(cols + 1):
            deg = 0
            if r > 0 and c < cols and h[r-1][c] == LINE: deg += 1
            if r < rows + 1 and c < cols and h[r][c] == LINE: deg += 1
            if r < rows and c > 0 and v[r][c-1] == LINE: deg += 1
            if r < rows and c < cols + 1 and v[r][c] == LINE: deg += 1

            if deg != 0 and deg != 2: return False

    # Check single loop
    start = None
    for r in range(len(h)):
        for c in range(len(h[0])):
            if h[r][c] == LINE:
                start = ('h', r, c)
                break
        if start: break
    if not start:
        for r in range(len(v)):
            for c in range(len(v[0])):
                if v[r][c] == LINE:
                    start = ('v', r, c)
                    break
            if start: break

    if not start:
        for row in clues:
            for k in row:
                if k is not None and k > 0: return False
        return True

    total_lines = 0
    for row in h:
        for val in row:
            if val == LINE: total_lines += 1
    for row in v:
        for val in row:
            if val == LINE: total_lines += 1

    if total_lines == 0: return True

    visited_edges = set([start])
    typ, r, c = start
    if typ == 'h':
        curr = (r, c+1)
    else:
        curr = (r+1, c)

    start_node = (r, c)

    while curr != start_node:
        cr, cc = curr
        incident = []
        if cr > 0 and cc < cols and h[cr-1][cc] == LINE: incident.append(('h', cr-1, cc))
        if cr < rows + 1 and cc < cols and h[cr][cc] == LINE: incident.append(('h', cr, cc))
        if cr < rows and cc > 0 and v[cr][cc-1] == LINE: incident.append(('v', cr, cc-1))
        if cr < rows and cc < cols + 1 and v[cr][cc] == LINE: incident.append(('v', cr, cc))

        unvisited = [e for e in incident if e not in visited_edges]
        if len(unvisited) != 1: return False

        next_e = unvisited[0]
        visited_edges.add(next_e)

        typ, r, c = next_e
        if typ == 'h':
            if curr == (r, c): curr = (r, c+1)
            else: curr = (r, c)
        else:
            if curr == (r, c): curr = (r+1, c)
            else: curr = (r, c)

    return len(visited_edges) == total_lines

def format_solution(h, v):
    rows = len(h) - 1
    cols = len(h[0])

    start = None
    for r in range(len(h)):
        for c in range(len(h[0])):
            if h[r][c] == LINE:
                start = ('h', r, c)
                break
        if start: break
    if not start:
        for r in range(len(v)):
            for c in range(len(v[0])):
                if v[r][c] == LINE:
                    start = ('v', r, c)
                    break
            if start: break

    if not start:
        return []

    path = []
    typ, r, c = start
    path.append((r, c))

    if typ == 'h':
        curr = (r, c+1)
    else:
        curr = (r+1, c)

    visited_edges = set([start])

    while curr != path[0]:
        path.append(curr)
        cr, cc = curr

        incident = []
        if cr > 0 and cc < cols and h[cr-1][cc] == LINE: incident.append(('h', cr-1, cc))
        if cr < rows + 1 and cc < cols and h[cr][cc] == LINE: incident.append(('h', cr, cc))
        if cr < rows and cc > 0 and v[cr][cc-1] == LINE: incident.append(('v', cr, cc-1))
        if cr < rows and cc < cols + 1 and v[cr][cc] == LINE: incident.append(('v', cr, cc))

        next_e = None
        for e in incident:
            if e not in visited_edges:
                next_e = e
                break

        if not next_e:
            break

        visited_edges.add(next_e)
        typ, r, c = next_e
        if typ == 'h':
            if curr == (r, c): curr = (r, c+1)
            else: curr = (r, c)
        else:
            if curr == (r, c): curr = (r+1, c)
            else: curr = (r, c)

    path.append(path[0])
    return path

def backtrack(h, v, clues):
    for r in range(len(h)):
        for c in range(len(h[0])):
            if h[r][c] == UNKNOWN:
                h1 = copy.deepcopy(h)
                v1 = copy.deepcopy(v)
                h1[r][c] = LINE
                if propagate(h1, v1, clues):
                    res = backtrack(h1, v1, clues)
                    if res: return res

                h2 = copy.deepcopy(h)
                v2 = copy.deepcopy(v)
                h2[r][c] = NO_LINE
                if propagate(h2, v2, clues):
                    res = backtrack(h2, v2, clues)
                    if res: return res
                return None

    for r in range(len(v)):
        for c in range(len(v[0])):
            if v[r][c] == UNKNOWN:
                h1 = copy.deepcopy(h)
                v1 = copy.deepcopy(v)
                v1[r][c] = LINE
                if propagate(h1, v1, clues):
                    res = backtrack(h1, v1, clues)
                    if res: return res

                h2 = copy.deepcopy(h)
                v2 = copy.deepcopy(v)
                v2[r][c] = NO_LINE
                if propagate(h2, v2, clues):
                    res = backtrack(h2, v2, clues)
                    if res: return res
                return None

    if is_valid(h, v, clues):
        return format_solution(h, v)
    return None

