OBSERVATION = {'data': [[2, None, None, None, None, None, 2], [None, None, None, None, None, None, None], [None, 1, None, None, None, None, 2], [None, None, None, None, None, None, None], [5, None, None, None, None, None, 3], [None, None, None, None, None, None, None], [4, None, None, None, 3, None, 2]]}

import sys

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])

    islands = []
    island_map = {} 

    # Parse islands
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is not None:
                idx = len(islands)
                islands.append({
                    'r': r, 
                    'c': c, 
                    'val': grid[r][c], 
                    'current': 0,
                    'id': idx
                })
                island_map[(r, c)] = idx

    # Identify possible edges (bridges) between islands
    possible_edges = []
    edge_map = {} 

    # Horizontal connections
    for r in range(rows):
        last_island_idx = None
        for c in range(cols):
            if (r, c) in island_map:
                idx = island_map[(r, c)]
                if last_island_idx is not None:
                    u, v = sorted((last_island_idx, idx))
                    if (u, v) not in edge_map:
                        edge_map[(u, v)] = len(possible_edges)
                        possible_edges.append((u, v))
                last_island_idx = idx

    # Vertical connections
    for c in range(cols):
        last_island_idx = None
        for r in range(rows):
            if (r, c) in island_map:
                idx = island_map[(r, c)]
                if last_island_idx is not None:
                    u, v = sorted((last_island_idx, idx))
                    if (u, v) not in edge_map:
                        edge_map[(u, v)] = len(possible_edges)
                        possible_edges.append((u, v))
                last_island_idx = idx

    # State: number of bridges on each edge (0, 1, or 2)
    bridge_counts = [0] * len(possible_edges)

    # Adjacency list for islands: island_idx -> list of (edge_idx, neighbor_island_idx)
    island_adj = [[] for _ in range(len(islands))]
    for i, (u, v) in enumerate(possible_edges):
        island_adj[u].append((i, v))
        island_adj[v].append((i, u))

    # Check if all islands are connected
    def is_connected():
        if not islands: return True
        visited = set()
        stack = [0]
        visited.add(0)
        while stack:
            u = stack.pop()
            for edge_idx, v in island_adj[u]:
                if bridge_counts[edge_idx] > 0 and v not in visited:
                    visited.add(v)
                    stack.append(v)
        return len(visited) == len(islands)

    # Constraint propagation
    def propagate():
        changed = True
        while changed:
            changed = False
            for i in range(len(islands)):
                island = islands[i]
                needed = island['val'] - island['current']

                if needed < 0: return False # Contradiction

                available_edges = []
                max_possible_sum = 0

                for edge_idx, neighbor_idx in island_adj[i]:
                    count = bridge_counts[edge_idx]
                    if count < 2:
                        neighbor_needed = islands[neighbor_idx]['val'] - islands[neighbor_idx]['current']
                        can_add = min(2 - count, neighbor_needed)
                        if can_add > 0:
                            available_edges.append((edge_idx, can_add))
                            max_possible_sum += can_add

                # If needed bridges exceed max possible, contradiction
                if needed > max_possible_sum:
                    return False

                # Rule 1: If needed equals sum of max capacities, fill all available edges to capacity
                if needed == max_possible_sum and needed > 0:
                    for edge_idx, cap in available_edges:
                        add_val = cap 
                        bridge_counts[edge_idx] += add_val
                        u, v = possible_edges[edge_idx]
                        if u == i:
                            islands[u]['current'] += add_val
                            islands[v]['current'] += add_val
                        else:
                            islands[v]['current'] += add_val
                            islands[u]['current'] += add_val
                        changed = True

                # Rule 2: If only 1 option available and needed > 0, take exactly what is needed
                elif len(available_edges) == 1 and needed > 0:
                    edge_idx, cap = available_edges[0]
                    add_val = needed
                    bridge_counts[edge_idx] += add_val
                    u, v = possible_edges[edge_idx]
                    if u == i:
                        islands[u]['current'] += add_val
                        islands[v]['current'] += add_val
                    else:
                        islands[v]['current'] += add_val
                        islands[u]['current'] += add_val
                    changed = True

        return True

    # Recursive backtracking search
    def solve_recursive():
        # Apply constraints
        if not propagate():
            return False

        # Check if solved
        if all(isl['current'] == isl['val'] for isl in islands):
            return is_connected()

        # Save state for backtracking
        saved_counts = list(bridge_counts)
        saved_currents = [isl['current'] for isl in islands]

        # Heuristic: Pick edge connected to island with highest remaining need
        best_edge = None
        max_need = -1

        for i in range(len(possible_edges)):
            u, v = possible_edges[i]
            if bridge_counts[i] < 2:
                need_u = islands[u]['val'] - islands[u]['current']
                need_v = islands[v]['val'] - islands[v]['current']
                if need_u > 0 and need_v > 0:
                    if max(need_u, need_v) > max_need:
                        max_need = max(need_u, need_v)
                        best_edge = i

        # If no valid moves but not solved, backtrack
        if best_edge is None:
            return False

        u, v = possible_edges[best_edge]
        current_val = bridge_counts[best_edge]
        max_add = min(2 - current_val, 
                      islands[u]['val'] - islands[u]['current'], 
                      islands[v]['val'] - islands[v]['current'])

        # Try adding bridges (1 to max_add)
        for add in range(1, max_add + 1):
            bridge_counts[best_edge] = current_val + add
            islands[u]['current'] += add
            islands[v]['current'] += add

            if solve_recursive():
                return True

            # Restore state
            for k in range(len(bridge_counts)): bridge_counts[k] = saved_counts[k]
            for k in range(len(islands)): islands[k]['current'] = saved_currents[k]

        return False

    if solve_recursive():
        result = {}
        for i, (u, v) in enumerate(possible_edges):
            if bridge_counts[i] > 0:
                r1, c1 = islands[u]['r'], islands[u]['c']
                r2, c2 = islands[v]['r'], islands[v]['c']
                # Ensure consistent key ordering
                key = ((r1, c1), (r2, c2))
                if (r1, c1) > (r2, c2):
                    key = ((r2, c2), (r1, c1))
                result[key] = bridge_counts[i]
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
