OBSERVATION = {'data': [[None, None, None, None, None, None, None, None, 3, None], [3, None, 2, 2, None, None, None, None, 1, None], [None, None, 2, 3, 2, 0, None, None, 3, 2], [None, None, 1, None, None, 1, None, None, 2, 3], [1, None, None, 3, 3, 3, None, 3, 2, None], [None, 3, None, 2, None, None, None, 2, 2, None], [None, 1, None, 2, None, None, None, 1, 1, 2], [3, None, 2, None, None, None, None, 2, None, None], [None, None, 2, 3, None, None, 2, 1, None, None], [3, None, 2, 3, None, 1, 2, None, 3, None]]}

import sys

# Increase recursion depth to handle deep backtracking if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    H = len(data)
    W = len(data[0])

    # Edges: 
    # h_edges[r][c] is horizontal edge at row r, between col c and c+1. r in 0..H, c in 0..W-1
    # v_edges[r][c] is vertical edge at col c, between row r and r+1. r in 0..H-1, c in 0..W
    # State: 0 (False/X), 1 (True/O), -1 (Unknown)

    h_edges = [[-1] * W for _ in range(H + 1)]
    v_edges = [[-1] * (W + 1) for _ in range(H)]

    def get_edge_val(type, r, c):
        if type == 'h':
            return h_edges[r][c]
        return v_edges[r][c]

    def set_edge(type, r, c, val):
        if type == 'h':
            if h_edges[r][c] != -1 and h_edges[r][c] != val:
                return False # Contradiction
            h_edges[r][c] = val
        else:
            if v_edges[r][c] != -1 and v_edges[r][c] != val:
                return False
            v_edges[r][c] = val
        return True

    def get_cell_edges(r, c):
        # Top (h, r, c), Bottom (h, r+1, c), Left (v, r, c), Right (v, r, c+1)
        return [
            ('h', r, c),
            ('h', r + 1, c),
            ('v', r, c),
            ('v', r, c + 1)
        ]

    def get_vertex_edges(r, c):
        edges = []
        # Top (v, r-1, c)
        if r > 0: edges.append(('v', r - 1, c))
        # Bottom (v, r, c)
        if r < H: edges.append(('v', r, c))
        # Left (h, r, c-1)
        if c > 0: edges.append(('h', r, c - 1))
        # Right (h, r, c)
        if c < W: edges.append(('h', r, c))
        return edges

    def count_unknowns():
        count = 0
        for r in range(H + 1):
            for c in range(W):
                if h_edges[r][c] == -1: count += 1
        for r in range(H):
            for c in range(W + 1):
                if v_edges[r][c] == -1: count += 1
        return count

    # DSU for connectivity
    parent = list(range((H + 1) * (W + 1)))
    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    def reset_dsu():
        nonlocal parent
        parent = list(range((H + 1) * (W + 1)))
        for r in range(H + 1):
            for c in range(W):
                if h_edges[r][c] == 1:
                    u = r * (W + 1) + c
                    v = r * (W + 1) + (c + 1)
                    union(u, v)
        for r in range(H):
            for c in range(W + 1):
                if v_edges[r][c] == 1:
                    u = r * (W + 1) + c
                    v = (r + 1) * (W + 1) + c
                    union(u, v)

    def propagate():
        changed = True
        while changed:
            changed = False

            # 1. Clue Constraints
            for r in range(H):
                for c in range(W):
                    clue = data[r][c]
                    if clue is None: continue

                    edges = get_cell_edges(r, c)
                    t_count = 0
                    u_edges = []

                    for etype, er, ec in edges:
                        val = get_edge_val(etype, er, ec)
                        if val == 1: t_count += 1
                        elif val == -1: u_edges.append((etype, er, ec))

                    if t_count > clue: return False 
                    if t_count + len(u_edges) < clue: return False 

                    if t_count == clue:
                        for etype, er, ec in u_edges:
                            if not set_edge(etype, er, ec, 0): return False
                            changed = True
                    elif t_count + len(u_edges) == clue:
                        for etype, er, ec in u_edges:
                            if not set_edge(etype, er, ec, 1): return False
                            changed = True

            # 2. Vertex Constraints (Degree 0 or 2)
            for r in range(H + 1):
                for c in range(W + 1):
                    edges = get_vertex_edges(r, c)
                    t_count = 0
                    u_count = 0
                    u_edges = []

                    for etype, er, ec in edges:
                        val = get_edge_val(etype, er, ec)
                        if val == 1: t_count += 1
                        elif val == -1: 
                            u_count += 1
                            u_edges.append((etype, er, ec))

                    # Rule 1: Degree > 2 is invalid
                    if t_count > 2: return False

                    # Rule 2: If degree is already 2, all unknowns must be False
                    if t_count == 2:
                        for etype, er, ec in u_edges:
                            if not set_edge(etype, er, ec, 0): return False
                            changed = True

                    # Rule 3: If max possible degree < 2, then degree must be 0.
                    # So if t_count > 0, invalid. Else all u must be False.
                    if t_count + u_count < 2:
                        if t_count > 0: return False
                        for etype, er, ec in u_edges:
                            if not set_edge(etype, er, ec, 0): return False
                            changed = True

                    # Rule 4: If t_count == 1 and u_count == 1, the unknown must be True.
                    # Because if it were False, degree would be 1 (invalid).
                    if t_count == 1 and u_count == 1:
                        etype, er, ec = u_edges[0]
                        if not set_edge(etype, er, ec, 1): return False
                        changed = True

            # 3. Connectivity / Sub-loop prevention
            reset_dsu()
            has_cycle = False

            # Check horizontal edges
            for r in range(H + 1):
                for c in range(W):
                    if h_edges[r][c] == 1:
                        u = r * (W + 1) + c
                        v = r * (W + 1) + (c + 1)
                        if find(u) == find(v):
                            has_cycle = True
                        else:
                            union(u, v)
            # Check vertical edges
            for r in range(H):
                for c in range(W + 1):
                    if v_edges[r][c] == 1:
                        u = r * (W + 1) + c
                        v = (r + 1) * (W + 1) + c
                        if find(u) == find(v):
                            has_cycle = True
                        else:
                            union(u, v)

            if has_cycle:
                u_count = count_unknowns()
                if u_count > 0:
                    return False # Sub-loop detected while edges are still unknown

                # If no unknowns, check if it's a single loop
                # Count True edges
                true_edges_count = 0
                for r in range(H + 1):
                    for c in range(W):
                        if h_edges[r][c] == 1: true_edges_count += 1
                for r in range(H):
                    for c in range(W + 1):
                        if v_edges[r][c] == 1: true_edges_count += 1

                # Check connectivity of all True edges
                reset_dsu()
                for r in range(H + 1):
                    for c in range(W):
                        if h_edges[r][c] == 1:
                            union(r * (W + 1) + c, r * (W + 1) + c + 1)
                for r in range(H):
                    for c in range(W + 1):
                        if v_edges[r][c] == 1:
                            union(r * (W + 1) + c, (r + 1) * (W + 1) + c)

                # Find a root of a True edge
                first_root = -1
                valid_loop = True
                found_any = False

                for r in range(H + 1):
                    for c in range(W):
                        if h_edges[r][c] == 1:
                            found_any = True
                            root = find(r * (W + 1) + c)
                            if first_root == -1:
                                first_root = root
                            elif root != first_root:
                                valid_loop = False
                                break
                    if not valid_loop: break

                if valid_loop and found_any:
                    for r in range(H):
                        for c in range(W + 1):
                            if v_edges[r][c] == 1:
                                root = find(r * (W + 1) + c)
                                if first_root == -1:
                                    first_root = root
                                elif root != first_root:
                                    valid_loop = False
                                    break
                        if not valid_loop: break

                if not valid_loop:
                    return False

        return True

    def solve_recursive():
        if not propagate():
            return False

        if count_unknowns() == 0:
            return True

        # Pick an unknown edge
        next_type, next_r, next_c = None, None, None
        found = False

        # Heuristic: Try to pick edges near clues or with fewer options?
        # For simplicity, pick first unknown.
        for r in range(H + 1):
            for c in range(W):
                if h_edges[r][c] == -1:
                    next_type, next_r, next_c = 'h', r, c
                    found = True
                    break
            if found: break

        if not found:
            for r in range(H):
                for c in range(W + 1):
                    if v_edges[r][c] == -1:
                        next_type, next_r, next_c = 'v', r, c
                        found = True
                        break
                if found: break

        if not found:
            return True 

        # Save state
        h_snapshot = [row[:] for row in h_edges]
        v_snapshot = [row[:] for row in v_edges]

        # Try True
        if set_edge(next_type, next_r, next_c, 1):
            if solve_recursive():
                return True

        # Restore
        for r in range(H + 1):
            h_edges[r] = h_snapshot[r][:]
        for r in range(H):
            v_edges[r] = v_snapshot[r][:]

        # Try False
        if set_edge(next_type, next_r, next_c, 0):
            if solve_recursive():
                return True

        # Restore
        for r in range(H + 1):
            h_edges[r] = h_snapshot[r][:]
        for r in range(H):
            v_edges[r] = v_snapshot[r][:]

        return False

    if solve_recursive():
        # Construct output path
        start_r, start_c = -1, -1
        for r in range(H + 1):
            for c in range(W + 1):
                deg = 0
                if r > 0 and v_edges[r-1][c] == 1: deg += 1
                if r < H and v_edges[r][c] == 1: deg += 1
                if c > 0 and h_edges[r][c-1] == 1: deg += 1
                if c < W and h_edges[r][c] == 1: deg += 1
                if deg == 2:
                    start_r, start_c = r, c
                    break
            if start_r != -1: break

        if start_r == -1:
            return "No Solution"

        path = [(start_r, start_c)]
        curr_r, curr_c = start_r, start_c
        prev_r, prev_c = -1, -1

        # Trace loop
        # Max steps to prevent infinite loop in case of error
        max_steps = (H + 1) * (W + 1) * 2
        steps = 0

        while steps < max_steps:
            steps += 1
            neighbors = []
            if curr_r > 0 and v_edges[curr_r-1][curr_c] == 1:
                neighbors.append((curr_r - 1, curr_c))
            if curr_r < H and v_edges[curr_r][curr_c] == 1:
                neighbors.append((curr_r + 1, curr_c))
            if curr_c > 0 and h_edges[curr_r][curr_c-1] == 1:
                neighbors.append((curr_r, curr_c - 1))
            if curr_c < W and h_edges[curr_r][curr_c] == 1:
                neighbors.append((curr_r, curr_c + 1))

            next_node = None
            for nr, nc in neighbors:
                if nr != prev_r or nc != prev_c:
                    next_node = (nr, nc)
                    break

            if next_node is None:
                break 

            prev_r, prev_c = curr_r, curr_c
            curr_r, curr_c = next_node
            path.append((curr_r, curr_c))

            if curr_r == start_r and curr_c == start_c:
                break

        return path
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
