OBSERVATION = {'region': [[0, 1, 1, 1, 1, 1], [0, 1, 1, 1, 2, 2], [3, 3, 4, 2, 2, 2], [3, 4, 4, 4, 4, 5], [3, 4, 3, 3, 3, 5], [3, 3, 3, 3, 5, 5]], 'row_water_counts': [1, 4, 4, 5, 5, 4], 'col_water_counts': [5, 4, 5, 5, 3, 1]}

def solve(observation):
    region_grid = observation['region']
    row_clues = observation['row_water_counts']
    col_clues = observation['col_water_counts']

    rows = len(region_grid)
    cols = len(region_grid[0])

    # Identify regions and their cells
    regions = {}
    for r in range(rows):
        for c in range(cols):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_ids = sorted(regions.keys())
    num_regions = len(region_ids)

    # Precompute contributions for each region at each water level
    # Level h means cells with row index >= h are water.
    # Level = rows means empty (no cells have row >= rows).
    max_level = rows

    # contributions[rid][level] = (row_counts_list, col_counts_list)
    contributions = {}

    for rid in region_ids:
        cells = regions[rid]
        contributions[rid] = {}
        for level in range(max_level + 1):
            r_counts = [0] * rows
            c_counts = [0] * cols
            for (r, c) in cells:
                if r >= level:
                    r_counts[r] += 1
                    c_counts[c] += 1
            contributions[rid][level] = (r_counts, c_counts)

    # Backtracking solver
    current_row_counts = [0] * rows
    current_col_counts = [0] * cols
    solution_levels = {}

    # Sort region IDs to process larger regions first (heuristic for pruning)
    # Actually, just processing in order is fine for N=6.

    def backtrack(idx):
        if idx == num_regions:
            # Check if exact match
            if current_row_counts == row_clues and current_col_counts == col_clues:
                return True
            return False

        rid = region_ids[idx]

        # Try all possible water levels for this region
        for level in range(max_level + 1):
            r_add, c_add = contributions[rid][level]

            # Pruning: Check if adding this region's contribution exceeds clues
            valid = True
            for r in range(rows):
                if current_row_counts[r] + r_add[r] > row_clues[r]:
                    valid = False
                    break
            if not valid: continue

            for c in range(cols):
                if current_col_counts[c] + c_add[c] > col_clues[c]:
                    valid = False
                    break
            if not valid: continue

            # Apply contribution
            for r in range(rows): current_row_counts[r] += r_add[r]
            for c in range(cols): current_col_counts[c] += c_add[c]
            solution_levels[rid] = level

            if backtrack(idx + 1):
                return True

            # Undo contribution
            for r in range(rows): current_row_counts[r] -= r_add[r]
            for c in range(cols): current_col_counts[c] -= c_add[c]
            del solution_levels[rid]

        return False

    if backtrack(0):
        # Construct the final grid
        result_grid = [[None for _ in range(cols)] for _ in range(rows)]
        for rid, level in solution_levels.items():
            for (r, c) in regions[rid]:
                if r >= level:
                    result_grid[r][c] = 'W'
        return result_grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
