import sys
import copy

# Increase recursion depth to handle deep backtracking if necessary
sys.setrecursionlimit(20000)

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], ['W', None, None, 'W', None, None, 'B', 'W'], ['W', None, None, 'W', None, None, 'W', 'W'], [None, None, None, 'W', 'B', 'W', None, None], [None, None, 'W', None, 'W', None, 'W', None], [None, None, 'W', None, None, None, None, None], [None, None, 'W', None, 'W', None, 'W', None], ['B', 'W', None, None, None, 'W', None, None]]}

class MasyuSolver:
    def __init__(self, grid):
        self.grid = grid
        self.N = len(grid)
        # Edge status: 0=Unknown, 1=Present, -1=Absent
        # Directions: 0:Up, 1:Right, 2:Down, 3:Left
        self.edges = [[[0]*4 for _ in range(self.N)] for _ in range(self.N)]
        self.parent = list(range(self.N * self.N))
        self.queue = []

    def _idx(self, r, c):
        return r * self.N + c

    def _find(self, i):
        path = []
        while self.parent[i] != i:
            path.append(i)
            i = self.parent[i]
        for node in path:
            self.parent[node] = i
        return i

    def _union(self, i, j):
        root_i, root_j = self._find(i), self._find(j)
        if root_i != root_j:
            self.parent[root_i] = root_j
            return True
        return False

    def _get_neighbor(self, r, c, d):
        if d == 0: return (r-1, c)
        if d == 1: return (r, c+1)
        if d == 2: return (r+1, c)
        if d == 3: return (r, c-1)
        return None

    def _opposite(self, d):
        return (d + 2) % 4

    def _set_edge(self, r, c, d, val):
        nr, nc = self._get_neighbor(r, c, d)
        # Check bounds
        if nr < 0 or nr >= self.N or nc < 0 or nc >= self.N:
            return val != 1 # If val is 1, contradiction (edge out of bounds). If -1, ok.

        # Check consistency
        if self.edges[r][c][d] != 0 and self.edges[r][c][d] != val:
            return False

        if self.edges[r][c][d] == val:
            return True

        self.edges[r][c][d] = val
        od = self._opposite(d)
        self.edges[nr][nc][od] = val

        self.queue.append((r, c))
        self.queue.append((nr, nc))

        if val == 1:
            u, v = self._idx(r, c), self._idx(nr, nc)
            if not self._union(u, v):
                # Cycle detected. Check validity immediately.
                if not self._check_cycle_validity(r, c):
                    return False
        return True

    def _check_cycle_validity(self, r, c):
        # A cycle was just formed involving (r,c).
        # Check if it's the final valid solution loop.
        root = self._find(self._idx(r, c))

        # 1. All circles must be in this component and have degree 2.
        for r_c in range(self.N):
            for c_c in range(self.N):
                if self.grid[r_c][c_c] is not None:
                    if self._find(self._idx(r_c, c_c)) != root:
                        return False
                    deg = 0
                    for d in range(4):
                        if self.edges[r_c][c_c][d] == 1:
                            deg += 1
                    if deg != 2:
                        return False

        # 2. No other active edges outside this component.
        for r_c in range(self.N):
            for c_c in range(self.N):
                for d in range(4):
                    if self.edges[r_c][c_c][d] == 1:
                        if self._find(self._idx(r_c, c_c)) != root:
                            return False
        return True

    def _propagate(self):
        while self.queue:
            r, c = self.queue.pop(0)

            # Degree check
            deg = 0
            unknown_dirs = []
            for d in range(4):
                if self.edges[r][c][d] == 1:
                    deg += 1
                elif self.edges[r][c][d] == 0:
                    unknown_dirs.append(d)

            if deg > 2:
                return False

            if deg == 2:
                for d in unknown_dirs:
                    if not self._set_edge(r, c, d, -1):
                        return False

            cell = self.grid[r][c]

            if cell == 'W':
                # White circle: Must go straight through.
                present_dirs = [d for d in range(4) if self.edges[r][c][d] == 1]
                if len(present_dirs) == 1:
                    d1 = present_dirs[0]
                    d2 = self._opposite(d1)
                    if self.edges[r][c][d2] == -1: return False
                    if self.edges[r][c][d2] == 0:
                        if not self._set_edge(r, c, d2, 1): return False
                elif len(present_dirs) == 2:
                    if present_dirs[0] != self._opposite(present_dirs[1]):
                        return False # Not straight

            elif cell == 'B':
                # Black circle: Must turn.
                present_dirs = [d for d in range(4) if self.edges[r][c][d] == 1]
                if len(present_dirs) == 1:
                    d1 = present_dirs[0]
                    # Opposite must be absent (cannot go straight)
                    if not self._set_edge(r, c, self._opposite(d1), -1): return False
                elif len(present_dirs) == 2:
                    if present_dirs[0] == self._opposite(present_dirs[1]):
                        return False # Cannot go straight

                # "Straight" rule for neighbors:
                # The line must go straight through the cells immediately before and after the black circle.
                for d in range(4):
                    if self.edges[r][c][d] == 1:
                        nr, nc = self._get_neighbor(r, c, d)
                        if 0 <= nr < self.N and 0 <= nc < self.N:
                            # At neighbor (nr, nc), the path must continue in direction d.
                            if self.edges[nr][nc][d] == -1: return False
                            if self.edges[nr][nc][d] == 0:
                                if not self._set_edge(nr, nc, d, 1): return False

                            # Perpendicular edges at neighbor must be absent (cannot turn)
                            p1, p2 = (d+1)%4, (d+3)%4
                            if not self._set_edge(nr, nc, p1, -1): return False
                            if not self._set_edge(nr, nc, p2, -1): return False

        return True

    def _check_white_turn_rule(self):
        # White circle rule: Turn at least once in the previous or next step.
        for r in range(self.N):
            for c in range(self.N):
                if self.grid[r][c] == 'W':
                    dirs = [d for d in range(4) if self.edges[r][c][d] == 1]
                    if len(dirs) != 2: continue # Not fully connected yet

                    d1, d2 = dirs[0], dirs[1]

                    # Check neighbor in d1
                    nr1, nc1 = self._get_neighbor(r, c, d1)
                    turn_at_1 = False
                    if 0 <= nr1 < self.N and 0 <= nc1 < self.N:
                        for d in range(4):
                            if d == self._opposite(d1): continue
                            if self.edges[nr1][nc1][d] == 1:
                                if d != d1: # Not continuing straight
                                    turn_at_1 = True
                                break

                    # Check neighbor in d2
                    nr2, nc2 = self._get_neighbor(r, c, d2)
                    turn_at_2 = False
                    if 0 <= nr2 < self.N and 0 <= nc2 < self.N:
                        for d in range(4):
                            if d == self._opposite(d2): continue
                            if self.edges[nr2][nc2][d] == 1:
                                if d != d2:
                                    turn_at_2 = True
                                break

                    if not (turn_at_1 or turn_at_2):
                        return False
        return True

    def _is_solved(self):
        # All circles degree 2
        for r in range(self.N):
            for c in range(self.N):
                if self.grid[r][c] is not None:
                    deg = sum(1 for d in range(4) if self.edges[r][c][d] == 1)
                    if deg != 2:
                        return False

        # Check for degree 1 (dangling ends)
        for r in range(self.N):
            for c in range(self.N):
                deg = sum(1 for d in range(4) if self.edges[r][c][d] == 1)
                if deg == 1:
                    return False

        # Check connectivity of all active edges
        first_node = None
        for r in range(self.N):
            for c in range(self.N):
                if any(self.edges[r][c][d] == 1 for d in range(4)):
                    first_node = (r, c)
                    break
            if first_node: break

        if not first_node:
            return False

        root = self._find(self._idx(*first_node))
        for r in range(self.N):
            for c in range(self.N):
                if any(self.edges[r][c][d] == 1 for d in range(4)):
                    if self._find(self._idx(r, c)) != root:
                        return False

        # Check White circle turn rule
        if not self._check_white_turn_rule():
            return False

        return True

    def _get_path(self):
        start = None
        for r in range(self.N):
            for c in range(self.N):
                if self.grid[r][c] is not None:
                    start = (r, c)
                    break
            if start: break

        if not start: return []

        path = [start]
        curr = start
        prev = None

        # Traverse the loop
        while True:
            r, c = curr
            found_next = False
            for d in range(4):
                if self.edges[r][c][d] == 1:
                    nr, nc = self._get_neighbor(r, c, d)
                    if (nr, nc) != prev:
                        path.append((nr, nc))
                        prev = curr
                        curr = (nr, nc)
                        found_next = True
                        break
            if not found_next or curr == start:
                break
        return path

    def solve(self):
        # Initial boundary deductions
        for r in range(self.N):
            for c in range(self.N):
                if r == 0: self._set_edge(r, c, 0, -1)
                if r == self.N - 1: self._set_edge(r, c, 2, -1)
                if c == 0: self._set_edge(r, c, 3, -1)
                if c == self.N - 1: self._set_edge(r, c, 1, -1)

        if not self._propagate():
            return None

        return self._backtrack()

    def _backtrack(self):
        if not self._propagate():
            return None

        if self._is_solved():
            return self._get_path()

        # Find first unknown edge
        for r in range(self.N):
            for c in range(self.N):
                for d in range(4):
                    if self.edges[r][c][d] == 0:
                        # Save state
                        old_edges = copy.deepcopy(self.edges)
                        old_parent = list(self.parent)
                        old_queue = list(self.queue)

                        # Try Present
                        self._set_edge(r, c, d, 1)
                        res = self._backtrack()
                        if res:
                            return res

                        # Restore
                        self.edges = old_edges
                        self.parent = old_parent
                        self.queue = old_queue

                        # Try Absent
                        self._set_edge(r, c, d, -1)
                        res = self._backtrack()
                        if res:
                            return res

                        # Restore
                        self.edges = old_edges
                        self.parent = old_parent
                        self.queue = old_queue

                        return None # Both branches failed
        return None

def solve(observation):
    solver = MasyuSolver(observation['data'])
    path = solver.solve()
    if path:
        return path
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
