def solve(observation):
    data = observation['data']
    N = len(data)
    # Create a mutable copy of the grid
    grid = [list(row) for row in data]

    # Rule 1 & 4: No 2x2 monochromatic blocks.
    # Propagation: If 3 cells in a 2x2 are same color, the 4th must be opposite.
    def propagate_2x2(g):
        changed = True
        while changed:
            changed = False
            for r in range(N - 1):
                for c in range(N - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    vals = [g[rr][cc] for rr, cc in cells]
                    b_count = vals.count('B')
                    w_count = vals.count('W')
                    none_count = vals.count(None)

                    # Invalid state: 4 same colors
                    if b_count == 4 or w_count == 4:
                        return None 

                    # Propagation: 3 same colors -> 4th must be opposite
                    if b_count == 3 and none_count == 1:
                        for rr, cc in cells:
                            if g[rr][cc] is None:
                                g[rr][cc] = 'W'
                                changed = True
                    elif w_count == 3 and none_count == 1:
                        for rr, cc in cells:
                            if g[rr][cc] is None:
                                g[rr][cc] = 'B'
                                changed = True
        return g

    # Rule 2 & 3: Connectivity pruning.
    # All Black cells must be connected eventually.
    # All White cells must be connected eventually.
    # Pruning condition: 
    # - All current Black cells must be in the same component of the graph (Black U Empty).
    # - All current White cells must be in the same component of the graph (White U Empty).
    # If they are separated by a wall of the opposite color, they can never connect.
    def check_connectivity_pruning(g):
        # Check Black connectivity in (Black + Empty)
        black_cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == 'B':
                    black_cells.append((r, c))

        if len(black_cells) > 1:
            start = black_cells[0]
            visited = set([start])
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        # Can traverse Black or Empty (potential Black)
                        if (nr, nc) not in visited and g[nr][nc] != 'W': 
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            # If any black cell is not reachable via (Black + Empty), it's isolated by White
            for bc in black_cells:
                if bc not in visited:
                    return False

        # Check White connectivity in (White + Empty)
        white_cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == 'W':
                    white_cells.append((r, c))

        if len(white_cells) > 1:
            start = white_cells[0]
            visited = set([start])
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        # Can traverse White or Empty (potential White)
                        if (nr, nc) not in visited and g[nr][nc] != 'B': 
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            for wc in white_cells:
                if wc not in visited:
                    return False

        return True

    # Final validation when grid is full
    def is_valid_final(g):
        # Check 2x2
        for r in range(N - 1):
            for c in range(N - 1):
                cells = [g[r][c], g[r][c+1], g[r+1][c], g[r+1][c+1]]
                if all(x == 'B' for x in cells) or all(x == 'W' for x in cells):
                    return False

        # Check Black connected
        black_cells = [(r, c) for r in range(N) for c in range(N) if g[r][c] == 'B']
        if not black_cells: return False # Must have black cells to avoid 2x2 white everywhere

        start = black_cells[0]
        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and g[nr][nc] == 'B' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        if len(visited) != len(black_cells):
            return False

        # Check White connected
        white_cells = [(r, c) for r in range(N) for c in range(N) if g[r][c] == 'W']
        if not white_cells: return False

        start = white_cells[0]
        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and g[nr][nc] == 'W' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        if len(visited) != len(white_cells):
            return False

        return True

    # Initial propagation
    grid = propagate_2x2(grid)
    if grid is None:
        return "No Solution"

    # List of empty cells to fill
    empty_cells = [(r, c) for r in range(N) for c in range(N) if grid[r][c] is None]

    def backtrack(idx, current_grid):
        # Apply deductive rules (2x2 propagation)
        current_grid = propagate_2x2(current_grid)
        if current_grid is None:
            return None

        # Apply global pruning (connectivity)
        if not check_connectivity_pruning(current_grid):
            return None

        # Find the next empty cell to fill
        next_idx = -1
        for i in range(idx, len(empty_cells)):
            r, c = empty_cells[i]
            if current_grid[r][c] is None:
                next_idx = i
                break

        # If no empty cells left, check validity
        if next_idx == -1:
            if is_valid_final(current_grid):
                return current_grid
            else:
                return None

        r, c = empty_cells[next_idx]

        # Try placing Black
        grid_b = [row[:] for row in current_grid]
        grid_b[r][c] = 'B'
        res = backtrack(next_idx + 1, grid_b)
        if res: return res

        # Try placing White
        grid_w = [row[:] for row in current_grid]
        grid_w[r][c] = 'W'
        res = backtrack(next_idx + 1, grid_w)
        if res: return res

        return None

    result = backtrack(0, grid)
    if result:
        return result
    return "No Solution"

