OBSERVATION = {
    'row_sum': [6, 4, 9, 7, 11],
    'col_sum': [4, 9, 3, 7, 13],
    'row_weights': [1, 2, 3, 4, 5],
    'col_weights': [1, 2, 3, 4, 5]
}

def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    # Extract weights. If not provided, assume 1..N based on standard puzzle rules 
    # and the visual cues (1, 2, 3, 4, 5 headers).
    row_weights = observation.get('row_weights', list(range(1, len(row_targets) + 1)))
    col_weights = observation.get('col_weights', list(range(1, len(col_targets) + 1)))

    R = len(row_targets)
    C = len(col_targets)

    # Precompute valid masks for each row.
    # A mask is an integer where the j-th bit is 1 if cell (r, j) is black.
    # The constraint for a row is: sum(col_weights[j] for j in mask) == row_target[r].
    valid_row_masks = []
    for r in range(R):
        target = row_targets[r]
        masks = []
        # Iterate through all 2^C subsets of columns
        for m in range(1 << C):
            current_sum = 0
            for c in range(C):
                if (m >> c) & 1:
                    current_sum += col_weights[c]
            if current_sum == target:
                masks.append(m)
        valid_row_masks.append(masks)

    # Precompute suffix sums of row weights for pruning.
    # suffix_row_weights[r] is the maximum possible contribution to any column 
    # from rows r, r+1, ..., R-1 (assuming all cells in that column are black).
    suffix_row_weights = [0] * (R + 1)
    for i in range(R - 1, -1, -1):
        suffix_row_weights[i] = suffix_row_weights[i+1] + row_weights[i]

    solution_masks = [None] * R

    def backtrack(r, current_col_sums):
        # Base case: All rows have been assigned a mask.
        if r == R:
            # Verify that column targets are exactly met.
            for c in range(C):
                if current_col_sums[c] != col_targets[c]:
                    return False
            return True

        # Pruning 1: Feasibility check.
        # For each column, check if the current sum plus the maximum possible 
        # remaining sum (from rows r to R-1) is at least the target.
        for c in range(C):
            if current_col_sums[c] + suffix_row_weights[r] < col_targets[c]:
                return False

        # Try each valid mask for the current row.
        for mask in valid_row_masks[r]:
            new_col_sums = list(current_col_sums)
            valid_mask = True

            # Update column sums and check for immediate violation (exceeding target).
            for c in range(C):
                if (mask >> c) & 1:
                    new_col_sums[c] += row_weights[r]
                    if new_col_sums[c] > col_targets[c]:
                        valid_mask = False
                        break

            if not valid_mask:
                continue

            # Pruning 2: Lookahead feasibility.
            # After choosing this mask, check if targets are still reachable 
            # with the remaining rows (r+1 to R-1).
            possible = True
            for c in range(C):
                if new_col_sums[c] + suffix_row_weights[r+1] < col_targets[c]:
                    possible = False
                    break

            if not possible:
                continue

            # Recurse
            solution_masks[r] = mask
            if backtrack(r + 1, new_col_sums):
                return True
            solution_masks[r] = None # Backtrack

        return False

    if backtrack(0, [0] * C):
        # Construct the grid from the solution masks.
        grid = []
        for r in range(R):
            row_cells = []
            mask = solution_masks[r]
            for c in range(C):
                if (mask >> c) & 1:
                    row_cells.append('B')
                else:
                    row_cells.append(None)
            grid.append(row_cells)
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
