import sys
sys.setrecursionlimit(5000)

class HashiSolver:
    def __init__(self, observation):
        self.data = observation['data']
        self.rows = len(self.data)
        self.cols = len(self.data[0])
        self.islands = []
        self.island_map = {}

        for r in range(self.rows):
            for c in range(self.cols):
                val = self.data[r][c]
                if val is not None:
                    self.islands.append((r, c, val))
                    self.island_map[(r, c)] = val

        self.neighbors = { (r, c): [] for (r, c, _) in self.islands }
        self._find_neighbors()

    def _find_neighbors(self):
        for i, (r1, c1, v1) in enumerate(self.islands):
            for j, (r2, c2, v2) in enumerate(self.islands):
                if i >= j: continue
                if r1 == r2:
                    min_c, max_c = min(c1, c2), max(c1, c2)
                    blocked = False
                    for c in range(min_c + 1, max_c):
                        if (r1, c) in self.island_map:
                            blocked = True
                            break
                    if not blocked:
                        self.neighbors[(r1, c1)].append((r2, c2))
                        self.neighbors[(r2, c2)].append((r1, c1))
                elif c1 == c2:
                    min_r, max_r = min(r1, r2), max(r1, r2)
                    blocked = False
                    for r in range(min_r + 1, max_r):
                        if (r, c1) in self.island_map:
                            blocked = True
                            break
                    if not blocked:
                        self.neighbors[(r1, c1)].append((r2, c2))
                        self.neighbors[(r2, c2)].append((r1, c1))

    def solve(self):
        initial_bridges = {}
        for u in self.neighbors:
            for v in self.neighbors[u]:
                key = tuple(sorted([u, v]))
                if key not in initial_bridges:
                    initial_bridges[key] = 0

        result = self._solve_recursive(initial_bridges)
        if result is None:
            return "No Solution"

        output = {}
        for k, v in result.items():
            if v > 0:
                output[k] = v
        return output

    def _get_current_bridges(self, island, bridges):
        count = 0
        for neighbor in self.neighbors[island]:
            key = tuple(sorted([island, neighbor]))
            count += bridges[key]
        return count

    def _propagate(self, bridges):
        changed = True
        while changed:
            changed = False
            for island in self.island_map:
                target = self.island_map[island]
                current = self._get_current_bridges(island, bridges)
                remaining = target - current

                if remaining < 0:
                    return False 

                flexible = []
                for n in self.neighbors[island]:
                    key = tuple(sorted([island, n]))
                    if bridges[key] < 2:
                        flexible.append(n)

                num_flex = len(flexible)

                if remaining == num_flex * 2 and num_flex > 0:
                    for n in flexible:
                        key = tuple(sorted([island, n]))
                        if bridges[key] != 2:
                            bridges[key] = 2
                            changed = True

                if remaining == num_flex and num_flex > 0:
                    for n in flexible:
                        key = tuple(sorted([island, n]))
                        if bridges[key] < 1:
                            bridges[key] = 1
                            changed = True

                if remaining > num_flex * 2:
                    return False
        return True

    def _is_connected(self, bridges):
        if not self.islands: return True
        start = self.islands[0][:2]
        visited = set([start])
        stack = [start]

        adj = { (r, c): [] for (r, c, _) in self.islands }
        for (u, v), count in bridges.items():
            if count > 0:
                adj[u].append(v)
                adj[v].append(u)

        while stack:
            curr = stack.pop()
            for nxt in adj[curr]:
                if nxt not in visited:
                    visited.add(nxt)
                    stack.append(nxt)

        return len(visited) == len(self.islands)

    def _solve_recursive(self, bridges):
        current_bridges = bridges.copy()

        if not self._propagate(current_bridges):
            return None

        all_satisfied = True
        for island in self.island_map:
            if self._get_current_bridges(island, current_bridges) != self.island_map[island]:
                all_satisfied = False
                break

        if all_satisfied:
            if self._is_connected(current_bridges):
                return current_bridges
            else:
                return None

        best_island = None
        best_neighbors = []
        min_flex = 100

        for island in self.island_map:
            rem = self.island_map[island] - self._get_current_bridges(island, current_bridges)
            if rem > 0:
                flex = []
                for n in self.neighbors[island]:
                    key = tuple(sorted([island, n]))
                    if current_bridges[key] < 2:
                        n_rem = self.island_map[n] - self._get_current_bridges(n, current_bridges)
                        if n_rem > 0:
                            flex.append(n)

                if len(flex) < min_flex:
                    min_flex = len(flex)
                    best_island = island
                    best_neighbors = flex

        if best_island is None:
            return None

        if min_flex == 0:
            return None

        for n in best_neighbors:
            key = tuple(sorted([best_island, n]))
            current_val = current_bridges[key]

            if current_val < 2:
                new_bridges = current_bridges.copy()
                new_bridges[key] = 2
                res = self._solve_recursive(new_bridges)
                if res: return res

            if current_val < 1:
                new_bridges = current_bridges.copy()
                new_bridges[key] = 1
                res = self._solve_recursive(new_bridges)
                if res: return res

        return None

def solve(observation):
    solver = HashiSolver(observation)
    return solver.solve()

if __name__ == "__main__":
    print(solve(OBSERVATION))
