    import sys
    sys.setrecursionlimit(20000)

    data = observation['data']
    adjacent = observation['adjacent']

    N = len(data)
    grid = [row[:] for row in data]

    # Parse adjacencies into a set for O(1) lookup
    # adjacent contains coordinates like [0, 1.5] or [0.5, 0]
    # We need to map these to pairs of cells ((r1, c1), (r2, c2))
    adj_set = set()
    no_adj_set = set() # Not strictly needed if we check all neighbors, but good for logic

    # We will store constraints as: for each cell, which neighbors must be consecutive
    # and which must NOT be consecutive.
    # Actually, the rule is:
    # 1. If dot exists, |v1 - v2| == 1
    # 2. If no dot exists, |v1 - v2| != 1

    # Let's build a map of required consecutive neighbors
    # consecutive_neighbors[(r, c)] = set of (nr, nc)
    consecutive_neighbors = {}
    for r in range(N):
        for c in range(N):
            consecutive_neighbors[(r, c)] = set()

    for coord in adjacent:
        r, c = coord
        if r == int(r): # Horizontal gap: (row, col+0.5) -> between (r, c-0.5) and (r, c+0.5) -> (r, int(c-0.5)) and (r, int(c+0.5))
            # c is like 1.5. So cells are (r, 1) and (r, 2)
            c_int = int(c - 0.5)
            r_int = int(r)
            cell1 = (r_int, c_int)
            cell2 = (r_int, c_int + 1)
            consecutive_neighbors[cell1].add(cell2)
            consecutive_neighbors[cell2].add(cell1)
        else: # Vertical gap: (row+0.5, col) -> between (r-0.5, c) and (r+0.5, c) -> (int(r-0.5), c) and (int(r+0.5), c)
            # r is like 0.5. So cells are (0, c) and (1, c)
            r_int = int(r - 0.5)
            c_int = int(c)
            cell1 = (r_int, c_int)
            cell2 = (r_int + 1, c_int)
            consecutive_neighbors[cell1].add(cell2)
            consecutive_neighbors[cell2].add(cell1)

    # Domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                domains[(r, c)] = {grid[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    def is_consistent(r, c, val, current_grid):
        # Check row and col uniqueness
        for i in range(N):
            if i != c and current_grid[r][i] == val:
                return False
            if i != r and current_grid[i][c] == val:
                return False

        # Check consecutive constraints with already filled neighbors
        # We only need to check neighbors that are already filled to prune early.
        # But for full consistency, we should check all constraints if possible.
        # However, in backtracking, we usually check against assigned values.

        # Check consecutive neighbors
        for nr, nc in consecutive_neighbors[(r, c)]:
            if current_grid[nr][nc] is not None:
                if abs(val - current_grid[nr][nc]) != 1:
                    return False

        # Check non-consecutive neighbors (orthogonal neighbors without dots)
        # Orthogonal neighbors are (r-1, c), (r+1, c), (r, c-1), (r, c+1)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                # If this neighbor is NOT in consecutive_neighbors, then it must NOT be consecutive
                if (nr, nc) not in consecutive_neighbors[(r, c)]:
                    if current_grid[nr][nc] is not None:
                        if abs(val - current_grid[nr][nc]) == 1:
                            return False

        return True

    # Forward checking / Constraint Propagation
    def propagate(current_grid, current_domains):
        # This is a simple AC-3 like propagation or just forward checking
        # Given the constraints, simple forward checking might be enough.
        # But let's try to prune domains.
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if current_grid[r][c] is not None:
                        continue
                    val_domain = current_domains[(r, c)]
                    new_domain = set()
                    for val in val_domain:
                        # Check consistency with assigned neighbors
                        consistent = True

                        # Check row/col
                        for i in range(N):
                            if i != c and current_grid[r][i] == val:
                                consistent = False; break
                            if i != r and current_grid[i][c] == val:
                                consistent = False; break
                        if not consistent: continue

                        # Check consecutive neighbors
                        for nr, nc in consecutive_neighbors[(r, c)]:
                            if current_grid[nr][nc] is not None:
                                if abs(val - current_grid[nr][nc]) != 1:
                                    consistent = False; break
                            else:
                                # If neighbor is unassigned, check if it has any possible value
                                # that is consecutive to val
                                neighbor_domain = current_domains[(nr, nc)]
                                has_consecutive = False
                                for nval in neighbor_domain:
                                    if abs(val - nval) == 1:
                                        has_consecutive = True
                                        break
                                if not has_consecutive:
                                    consistent = False; break

                        if not consistent: continue

                        # Check non-consecutive neighbors
                        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
                        for dr, dc in directions:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if (nr, nc) not in consecutive_neighbors[(r, c)]:
                                    if current_grid[nr][nc] is not None:
                                        if abs(val - current_grid[nr][nc]) == 1:
                                            consistent = False; break
                                    else:
                                        # If neighbor is unassigned, check if it has any possible value
                                        # that is NOT consecutive to val (i.e., |val - nval| != 1)
                                        # Actually, the constraint is |val - nval| != 1.
                                        # So we need at least one value in neighbor_domain such that |val - nval| != 1.
                                        # Wait, no. The constraint is pairwise.
                                        # If I pick val, the neighbor must pick something not consecutive.
                                        # So neighbor_domain must contain at least one value not consecutive to val.
                                        neighbor_domain = current_domains[(nr, nc)]
                                        has_non_consecutive = False
                                        for nval in neighbor_domain:
                                            if abs(val - nval) != 1:
                                                has_non_consecutive = True
                                                break
                                        if not has_non_consecutive:
                                            consistent = False; break

                        if consistent:
                            new_domain.add(val)

                    if new_domain != current_domains[(r, c)]:
                        current_domains[(r, c)] = new_domain
                        changed = True
                        if not new_domain:
                            return False # Domain wipeout
        return True

    def solve_backtrack(current_grid, current_domains):
        # Find unassigned cell with MRV
        unassigned = []
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] is None:
                    unassigned.append((r, c))

        if not unassigned:
            return current_grid

        # MRV
        r, c = min(unassigned, key=lambda pos: len(current_domains[pos]))

        # Order values (LCV could be used, but simple order is fine for now)
        for val in sorted(list(current_domains[(r, c)])):
            # Check consistency
            if is_consistent(r, c, val, current_grid):
                current_grid[r][c] = val

                # Save domains for backtracking
                saved_domains = {k: v.copy() for k, v in current_domains.items()}

                # Update domains of neighbors
                # Remove val from row and col
                for i in range(N):
                    if i != c:
                        if val in current_domains[(r, i)]:
                            current_domains[(r, i)].remove(val)
                    if i != r:
                        if val in current_domains[(i, c)]:
                            current_domains[(i, c)].remove(val)

                # Propagate constraints
                if propagate(current_grid, current_domains):
                    result = solve_backtrack(current_grid, current_domains)
                    if result:
                        return result

                # Backtrack
                current_grid[r][c] = None
                # Restore domains (deep copy was saved)
                # Actually, we modified current_domains in place.
                # We need to restore it.
                # Since we passed the reference, we need to be careful.
                # Let's just re-copy from saved_domains
                for k in current_domains:
                    current_domains[k] = saved_domains[k]

        return None

    # Initial propagation
    if not propagate(grid, domains):
        return "No Solution"

    result = solve_backtrack(grid, domains)
    if result:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
