                                if 0<=nr<rows and 0<=nc<cols:
                                    if g[nr][nc] == 'T':
                                        tree_adj += 1
                            if tree_adj != 1: return False

                            touch = False
                            for dr in [-1, 0, 1]:
                                for dc in [-1, 0, 1]:
                                    if dr==0 and dc==0: continue
                                    nr, nc = r+dr, c+dc
                                    if 0<=nr<rows and 0<=nc<cols:
                                        if g[nr][nc] == 't':
                                            touch = True
                            if touch: return False

                            g[r][c] = 't'
                            changed = True

            for c in range(cols):
                t_count = sum(1 for row in g if row[c] == 't')
                u_count = sum(1 for row in g if row[c] == '?')
                if t_count > col_counts[c]: return False
                if t_count == col_counts[c]:
