                                    if 0<=nr<rows and 0<=nc<cols:
                                        if g[nr][nc] == 't':
                                            touch = True
                            if touch: return False

                            g[r][c] = 't'
                            changed = True

            # 2. Tree Logic
            for r, c in tree_positions:
                adj_tents = []
                adj_unknowns = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
