                            adj_tents.append((nr, nc))
                        elif g[nr][nc] == '?':
                            adj_unknowns.append((nr, nc))

                if len(adj_tents) > 1: return False
                if len(adj_tents) == 1:
                    for nr, nc in adj_unknowns:
                        if g[nr][nc] == '?':
                            g[nr][nc] = 'G'
                            changed = True
                elif len(adj_tents) == 0:
                    if len(adj_unknowns) == 1:
                        nr, nc = adj_unknowns[0]
