        new_grid[r][c] = 'G'
        res = run_propagation(new_grid)
        if res is not False:
            result = solve_recursive(res)
            if result: return result

        return None

    final_grid = run_propagation(grid)
    if final_grid is False:
        return "No Solution"

    result = solve_recursive(final_grid)
    if result is None:
        return "No Solution"

    out_grid = []
    for r in range(rows):
        row_out = []
        for c in range(cols):
            if result[r][c] == 't':
                row_out.append('t')
            else:
                row_out.append(None)
        out_grid.append(row_out)
    return out_grid

