def solve(observation):
    grid = [row[:] for row in observation['data']]
    N = len(grid)

    # Pre-calculate 2x2 blocks coordinates
    blocks = []
    for r in range(N - 1):
        for c in range(N - 1):
            blocks.append([(r, c), (r, c+1), (r+1, c), (r+1, c+1)])

    def propagate(g):
        changed = True
        while changed:
            changed = False
            for block in blocks:
                cells = [g[r][c] for r, c in block]
                b_count = cells.count('B')
                w_count = cells.count('W')
                none_count = cells.count(None)

                if b_count == 4 or w_count == 4:
                    return False 

                if b_count == 3 and none_count == 1:
                    for r, c in block:
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == 3 and none_count == 1:
                    for r, c in block:
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True
        return True

    def check_connectivity(g):
        # Check B connectivity potential
        b_cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == 'B':
                    b_cells.append((r, c))

        if b_cells:
            start = b_cells[0]
            visited = set()
            queue = [start]
            visited.add(start)
            while queue:
                r, c = queue.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if (nr, nc) not in visited and g[nr][nc] != 'W': 
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            for r, c in b_cells:
                if (r, c) not in visited:
                    return False

        # Check W connectivity potential
        w_cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == 'W':
                    w_cells.append((r, c))

        if w_cells:
            start = w_cells[0]
            visited = set()
            queue = [start]
            visited.add(start)
            while queue:
                r, c = queue.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if (nr, nc) not in visited and g[nr][nc] != 'B': 
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            for r, c in w_cells:
                if (r, c) not in visited:
                    return False

        return True

    def get_next_cell(g):
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    return (r, c)
        return None

    def backtrack(g):
        if not check_connectivity(g):
            return None

        next_cell = get_next_cell(g)
        if next_cell is None:
            return g 

        r, c = next_cell

        for val in ['B', 'W']:
            new_g = [row[:] for row in g]
            new_g[r][c] = val
            if propagate(new_g): 
                res = backtrack(new_g)
                if res:
                    return res
        return None

    if not propagate(grid):
        return "No Solution"

    result = backtrack(grid)
    if result:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
