        if r1 == r2: # Horizontal
            mr, mc = r1, (c1 + c2) / 2.0
        else: # Vertical
            mr, mc = (r1 + r2) / 2.0, c1

        for m in adjacent_midpoints:
            if abs(m[0] - mr) < 1e-9 and abs(m[1] - mc) < 1e-9:
                return True
        return False

    for r in range(N):
        for c in range(N):
            neighbors = []
            # Right
            if c + 1 < N:
                neighbors.append(((r, c + 1), is_adjacent(r, c, r, c + 1)))
            # Down
            if r + 1 < N:
                neighbors.append(((r + 1, c), is_adjacent(r, c, r + 1, c)))
            # Left
            if c - 1 >= 0:
                neighbors.append(((r, c - 1), is_adjacent(r, c, r, c - 1)))
            # Up
            if r - 1 >= 0:
                neighbors.append(((r - 1, c), is_adjacent(r, c, r - 1, c)))
            adj_map[(r, c)] = neighbors

    # Propagation Queue
    queue = []
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) == 1:
                queue.append((r, c))

    def propagate():
        while queue:
            r, c = queue.pop(0)

            # If domain empty, fail
            if len(domains[r][c]) == 0:
                return False

            # If domain size 1, propagate value
            if len(domains[r][c]) == 1:
                val = list(domains[r][c])[0]

                # 1. Row and Col peers (AllDifferent)
                for i in range(N):
                    # Row peer
                    if i != c:
                        if val in domains[r][i]:
                            domains[r][i].discard(val)
                            if len(domains[r][i]) == 0: return False
                            if len(domains[r][i]) == 1:
                                queue.append((r, i))
                    # Col peer
                    if i != r:
                        if val in domains[i][c]:
                            domains[i][c].discard(val)
                            if len(domains[i][c]) == 0: return False
                            if len(domains[i][c]) == 1:
                                queue.append((i, c))

                # 2. Adjacency neighbors
                for (nr, nc), is_consec in adj_map[(r, c)]:
                    if is_consec:
                        allowed = {val - 1, val + 1}
                        allowed = {x for x in allowed if 1 <= x <= N}
                        old_len = len(domains[nr][nc])
                        domains[nr][nc] &= allowed
                        if len(domains[nr][nc]) == 0: return False
                        if len(domains[nr][nc]) < old_len:
                            if len(domains[nr][nc]) == 1:
                                queue.append((nr, nc))
                    else:
                        forbidden = {val - 1, val + 1}
                        old_len = len(domains[nr][nc])
                        domains[nr][nc] -= forbidden
                        if len(domains[nr][nc]) == 0: return False
                        if len(domains[nr][nc]) < old_len:
                            if len(domains[nr][nc]) == 1:
                                queue.append((nr, nc))
            else:
                # Domain size > 1. Propagate constraints to neighbors (Arc Consistency)
                # Check neighbors
                for (nr, nc), is_consec in adj_map[(r, c)]:
                    # Prune domains[nr][nc] based on domains[r][c]
                    new_domain = set()
                    for val_neighbor in domains[nr][nc]:
                        # Check if val_neighbor has support in domains[r][c]
                        has_support = False
                        for val_self in domains[r][c]:
                            if is_consec:
                                if abs(val_neighbor - val_self) == 1:
                                    has_support = True
                                    break
                            else:
                                if abs(val_neighbor - val_self) != 1:
                                    has_support = True
                                    break
                        if has_support:
                            new_domain.add(val_neighbor)

                    if new_domain != domains[nr][nc]:
                        domains[nr][nc] = new_domain
                        if len(domains[nr][nc]) == 0: return False
                        if len(domains[nr][nc]) == 1:
                            queue.append((nr, nc))
                        else:
                             # If reduced but > 1, add to queue to propagate further
                             queue.append((nr, nc))

        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Backtracking
    # Find cell with min domain size > 1
    def get_mrv():
        min_size = N + 1
        best = None
        for r in range(N):
            for c in range(N):
                s = len(domains[r][c])
                if 1 < s < min_size:
                    min_size = s
                    best = (r, c)
        return best

    def backtrack():
        cell = get_mrv()
        if cell is None:
            return True # Solved

        r, c = cell
        # Save state
        # Deep copy domains
        saved_domains = [[s.copy() for s in row] for row in domains]

        # Try values
        for val in sorted(list(domains[r][c])):
            domains[r][c] = {val}
            queue.append((r, c))

            if propagate():
                if backtrack():
                    return True

            # Restore
            for rr in range(N):
                for cc in range(N):
                    domains[rr][cc] = saved_domains[rr][cc]
            del queue[:] # Clear queue for next iteration

        return False

    if backtrack():
        result = []
        for r in range(N):
            result.append([list(domains[r][c])[0] for c in range(N)])
        return result
    else:
        return "No Solution"

