import sys
import copy

# Increase recursion depth to handle deep search if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # Grid state
    # connections[r][c] = set of (nr, nc)
    # forbidden[r][c] = set of (nr, nc)
    # We will manage these inside the state tuple to allow backtracking

    # Clues
    clues = []
    for r in range(N):
        for c in range(N):
            if data[r][c] in ['B', 'W']:
                clues.append((r, c, data[r][c]))

    # Helper to check bounds
    def in_bounds(r, c):
        return 0 <= r < N and 0 <= c < N

    # Helper to get neighbors
    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc):
                neighs.append((nr, nc))
        return neighs

    def idx(r, c):
        return r * N + c

    # Propagation function
    # Returns (success, state)
    # state = (connections, forbidden, parent)
    def propagate(state):
        conns, forb, par = state

        changed = True
        while changed:
            changed = False

            # 1. Degree constraints & Non-clue forcing
            for r in range(N):
                for c in range(N):
                    deg = len(conns[r][c])
                    if deg > 2:
                        return False, state

                    # If deg == 2, forbid others
                    if deg == 2:
                        for nr, nc in get_neighbors(r, c):
                            if (nr, nc) not in conns[r][c]:
                                if (nr, nc) not in forb[r][c]:
                                    forb[r][c].add((nr, nc))
                                    forb[nr][nc].add((r, c))
                                    changed = True

                    # If non-clue and deg == 1, must add one more if only 1 option
                    if data[r][c] is None and deg == 1:
                        possible = []
                        for nr, nc in get_neighbors(r, c):
                            if (nr, nc) not in conns[r][c] and (nr, nc) not in forb[r][c]:
                                possible.append((nr, nc))
                        if len(possible) == 1:
                            nr, nc = possible[0]
                            conns[r][c].add((nr, nc))
                            conns[nr][nc].add((r, c))
                            changed = True
                        elif len(possible) == 0:
                            return False, state 

            # 2. Clue Rules
            for r, c, ctype in clues:
                deg = len(conns[r][c])

                if ctype == 'B':
                    if deg == 1:
                        # Must add perpendicular edge
                        existing = list(conns[r][c])[0]
                        dr, dc = existing[0] - r, existing[1] - c
                        perps = []
                        if dr != 0: # Existing is Vertical
                            perps.append((r, c - 1)) 
                            perps.append((r, c + 1)) 
                        else: # Existing is Horizontal
                            perps.append((r - 1, c)) 
                            perps.append((r + 1, c)) 

                        valid_perps = []
                        for pr, pc in perps:
                            if in_bounds(pr, pc) and (pr, pc) not in conns[r][c] and (pr, pc) not in forb[r][c]:
                                valid_perps.append((pr, pc))

                        if len(valid_perps) == 1:
                            pr, pc = valid_perps[0]
                            conns[r][c].add((pr, pc))
                            conns[pr][pc].add((r, c))
                            changed = True
                        elif len(valid_perps) == 0:
                            return False, state

                    if deg == 2:
                        neighs = list(conns[r][c])
                        (r1, c1), (r2, c2) = neighs
                        v1 = (r1 - r, c1 - c)
                        v2 = (r2 - r, c2 - c)
                        # Check perpendicular
                        if v1[0]*v2[0] + v1[1]*v2[1] != 0:
                            return False, state 

                        # Force straight extensions
                        for nr, nc in neighs:
                            dr, dc = nr - r, nc - c
                            nnr, nnc = nr + dr, nc + dc
                            if not in_bounds(nnr, nnc):
                                return False, state
                            if (nnr, nnc) not in conns[nr][nc]:
                                if (nnr, nnc) in forb[nr][nc]:
                                    return False, state
                                conns[nr][nc].add((nnr, nnc))
                                conns[nnr][nnc].add((nr, nc))
                                changed = True

                elif ctype == 'W':
                    if deg == 1:
                        existing = list(conns[r][c])[0]
                        dr, dc = existing[0] - r, existing[1] - c
                        opp_r, opp_c = r - dr, c - dc
                        if in_bounds(opp_r, opp_c):
                            if (opp_r, opp_c) not in conns[r][c] and (opp_r, opp_c) not in forb[r][c]:
                                conns[r][c].add((opp_r, opp_c))
                                conns[opp_r][opp_c].add((r, c))
                                changed = True
                            elif (opp_r, opp_c) in forb[r][c]:
                                return False, state
                        else:
                            return False, state 

                    if deg == 2:
                        neighs = list(conns[r][c])
                        (r1, c1), (r2, c2) = neighs
                        v1 = (r1 - r, c1 - c)
                        v2 = (r2 - r, c2 - c)
                        # Check collinear
                        if v1[0]*v2[1] - v1[1]*v2[0] != 0:
                            return False, state

                        # Turn constraint: If one neighbor is straight, other MUST turn
                        n1, n2 = neighs
                        # Check n1
                        if len(conns[n1[0]][n1[1]]) == 2:
                            other_n1 = [n for n in conns[n1[0]][n1[1]] if n != (r,c)][0]
                            v_in = (r - n1[0], c - n1[1])
                            v_out = (other_n1[0] - n1[0], other_n1[1] - n1[1])
                            straight_n1 = (v_in[0]*v_out[1] - v_in[1]*v_out[0] == 0)

                            if straight_n1:
                                # n2 MUST turn. Forbid straight extension at n2.
                                dr2, dc2 = r2 - r, c2 - c
                                forbidden_dir_at_n2 = (r2 + dr2, c2 + dc2)
                                if in_bounds(forbidden_dir_at_n2[0], forbidden_dir_at_n2[1]):
                                    if forbidden_dir_at_n2 not in conns[r2][c2]:
                                         if forbidden_dir_at_n2 not in forb[r2][c2]:
                                             forb[r2][c2].add(forbidden_dir_at_n2)
                                             forb[forbidden_dir_at_n2[0]][forbidden_dir_at_n2[1]].add((r2, c2))
                                             changed = True
                                    else:
                                        return False, state 

                                if len(conns[r2][c2]) == 2:
                                    other_n2 = [n for n in conns[r2][c2] if n != (r,c)][0]
                                    v_in2 = (r - r2, c - c2)
                                    v_out2 = (other_n2[0] - r2, other_n2[1] - c2)
                                    straight_n2 = (v_in2[0]*v_out2[1] - v_in2[1]*v_out2[0] == 0)
                                    if straight_n2:
                                        return False, state 

            # 3. Cycle Detection
            par = list(range(N * N))
            def find_p(i):
                path = []
                while par[i] != i:
                    path.append(i)
                    i = par[i]
                for node in path:
                    par[node] = i
                return i

            def union_p(i, j):
                ri, rj = find_p(i), find_p(j)
                if ri != rj:
                    par[ri] = rj
                    return True
                return False

            edges_count = 0
            cycle_detected = False
            cycle_root = -1

            for r in range(N):
                for c in range(N):
                    for nr, nc in conns[r][c]:
                        if (r, c) < (nr, nc): 
                            edges_count += 1
                            if not union_p(idx(r, c), idx(nr, nc)):
                                cycle_detected = True
                                cycle_root = find_p(idx(r, c))

            if cycle_detected:
                # Check if valid final loop
                nodes_in_comp = 0
                clues_in_comp = 0
                all_deg2 = True

                for rr in range(N):
                    for cc in range(N):
                        if find_p(idx(rr, cc)) == cycle_root:
                            nodes_in_comp += 1
                            if data[rr][cc] in ['B', 'W']:
                                clues_in_comp += 1
                            if len(conns[rr][cc]) != 2:
                                all_deg2 = False

                if not all_deg2:
                    return False, state 

                total_clues = len(clues)
                if clues_in_comp == total_clues and edges_count == nodes_in_comp:
                     has_other_edges = False
                     for rr in range(N):
                         for cc in range(N):
                             if find_p(idx(rr, cc)) != cycle_root and len(conns[rr][cc]) > 0:
                                 has_other_edges = True
                                 break
                         if has_other_edges: break

                     if not has_other_edges:
                         return True, (conns, forb, par)
                    else:
                         return False, state 
                else:
                    return False, state 

            state = (conns, forb, par)

        return True, state

    # Initial State
    initial_conns = [[set() for _ in range(N)] for _ in range(N)]
    initial_forb = [[set() for _ in range(N)] for _ in range(N)]
    initial_par = list(range(N * N))
    initial_state = (initial_conns, initial_forb, initial_par)

    def solve_recursive(state):
        success, state = propagate(state)
        if not success:
            return None

        conns, forb, par = state

        # Check if solved
        all_clues_deg2 = True
        for r, c, _ in clues:
            if len(conns[r][c]) != 2:
                all_clues_deg2 = False
                break

        if all_clues_deg2:
            # Check connectivity (single component with edges)
            root = -1
            for r in range(N):
                for c in range(N):
                    if len(conns[r][c]) > 0:
                        i = idx(r, c)
                        path = []
                        curr = i
                        while par[curr] != curr:
                            path.append(curr)
                            curr = par[curr]
                        for node in path: par[node] = curr
                        root = curr
                        break
                if root != -1: break

            if root != -1:
                clues_in_root = 0
                for r, c, _ in clues:
                    i = idx(r, c)
                    curr = i
                    while par[curr] != curr:
                        curr = par[curr]
                    if curr == root:
                        clues_in_root += 1

                if clues_in_root == len(clues):
                    has_other = False
                    for r in range(N):
                        for c in range(N):
                            if len(conns[r][c]) > 0:
                                i = idx(r, c)
                                curr = i
                                while par[curr] != curr:
                                    curr = par[curr]
                                if curr != root:
                                    has_other = True
                                    break
                        if has_other: break

                    if not has_other:
                        return conns 

        # Branch
        candidates = []
        for r, c, ctype in clues:
            if len(conns[r][c]) < 2:
                for nr, nc in get_neighbors(r, c):
                    if (nr, nc) not in conns[r][c] and (nr, nc) not in forb[r][c]:
                        candidates.append(((r, c), (nr, nc)))

        if not candidates:
            for r in range(N):
                for c in range(N):
                    if len(conns[r][c]) < 2:
                        for nr, nc in get_neighbors(r, c):
                            if (nr, nc) not in conns[r][c] and (nr, nc) not in forb[r][c]:
                                candidates.append(((r, c), (nr, nc)))

        if not candidates:
            return None 

        (r1, c1), (r2, c2) = candidates[0]

        # Option 1: Add edge
        new_conns = copy.deepcopy(conns)
        new_forb = copy.deepcopy(forb)
        new_par = list(par)

        new_conns[r1][c1].add((r2, c2))
        new_conns[r2][c2].add((r1, c1))

        i1, i2 = idx(r1, c1), idx(r2, c2)
        # Simple union for new_par (propagate will fix it)
        ri1, ri2 = i1, i2
        while new_par[ri1] != ri1: ri1 = new_par[ri1]
        while new_par[ri2] != ri2: ri2 = new_par[ri2]
        if ri1 != ri2:
            new_par[ri1] = ri2

        new_state = (new_conns, new_forb, new_par)
        res = solve_recursive(new_state)
        if res:
            return res

        # Option 2: Forbid edge
        new_forb2 = copy.deepcopy(forb)
        new_forb2[r1][c1].add((r2, c2))
        new_forb2[r2][c2].add((r1, c1))
        new_state2 = (conns, new_forb2, par)
        res2 = solve_recursive(new_state2)
        if res2:
            return res2

        return None

    final_conns = solve_recursive(initial_state)

    if final_conns is None:
        return "No Solution"

    # Reconstruct path
    start_r, start_c = clues[0][0], clues[0][1]
    path = [(start_r, start_c)]
    curr_r, curr_c = start_r, start_c
    prev_r, prev_c = -1, -1

    # Limit iterations to prevent infinite loop if logic fails
    for _ in range(N * N * 2):
        next_node = None
        for nr, nc in final_conns[curr_r][curr_c]:
            if (nr, nc) != (prev_r, prev_c):
                next_node = (nr, nc)
                break

        if next_node is None:
            break 

        path.append(next_node)
        prev_r, prev_c = curr_r, curr_c
        curr_r, curr_c = next_node

        if (curr_r, curr_c) == (start_r, start_c):
            break

    return path

