OBSERVATION = {'row_sum': [11, 1, 8, 4, 3, 1], 'col_sum': [8, 4, 5, 5, 1, 3]}

def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    n_rows = len(row_targets)
    n_cols = len(col_targets)

    # Weights are 1..N based on the large grey numbers in the image (1, 2, 3, 4, 5, 6)
    # The small numbers 0..5 are coordinates.
    row_weights = list(range(1, n_rows + 1))
    col_weights = list(range(1, n_cols + 1))

    # Precompute valid masks for each row
    # A mask is an integer where bit c is 1 if cell (r, c) is black
    # The value added to row sum is col_weights[c]
    valid_row_masks = []
    for r in range(n_rows):
        target = row_targets[r]
        masks = []
        # Iterate all subsets of columns (2^n_cols)
        for m in range(1 << n_cols):
            current_sum = 0
            for c in range(n_cols):
                if (m >> c) & 1:
                    current_sum += col_weights[c]
            if current_sum == target:
                masks.append(m)
        valid_row_masks.append(masks)

    # Precompute suffix sums of row weights for pruning
    # suffix_sum_row_weights[i] = sum(row_weights[i:])
    # This represents the max possible addition to any column sum from rows i to end
    suffix_sum_row_weights = [0] * (n_rows + 1)
    for i in range(n_rows - 1, -1, -1):
        suffix_sum_row_weights[i] = suffix_sum_row_weights[i+1] + row_weights[i]

    grid_masks = [0] * n_rows

    def dfs(r, current_col_sums):
        # Base case: all rows filled
        if r == n_rows:
            # Check if column sums match exactly
            for c in range(n_cols):
                if current_col_sums[c] != col_targets[c]:
                    return None
            return grid_masks[:]

        # Pruning: check feasibility for all columns
        # Max possible addition from remaining rows (r+1 to n_rows-1)
        max_add = suffix_sum_row_weights[r+1]

        for c in range(n_cols):
            curr = current_col_sums[c]
            target = col_targets[c]
            # If current sum exceeds target, invalid
            if curr > target:
                return None
            # If even taking all remaining cells we can't reach target, invalid
            if curr + max_add < target:
                return None

        # Try valid masks for current row
        for mask in valid_row_masks[r]:
            # Calculate new col sums
            new_col_sums = list(current_col_sums)
            valid_choice = True

            for c in range(n_cols):
                if (mask >> c) & 1:
                    new_col_sums[c] += row_weights[r]
                    # Early break if exceeds
                    if new_col_sums[c] > col_targets[c]:
                        valid_choice = False
                        break

            if valid_choice:
                grid_masks[r] = mask
                res = dfs(r + 1, new_col_sums)
                if res is not None:
                    return res

        return None

    initial_col_sums = [0] * n_cols
    result_masks = dfs(0, initial_col_sums)

    if result_masks is None:
        return "No Solution"

    # Convert masks to grid format
    # 'B' for black, None for non-black
    grid = []
    for r in range(n_rows):
        row_cells = []
        mask = result_masks[r]
        for c in range(n_cols):
            if (mask >> c) & 1:
                row_cells.append('B')
            else:
                row_cells.append(None)
        grid.append(row_cells)

    return grid

