        valid_masks.append(masks)

    # Precompute suffix sums of row weights for pruning (lower bound check)
    # suffix_row_weights[r] = sum(row_weights[r:])
    # This represents the maximum possible contribution remaining rows can make to any column
    # (assuming all cells in that column are black for remaining rows).
    suffix_row_weights = [0] * (R + 1)
    for r in range(R - 1, -1, -1):
        suffix_row_weights[r] = suffix_row_weights[r+1] + row_weights[r]

    solution_masks = [0] * R

    # Backtracking function
    # r_idx: current row index we are trying to fill
    # current_col_totals: list of current sums for each column
    def backtrack(r_idx, current_col_totals):
        # Base case: all rows filled
        if r_idx == R:
            # Verify column sums match exactly (pruning ensures <=, but we need ==)
            for c in range(C):
                if current_col_totals[c] != col_sum[c]:
                    return False
            return True

        # Try each valid mask for the current row
        for mask in valid_masks[r_idx]:
            # Pruning Step 1: Upper Bound Check
            # If adding this row's contribution exceeds any column target, skip.
            possible = True
            for c in range(C):
                if (mask >> c) & 1:
                    if current_col_totals[c] + row_weights[r_idx] > col_sum[c]:
                        possible = False
                        break
            if not possible:
                continue

            # Pruning Step 2: Lower Bound Check
            # Even if we pick all remaining cells in a column, can we reach the target?
            remaining_max = suffix_row_weights[r_idx+1]
            for c in range(C):
                current_val = current_col_totals[c]
                if (mask >> c) & 1:
                    current_val += row_weights[r_idx]

                if current_val + remaining_max < col_sum[c]:
                    possible = False
                    break
            if not possible:
                continue

            # If valid, apply the mask and recurse
            for c in range(C):
                if (mask >> c) & 1:
                    current_col_totals[c] += row_weights[r_idx]

            solution_masks[r_idx] = mask

            if backtrack(r_idx + 1, current_col_totals):
                return True

            # Backtrack: remove the mask's contribution
            for c in range(C):
                if (mask >> c) & 1:
                    current_col_totals[c] -= row_weights[r_idx]

        return False

    initial_col_totals = [0] * C
    if backtrack(0, initial_col_totals):
        # Construct the grid from the solution masks
        grid = []
        for r in range(R):
            row_res = []
            mask = solution_masks[r]
            for c in range(C):
                if (mask >> c) & 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            grid.append(row_res)
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
