                        domains[r][c] -= set(fixed_in_row)
                        if len(domains[r][c]) != old_len:
                            changed = True
                            if not domains[r][c]: return False

                fixed_in_col = [grid[r][c] for r in range(N) if grid[r][c] != 0]
