                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                is_consecutive = (nr, nc) in neighbors

                                if grid[nr][nc] != 0:
