                        grid[r][c] = next(iter(domains[r][c]))
                        changed = True

            if not is_consistent():
                return False
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Backtracking with MRV
    def get_next_cell():
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    if len(domains[r][c]) < min_len:
                        min_len = len(domains[r][c])
                        best_cell = (r, c)
        return best_cell

    def solve_recursive():
