        possible_values = sorted(list(domains[r][c]))

        for val in possible_values:
            # Save state
            saved_domains = [[s.copy() for s in row] for row in domains]
            saved_grid = [row[:] for row in grid]

            grid[r][c] = val
            domains[r][c] = {val}

            if propagate():
                if solve_recursive():
                    return True

            # Restore state
            for i in range(N):
                for j in range(N):
                    domains[i][j] = saved_domains[i][j]
                    grid[i][j] = saved_grid[i][j]

        return False

    if solve_recursive():
        return grid
    else:
        return "No Solution"

