            return False
        if t == 'H': H[r][c] = val
        else: V[r][c] = val
        return True

    def check_loops():
        # Build graph of LINE edges
        adj = {}
        for r in range(H_rows):
            for c in range(V_cols):
                adj[(r,c)] = []

        line_edges = []
        total_lines = 0

        for r in range(H_rows):
            for c in range(H_cols):
                if H[r][c] == 1:
                    u, v = (r, c), (r, c+1)
                    adj[u].append(v)
                    adj[v].append(u)
                    line_edges.append((u, v))
                    total_lines += 1
        for r in range(V_rows):
            for c in range(V_cols):
                if V[r][c] == 1:
                    u, v = (r, c), (r+1, c)
                    adj[u].append(v)
                    adj[v].append(u)
                    line_edges.append((u, v))
                    total_lines += 1

        if total_lines == 0:
            return True

        visited = set()
        components = []
        all_nodes = set(u for u in adj if adj[u])

        for start_node in all_nodes:
            if start_node in visited: continue
            comp_nodes = set()
            comp_edges = set()
            q = [start_node]
            visited.add(start_node)
            comp_nodes.add(start_node)
            idx = 0
            while idx < len(q):
                curr = q[idx]
                idx += 1
                for neighbor in adj[curr]:
                    edge = tuple(sorted((curr, neighbor)))
                    comp_edges.add(edge)
                    if neighbor not in visited:
                        visited.add(neighbor)
                        comp_nodes.add(neighbor)
                        q.append(neighbor)
            components.append({'nodes': comp_nodes, 'edges': comp_edges})

        for comp in components:
            # In Slitherlink, max degree is 2. So components are paths or simple cycles.
            # If edges >= nodes, it's a cycle.
            if len(comp['edges']) >= len(comp['nodes']):
                # Cycle detected.
                # Must be the only loop containing all lines.
                if len(comp['edges']) < total_lines:
                    return False # Sub-loop or disconnected lines

                # If a cycle is formed, all unknown edges must be NO_LINE (0)
                # because the loop is closed and cannot be extended.
                forced = False
                for r in range(H_rows):
                    for c in range(H_cols):
                        if H[r][c] == -1:
                            H[r][c] = 0
                            forced = True
                for r in range(V_rows):
                    for c in range(V_cols):
                        if V[r][c] == -1:
                            V[r][c] = 0
                            forced = True
                if forced:
                    return "FORCED"
                return True
        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            # 1. Clue Constraints
            for r in range(R):
                for c in range(C):
                    clue = clues[r][c]
                    if clue is None: continue
                    edges = get_cell_edges(r, c)
                    vals = [get_val(t, rr, cc) for t, rr, cc in edges]
                    k_line = vals.count(1)
                    k_no = vals.count(0)
                    unk = vals.count(-1)

                    if k_line > clue: return False
                    if k_line + unk < clue: return False

                    if k_line == clue:
                        for i, (t, rr, cc) in enumerate(edges):
                            if vals[i] == -1:
                                if not set_val(t, rr, cc, 0): return False
                                changed = True
                    elif k_line + unk == clue:
                        for i, (t, rr, cc) in enumerate(edges):
                            if vals[i] == -1:
                                if not set_val(t, rr, cc, 1): return False
                                changed = True

            # 2. Vertex Constraints (Degree 0 or 2)
            for r in range(H_rows):
                for c in range(V_cols):
                    edges = get_vertex_edges(r, c)
                    vals = [get_val(t, rr, cc) for t, rr, cc in edges]
                    k_line = vals.count(1)
                    k_no = vals.count(0)
                    unk = vals.count(-1)

                    if k_line > 2: return False

                    if k_line == 2:
                        for i, (t, rr, cc) in enumerate(edges):
                            if vals[i] == -1:
                                if not set_val(t, rr, cc, 0): return False
                                changed = True
                    elif k_line == 1 and unk == 1:
                        for i, (t, rr, cc) in enumerate(edges):
                            if vals[i] == -1:
                                if not set_val(t, rr, cc, 1): return False
                                changed = True
                    elif k_no == 3: 
                         for i, (t, rr, cc) in enumerate(edges):
                            if vals[i] == -1:
                                if not set_val(t, rr, cc, 0): return False
                                changed = True

            # 3. Loop Constraints
            res = check_loops()
            if res is False: return False
            if res == "FORCED":
                changed = True

        return True

    if not propagate():
        return "No Solution"

    def get_unknown():
        for r in range(H_rows):
            for c in range(H_cols):
                if H[r][c] == -1: return ('H', r, c)
        for r in range(V_rows):
            for c in range(V_cols):
                if V[r][c] == -1: return ('V', r, c)
        return None

    def solve_rec():
        unk = get_unknown()
        if unk is None:
            # Verify solution
            for r in range(R):
                for c in range(C):
                    if clues[r][c] is not None:
                        edges = get_cell_edges(r, c)
                        cnt = sum(1 for t, rr, cc in edges if get_val(t, rr, cc) == 1)
                        if cnt != clues[r][c]: return None

            lines = []
            for r in range(H_rows):
                for c in range(H_cols):
                    if H[r][c] == 1: lines.append(((r,c), (r,c+1)))
            for r in range(V_rows):
                for c in range(V_cols):
                    if V[r][c] == 1: lines.append(((r,c), (r+1,c)))

            if not lines: return None

            adj = {}
            for u, v in lines:
                adj.setdefault(u, []).append(v)
                adj.setdefault(v, []).append(u)

            start = lines[0][0]
            visited = {start}
            q = [start]
            while q:
                curr = q.pop(0)
                for n in adj.get(curr, []):
                    if n not in visited:
                        visited.add(n)
                        q.append(n)

            line_verts = set()
            for u, v in lines:
                line_verts.add(u)
                line_verts.add(v)

            if visited != line_verts: return None

            # Trace path
            path = []
            curr = start
            prev = None
            while True:
                path.append(curr)
                neighbors = adj[curr]
                nxt = None
                for n in neighbors:
                    if n != prev:
                        nxt = n
                        break
                if nxt == start:
                    path.append(start)
                    break
                prev = curr
                curr = nxt
            return path

        t, r, c = unk

        H_bak = [row[:] for row in H]
        V_bak = [row[:] for row in V]

        # Try Line (1)
        if set_val(t, r, c, 1):
            if propagate():
                res = solve_rec()
                if res: return res

        # Restore
        for i in range(H_rows): H[i] = H_bak[i]
        for i in range(V_rows): V[i] = V_bak[i]

        # Try No Line (0)
        if set_val(t, r, c, 0):
            if propagate():
                res = solve_rec()
                if res: return res

        return None

    res = solve_rec()
    return res

if __name__ == "__main__":
    print(solve(OBSERVATION))
