OBSERVATION = {'data': [['B', None, None, None, None, 'B', None, None, None, None], [None, None, 'B', 'W', None, None, None, None, 'W', 'W'], [None, None, None, None, 'W', None, None, 'W', 'W', None], [None, None, 'W', 'W', None, None, None, None, None, None], ['W', None, None, 'W', 'B', 'W', None, 'W', None, None], ['W', None, 'W', 'B', None, 'B', None, 'W', None, 'W'], [None, 'W', None, None, 'W', 'W', None, None, None, None], [None, None, None, 'W', None, 'B', 'W', None, None, None], ['W', None, 'W', None, None, None, 'W', None, None, 'W'], ['B', None, None, None, None, None, None, None, None, None]]}

import sys

# Increase recursion depth to handle deep search if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Identify clues
    clues = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] in ['B', 'W']:
                clues[(r, c)] = data[r][c]

    # State representation
    # edges: set of normalized edges ((r1, c1), (r2, c2))
    edges = set()
    # forbidden: set of normalized edges
    forbidden = set()

    def norm_edge(u, v):
        if u > v:
            return (v, u)
        return (u, v)

    def get_neighbors(r, c):
        res = []
        if r > 0: res.append((r-1, c))
        if r < R-1: res.append((r+1, c))
        if c > 0: res.append((r, c-1))
        if c < C-1: res.append((r, c+1))
        return res

    def is_active(u, v):
        return norm_edge(u, v) in edges

    def is_forbidden(u, v):
        return norm_edge(u, v) in forbidden

    def get_degree(r, c):
        deg = 0
        for nr, nc in get_neighbors(r, c):
            if is_active((r, c), (nr, nc)):
                deg += 1
        return deg

    def get_active_neighbors(r, c):
        res = []
        for nr, nc in get_neighbors(r, c):
            if is_active((r, c), (nr, nc)):
                res.append((nr, nc))
        return res

    def get_available_neighbors(r, c):
        res = []
        for nr, nc in get_neighbors(r, c):
            e = norm_edge((r, c), (nr, nc))
            if e not in edges and e not in forbidden:
                res.append((nr, nc))
        return res

    def propagate():
        changed = True
        while changed:
            changed = False

            # 1. Degree constraints
            for r in range(R):
                for c in range(C):
                    deg = get_degree(r, c)
                    if deg > 2:
                        return False 

                    if deg == 2:
                        for nr, nc in get_neighbors(r, c):
                            e = norm_edge((r, c), (nr, nc))
                            if e not in edges:
                                if e not in forbidden:
                                    forbidden.add(e)
                                    changed = True

                    if deg == 1:
                        avail = get_available_neighbors(r, c)
                        if not avail:
                            # Node has degree 1 but no way to extend -> contradiction
                            # Unless it's an endpoint, but loop has no endpoints.
                            return False

            # 2. Clue Constraints
            for (r, c), ctype in clues.items():
                deg = get_degree(r, c)
                active = get_active_neighbors(r, c)

                if ctype == 'B':
                    # Black: Turn at circle. Straight before/after.
                    if deg == 2:
                        (r1, c1), (r2, c2) = active
                        # Check perpendicular
                        is_perp = (r1 != r2) and (c1 != c2)
                        if not is_perp:
                            return False 

                        # Check straight rule for both active neighbors
                        for nr, nc in active:
                            dr, dc = nr - r, nc - c
                            nnr, nnc = nr + dr, nc + dc
                            if 0 <= nnr < R and 0 <= nnc < C:
                                e_ext = norm_edge((nr, nc), (nnr, nnc))
                                if e_ext not in edges:
                                    if e_ext in forbidden:
                                        return False
                                    edges.add(e_ext)
                                    changed = True
                            else:
                                return False 

                    if deg == 1:
                        (nr, nc) = active[0]
                        dr, dc = nr - r, nc - c
                        # Straight extension for existing edge
                        nnr, nnc = nr + dr, nc + dc
                        if 0 <= nnr < R and 0 <= nnc < C:
                            e_ext = norm_edge((nr, nc), (nnr, nnc))
                            if e_ext not in edges:
                                if e_ext in forbidden:
                                    return False
                                edges.add(e_ext)
                                changed = True
                        else:
                            return False 

                        # Need perpendicular edge
                        perp_dirs = []
                        if dr != 0: perp_dirs = [(0, 1), (0, -1)]
                        else: perp_dirs = [(1, 0), (-1, 0)]

                        avail_perp = []
                        for pdr, pdc in perp_dirs:
                            pr, pc = r + pdr, c + pdc
                            if 0 <= pr < R and 0 <= pc < C:
                                e_perp = norm_edge((r, c), (pr, pc))
                                if e_perp not in edges and e_perp not in forbidden:
                                    avail_perp.append((pr, pc))

                        if len(avail_perp) == 0:
                            return False
                        if len(avail_perp) == 1:
                            pr, pc = avail_perp[0]
                            e_perp = norm_edge((r, c), (pr, pc))
                            edges.add(e_perp)
                            changed = True
                            # Straight rule for new edge
                            dr2, dc2 = pr - r, pc - c
                            nnr2, nnc2 = pr + dr2, pc + dc2
                            if 0 <= nnr2 < R and 0 <= nnc2 < C:
                                e_ext2 = norm_edge((pr, pc), (nnr2, nnc2))
                                if e_ext2 not in edges:
                                    if e_ext2 in forbidden:
                                        return False
                                    edges.add(e_ext2)
                                    changed = True
                            else:
                                return False

                elif ctype == 'W':
                    # White: Straight through. Turn prev or next.
                    if deg == 2:
                        (r1, c1), (r2, c2) = active
                        is_coll = (r1 == r2) or (c1 == c2)
                        is_opp = ((r1 - r) * (r2 - r) < 0) or ((c1 - c) * (c2 - c) < 0)
                        if not (is_coll and is_opp):
                            return False

                        # Check turn rule: NOT (straight prev AND straight next)
                        ext1_active = False
                        ext2_active = False

                        nr1, nc1 = active[0]
                        dr1, dc1 = nr1 - r, nc1 - c
                        nnr1, nnc1 = nr1 + dr1, nc1 + dc1
                        if 0 <= nnr1 < R and 0 <= nnc1 < C:
                            if norm_edge((nr1, nc1), (nnr1, nnc1)) in edges:
                                ext1_active = True

                        nr2, nc2 = active[1]
                        dr2, dc2 = nr2 - r, nc2 - c
                        nnr2, nnc2 = nr2 + dr2, nc2 + dc2
                        if 0 <= nnr2 < R and 0 <= nnc2 < C:
                            if norm_edge((nr2, nc2), (nnr2, nnc2)) in edges:
                                ext2_active = True

                        if ext1_active and ext2_active:
                            return False 

                    if deg == 1:
                        (nr, nc) = active[0]
                        dr, dc = nr - r, nc - c
                        opp_r, opp_c = r - dr, c - dc
                        if 0 <= opp_r < R and 0 <= opp_c < C:
                            e_opp = norm_edge((r, c), (opp_r, opp_c))
                            if e_opp not in forbidden:
                                edges.add(e_opp)
                                changed = True
                            else:
                                return False
                        else:
                            return False

            # 3. Cycle Detection (Small loops)
            adj = {}
            for u, v in edges:
                if u not in adj: adj[u] = []
                if v not in adj: adj[v] = []
                adj[u].append(v)
                adj[v].append(u)

            visited_global = set()
            for start_node in adj:
                if start_node in visited_global: continue
                component_nodes = set()
                queue = [start_node]
                visited_global.add(start_node)
                is_cycle = True
                while queue:
                    u = queue.pop(0)
                    component_nodes.add(u)
                    if len(adj[u]) != 2:
                        is_cycle = False 
                    for v in adj[u]:
                        if v not in visited_global:
                            visited_global.add(v)
                            queue.append(v)

                if is_cycle:
                    clues_in_component = all(clue in component_nodes for clue in clues)
                    if not clues_in_component:
                        return False

            # 4. Connectivity / Isolation check (Optional but good)
            # If a node has degree 2, it's part of the loop.
            # If a node has degree 0, it's not.
            # If we have a component that is a path (ends with degree 1), it's fine.

        return True

    def is_solved():
        for clue in clues:
            if get_degree(*clue) != 2:
                return False

        if not edges: return False

        adj = {}
        for u, v in edges:
            if u not in adj: adj[u] = []
            if v not in adj: adj[v] = []
            adj[u].append(v)
            adj[v].append(u)

        for u in adj:
            if len(adj[u]) != 2:
                return False

        start = list(adj.keys())[0]
        visited = set()
        queue = [start]
        visited.add(start)
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)

        if len(visited) != len(adj):
            return False 

        for clue in clues:
            if clue not in visited:
                return False

        return True

    def get_best_move():
        # Prioritize clues
        for (r, c), ctype in clues.items():
            deg = get_degree(r, c)
            if deg < 2:
                avail = get_available_neighbors(r, c)
                if avail:
                    return ((r, c), avail[0])

        # Prioritize degree 1 nodes
        for r in range(R):
            for c in range(C):
                if get_degree(r, c) == 1:
                    avail = get_available_neighbors(r, c)
                    if avail:
                        return ((r, c), avail[0])

        # Any available edge
        for r in range(R):
            for c in range(C):
                for nr, nc in get_neighbors(r, c):
                    e = norm_edge((r, c), (nr, nc))
                    if e not in edges and e not in forbidden:
                        return ((r, c), (nr, nc))
        return None

    def backtrack():
        if not propagate():
            return None

        if is_solved():
            adj = {}
            for u, v in edges:
                if u not in adj: adj[u] = []
                if v not in adj: adj[v] = []
                adj[u].append(v)
                adj[v].append(u)

            start = list(adj.keys())[0]
            path = [start]
            curr = start
            prev = None
            while True:
                neighbors = adj[curr]
                next_node = None
                for n in neighbors:
                    if n != prev:
                        next_node = n
                        break
                if next_node is None: break
                path.append(next_node)
                prev = curr
                curr = next_node
                if curr == start:
                    break
            return path

        move = get_best_move()
        if move is None:
            return None 

        u, v = move
        e = norm_edge(u, v)

        # Try adding edge
        edges.add(e)
        res = backtrack()
        if res: return res
        edges.remove(e)

        # Try forbidding edge
        forbidden.add(e)
        res = backtrack()
        if res: return res
        forbidden.remove(e)

        return None

    result = backtrack()
    if result:
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
