OBSERVATION = {'data': [[3, None, None, None, None, None, 3], [1, 2, 1, None, 1, 2, None], [2, 3, None, 2, None, None, 2], [3, None, None, 2, None, None, None], [None, 2, None, None, 3, None, 2], [None, None, None, 3, None, None, 3], [None, 2, None, 3, 2, 2, None]]}
import sys
sys.setrecursionlimit(10000)

def solve(observation):
    data = observation['data']
    R_clues = len(data)
    C_clues = len(data[0])

    R_dots = R_clues + 1
    C_dots = C_clues + 1

    # H[r][c]: horizontal edge at row r, between col c and c+1. Size: R_dots x C_clues
    # V[r][c]: vertical edge at col c, between row r and r+1. Size: R_clues x C_dots
    # Values: -1 (Unknown), 0 (No), 1 (Yes)
    H = [[-1] * C_clues for _ in range(R_dots)]
    V = [[-1] * C_dots for _ in range(R_clues)]

    def get_clue_edges_refs(r, c):
        # Top, Bottom, Left, Right
        return [('H', r, c), ('H', r+1, c), ('V', r, c), ('V', r, c+1)]

    def get_vertex_edges_refs(r, c):
        edges = []
        if r > 0: edges.append(('V', r-1, c)) # Top
        if r < R_clues: edges.append(('V', r, c)) # Bottom
        if c > 0: edges.append(('H', r, c-1)) # Left
        if c < C_clues: edges.append(('H', r, c)) # Right
        return edges

    def set_edge(type_, r, c, val):
        if type_ == 'H':
            if H[r][c] != -1 and H[r][c] != val:
                return False
            H[r][c] = val
        else:
            if V[r][c] != -1 and V[r][c] != val:
                return False
            V[r][c] = val
        return True

    def propagate():
        while True:
            made_change = False

            # 1. Clue Constraints
            for r in range(R_clues):
                for c in range(C_clues):
                    clue = data[r][c]
                    if clue is None: continue

                    edge_refs = get_clue_edges_refs(r, c)
                    known_lines = 0
                    unknowns = []
                    for t, tr, tc in edge_refs:
                        val = H[tr][tc] if t == 'H' else V[tr][tc]
                        if val == 1:
                            known_lines += 1
                        elif val == -1:
                            unknowns.append((t, tr, tc))

                    if known_lines == clue:
                        for t, tr, tc in unknowns:
                            if (t == 'H' and H[tr][tc] == -1) or (t == 'V' and V[tr][tc] == -1):
                                if not set_edge(t, tr, tc, 0): return False
                                made_change = True
                    elif known_lines + len(unknowns) == clue:
                        for t, tr, tc in unknowns:
                            if (t == 'H' and H[tr][tc] == -1) or (t == 'V' and V[tr][tc] == -1):
                                if not set_edge(t, tr, tc, 1): return False
                                made_change = True

            # 2. Vertex Degree Constraints
            for r in range(R_dots):
                for c in range(C_dots):
                    edge_refs = get_vertex_edges_refs(r, c)
                    known_lines = 0
                    unknowns = []
                    for t, tr, tc in edge_refs:
                        val = H[tr][tc] if t == 'H' else V[tr][tc]
                        if val == 1:
                            known_lines += 1
                        elif val == -1:
                            unknowns.append((t, tr, tc))

                    if known_lines == 2:
                        for t, tr, tc in unknowns:
                            if (t == 'H' and H[tr][tc] == -1) or (t == 'V' and V[tr][tc] == -1):
                                if not set_edge(t, tr, tc, 0): return False
                                made_change = True
                    elif known_lines == 1 and len(unknowns) == 1:
                        t, tr, tc = unknowns[0]
                        if (t == 'H' and H[tr][tc] == -1) or (t == 'V' and V[tr][tc] == -1):
                            if not set_edge(t, tr, tc, 1): return False
                            made_change = True

            if not made_change:
                break
        return True

    def is_complete():
        for r in range(R_dots):
            for c in range(C_clues):
                if H[r][c] == -1: return False
        for r in range(R_clues):
            for c in range(C_dots):
                if V[r][c] == -1: return False
        return True

    def check_cycles():
        p = list(range(R_dots * C_dots))
        def f(i):
            while p[i] != i:
                p[i] = p[p[i]]
                i = p[i]
            return i

        def u(i, j):
            ri, rj = f(i), f(j)
            if ri == rj: return False
            p[ri] = rj
            return True

        has_cycle = False
        for r in range(R_dots):
            for c in range(C_clues):
                if H[r][c] == 1:
                    u1 = r * C_dots + c
                    u2 = r * C_dots + c + 1
                    if not u(u1, u2):
                        has_cycle = True

        for r in range(R_clues):
            for c in range(C_dots):
                if V[r][c] == 1:
                    u1 = r * C_dots + c
                    u2 = (r + 1) * C_dots + c
                    if not u(u1, u2):
                        has_cycle = True

        complete = is_complete()

        if has_cycle:
            if not complete:
                return False # Small loop

            # Check single component
            degrees = [0] * (R_dots * C_dots)
            for r in range(R_dots):
                for c in range(C_clues):
                    if H[r][c] == 1:
                        degrees[r*C_dots+c] += 1
                        degrees[r*C_dots+c+1] += 1
            for r in range(R_clues):
                for c in range(C_dots):
                    if V[r][c] == 1:
                        degrees[r*C_dots+c] += 1
                        degrees[(r+1)*C_dots+c] += 1

            start_node = -1
            for i in range(len(degrees)):
                if degrees[i] > 0:
                    start_node = i
                    break

            if start_node == -1:
                return False 

            visited = set()
            stack = [start_node]
            visited.add(start_node)
            while stack:
                u = stack.pop()
                r, c = divmod(u, C_dots)
                if c > 0 and H[r][c-1] == 1:
                    v = u - 1
                    if v not in visited: visited.add(v); stack.append(v)
                if c < C_clues and H[r][c] == 1:
                    v = u + 1
                    if v not in visited: visited.add(v); stack.append(v)
                if r > 0 and V[r-1][c] == 1:
                    v = u - C_dots
                    if v not in visited: visited.add(v); stack.append(v)
                if r < R_clues and V[r][c] == 1:
                    v = u + C_dots
                    if v not in visited: visited.add(v); stack.append(v)

            for i in range(len(degrees)):
                if degrees[i] > 0 and i not in visited:
                    return False 

            return True

        else:
            if complete:
                return False 
            return True 

    def get_next_unknown():
        for r in range(R_dots):
            for c in range(C_clues):
                if H[r][c] == -1: return ('H', r, c)
        for r in range(R_clues):
            for c in range(C_dots):
                if V[r][c] == -1: return ('V', r, c)
        return None

    def backtrack():
        if not check_cycles():
            return False

        if not propagate():
            return False

        if not check_cycles(): 
            return False

        nxt = get_next_unknown()
        if nxt is None:
            return True

        t, r, c = nxt

        H_backup = [row[:] for row in H]
        V_backup = [row[:] for row in V]

        # Try 1
        if t == 'H': H[r][c] = 1
        else: V[r][c] = 1

        if backtrack():
            return True

        for i in range(R_dots): H[i] = H_backup[i][:]
        for i in range(R_clues): V[i] = V_backup[i][:]

        # Try 0
        if t == 'H': H[r][c] = 0
        else: V[r][c] = 0

        if backtrack():
            return True

        for i in range(R_dots): H[i] = H_backup[i][:]
        for i in range(R_clues): V[i] = V_backup[i][:]

        return False

    if not propagate():
        return "No Solution"

    if backtrack():
        start_r, start_c = -1, -1
        for r in range(R_dots):
            for c in range(C_dots):
                deg = 0
                if c < C_clues and H[r][c] == 1: deg += 1
                if c > 0 and H[r][c-1] == 1: deg += 1
                if r < R_clues and V[r][c] == 1: deg += 1
                if r > 0 and V[r-1][c] == 1: deg += 1
                if deg == 2:
                    start_r, start_c = r, c
                    break
            if start_r != -1: break

        if start_r == -1:
            return "No Solution"

        path = [(start_r, start_c)]
        curr_r, curr_c = start_r, start_c
        prev_r, prev_c = -1, -1

        while True:
            neighbors = []
            if curr_c < C_clues and H[curr_r][curr_c] == 1:
                neighbors.append((curr_r, curr_c + 1))
            if curr_c > 0 and H[curr_r][curr_c - 1] == 1:
                neighbors.append((curr_r, curr_c - 1))
            if curr_r < R_clues and V[curr_r][curr_c] == 1:
                neighbors.append((curr_r + 1, curr_c))
            if curr_r > 0 and V[curr_r - 1][curr_c] == 1:
                neighbors.append((curr_r - 1, curr_c))

            next_node = None
            for nr, nc in neighbors:
                if nr != prev_r or nc != prev_c:
                    next_node = (nr, nc)
                    break

            if next_node is None:
                break 

            path.append(next_node)
            prev_r, prev_c = curr_r, curr_c
            curr_r, curr_c = next_node

            if curr_r == start_r and curr_c == start_c:
                break

        return path

    return "No Solution"

