import sys

# Increase recursion depth to handle deep backtracking if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Count total pearls for validation
    total_pearls = 0
    for r in range(R):
        for c in range(C):
            if data[r][c] in ['W', 'B']:
                total_pearls += 1

    # Edges: h[r][c] is edge (r,c)-(r,c+1)
    # v[r][c] is edge (r,c)-(r+1,c)
    # Values: 0 (No), 1 (Yes), -1 (Unknown)
    # h dimensions: R x (C-1)
    # v dimensions: (R-1) x C
    h = [[-1] * (C - 1) for _ in range(R)]
    v = [[-1] * C for _ in range(R - 1)]

    class State:
        def __init__(self, h_init, v_init):
            self.h = [row[:] for row in h_init]
            self.v = [row[:] for row in v_init]

        def get_h(self, r, c): return self.h[r][c]
        def get_v(self, r, c): return self.v[r][c]

        def set_h(self, r, c, val):
            if self.h[r][c] != -1 and self.h[r][c] != val: return False
            self.h[r][c] = val
            return True

        def set_v(self, r, c, val):
            if self.v[r][c] != -1 and self.v[r][c] != val: return False
            self.v[r][c] = val
            return True

        def copy(self):
            return State(self.h, self.v)

    initial_state = State(h, v)

    def apply_rules(state):
        changed = True
        while changed:
            changed = False

            # 1. Degree Constraints & Pearl Constraints
            for r in range(R):
                for c in range(C):
                    edges_info = []
                    # Left: h[r][c-1]
                    if c > 0: edges_info.append(('h', c-1, state.get_h(r, c-1)))
                    # Right: h[r][c]
                    if c < C-1: edges_info.append(('h', c, state.get_h(r, c)))
                    # Up: v[r-1][c]
                    if r > 0: edges_info.append(('v', r-1, state.get_v(r-1, c)))
                    # Down: v[r][c]
                    if r < R-1: edges_info.append(('v', r, state.get_v(r, c)))

                    used_count = sum(1 for _, _, val in edges_info if val == 1)
                    unknown_edges = [(t, i) for t, i, val in edges_info if val == -1]

                    node_type = data[r][c]

                    # Rule: Max degree 2
                    if used_count > 2:
                        return False 

                    if used_count == 2:
                        for t, i in unknown_edges:
                            if t == 'h':
                                if not state.set_h(r, i, 0): return False
                            else:
                                if not state.set_v(i, c, 0): return False
                            changed = True
                        continue 

                    if used_count + len(unknown_edges) == 2:
                        for t, i in unknown_edges:
                            if t == 'h':
                                if not state.set_h(r, i, 1): return False
                            else:
                                if not state.set_v(i, c, 1): return False
                            changed = True
                        continue

                    if node_type == 'W':
                        h_used = any(t == 'h' and val == 1 for t, i, val in edges_info)
                        v_used = any(t == 'v' and val == 1 for t, i, val in edges_info)

                        if h_used and v_used:
                            return False 

                        if h_used:
                            for t, i, val in edges_info:
                                if t == 'h' and val == -1:
                                    if not state.set_h(r, i, 1): return False
                                    changed = True
                                if t == 'v' and val == -1:
                                    if not state.set_v(i, c, 0): return False
                                    changed = True
                                if t == 'v' and val == 1:
                                    return False

                        if v_used:
                            for t, i, val in edges_info:
                                if t == 'v' and val == -1:
                                    if not state.set_v(i, c, 1): return False
                                    changed = True
                                if t == 'h' and val == -1:
                                    if not state.set_h(r, i, 0): return False
                                    changed = True
                                if t == 'h' and val == 1:
                                    return False

                        h_zeros = [i for t, i, val in edges_info if t == 'h' and val == 0]
                        v_zeros = [i for t, i, val in edges_info if t == 'v' and val == 0]

                        if len(h_zeros) == 2: 
                            for t, i, val in edges_info:
                                if t == 'v' and val == -1:
                                    if not state.set_v(i, c, 1): return False
                                    changed = True
                        if len(v_zeros) == 2: 
                            for t, i, val in edges_info:
                                if t == 'h' and val == -1:
                                    if not state.set_h(r, i, 1): return False
                                    changed = True

                    elif node_type == 'B':
                        h_count = sum(1 for t, i, val in edges_info if t == 'h' and val == 1)
                        v_count = sum(1 for t, i, val in edges_info if t == 'v' and val == 1)

                        if h_count == 2 or v_count == 2:
                            return False 

                        for t, i, val in edges_info:
                            if val == 1:
                                if t == 'h':
                                    if i == c: # Right
                                        if c + 1 < C - 1:
                                            if state.get_h(r, c+1) == 0: return False
                                            if state.get_h(r, c+1) == -1:
                                                if not state.set_h(r, c+1, 1): return False
                                                changed = True
                                            if r > 0:
                                                if state.get_v(r-1, c+1) == 1: return False
                                                if state.get_v(r-1, c+1) == -1:
                                                    if not state.set_v(r-1, c+1, 0): return False
                                                    changed = True
                                            if r < R - 1:
                                                if state.get_v(r, c+1) == 1: return False
                                                if state.get_v(r, c+1) == -1:
                                                    if not state.set_v(r, c+1, 0): return False
                                                    changed = True
                                    elif i == c - 1: # Left
                                        if c - 2 >= 0:
                                            if state.get_h(r, c-2) == 0: return False
                                            if state.get_h(r, c-2) == -1:
                                                if not state.set_h(r, c-2, 1): return False
                                                changed = True
                                            if r > 0:
                                                if state.get_v(r-1, c-1) == 1: return False
                                                if state.get_v(r-1, c-1) == -1:
                                                    if not state.set_v(r-1, c-1, 0): return False
                                                    changed = True
                                            if r < R - 1:
                                                if state.get_v(r, c-1) == 1: return False
                                                if state.get_v(r, c-1) == -1:
                                                    if not state.set_v(r, c-1, 0): return False
                                                    changed = True
                                elif t == 'v':
                                    if i == r: # Down
                                        if r + 1 < R - 1:
                                            if state.get_v(r+1, c) == 0: return False
                                            if state.get_v(r+1, c) == -1:
                                                if not state.set_v(r+1, c, 1): return False
                                                changed = True
                                            if c > 0:
                                                if state.get_h(r+1, c-1) == 1: return False
                                                if state.get_h(r+1, c-1) == -1:
                                                    if not state.set_h(r+1, c-1, 0): return False
                                                    changed = True
                                            if c < C - 1:
                                                if state.get_h(r+1, c) == 1: return False
                                                if state.get_h(r+1, c) == -1:
                                                    if not state.set_h(r+1, c, 0): return False
                                                    changed = True
                                    elif i == r - 1: # Up
                                        if r - 2 >= 0:
                                            if state.get_v(r-2, c) == 0: return False
                                            if state.get_v(r-2, c) == -1:
                                                if not state.set_v(r-2, c, 1): return False
                                                changed = True
                                            if c > 0:
                                                if state.get_h(r-1, c-1) == 1: return False
                                                if state.get_h(r-1, c-1) == -1:
                                                    if not state.set_h(r-1, c-1, 0): return False
                                                    changed = True
                                            if c < C - 1:
                                                if state.get_h(r-1, c) == 1: return False
                                                if state.get_h(r-1, c) == -1:
                                                    if not state.set_h(r-1, c, 0): return False
                                                    changed = True

            # 2. Connectivity / Sub-loop check
            adj = [[] for _ in range(R*C)]
            for r in range(R):
                for c in range(C-1):
                    if state.get_h(r, c) == 1:
                        u, v_node = r * C + c, r * C + c + 1
                        adj[u].append(v_node)
                        adj[v_node].append(u)
            for r in range(R-1):
                for c in range(C):
                    if state.get_v(r, c) == 1:
                        u, v_node = r * C + c, (r + 1) * C + c
                        adj[u].append(v_node)
                        adj[v_node].append(u)

            visited = [False] * (R*C)
            for i in range(R*C):
                if not visited[i] and len(adj[i]) > 0:
                    comp = []
                    stack = [i]
                    visited[i] = True
                    while stack:
                        u = stack.pop()
                        comp.append(u)
                        for neighbor in adj[u]:
                            if not visited[neighbor]:
                                visited[neighbor] = True
                                stack.append(neighbor)

                    edges_in_comp = 0
                    for u in comp:
                        edges_in_comp += len(adj[u])
                    edges_in_comp //= 2

                    if edges_in_comp == len(comp):
                        pearls_in_comp = 0
                        for u in comp:
                            r, c = divmod(u, C)
                            if data[r][c] in ['W', 'B']:
                                pearls_in_comp += 1

                        if pearls_in_comp < total_pearls:
