                                    if c > 0 and state.get_h(r, c-1) == -1: has_unknown = True
                                    if c < C-1 and state.get_h(r, c) == -1: has_unknown = True
                                    if r > 0 and state.get_v(r-1, c) == -1: has_unknown = True
                                    if r < R-1 and state.get_v(r, c) == -1: has_unknown = True
                                    if not has_unknown:
                                        return False
        return True

    def solve_recursive(state):
        if not apply_rules(state):
            return None

        all_pearls_deg_2 = True
        for r in range(R):
            for c in range(C):
                if data[r][c] in ['W', 'B']:
                    deg = 0
                    if c > 0 and state.get_h(r, c-1) == 1: deg += 1
                    if c < C-1 and state.get_h(r, c) == 1: deg += 1
                    if r > 0 and state.get_v(r-1, c) == 1: deg += 1
                    if r < R-1 and state.get_v(r, c) == 1: deg += 1
                    if deg != 2:
                        all_pearls_deg_2 = False
                        break
            if not all_pearls_deg_2: break

        if all_pearls_deg_2:
            has_unknown = False
            for r in range(R):
                for c in range(C-1):
                    if state.get_h(r, c) == -1: has_unknown = True
            for r in range(R-1):
                for c in range(C):
                    if state.get_v(r, c) == -1: has_unknown = True

            if not has_unknown:
                start_r, start_c = -1, -1
                for r in range(R):
                    for c in range(C):
                        if data[r][c] in ['W', 'B']:
                            start_r, start_c = r, c
                            break
                    if start_r != -1: break

                path = []
                curr_r, curr_c = start_r, start_c
                prev_r, prev_c = -1, -1

                found_start = False
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        is_conn = False
                        if dr == 0:
                            c_min = min(curr_c, nc)
                            if state.get_h(curr_r, c_min) == 1: is_conn = True
                        else:
                            r_min = min(curr_r, nr)
                            if state.get_v(r_min, curr_c) == 1: is_conn = True

                        if is_conn:
