                            prev_r, prev_c = curr_r, curr_c
                            curr_r, curr_c = nr, nc
                            found_start = True
                            break

                if not found_start:
                    return None 

                while (curr_r, curr_c) != (start_r, start_c):
                    path.append((curr_r, curr_c))
                    found_next = False
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if nr == prev_r and nc == prev_c: continue
                        if 0 <= nr < R and 0 <= nc < C:
                            is_conn = False
                            if dr == 0:
                                c_min = min(curr_c, nc)
                                if state.get_h(curr_r, c_min) == 1: is_conn = True
                            else:
                                r_min = min(curr_r, nr)
                                if state.get_v(r_min, curr_c) == 1: is_conn = True

                            if is_conn:
                                prev_r, prev_c = curr_r, curr_c
                                curr_r, curr_c = nr, nc
                                found_next = True
                                break
                    if not found_next:
                        return None 

                path.append((start_r, start_c))
                return path

        found_branch = False
        branch_r, branch_c, branch_type = -1, -1, ''

        for r in range(R):
            for c in range(C-1):
                if state.get_h(r, c) == -1:
                    branch_r, branch_c, branch_type = r, c, 'h'
                    found_branch = True
                    break
            if found_branch: break

        if not found_branch:
            for r in range(R-1):
                for c in range(C):
                    if state.get_v(r, c) == -1:
                        branch_r, branch_c, branch_type = r, c, 'v'
                        found_branch = True
                        break
                if found_branch: break

        if not found_branch:
            return None 

        state_yes = state.copy()
        if branch_type == 'h':
            ok = state_yes.set_h(branch_r, branch_c, 1)
        else:
            ok = state_yes.set_v(branch_r, branch_c, 1)

        if ok:
            res = solve_recursive(state_yes)
            if res: return res

        state_no = state.copy()
        if branch_type == 'h':
            ok = state_no.set_h(branch_r, branch_c, 0)
        else:
            ok = state_no.set_v(branch_r, branch_c, 0)

        if ok:
            res = solve_recursive(state_no)
            if res: return res

        return None

    result = solve_recursive(initial_state)
    if result:
        return result
    return "No Solution"

