def solve(observation):
    data = observation['data']
    adjacent_list = observation['adjacent']

    N = len(data)

    # Parse adjacent dots into a set of frozensets for easy lookup
    # A dot at (r, c+0.5) connects (r, c) and (r, c+1)
    # A dot at (r+0.5, c) connects (r, c) and (r+1, c)
    dots = set()

    for coord in adjacent_list:
        r, c = coord
        if r == int(r): # Horizontal gap: (row, col+0.5)
            # Connects (r, int(c)) and (r, int(c)+1)
            # c is like 0.5, 1.5... so int(c) is the left cell col
            c_int = int(c)
            dots.add(((r, c_int), (r, c_int + 1)))
            dots.add(((r, c_int + 1), (r, c_int)))
        else: # Vertical gap: (row+0.5, col)
            # Connects (int(r), c) and (int(r)+1, c)
            r_int = int(r)
            dots.add(((r_int, c), (r_int + 1, c)))
            dots.add(((r_int + 1, c), (r_int, c)))

    # Initialize domains
    # domains[r][c] is a set of possible values
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Apply initial clues
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                domains[r][c] = {val}

    # Helper to get neighbors
    def get_neighbors(r, c):
        neighs = []
        if r > 0: neighs.append((r-1, c))
        if r < N - 1: neighs.append((r+1, c))
        if c > 0: neighs.append((r, c-1))
        if c < N - 1: neighs.append((r, c+1))
        return neighs

    # Constraint Propagation
    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1. Row and Column uniqueness (AllDifferent)
            # If a cell has a single value, remove it from peers
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        # Row peers
                        for k in range(N):
                            if k != c:
                                if val in domains[r][k]:
                                    domains[r][k].discard(val)
                                    changed = True
                        # Col peers
                        for k in range(N):
                            if k != r:
                                if val in domains[k][c]:
                                    domains[k][c].discard(val)
                                    changed = True

            # 2. Adjacency constraints
            for r in range(N):
                for c in range(N):
                    current_domain = domains[r][c]
                    if not current_domain: return False # Failure

                    neighbors = get_neighbors(r, c)
                    for nr, nc in neighbors:
                        neighbor_domain = domains[nr][nc]
                        if not neighbor_domain: return False # Failure

                        has_dot = ((r, c), (nr, nc)) in dots

                        # Prune current domain based on neighbor
                        new_current = set()
                        for val in current_domain:
                            valid = False
                            for n_val in neighbor_domain:
                                if has_dot:
                                    if abs(val - n_val) == 1:
                                        valid = True
                                        break
                                else:
                                    if abs(val - n_val) != 1:
                                        valid = True
                                        break
                            if valid:
                                new_current.add(val)

                        if len(new_current) < len(current_domain):
                            domains[r][c] = new_current
                            changed = True
                            if not new_current: return False

                        # Prune neighbor domain based on current
                        new_neighbor = set()
                        for n_val in neighbor_domain:
                            valid = False
                            for val in current_domain: # Use current (possibly updated) domain
                                if has_dot:
                                    if abs(val - n_val) == 1:
                                        valid = True
                                        break
                                else:
                                    if abs(val - n_val) != 1:
                                        valid = True
                                        break
                            if valid:
                                new_neighbor.add(n_val)

                        if len(new_neighbor) < len(neighbor_domain):
                            domains[nr][nc] = new_neighbor
                            changed = True
                            if not new_neighbor: return False

        return True

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    # Backtracking Search
    # Find unassigned cell with MRV
    def get_unassigned(domains):
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_len:
                        min_len = len(domains[r][c])
                        best_cell = (r, c)
        return best_cell

    def solve_recursive(domains):
        # Check if solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) != 1:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        cell = get_unassigned(domains)
        if cell is None:
            # Should be solved if no unassigned with >1 domain
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        r, c = cell
        # Try values. Heuristic: try values that constrain neighbors least? 
        # Or just sorted.
        for val in sorted(list(domains[r][c])):
            # Create copy
            new_domains = [row[:] for row in domains] # Shallow copy of rows
            new_domains[r] = [set(s) for s in domains[r]] # Deep copy of the row sets? No, need to copy the set at (r,c)
            # Actually, simpler deep copy for the specific cell
            # But propagate modifies domains in place. So we need a full copy or undo.
            # Given N=9, full copy is acceptable.

            # Let's do a proper copy
            copy_domains = [[set(s) for s in row] for row in domains]
            copy_domains[r][c] = {val}

            if propagate(copy_domains):
                result = solve_recursive(copy_domains)
                if result:
                    return result

        return None

    final_grid = solve_recursive(domains)
    if final_grid:
        return final_grid
    return "No Solution"

