import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    islands = []
    island_map = {} 

    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                idx = len(islands)
                islands.append({'r': r, 'c': c, 'val': data[r][c], 'current': 0})
                island_map[(r, c)] = idx

    n_islands = len(islands)
    if n_islands == 0:
        return {}

    # Precompute potential neighbors (visible in 4 directions)
    potential_neighbors = [[] for _ in range(n_islands)]

    for i in range(n_islands):
        r1, c1 = islands[i]['r'], islands[i]['c']
        # Up
        for r in range(r1 - 1, -1, -1):
            if data[r][c1] is not None:
                potential_neighbors[i].append(island_map[(r, c1)])
                break
        # Down
        for r in range(r1 + 1, rows):
            if data[r][c1] is not None:
                potential_neighbors[i].append(island_map[(r, c1)])
                break
        # Left
        for c in range(c1 - 1, -1, -1):
            if data[r1][c] is not None:
                potential_neighbors[i].append(island_map[(r1, c)])
                break
        # Right
        for c in range(c1 + 1, cols):
            if data[r1][c] is not None:
                potential_neighbors[i].append(island_map[(r1, c)])
                break

    # Identify all potential connections (i, j) with i < j
    potential_connections = []
    for i in range(n_islands):
        for j in potential_neighbors[i]:
            if i < j:
                potential_connections.append((i, j))

    M = len(potential_connections)
    conn_to_idx = {conn: idx for idx, conn in enumerate(potential_connections)}
    conn_islands = list(potential_connections)

    # Map island to connections
    island_connections = [[] for _ in range(n_islands)]
    for idx, (i, j) in enumerate(potential_connections):
        island_connections[i].append(idx)
        island_connections[j].append(idx)

    # Identify crossing conflicts
    # Two connections (i, j) and (k, l) cross if one is horizontal, one vertical, and segments intersect
    crossing_conflicts = {} 

    for idx1, (i, j) in enumerate(potential_connections):
        r1, c1 = islands[i]['r'], islands[i]['c']
        r2, c2 = islands[j]['r'], islands[j]['c']
        is_horiz_1 = (r1 == r2)

        for idx2, (k, l) in enumerate(potential_connections):
            if idx1 >= idx2: continue
            r3, c3 = islands[k]['r'], islands[k]['c']
            r4, c4 = islands[l]['r'], islands[l]['c']
            is_horiz_2 = (r3 == r4)

            if is_horiz_1 == is_horiz_2: continue

            # Determine horizontal and vertical segments
            if is_horiz_1:
                h_r, h_c_min, h_c_max = r1, min(c1, c2), max(c1, c2)
                v_c, v_r_min, v_r_max = c3, min(r3, r4), max(r3, r4)
            else:
                h_r, h_c_min, h_c_max = r3, min(c3, c4), max(c3, c4)
                v_c, v_r_min, v_r_max = c1, min(r1, r2), max(r1, r2)

            # Check intersection (strictly between endpoints)
            if v_r_min < h_r < v_r_max and h_c_min < v_c < h_c_max:
                key1 = (i, j)
                key2 = (k, l)
                if key1 not in crossing_conflicts: crossing_conflicts[key1] = []
                if key2 not in crossing_conflicts: crossing_conflicts[key2] = []
                crossing_conflicts[key1].append(key2)
                crossing_conflicts[key2].append(key1)

    conn_conflicts = [[] for _ in range(M)]
    for (i, j), conflicts in crossing_conflicts.items():
        idx1 = conn_to_idx[(i, j)]
        for (k, l) in conflicts:
            idx2 = conn_to_idx[(k, l)]
            conn_conflicts[idx1].append(idx2)

    target_degrees = [isl['val'] for isl in islands]

    # State
    values = [-1] * M # -1: unassigned, 0, 1, 2: bridges
    current_degrees = [0] * n_islands

    def is_valid_state(vals, degs):
        for i in range(n_islands):
            if degs[i] > target_degrees[i]:
                return False
            max_add = 0
            for conn_idx in island_connections[i]:
                if vals[conn_idx] == -1:
                    # Check if forced 0 by crossing
                    forced_zero = False
                    for c_idx in conn_conflicts[conn_idx]:
                        if vals[c_idx] > 0:
                            forced_zero = True
                            break
                    if not forced_zero:
                        max_add += 2
            if degs[i] + max_add < target_degrees[i]:
                return False
        return True

    def is_complete(vals, degs):
        for i in range(n_islands):
            if degs[i] != target_degrees[i]:
                return False
        for v in vals:
            if v == -1:
                return False
        return True

    def check_connectivity(vals):
        adj = [[] for _ in range(n_islands)]
        for idx, count in enumerate(vals):
            if count > 0:
                i, j = conn_islands[idx]
                adj[i].append(j)
                adj[j].append(i)

        visited = [False] * n_islands
        queue = [0]
        visited[0] = True
        count = 1
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    count += 1
                    queue.append(v)
        return count == n_islands

    def propagate(vals, degs):
        # Returns (vals, degs, success)
        # Modifies vals and degs in place (lists are mutable)
        changed = True
        while changed:
            changed = False
            for i in range(n_islands):
                if degs[i] == target_degrees[i]:
                    for conn_idx in island_connections[i]:
                        if vals[conn_idx] == -1:
                            vals[conn_idx] = 0
                            changed = True
                        elif vals[conn_idx] > 0:
                            return None, None, False
                else:
                    need = target_degrees[i] - degs[i]
                    available = []
                    for conn_idx in island_connections[i]:
                        if vals[conn_idx] == -1:
                            forced_zero = False
                            for c_idx in conn_conflicts[conn_idx]:
                                if vals[c_idx] > 0:
                                    forced_zero = True
                                    break
                            if not forced_zero:
                                available.append(conn_idx)
                        elif vals[conn_idx] > 0:
                            pass 

                    if len(available) == 0:
                        if need > 0:
                            return None, None, False
                    else:
                        if need == len(available):
                            for conn_idx in available:
                                if vals[conn_idx] == -1:
                                    vals[conn_idx] = 1
                                    j = conn_islands[conn_idx][1] if conn_islands[conn_idx][0] == i else conn_islands[conn_idx][0]
                                    degs[i] += 1
                                    degs[j] += 1
                                    changed = True
                                    for c_idx in conn_conflicts[conn_idx]:
                                        if vals[c_idx] == -1:
                                            vals[c_idx] = 0
                                            changed = True
                                        elif vals[c_idx] > 0:
                                            return None, None, False
                                elif vals[conn_idx] != 1:
                                    return None, None, False

                        if need == 2 * len(available):
                            for conn_idx in available:
                                if vals[conn_idx] == -1:
                                    vals[conn_idx] = 2
                                    j = conn_islands[conn_idx][1] if conn_islands[conn_idx][0] == i else conn_islands[conn_idx][0]
                                    degs[i] += 2
                                    degs[j] += 2
                                    changed = True
                                    for c_idx in conn_conflicts[conn_idx]:
                                        if vals[c_idx] == -1:
                                            vals[c_idx] = 0
                                            changed = True
                                        elif vals[c_idx] > 0:
                                            return None, None, False
                                elif vals[conn_idx] != 2:
                                    return None, None, False
        return vals, degs, True

    def get_next_variable(vals, degs):
        best_island = -1
        min_options = 1000

        for i in range(n_islands):
            if degs[i] < target_degrees[i]:
                unassigned = 0
                for conn_idx in island_connections[i]:
                    if vals[conn_idx] == -1:
                        forced_zero = False
                        for c_idx in conn_conflicts[conn_idx]:
                            if vals[c_idx] > 0:
                                forced_zero = True
                                break
                        if not forced_zero:
                            unassigned += 1

                if unassigned < min_options:
                    min_options = unassigned
                    best_island = i

        if best_island == -1:
            return None

        for conn_idx in island_connections[best_island]:
            if vals[conn_idx] == -1:
                forced_zero = False
                for c_idx in conn_conflicts[conn_idx]:
                    if vals[c_idx] > 0:
                        forced_zero = True
                        break
                if not forced_zero:
                    return conn_idx
        return None

    def solve_recursive(vals, degs):
        vals, degs, success = propagate(vals, degs)
        if not success:
            return None

        if not is_valid_state(vals, degs):
            return None

        if is_complete(vals, degs):
            if check_connectivity(vals):
                return vals
            else:
                return None

        conn_idx = get_next_variable(vals, degs)
        if conn_idx is None:
            if is_complete(vals, degs):
                if check_connectivity(vals): return vals
            return None

        i, j = conn_islands[conn_idx]

        # Check if forced zero by crossing
        forced_zero = False
        for c_idx in conn_conflicts[conn_idx]:
            if vals[c_idx] > 0:
                forced_zero = True
                break

        if forced_zero:
            new_vals = list(vals)
            new_vals[conn_idx] = 0
            res = solve_recursive(new_vals, list(degs))
            return res

        candidates = []
        if degs[i] + 2 <= target_degrees[i] and degs[j] + 2 <= target_degrees[j]:
            candidates.append(2)
        if degs[i] + 1 <= target_degrees[i] and degs[j] + 1 <= target_degrees[j]:
            candidates.append(1)
        candidates.append(0)

        # Heuristic order
        need_i = target_degrees[i] - degs[i]
        need_j = target_degrees[j] - degs[j]

        if need_i > 2 or need_j > 2:
            candidates.sort(reverse=True)
        else:
            if 1 in candidates:
                candidates.remove(1)
                candidates.insert(0, 1)

        for val in candidates:
            if val == 0:
                # Pruning: check if 0 makes it impossible to satisfy degrees
                avail_i = 0
                for idx in island_connections[i]:
                    if idx == conn_idx: continue
                    if vals[idx] == -1:
                         is_crossed = False
                         for c_idx in conn_conflicts[idx]:
                             if vals[c_idx] > 0:
                                 is_crossed = True
                                 break
                         if not is_crossed:
                             avail_i += 1
                max_add_i = avail_i * 2
                if degs[i] + max_add_i < target_degrees[i]:
                    continue 

                avail_j = 0
                for idx in island_connections[j]:
                    if idx == conn_idx: continue
                    if vals[idx] == -1:
                         is_crossed = False
                         for c_idx in conn_conflicts[idx]:
                             if vals[c_idx] > 0:
                                 is_crossed = True
                                 break
                         if not is_crossed:
                             avail_j += 1
                max_add_j = avail_j * 2
                if degs[j] + max_add_j < target_degrees[j]:
                    continue

            new_vals = list(vals)
            new_vals[conn_idx] = val
            new_degs = list(degs)
            if val > 0:
                new_degs[i] += val
                new_degs[j] += val

            if val > 0:
                conflict_invalid = False
                for c_idx in conn_conflicts[conn_idx]:
                    if new_vals[c_idx] == -1:
                        new_vals[c_idx] = 0
                    elif new_vals[c_idx] > 0:
                        conflict_invalid = True
                        break
                if conflict_invalid:
                    continue

            res = solve_recursive(new_vals, new_degs)
            if res: return res

        return None

    # Initial Propagate
    values, current_degrees, success = propagate(values, current_degrees)
    if not success:
        return "No Solution"

    final_values = solve_recursive(values, current_degrees)

    if final_values is None:
        return "No Solution"

    result = {}
    for idx, count in enumerate(final_values):
        if count > 0:
            i, j = conn_islands[idx]
            r1, c1 = islands[i]['r'], islands[i]['c']
            r2, c2 = islands[j]['r'], islands[j]['c']
            key = ((r1, c1), (r2, c2))
            if key[0] > key[1]:
                key = (key[1], key[0])
            result[key] = count

    return result

