OBSERVATION = {
    'region': [
        [0, 0, 0, 1, 1, 1, 1, 1, 1, 2],
        [0, 3, 4, 1, 5, 5, 5, 6, 6, 2],
        [0, 3, 4, 1, 7, 7, 7, 8, 8, 9],
        [0, 3, 4, 1, 10, 10, 10, 10, 8, 9],
        [0, 3, 11, 11, 11, 11, 11, 11, 8, 9],
        [12, 3, 11, 13, 13, 13, 13, 13, 8, 9],
        [12, 14, 14, 15, 15, 15, 16, 16, 16, 17],
        [12, 18, 19, 19, 20, 20, 16, 21, 21, 17],
        [12, 18, 22, 23, 23, 23, 23, 21, 21, 17],
        [12, 18, 22, 24, 24, 24, 24, 21, 21, 17]
    ],
    'row_water_counts': [5, 3, 3, 7, 1, 1, 5, 6, 3, 2],
    'col_water_counts': [3, 2, 2, 6, 4, 5, 4, 4, 4, 2]
}

def solve(observation):
    region_grid = observation['region']
    row_clues = observation['row_water_counts']
    col_clues = observation['col_water_counts']

    rows = len(region_grid)
    cols = len(region_grid[0])

    # Identify regions and their cells
    regions = {}
    for r in range(rows):
        for c in range(cols):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_ids = sorted(regions.keys())

    # Precompute options for each region
    # For each region, possible water levels are the unique row indices present in the region.
    # Plus an "empty" option.
    # If level is L, water cells are {(r, c) in region | r >= L}.

    region_options = {}
    for rid in region_ids:
        cells = regions[rid]
        row_indices = sorted(list(set(r for r, c in cells)))
        options = []

        # Option: Empty
        # row_counts: all 0, col_counts: all 0
        options.append({
            'level': None,
            'row_counts': [0] * rows,
            'col_counts': [0] * cols,
            'cells': []
        })

        # Options: Water from level L downwards
        for L in row_indices:
            water_cells = [(r, c) for r, c in cells if r >= L]
            r_counts = [0] * rows
            c_counts = [0] * cols
            for r, c in water_cells:
                r_counts[r] += 1
                c_counts[c] += 1
            options.append({
                'level': L,
                'row_counts': r_counts,
                'col_counts': c_counts,
                'cells': water_cells
            })
        region_options[rid] = options

    # Backtracking solver
    # State: current row counts, current col counts, assignment for each region
    current_row_counts = [0] * rows
    current_col_counts = [0] * cols
    assignment = {} # rid -> option_index

    # Order regions by something? Maybe number of options (MRV)
    # But options depend on region size.
    # Let's just use the order of region_ids.

    def is_consistent(rid, option_idx):
        opt = region_options[rid][option_idx]
        # Check if adding this option exceeds clues
        for r in range(rows):
            if current_row_counts[r] + opt['row_counts'][r] > row_clues[r]:
                return False
        for c in range(cols):
            if current_col_counts[c] + opt['col_counts'][c] > col_clues[c]:
                return False
        return True

    def apply(rid, option_idx, delta=1):
        opt = region_options[rid][option_idx]
        for r in range(rows):
            current_row_counts[r] += delta * opt['row_counts'][r]
        for c in range(cols):
            current_col_counts[c] += delta * opt['col_counts'][c]
        assignment[rid] = option_idx

    def unapply(rid):
        option_idx = assignment[rid]
        apply(rid, option_idx, delta=-1)
        del assignment[rid]

    def solve_recursive(idx):
        if idx == len(region_ids):
            # Check if all clues are met exactly
            for r in range(rows):
                if current_row_counts[r] != row_clues[r]:
                    return False
            for c in range(cols):
                if current_col_counts[c] != col_clues[c]:
                    return False
            return True

        rid = region_ids[idx]
        options = region_options[rid]

        # Try options
        # Heuristic: Try options that fill more cells first? Or less?
        # Let's try all.
        for opt_idx in range(len(options)):
            if is_consistent(rid, opt_idx):
                apply(rid, opt_idx)
                if solve_recursive(idx + 1):
                    return True
                unapply(rid)
        return False

    if solve_recursive(0):
        # Construct result grid
        result = [[None for _ in range(cols)] for _ in range(rows)]
        for rid in region_ids:
            opt_idx = assignment[rid]
            opt = region_options[rid][opt_idx]
            for r, c in opt['cells']:
                result[r][c] = 'W'
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
